def _norm_key(s):
    try:
        return str(s).strip().lower().replace('-', '_')
    except BaseException:
        return ''


def _truthy(v, default=False):
    try:
        if v is None:
            return default
        return str(v).strip().lower() in ('1', 'true', 'yes', 'y', 'on', 'enable', 'enabled')
    except BaseException:
        return default


def _is_stop_requested_like(obj):
    try:
        if obj is None:
            return False
        if isinstance(obj, (str, bytes, int, float, bool)):
            return False
        for n in ('stop_requested', '_stop_requested', 'should_stop', '_should_stop'):
            try:
                if hasattr(obj, n):
                    v = getattr(obj, n)
                    if callable(v):
                        v = v()
                    if bool(v):
                        return True
            except BaseException:
                pass
        for n in ('stop_event', '_stop_event', 'stop_signal', '_stop_signal', 'cancel_event', '_cancel_event'):
            try:
                ev = getattr(obj, n, None)
                if ev is not None:
                    if hasattr(ev, 'is_set') and callable(getattr(ev, 'is_set')):
                        if bool(ev.is_set()):
                            return True
                    elif bool(ev):
                        return True
            except BaseException:
                pass
        for n in ('running', '_running', 'is_running'):
            try:
                if hasattr(obj, n):
                    v = getattr(obj, n)
                    if callable(v):
                        v = v()
                    if bool(v) is False:
                        return True
            except BaseException:
                pass
    except BaseException:
        pass
    return False


# A Start click is a transition out of a fully stopped runtime.  The general
# stop gate intentionally treats an inactive runtime as non-runnable, but that
# same predicate must not reject the entry point that is responsible for
# starting it again.
