def _runtime_start_is_currently_stopping(args, kwargs=None):
    """Return True only for an active stop transition, not stale stop residue."""
    try:
        items = []
        try:
            items.extend(list(args or ())[:8])
        except BaseException:
            pass
        try:
            if kwargs:
                for key in ('bot', 'engine', 'runtime', 'service', 'controller', 'ctx', 'context'):
                    if key in kwargs:
                        items.append(kwargs.get(key))
                items.extend(list(kwargs.values())[:8])
        except BaseException:
            pass
        seen = set()
        stack = list(items)
        depth = 0
        while stack and depth < 32:
            depth += 1
            obj = stack.pop(0)
            if obj is None or isinstance(obj, (str, bytes, int, float, bool)):
                continue
            try:
                oid = id(obj)
                if oid in seen:
                    continue
                seen.add(oid)
            except BaseException:
                pass
            for name in (
                '_bot_stopping', 'bot_stopping', '_stopping', 'stopping',
                '_stop_in_progress', 'stop_in_progress', 'is_stopping',
            ):
                try:
                    value = getattr(obj, name, None)
                    if callable(value):
                        value = value()
                    if bool(value):
                        return True
                except BaseException:
                    pass
            try:
                states = getattr(obj, '_instance_runtime_ui_state', None)
                if isinstance(states, dict):
                    ids = []
                    for name in ('current_instance_id', 'active_instance_id', 'instance_id'):
                        value = getattr(obj, name, None)
                        if value not in (None, ''):
                            ids.append(str(value))
                    for key in ids:
                        state = states.get(key)
                        if state is None:
                            try:
                                state = states.get(int(key))
                            except BaseException:
                                state = None
                        if isinstance(state, dict) and bool(state.get('stopping', False)):
                            return True
            except BaseException:
                pass
            for name in (
                'bot', '_bot', 'engine', '_engine', 'runtime', '_runtime',
                'service', '_service', 'controller', '_controller',
            ):
                try:
                    child = getattr(obj, name, None)
                    if child is not None:
                        stack.append(child)
                except BaseException:
                    pass
    except BaseException:
        pass
    return False


def _prepare_runtime_start_request(args, kwargs=None):
    """Clear stale in-memory stop flags before a user-initiated Start request.

    This only changes live runtime objects.  It does not edit configuration or
    persisted user state, and deliberately leaves `running` false until the
    native start method has successfully created its worker.
    """
    changed = 0
    try:
        items = []
        try:
            items.extend(list(args or ())[:8])
        except BaseException:
            pass
        try:
            if kwargs:
                for key in ('bot', 'engine', 'runtime', 'service', 'controller', 'ctx', 'context'):
                    if key in kwargs:
                        items.append(kwargs.get(key))
                items.extend(list(kwargs.values())[:8])
        except BaseException:
            pass
        seen = set()
        stack = list(items)
        depth = 0
        while stack and depth < 32:
            depth += 1
            obj = stack.pop(0)
            if obj is None or isinstance(obj, (str, bytes, int, float, bool)):
                continue
            try:
                oid = id(obj)
                if oid in seen:
                    continue
                seen.add(oid)
            except BaseException:
                pass
            for name in (
                'stop_requested', '_stop_requested', 'should_stop',
                '_should_stop', 'exit_on_stop', '_exit_on_stop',
            ):
                try:
                    value = getattr(obj, name, None)
                    if isinstance(value, bool) and value:
                        setattr(obj, name, False)
                        changed += 1
                except BaseException:
                    pass
            for name in (
                'stop_event', '_stop_event', 'stop_signal', '_stop_signal',
                'cancel_event', '_cancel_event',
            ):
                try:
                    event = getattr(obj, name, None)
                    is_set = getattr(event, 'is_set', None)
                    clear = getattr(event, 'clear', None)
                    if callable(is_set) and bool(is_set()) and callable(clear):
                        clear()
                        changed += 1
                except BaseException:
                    pass
            for name in (
                'bot', '_bot', 'engine', '_engine', 'runtime', '_runtime',
                'service', '_service', 'controller', '_controller',
            ):
                try:
                    child = getattr(obj, name, None)
                    if child is not None:
                        stack.append(child)
                except BaseException:
                    pass
    except BaseException:
        pass
    return changed


def _stop_requested_in_args(args, kwargs=None):
    # An inactive runtime is expected during `start()`. Older wrappers call
    # this predicate before native start can flip `running` to True, so scope a
    # bypass to that one synchronous Start dispatch only.
    try:
        local = globals().get('_RUNTIME_START_STOP_GATE_LOCAL')
        if local is not None and int(getattr(local, 'depth', 0) or 0) > 0:
            return False
    except BaseException:
        pass
    try:
        items = []
        try:
            items.extend(list(args or ())[:8])
        except BaseException:
            pass
        try:
            if kwargs:
                for k in ('bot', 'engine', 'runtime', 'service', 'controller', 'ctx', 'context'):
                    if k in kwargs:
                        items.append(kwargs.get(k))
                items.extend(list(kwargs.values())[:8])
        except BaseException:
            pass
        seen = set()
        stack = list(items)
        depth = 0
        while stack and depth < 32:
            depth += 1
            obj = stack.pop(0)
            try:
                oid = id(obj)
                if oid in seen:
                    continue
                seen.add(oid)
            except BaseException:
                pass
            if _is_stop_requested_like(obj):
                return True
            try:
                if obj is not None and not isinstance(obj, (str, bytes, int, float, bool)):
                    for n in ('bot', '_bot', 'engine', '_engine', 'runtime', '_runtime', 'service', '_service', 'controller', '_controller'):
                        try:
                            child = getattr(obj, n, None)
                            if child is not None:
                                stack.append(child)
                        except BaseException:
                            pass
            except BaseException:
                pass
    except BaseException:
        pass
    return False


def _stop_gate_return(name):
    try:
        _throttled_write('stop-gate-' + str(name), 'v30 stop gate blocked ' + str(name), 3.0)
    except BaseException:
        pass
    return False


def _cfg_path():
    try:
        base = os.environ.get('LOCALAPPDATA', '')
        if not base:
            return ''
        return os.path.join(base, 'qq-farm-bot-rev', 'config-multi.ini')
    except BaseException:
        return ''


def _read_ini_values():
    global _INI_CACHE_TS, _INI_CACHE_VALS
    vals = {}
    try:
        now = time.time()
        if _INI_CACHE_VALS is not None and (now - _INI_CACHE_TS) < 5.0:
            return _INI_CACHE_VALS
        cfg = _cfg_path()
        if not cfg or not os.path.exists(cfg):
            return vals
        try:
            data = open(cfg, 'rb').read().decode('utf-8', 'replace')
        except BaseException:
            data = open(cfg, 'r').read()
        sec = ''
        for raw in data.splitlines():
            line = raw.strip()
            if not line or line.startswith('#') or line.startswith(';'):
                continue
            if line.startswith('[') and ']' in line:
                sec = _norm_key(line[1:line.find(']')])
                continue
            if '=' in line:
                k, v = line.split('=', 1)
                vals[(sec, _norm_key(k))] = v.strip()
        _INI_CACHE_VALS = vals
        _INI_CACHE_TS = time.time()
    except BaseException as e:
        try: _write('read ini values error ' + repr(e))
        except BaseException: pass
    return vals


def _cfg_get(sections, option, default=None):
    try:
        vals = _read_ini_values()
        opt = _norm_key(option)
        for sec in sections:
            key = (_norm_key(sec), opt)
            if key in vals:
                return vals.get(key)
    except BaseException:
        pass
    return default


def _effective_friend_cooldown(check_interval, friend_cooldown):
    # The legacy scheduler refreshes its friend timestamp even when a friend
    # cycle exits during cooldown.  A cooldown at or above the patrol interval
    # can therefore keep every later cycle on the friend page indefinitely.
    try:
        patrol = max(1, int(float(check_interval)))
    except BaseException:
        patrol = 15
    try:
        cooldown = max(0, int(float(friend_cooldown)))
    except BaseException:
        cooldown = 0
    safe_max = max(1, patrol - 5)
    if cooldown >= patrol:
        return safe_max
    return cooldown


def _friend_guard_poll_interval_seconds(context=None):
    """Return the stable interval between empty friend-guard patrols.

    This is deliberately independent of the fast scheduler interval used while
    an active friend chain is moving between cards.  A confirmed empty friend
    round must not turn ``check_interval=2`` into a 2-second no-op loop.
    """
    configured = None
    try:
        sections_fn = globals().get('_active_friend_sections')
        sections = sections_fn() if callable(sections_fn) else None
        if not sections:
            bot_sections_fn = globals().get('_active_bot_sections')
            sections = bot_sections_fn() if callable(bot_sections_fn) else []
        cfg_fn = globals().get('_cfg_get')
        if callable(cfg_fn):
            configured = cfg_fn(
                sections,
                'friend_guard_empty_poll_interval_seconds',
                None,
            )
    except BaseException:
        configured = None

    try:
        configured_seconds = float(configured)
    except BaseException:
        configured_seconds = 0.0
    if configured_seconds > 0.0:
        # Keep the setting bounded and never permit an empty friend screen to
        # become a high-frequency poll loop.
        return max(15.0, min(3600.0, configured_seconds))

    check_interval = None
    friend_cooldown = None
    try:
        check_interval = getattr(context, 'check_interval', None)
    except BaseException:
        check_interval = None
    try:
        friend_cooldown = getattr(context, 'friend_colddown_time', None)
        if friend_cooldown is None:
            friend_cooldown = getattr(context, 'friend_cooldown_time', None)
    except BaseException:
        friend_cooldown = None
    try:
        sections_fn = globals().get('_active_bot_sections')
        sections = sections_fn() if callable(sections_fn) else []
        cfg_fn = globals().get('_cfg_get')
        if callable(cfg_fn):
            if check_interval is None:
                check_interval = cfg_fn(sections, 'check_interval', 15.0)
            if friend_cooldown is None:
                friend_cooldown = cfg_fn(
                    sections,
                    'friend_colddown_time',
                    cfg_fn(sections, 'friend_cooldown_time', 0.0),
                )
    except BaseException:
        pass
    try:
        normal_interval = max(0.0, float(check_interval))
    except BaseException:
        normal_interval = 0.0
    try:
        safe_cooldown = float(
            _effective_friend_cooldown(check_interval, friend_cooldown)
        )
    except BaseException:
        safe_cooldown = 0.0
    return max(15.0, normal_interval, safe_cooldown)


def _friend_guard_schedule_empty_poll(context, reason='', now_ts=None):
    """Lock a stable empty friend round until verified self-farm progress rearms it."""
    if context is None:
        return 0.0
    try:
        if now_ts is None:
            now_fn = globals().get('_friend_guard_poll_now')
            now_ts = float(now_fn()) if callable(now_fn) else float(
                __import__('time').time()
            )
        else:
            now_ts = float(now_ts)
    except BaseException:
        try:
            now_ts = float(__import__('time').time())
        except BaseException:
            now_ts = 0.0
    try:
        setattr(context, '_qqfarm_friend_guard_last_empty_poll_ts', float(now_ts))
        setattr(context, '_qqfarm_friend_guard_next_poll_ts', 0.0)
        setattr(context, '_qqfarm_friend_guard_empty_latched', True)
        setattr(context, '_qqfarm_friend_guard_empty_latched_since_ts', float(now_ts))
        setattr(context, '_qqfarm_friend_guard_last_empty_reason', str(reason or ''))
        setattr(context, '_qqfarm_friend_chain_pending', False)
        setattr(context, '_qqfarm_friend_chain_active', False)
        setattr(context, '_qqfarm_friend_chain_exhausted', True)
        setattr(context, '_qqfarm_friend_chain_allow_home', True)
    except BaseException:
        return 0.0
    try:
        fast_fn = globals().get('_set_friend_chain_fast_interval')
        if callable(fast_fn):
            fast_fn(context, False)
    except BaseException:
        pass
    try:
        _write(
            'v249 friend guard stable empty round locked; waiting for verified '
            'home progress reason=' + str(reason or '')
        )
    except BaseException:
        pass
    return 0.0


def _friend_guard_clear_empty_poll_wait(context, reopen_chain=False):
    """Clear a legacy timestamp without reopening a locked friend patrol."""
    if context is None:
        return False
    try:
        setattr(context, '_qqfarm_friend_guard_next_poll_ts', 0.0)
        if reopen_chain:
            try:
                _write(
                    'v249 ignored automatic friend-poll reopen; verified home '
                    'progress is required'
                )
            except BaseException:
                pass
        return True
    except BaseException:
        return False


def _friend_guard_rearm_after_home_progress(context, reason='', now_ts=None):
    """Reopen one friend round only after stable, verified self-farm completion."""
    if context is None:
        return False
    try:
        if not bool(getattr(context, '_qqfarm_friend_guard_empty_latched', False)):
            return False
    except BaseException:
        return False
    try:
        if now_ts is None:
            now_fn = globals().get('_friend_guard_poll_now')
            now_ts = float(now_fn()) if callable(now_fn) else float(
                __import__('time').time()
            )
        else:
            now_ts = float(now_ts)
    except BaseException:
        try:
            now_ts = float(__import__('time').time())
        except BaseException:
            now_ts = 0.0
    try:
        setattr(context, '_qqfarm_friend_guard_empty_latched', False)
        setattr(context, '_qqfarm_friend_guard_empty_latched_since_ts', 0.0)
        setattr(context, '_qqfarm_friend_guard_next_poll_ts', 0.0)
        setattr(context, '_qqfarm_friend_guard_last_rearm_ts', float(now_ts))
        setattr(context, '_qqfarm_friend_guard_last_rearm_reason', str(reason or ''))
        setattr(context, '_qqfarm_friend_chain_pending', False)
        setattr(context, '_qqfarm_friend_chain_active', False)
        setattr(context, '_qqfarm_friend_chain_exhausted', False)
        setattr(context, '_qqfarm_friend_chain_allow_home', False)
        setattr(context, '_qqfarm_force_self_cycle_next', False)
        setattr(context, '_qqfarm_cycle_branch_hint', 'friend')
    except BaseException:
        return False
    try:
        fast_fn = globals().get('_set_friend_chain_fast_interval')
        if callable(fast_fn):
            fast_fn(context, False)
    except BaseException:
        pass
    try:
        _write(
            'v249 friend guard rearmed after verified home progress reason=' +
            str(reason or '')
        )
    except BaseException:
        pass
    return True


def _friend_home_request_toast_visible(frame):
    """Recognize the bottom-right home friend-request card with a text template."""
    try:
        np_module = globals().get('np') or __import__('numpy')
        cv_module = globals().get('cv2') or __import__('cv2')
        image = np_module.asarray(frame)
        shape = getattr(image, 'shape', None)
        if shape is None or len(shape) < 3 or int(shape[2]) < 3:
            return False
        height, width = int(shape[0]), int(shape[1])
        if height < 320 or width < 220:
            return False
        canonical = image[:, :, :3]
        if width != 428 or height != 800:
            canonical = cv_module.resize(
                canonical, (428, 800), interpolation=cv_module.INTER_AREA
            )
        template = globals().get('_FRIEND_HOME_REQUEST_TEXT_TEMPLATE_CACHE')
        if template is None:
            try:
                path_module = __import__('os').path
                template_path = path_module.join(
                    path_module.dirname(__file__), 'friend_help_request_text.png'
                )
                template = cv_module.imread(
                    template_path, cv_module.IMREAD_GRAYSCALE
                )
            except BaseException:
                template = None
            globals()['_FRIEND_HOME_REQUEST_TEXT_TEMPLATE_CACHE'] = template
        if template is None or getattr(template, 'size', 0) <= 0:
            return False
        search = canonical[560:730, 190:428, :3]
        search_gray = cv_module.cvtColor(search, cv_module.COLOR_BGR2GRAY)
        template_edge = cv_module.Canny(template, 60, 140)
        search_edge = cv_module.Canny(search_gray, 60, 140)
        if (
            template_edge.shape[0] >= search_edge.shape[0] or
            template_edge.shape[1] >= search_edge.shape[1]
        ):
            return False
        match = cv_module.matchTemplate(
            search_edge, template_edge, cv_module.TM_CCOEFF_NORMED
        )
        _, semantic_score, _, _ = cv_module.minMaxLoc(match)
        if float(semantic_score) < 0.42:
            return False
        roi = canonical[628:712, 248:426, :3]
        blue = roi[:, :, 0].astype('int16')
        green = roi[:, :, 1].astype('int16')
        red = roi[:, :, 2].astype('int16')
        cream = (
            (red >= 185) & (green >= 165) & (blue >= 120) &
            (green <= 250) & (blue <= 235) & ((red - blue) >= 5)
        ).astype('uint8')
        bright = (
            (red >= 210) & (green >= 210) & (blue >= 190)
        )
        cream_ratio = float(np_module.mean(cream > 0))
        bright_ratio = float(np_module.mean(bright))
        component_count, _, stats, _ = cv_module.connectedComponentsWithStats(
            cream, 8
        )
        largest_ratio = 0.0
        if int(component_count) > 1:
            for index in range(1, int(component_count)):
                area = int(stats[index, cv_module.CC_STAT_AREA])
                largest_ratio = max(
                    largest_ratio,
                    float(area) / float(max(1, cream.size)),
                )
        edge_ratio = float(np_module.mean(
            cv_module.Canny(
                cv_module.cvtColor(roi, cv_module.COLOR_BGR2GRAY), 80, 160
            ) > 0
        ))
        return bool(
            cream_ratio >= 0.28 and
            bright_ratio >= 0.10 and
            largest_ratio >= 0.24 and
            edge_ratio >= 0.07
        )
    except BaseException:
        return False


def _friend_home_visual_entry_candidate(frame):
    """Return only a tightly located, visible home-page friend-entry click."""
    try:
        np_module = globals().get('np') or __import__('numpy')
        cv_module = globals().get('cv2') or __import__('cv2')
        image = np_module.asarray(frame)
        shape = getattr(image, 'shape', None)
        if shape is None or len(shape) < 3 or int(shape[2]) < 3:
            return None
        frame_height, frame_width = int(shape[0]), int(shape[1])
        if frame_height < 320 or frame_width < 220:
            return None
        canonical = image[:, :, :3]
        if frame_width != 428 or frame_height != 800:
            canonical = cv_module.resize(
                canonical, (428, 800), interpolation=cv_module.INTER_AREA
            )

        def _load_template(cache_key, filename):
            template = globals().get(cache_key)
            if template is not None and getattr(template, 'size', 0) > 0:
                return template
            try:
                path_module = __import__('os').path
                template_path = path_module.join(
                    path_module.dirname(__file__), filename
                )
                # OpenCV imread on this Windows runtime cannot reliably open a
                # deployment path containing Chinese characters. Read bytes via
                # numpy and decode in memory; retain imread for unusual backends.
                template = None
                try:
                    encoded_template = np_module.fromfile(
                        template_path, dtype=np_module.uint8
                    )
                    if int(getattr(encoded_template, 'size', 0) or 0) > 0:
                        template = cv_module.imdecode(
                            encoded_template, cv_module.IMREAD_GRAYSCALE
                        )
                except BaseException:
                    template = None
                if template is None or getattr(template, 'size', 0) <= 0:
                    template = cv_module.imread(
                        template_path, cv_module.IMREAD_GRAYSCALE
                    )
            except BaseException:
                template = None
            globals()[cache_key] = template
            return template

        # Preserve the existing, more specific help-request-card entry first.
        template = _load_template(
            '_FRIEND_HOME_REQUEST_TEXT_TEMPLATE_CACHE',
            'friend_help_request_text.png',
        )
        if template is not None and getattr(template, 'size', 0) > 0:
            search_left, search_top = 250, 630
            search_right, search_bottom = 428, 720
            search = canonical[
                search_top:search_bottom, search_left:search_right, :3
            ]
            search_gray = cv_module.cvtColor(search, cv_module.COLOR_BGR2GRAY)
            template_height, template_width = template.shape[:2]
            if (
                template_height < search_gray.shape[0] and
                template_width < search_gray.shape[1]
            ):
                match = cv_module.matchTemplate(
                    search_gray, template, cv_module.TM_CCOEFF_NORMED
                )
                _, score, _, top_left = cv_module.minMaxLoc(match)
                score = float(score)
                text_left = int(search_left + int(top_left[0]))
                text_top = int(search_top + int(top_left[1]))
                if score >= 0.66 and (
                    280 <= text_left <= 340 and 640 <= text_top <= 690
                ):
                    canonical_x = float(text_left) + (float(template_width) / 2.0)
                    canonical_y = float(text_top) + (float(template_height) / 2.0)
                    click_x = int(round(canonical_x * float(frame_width) / 428.0))
                    click_y = int(round(canonical_y * float(frame_height) / 800.0))
                    click_x = max(0, min(frame_width - 1, click_x))
                    click_y = max(0, min(frame_height - 1, click_y))
                    return {
                        'kind': 'home-friend-request-card',
                        'x': int(click_x),
                        'y': int(click_y),
                        'score': score,
                        'frame_size': (int(frame_width), int(frame_height)),
                        'template_box': (
                            int(text_left), int(text_top),
                            int(template_width), int(template_height),
                        ),
                    }

        # v410: when native entries and the request card are absent, admit just
        # the bottom-right ?? button. Its template and expected normalized box
        # deliberately exclude every other footer button and all friend-farm UI.
        nav_template = _load_template(
            '_FRIEND_HOME_BOTTOM_NAV_TEMPLATE_CACHE',
            'friend_bottom_nav_button.png',
        )
        if nav_template is None or getattr(nav_template, 'size', 0) <= 0:
            return None
        nav_left_bound, nav_top_bound = 335, 675
        nav_right_bound, nav_bottom_bound = 428, 800
        nav_search = canonical[
            nav_top_bound:nav_bottom_bound, nav_left_bound:nav_right_bound, :3
        ]
        nav_gray = cv_module.cvtColor(nav_search, cv_module.COLOR_BGR2GRAY)
        nav_height, nav_width = nav_template.shape[:2]
        if nav_height >= nav_gray.shape[0] or nav_width >= nav_gray.shape[1]:
            return None
        nav_match = cv_module.matchTemplate(
            nav_gray, nav_template, cv_module.TM_CCOEFF_NORMED
        )
        _, nav_score, _, nav_top_left = cv_module.minMaxLoc(nav_match)
        nav_score = float(nav_score)
        nav_left = int(nav_left_bound + int(nav_top_left[0]))
        nav_top = int(nav_top_bound + int(nav_top_left[1]))
        if nav_score < 0.75:
            return None
        if not (348 <= nav_left <= 362 and 694 <= nav_top <= 728):
            return None
        # Aim at the lower, text-bearing portion of the matched button rather
        # than at a decoration near its edge. The whole control is viewport
        # relative, so normalizing before matching preserves resize behavior.
        canonical_x = float(nav_left) + (float(nav_width) * 0.50)
        canonical_y = float(nav_top) + (float(nav_height) * 0.64)
        click_x = int(round(canonical_x * float(frame_width) / 428.0))
        click_y = int(round(canonical_y * float(frame_height) / 800.0))
        click_x = max(0, min(frame_width - 1, click_x))
        click_y = max(0, min(frame_height - 1, click_y))
        return {
            'kind': 'home-friend-bottom-nav',
            'x': int(click_x),
            'y': int(click_y),
            'score': nav_score,
            'frame_size': (int(frame_width), int(frame_height)),
            'template_box': (
                int(nav_left), int(nav_top), int(nav_width), int(nav_height),
            ),
        }
    except BaseException:
        return None

def _friend_guard_poll_dispatch_allowed(context, now_ts=None):
    """Block empty friend loops until self-farm completion explicitly rearms them."""
    if context is None:
        return True
    try:
        if bool(getattr(context, '_qqfarm_friend_guard_empty_latched', False)):
            request_visible = False
            try:
                capture_fn = globals().get('_qqfarm_capture_visible_farm_frame')
                state_fn = globals().get('_friend_guard_friend_ui_state')
                request_fn = globals().get('_friend_home_request_toast_visible')
                request_frame = capture_fn() if callable(capture_fn) else None
                live_state = (
                    state_fn(request_frame)
                    if callable(state_fn) and request_frame is not None
                    else None
                )
                priority_fn = globals().get('_qqfarm_home_priority_active')
                home_work_pending = bool(
                    (callable(priority_fn) and priority_fn(context)) or
                    getattr(
                        context, '_qqfarm_single_harvest_planting_pending', False
                    ) or
                    getattr(context, '_qqfarm_post_harvest_pending', False) or
                    int(getattr(context, 'planting_harvest_quota', 0) or 0) > 0
                )
                try:
                    current_now = float(
                        now_ts if now_ts is not None else
                        globals().get('_friend_guard_poll_now', lambda: 0.0)()
                    )
                except BaseException:
                    current_now = 0.0
                last_rearm = float(getattr(
                    context, '_qqfarm_friend_home_request_last_rearm_ts', 0.0
                ) or 0.0)
                try:
                    rearm_cooldown = float(getattr(
                        context,
                        'friend_home_request_rearm_cooldown_seconds',
                        30.0,
                    ) or 30.0)
                except BaseException:
                    rearm_cooldown = 30.0
                rearm_cooldown = max(12.0, min(180.0, rearm_cooldown))
                cooldown_clear = bool(
                    last_rearm <= 0.0 or current_now <= 0.0 or
                    current_now - last_rearm >= rearm_cooldown
                )
                request_visible = bool(
                    not home_work_pending and cooldown_clear and
                    live_state is False and callable(request_fn) and
                    request_fn(request_frame)
                )
            except BaseException:
                request_visible = False
            if request_visible:
                rearm_fn = globals().get('_friend_guard_rearm_after_home_progress')
                rearmed = bool(rearm_fn(
                    context,
                    reason='visible-home-friend-request',
                    now_ts=now_ts,
                )) if callable(rearm_fn) else False
                if rearmed:
                    try:
                        setattr(
                            context,
                            '_qqfarm_friend_direct_entry_cooldown_until',
                            0.0,
                        )
                        setattr(context, '_qqfarm_friend_entry_prefer_icon', False)
                        setattr(context, '_qqfarm_cycle_branch_hint', 'self')
                        setattr(context, '_qqfarm_friend_entry_pending', False)
                        setattr(
                            context,
                            '_qqfarm_friend_home_request_last_rearm_ts',
                            float(current_now),
                        )
                    except BaseException:
                        pass
                    try:
                        hint_fn = globals().get('_qqfarm_set_live_scene_hint')
                        if callable(hint_fn):
                            hint_fn(context, scene_hint='home')
                    except BaseException:
                        pass
                    try:
                        _write(
                            'v359 visible home friend request rearmed stable empty '
                            'friend patrol and restored direct entry'
                        )
                    except BaseException:
                        pass
                    return True
            _throttled_write(
                'v249-friend-guard-empty-latched',
                'v249 friend patrol remains locked after a stable empty friend; '
                'waiting for verified home progress',
                15.0,
            )
            return False
    except BaseException:
        pass
    try:
        pending = bool(getattr(context, '_qqfarm_friend_chain_pending', False))
        active = bool(getattr(context, '_qqfarm_friend_chain_active', False))
        if pending or active:
            return True
    except BaseException:
        pass
    try:
        next_poll_ts = float(getattr(
            context, '_qqfarm_friend_guard_next_poll_ts', 0.0
        ) or 0.0)
    except BaseException:
        next_poll_ts = 0.0
    if next_poll_ts <= 0.0:
        return True
    # A timestamp from an older run previously reopened the friend chain after
    # fifteen seconds.  Convert it to the same lock used by new empty rounds.
    _friend_guard_schedule_empty_poll(
        context,
        reason='legacy-empty-poll-converted-to-home-progress-lock',
        now_ts=now_ts,
    )
    return False


