def _qqfarm_deconflict_assistant_window_titles(app=None):
    """Keep the helper title out of the substring used to select the QQ game."""
    game_title = 'QQ\u7ecf\u5178\u519c\u573a'
    helper_title = '\u519c\u573a\u52a9\u624b - \u89c6\u89c9\u81ea\u52a8\u5316'
    visual_suffix = '\u89c6\u89c9\u81ea\u52a8\u5316'
    if app is None:
        try:
            sys_module = globals().get('sys') or __import__('sys')
            widgets_module = sys_module.modules.get('PySide6.QtWidgets')
            application_type = getattr(widgets_module, 'QApplication', None)
            app = application_type.instance() if application_type is not None else None
        except BaseException:
            app = None
    if app is None:
        return 0
    try:
        widgets = list(app.topLevelWidgets())
    except BaseException:
        widgets = []
    changed = 0
    for widget in widgets:
        try:
            title_fn = getattr(widget, 'windowTitle', None)
            title = str(title_fn() or '') if callable(title_fn) else ''
        except BaseException:
            title = ''
        if (
            not title or title == game_title or game_title not in title or
            visual_suffix not in title
        ):
            continue
        try:
            setter = getattr(widget, 'setWindowTitle', None)
            if callable(setter):
                setter(helper_title)
                changed += 1
        except BaseException:
            continue
    if changed:
        try:
            log_fn = globals().get('_throttled_write')
            message = (
                'v311 helper title deconflicted for WGC selector changed=' +
                str(changed)
            )
            if callable(log_fn):
                log_fn('v311-wgc-title-deconflicted', message, 30.0)
            else:
                writer = globals().get('_write')
                if callable(writer):
                    writer(message)
        except BaseException:
            pass
    return changed


def _qqfarm_wgc_window_title_conflicted():
    """Return whether this process still exposes the QQ game selector substring."""
    game_title = 'QQ\u7ecf\u5178\u519c\u573a'
    try:
        sys_module = globals().get('sys') or __import__('sys')
        widgets_module = sys_module.modules.get('PySide6.QtWidgets')
        application_type = getattr(widgets_module, 'QApplication', None)
        app = application_type.instance() if application_type is not None else None
        if app is not None:
            for widget in list(app.topLevelWidgets()):
                try:
                    title = str(widget.windowTitle() or '')
                except BaseException:
                    title = ''
                if title and title != game_title and game_title in title:
                    return True
    except BaseException:
        pass
    try:
        ctypes_module = __import__('ctypes')
        os_module = __import__('os')
        user32 = ctypes_module.windll.user32
        current_pid = int(os_module.getpid())
        conflicted = [False]
        callback_type = ctypes_module.WINFUNCTYPE(
            ctypes_module.c_bool, ctypes_module.c_void_p, ctypes_module.c_void_p
        )

        def _visit(hwnd, _lparam):
            try:
                pid = ctypes_module.c_ulong(0)
                user32.GetWindowThreadProcessId(hwnd, ctypes_module.byref(pid))
                if int(pid.value) != current_pid:
                    return True
                length = int(user32.GetWindowTextLengthW(hwnd) or 0)
                if length <= 0:
                    return True
                buffer = ctypes_module.create_unicode_buffer(length + 1)
                user32.GetWindowTextW(hwnd, buffer, length + 1)
                title = str(buffer.value or '')
                if title and title != game_title and game_title in title:
                    conflicted[0] = True
                    return False
            except BaseException:
                pass
            return True

        user32.EnumWindows(callback_type(_visit), 0)
        return bool(conflicted[0])
    except BaseException:
        return False


