def _qqfarm_wgc_frame_arrived(
        buffer_ptr, buffer_len, width, height, _stop_list=None, _timestamp=None):
    """Copy a native BGRA frame before the Windows Capture callback returns."""
    try:
        width_value = int(width or 0)
        height_value = int(height or 0)
        length_value = int(buffer_len or 0)
        address_value = getattr(buffer_ptr, 'value', buffer_ptr)
        address_value = int(address_value or 0)
        if (
            address_value <= 0 or width_value <= 0 or height_value <= 0 or
            width_value > 8192 or height_value > 8192
        ):
            return None
        minimum = width_value * height_value * 4
        if length_value < minimum:
            return None
        row_bytes = int(length_value // height_value)
        if row_bytes < width_value * 4:
            return None
        now_value = float(__import__('time').monotonic())
        last_accept = float(globals().get(
            '_QQFARM_WGC_FRAME_ACCEPT_TS', 0.0
        ) or 0.0)
        copy_interval = float(globals().get(
            '_QQFARM_WGC_FRAME_COPY_INTERVAL', 0.12
        ) or 0.12)
        if last_accept > 0.0 and (now_value - last_accept) < copy_interval:
            return None
        globals()['_QQFARM_WGC_FRAME_ACCEPT_TS'] = now_value
        ctypes_module = __import__('ctypes')
        np_module = globals().get('np') or __import__('numpy')
        raw_type = ctypes_module.c_ubyte * length_value
        raw = raw_type.from_address(address_value)
        rows = np_module.ctypeslib.as_array(raw).reshape(height_value, row_bytes)
        bgra = rows[:, :width_value * 4].reshape(height_value, width_value, 4)
        frame = np_module.ascontiguousarray(bgra[:, :, :3])
        globals()['_QQFARM_WGC_FRAME'] = frame
        globals()['_QQFARM_WGC_FRAME_TS'] = now_value
        globals()['_QQFARM_WGC_RAW_SIZE'] = (width_value, height_value)
        return None
    except BaseException:
        return None


