def _qqfarm_restore_hidden_miniapp_taskbar_card(reason=''):
    """Restore the QQ farm taskbar identity without activating or moving it."""
    try:
        configured_fn = globals().get('_configured_bool')
        sections_fn = globals().get('_active_bot_sections')
        sections = sections_fn() if callable(sections_fn) else ('bot',)
        compat_enabled = bool(configured_fn(
            sections, 'hide_miniapp_compat_mode', False
        )) if callable(configured_fn) else False
        if not compat_enabled:
            return False
        visible_fn = globals().get('_qqfarm_farm_window_is_visible')
        if callable(visible_fn) and bool(visible_fn()):
            return False
        finder = globals().get('_share_find_farm_window_hwnd')
        hwnd = int(finder() or 0) if callable(finder) else int(
            globals().get('_QQFARM_WGC_BOUND_HWND', 0) or 0
        )
        if hwnd <= 0:
            return False
        ctypes_module = __import__('ctypes')
        user32 = ctypes_module.windll.user32
        get_style = getattr(user32, 'GetWindowLongPtrW', None)
        set_style = getattr(user32, 'SetWindowLongPtrW', None)
        if not callable(get_style) or not callable(set_style):
            get_style = user32.GetWindowLongW
            set_style = user32.SetWindowLongW
        ex_style = int(get_style(hwnd, -20) or 0)
        desired_style = (ex_style & ~0x00000080) | 0x00040000
        if desired_style != ex_style:
            set_style(hwnd, -20, desired_style)
        user32.SetWindowPos(hwnd, 0, 0, 0, 0, 0, 0x0037)
        log_fn = globals().get('_throttled_write')
        if callable(log_fn):
            log_fn(
                'v156-hidden-taskbar-card-' + str(reason),
                'v156 hidden miniapp compatibility restored taskbar card reason=' +
                str(reason),
                30.0,
            )
        return True
    except BaseException:
        return False


def _qqfarm_start_wgc_capture():
    capture = globals().get('_QQFARM_WGC_CAPTURE')
    control = globals().get('_QQFARM_WGC_CONTROL')
    farm_hwnd = 0
    try:
        find_window_fn = globals().get('_share_find_farm_window_hwnd')
        if callable(find_window_fn):
            farm_hwnd = int(find_window_fn() or 0)
    except BaseException:
        farm_hwnd = 0
    if capture is not None:
        bound_hwnd = int(globals().get('_QQFARM_WGC_BOUND_HWND', 0) or 0)
        if bound_hwnd > 0 and farm_hwnd > 0 and bound_hwnd != farm_hwnd:
            stop_fn = globals().get('_qqfarm_stop_wgc_capture')
            if callable(stop_fn):
                stop_fn('window-handle-changed')
            capture = globals().get('_QQFARM_WGC_CAPTURE')
            control = globals().get('_QQFARM_WGC_CONTROL')
        if capture is not None:
            try:
                finished_fn = getattr(control, 'is_finished', None)
                if callable(finished_fn) and bool(finished_fn()):
                    globals()['_QQFARM_WGC_CAPTURE'] = None
                    globals()['_QQFARM_WGC_CONTROL'] = None
                    globals()['_QQFARM_WGC_BLANK_TS'] = 0.0
                    globals()['_QQFARM_WGC_BOUND_HWND'] = 0
                else:
                    return True
            except BaseException:
                return True
    time_module = __import__('time')
    now_value = float(time_module.monotonic())
    last_attempt = float(globals().get(
        '_QQFARM_WGC_START_ATTEMPT_TS', 0.0
    ) or 0.0)
    if last_attempt > 0.0 and (now_value - last_attempt) < 1.0:
        return False
    globals()['_QQFARM_WGC_START_ATTEMPT_TS'] = now_value
    try:
        rename_fn = globals().get('_qqfarm_deconflict_assistant_window_titles')
        if callable(rename_fn):
            rename_fn()
        conflict_fn = globals().get('_qqfarm_wgc_window_title_conflicted')
        if callable(conflict_fn) and bool(conflict_fn()):
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                log_fn(
                    'v311-wgc-title-conflict',
                    'v311 WGC start deferred until helper title no longer matches game',
                    5.0,
                )
            return False
        class_fn = globals().get('_qqfarm_load_native_windows_capture_class')
        capture_type = class_fn() if callable(class_fn) else None
        if capture_type is None:
            return False
        frame_callback = globals().get('_qqfarm_wgc_frame_arrived')
        close_callback = globals().get('_qqfarm_wgc_closed')
        if not callable(frame_callback) or not callable(close_callback):
            return False
        capture_options = {
            'cursor_capture': False,
            'draw_border': False,
            # Three frames per second still yields multiple fresh frames during
            # the 0.75s active patrol settle while reducing continuous QQ work.
            'minimum_update_interval': 333,
        }
        if farm_hwnd <= 0:
            try:
                find_window_fn = globals().get('_share_find_farm_window_hwnd')
                if callable(find_window_fn):
                    farm_hwnd = int(find_window_fn() or 0)
            except BaseException:
                farm_hwnd = 0
        supports_window_hwnd = False
        if farm_hwnd > 0:
            try:
                parameters = __import__('inspect').signature(
                    capture_type
                ).parameters
                supports_window_hwnd = 'window_hwnd' in parameters
            except BaseException:
                try:
                    text_signature = str(getattr(
                        capture_type, '__text_signature__', ''
                    ) or '')
                    supports_window_hwnd = 'window_hwnd' in text_signature
                except BaseException:
                    supports_window_hwnd = False
        if farm_hwnd > 0 and supports_window_hwnd:
            capture_options['window_hwnd'] = farm_hwnd
            capture_selector = 'hwnd=' + str(farm_hwnd)
        else:
            capture_options['window_name'] = 'QQ\u7ecf\u5178\u519c\u573a'
            capture_selector = 'title=QQ-farm'
        capture = capture_type(
            frame_callback,
            close_callback,
            **capture_options
        )
        globals()['_QQFARM_WGC_CAPTURE'] = capture
        control = capture.start_free_threaded()
        globals()['_QQFARM_WGC_CONTROL'] = control
        globals()['_QQFARM_WGC_STARTED_TS'] = now_value
        globals()['_QQFARM_WGC_BOUND_HWND'] = int(
            farm_hwnd if supports_window_hwnd else 0
        )
        globals()['_QQFARM_WGC_BAD_GEOMETRY_COUNT'] = 0
        log_fn = globals().get('_throttled_write')
        if callable(log_fn):
            log_fn(
                'v311-wgc-started',
                'v313 WGC game-window capture started selector=' + capture_selector,
                30.0,
            )
        return True
    except BaseException as error:
        globals()['_QQFARM_WGC_CAPTURE'] = None
        globals()['_QQFARM_WGC_CONTROL'] = None
        try:
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                log_fn(
                    'v311-wgc-start-error',
                    'v311 WGC start error=' + repr(error)[:220],
                    10.0,
                )
        except BaseException:
            pass
        return False


def _qqfarm_remember_good_capture_frame(frame):
    if frame is None:
        return None
    globals()['_QQFARM_LAST_GOOD_CAPTURE_FRAME'] = frame
    globals()['_QQFARM_LAST_GOOD_CAPTURE_TS'] = float(
        __import__('time').monotonic()
    )
    return frame


def _qqfarm_recent_good_capture_frame(max_age=8.0):
    frame = globals().get('_QQFARM_LAST_GOOD_CAPTURE_FRAME')
    timestamp = float(globals().get(
        '_QQFARM_LAST_GOOD_CAPTURE_TS', 0.0
    ) or 0.0)
    if frame is None or timestamp <= 0.0:
        return None
    if (float(__import__('time').monotonic()) - timestamp) > float(max_age):
        return None
    return frame


def _qqfarm_visible_capture_frame_is_trusted(frame, max_age=4.0):
    if frame is None or frame is not globals().get('_QQFARM_LAST_WGC_NORMALIZED_FRAME'):
        return False
    timestamp = float(globals().get(
        '_QQFARM_LAST_WGC_NORMALIZED_TS', 0.0
    ) or 0.0)
    return bool(
        timestamp > 0.0 and
        (float(__import__('time').monotonic()) - timestamp) <= float(max_age)
    )


def _qqfarm_wgc_frame_is_rendered_game_surface(frame):
    """Reject blank WGC surfaces while allowing rendered game/menu frames."""
    try:
        np_module = globals().get('np') or __import__('numpy')
        image = np_module.asarray(frame)
        shape = getattr(image, 'shape', None)
        if shape is None or len(shape) < 3 or int(shape[2]) < 3:
            return False
        height, width = int(shape[0]), int(shape[1])
        if height < 32 or width < 32:
            return False
        row_step = max(1, height // 160)
        column_step = max(1, width // 96)
        sample = image[::row_step, ::column_step, :3]
        if getattr(sample, 'size', 0) <= 0:
            return False
        if sample.dtype != np_module.uint8:
            sample = np_module.clip(sample, 0, 255).astype(np_module.uint8)
        white_ratio = float(np_module.mean(np_module.all(sample >= 245, axis=2)))
        return bool(white_ratio < 0.92)
    except BaseException:
        return False


def _qqfarm_capture_wgc_farm_frame(max_age=3.0):
    try:
        start_fn = globals().get('_qqfarm_start_wgc_capture')
        if callable(start_fn):
            start_fn()
        frame = globals().get('_QQFARM_WGC_FRAME')
        timestamp = float(globals().get('_QQFARM_WGC_FRAME_TS', 0.0) or 0.0)
        if frame is None or timestamp <= 0.0:
            return None
        now_value = float(__import__('time').monotonic())
        if (now_value - timestamp) > float(max_age):
            return None
        np_module = globals().get('np') or __import__('numpy')
        image = np_module.asarray(frame)
        shape = getattr(image, 'shape', None)
        if shape is None or len(shape) < 3:
            return None
        height, width = int(shape[0]), int(shape[1])
        ratio = float(width) / float(max(1, height))
        if ratio < 0.45 or ratio > 0.62:
            count = int(globals().get(
                '_QQFARM_WGC_BAD_GEOMETRY_COUNT', 0
            ) or 0) + 1
            globals()['_QQFARM_WGC_BAD_GEOMETRY_COUNT'] = count
            if count >= 2:
                stop_fn = globals().get('_qqfarm_stop_wgc_capture')
                if callable(stop_fn):
                    stop_fn('wrong-window-geometry')
            return None
        globals()['_QQFARM_WGC_BAD_GEOMETRY_COUNT'] = 0
        surface_fn = globals().get(
            '_qqfarm_wgc_frame_is_rendered_game_surface'
        )
        if callable(surface_fn) and not bool(surface_fn(image)):
            blank_count = int(globals().get(
                '_QQFARM_WGC_BLANK_COUNT', 0
            ) or 0) + 1
            globals()['_QQFARM_WGC_BLANK_COUNT'] = blank_count
            globals()['_QQFARM_WGC_BLANK_TS'] = now_value
            globals()['_QQFARM_LAST_GOOD_CAPTURE_FRAME'] = None
            globals()['_QQFARM_LAST_GOOD_CAPTURE_TS'] = 0.0
            globals()['_QQFARM_LAST_WGC_NORMALIZED_FRAME'] = None
            globals()['_QQFARM_LAST_WGC_NORMALIZED_TS'] = 0.0
            globals()['_QQFARM_LAST_WGC_NORMALIZED_SOURCE_TS'] = 0.0
            globals()['_QQFARM_LAST_WGC_NORMALIZED_SOURCE_ID'] = 0
            if blank_count >= 2:
                restore_fn = globals().get(
                    '_qqfarm_restore_hidden_miniapp_taskbar_card'
                )
                if callable(restore_fn):
                    try:
                        restore_fn('blank-surface')
                    except BaseException:
                        pass
                stop_fn = globals().get('_qqfarm_stop_wgc_capture')
                if callable(stop_fn):
                    stop_fn('blank-surface')
                # Preserve the latch until the replacement session produces a
                # rendered frame. Hidden/minimized windows therefore remain
                # blocked while a restored visible window may use validated
                # desktop/native pixels during the WGC warm-up.
                globals()['_QQFARM_WGC_BLANK_TS'] = now_value
                globals()['_QQFARM_WGC_BLANK_COUNT'] = 0
            try:
                log_fn = globals().get('_throttled_write')
                if callable(log_fn):
                    log_fn(
                        'v311-wgc-blank-surface',
                        'v311 WGC blank/unrendered game surface rejected',
                        10.0,
                    )
            except BaseException:
                pass
            return None
        globals()['_QQFARM_WGC_BLANK_TS'] = 0.0
        globals()['_QQFARM_WGC_BLANK_COUNT'] = 0
        source_id = int(id(frame))
        cached_frame = globals().get('_QQFARM_LAST_WGC_NORMALIZED_FRAME')
        cached_source_ts = float(globals().get(
            '_QQFARM_LAST_WGC_NORMALIZED_SOURCE_TS', 0.0
        ) or 0.0)
        cached_source_id = int(globals().get(
            '_QQFARM_LAST_WGC_NORMALIZED_SOURCE_ID', 0
        ) or 0)
        if (
            cached_frame is not None and
            cached_source_ts == timestamp and cached_source_id == source_id
        ):
            globals()['_QQFARM_LAST_WGC_NORMALIZED_TS'] = now_value
            remember_fn = globals().get('_qqfarm_remember_good_capture_frame')
            if callable(remember_fn):
                remember_fn(cached_frame)
            return cached_frame
        if width != 428 or height != 800:
            cv_module = globals().get('cv2') or __import__('cv2')
            image = cv_module.resize(
                image[:, :, :3], (428, 800),
                interpolation=cv_module.INTER_AREA,
            )
        normalized = np_module.ascontiguousarray(image[:, :, :3]).copy()
        globals()['_QQFARM_LAST_WGC_NORMALIZED_FRAME'] = normalized
        globals()['_QQFARM_LAST_WGC_NORMALIZED_TS'] = now_value
        globals()['_QQFARM_LAST_WGC_NORMALIZED_SOURCE_TS'] = timestamp
        globals()['_QQFARM_LAST_WGC_NORMALIZED_SOURCE_ID'] = source_id
        remember_fn = globals().get('_qqfarm_remember_good_capture_frame')
        if callable(remember_fn):
            remember_fn(normalized)
        return normalized
    except BaseException:
        return None



def _qqfarm_farm_window_is_visible():
    """Return true only while the current QQ Farm window is shown and restored."""
    try:
        find_fn = globals().get('_share_find_farm_window_hwnd')
        hwnd = int(find_fn() or 0) if callable(find_fn) else 0
        if hwnd <= 0:
            return False
        try:
            win32gui = __import__('win32gui')
            if not bool(win32gui.IsWindowVisible(hwnd)):
                return False
            if bool(win32gui.IsIconic(hwnd)):
                return False
            rect = win32gui.GetWindowRect(hwnd)
            return bool(
                rect and len(rect) >= 4 and
                int(rect[2] - rect[0]) >= 300 and
                int(rect[3] - rect[1]) >= 400
            )
        except BaseException:
            rect_fn = globals().get('_share_get_rect')
            rect = rect_fn(hwnd) if callable(rect_fn) else None
            return bool(
                rect and len(rect) >= 4 and
                int(rect[2] - rect[0]) >= 300 and
                int(rect[3] - rect[1]) >= 400
            )
    except BaseException:
        return False

def _qqfarm_native_capture_fallback_allowed(now=None):
    try:
        time_module = globals().get('time') or __import__('time')
        now_value = float(
            time_module.monotonic() if now is None else now
        )
        blank_ts = float(globals().get(
            '_QQFARM_WGC_BLANK_TS', 0.0
        ) or 0.0)
        if blank_ts > 0.0:
            visible_fn = globals().get('_qqfarm_farm_window_is_visible')
            if not callable(visible_fn) or not bool(visible_fn()):
                return False
        attempt_ts = float(globals().get(
            '_QQFARM_WGC_START_ATTEMPT_TS', 0.0
        ) or 0.0)
        started_ts = float(globals().get(
            '_QQFARM_WGC_STARTED_TS', 0.0
        ) or 0.0)
        occluded_ts = float(globals().get(
            '_QQFARM_VISIBLE_CAPTURE_OCCLUDED_TS', 0.0
        ) or 0.0)
        capture_active = globals().get('_QQFARM_WGC_CAPTURE') is not None
        if not capture_active and attempt_ts <= 0.0 and occluded_ts <= 0.0:
            return True
        warmup_base = max(attempt_ts, started_ts)
        if warmup_base > 0.0 and (now_value - warmup_base) < 2.0:
            return False
        try:
            os_module = __import__('os')
            interval = float(os_module.environ.get(
                'QQFARM_NATIVE_CAPTURE_FALLBACK_INTERVAL', '12.0'
            ) or 12.0)
        except BaseException:
            interval = 12.0
        interval = max(2.0, min(60.0, interval))
        last_native = float(globals().get(
            '_QQFARM_NATIVE_CAPTURE_LAST_TS', 0.0
        ) or 0.0)
        return bool(last_native <= 0.0 or (now_value - last_native) >= interval)
    except BaseException:
        return True


def _qqfarm_note_native_capture_fallback(now=None):
    globals()['_QQFARM_NATIVE_CAPTURE_LAST_TS'] = float(
        __import__('time').monotonic() if now is None else now
    )
    return True


def _qqfarm_visible_frame_has_farm_scene(frame):
    """Reject desktop/browser pixels when the QQ farm window is visibly occluded."""
    try:
        shape = getattr(frame, 'shape', None)
        if shape is None or len(shape) < 3:
            return False
        height, width = int(shape[0]), int(shape[1])
        if height < 120 or width < 120:
            return False
        cv_module = globals().get('cv2') or __import__('cv2')
        np_module = globals().get('np') or __import__('numpy')
        image = np_module.asarray(frame)[:, :, :3]
        if image.dtype != np_module.uint8:
            image = np_module.clip(image, 0, 255).astype(np_module.uint8)
        hsv = cv_module.cvtColor(image, cv_module.COLOR_BGR2HSV)
        top = max(0, min(height - 1, int(round(height * 0.07))))
        bottom = max(top + 1, min(height, int(round(height * 0.46))))
        upper = hsv[top:bottom]
        upper_bgr = image[top:bottom]
        if getattr(upper, 'size', 0) <= 0:
            return False
        sky = (
            (upper[:, :, 0] >= 85) & (upper[:, :, 0] <= 115) &
            (upper[:, :, 1] >= 70) & (upper[:, :, 2] >= 100)
        )
        bright = upper[:, :, 2] >= 120
        blue_dominant = (
            upper_bgr[:, :, 0].astype(np_module.int16) >=
            upper_bgr[:, :, 2].astype(np_module.int16) + 25
        )
        mean_value = float(np_module.mean(hsv[:, :, 2]))
        sky_ratio = float(np_module.mean(sky))
        bright_ratio = float(np_module.mean(bright))
        blue_ratio = float(np_module.mean(blue_dominant))
        lower = hsv[max(0, int(round(height * 0.45))):height]
        land = (
            (lower[:, :, 0] >= 5) & (lower[:, :, 0] <= 30) &
            (lower[:, :, 1] >= 50) & (lower[:, :, 2] >= 40)
        )
        land_ratio = float(np_module.mean(land)) if getattr(lower, 'size', 0) else 0.0
        return bool(
            mean_value >= 70.0 and
            sky_ratio >= 0.07 and
            bright_ratio >= 0.25 and
            blue_ratio >= 0.12 and
            land_ratio >= 0.12
        )
    except BaseException:
        return False


def _qqfarm_native_capture_frame_is_business_safe(frame):
    """Reject desktop/occluder pixels returned by a native fallback capture."""
    if frame is None:
        return False
    validator = globals().get('_qqfarm_visible_frame_has_farm_scene')
    try:
        valid = bool(not callable(validator) or validator(frame))
    except BaseException:
        valid = False
    if valid:
        return True
    globals()['_QQFARM_LAST_GOOD_CAPTURE_FRAME'] = None
    globals()['_QQFARM_LAST_GOOD_CAPTURE_TS'] = 0.0
    globals()['_QQFARM_VISIBLE_CAPTURE_OCCLUDED_TS'] = float(
        __import__('time').monotonic()
    )
    try:
        log_fn = globals().get('_throttled_write')
        if callable(log_fn):
            log_fn(
                'v458-native-nonfarm-rejected',
                'v458 native fallback returned desktop/non-farm pixels; '
                'cleared stale frame and blocked business recognition',
                4.0,
            )
    except BaseException:
        pass
    return False


def _qqfarm_install_visible_capture_priority(context):
    """Patch loaded QQ capture owners so visible pixels bypass slow PrintWindow first."""
    try:
        mode_fn = globals().get('_active_is_qq_mode')
        if not callable(mode_fn) or not bool(mode_fn()):
            return 0
    except BaseException:
        return 0
    owners = []
    seen = set()
    for owner_name in ('screen_capture', 'screen', 'capture', 'screenshotter'):
        try:
            owner = getattr(context, owner_name, None)
        except BaseException:
            owner = None
        if owner is None or id(owner) in seen:
            continue
        seen.add(id(owner))
        owners.append(owner)
    if context is not None and id(context) not in seen:
        owners.append(context)
    changed = 0
    for owner in owners:
        for method_name in ('get_window_frame', 'capture_window'):
            try:
                original = getattr(owner, method_name, None)
            except BaseException:
                original = None
            if not callable(original):
                continue
            if bool(getattr(original, '__qqfarm_visible_capture_priority__', False)):
                continue

            def _visible_first(*args, __original=original, **kwargs):
                qq_mode = False
                try:
                    active_fn = globals().get('_active_is_qq_mode')
                    qq_mode = bool(callable(active_fn) and bool(active_fn()))
                    if qq_mode and not bool(globals().get(
                            '_QQFARM_NATIVE_CAPTURE_GATE_ACTIVE', False)):
                        visible_fn = globals().get('_qqfarm_capture_visible_farm_frame')
                        visible = visible_fn() if callable(visible_fn) else None
                        trusted_fn = globals().get(
                            '_qqfarm_visible_capture_frame_is_trusted'
                        )
                        trusted = bool(
                            visible is not None and callable(trusted_fn) and
                            bool(trusted_fn(visible))
                        )
                        validator = globals().get(
                            '_qqfarm_visible_frame_has_farm_scene'
                        )
                        visible_valid = bool(
                            visible is not None and (
                                trusted or not callable(validator) or
                                bool(validator(visible))
                            )
                        )
                        if visible_valid:
                            return visible
                except BaseException:
                    pass
                if qq_mode and not bool(globals().get(
                        '_QQFARM_NATIVE_CAPTURE_GATE_ACTIVE', False)):
                    try:
                        gate_fn = globals().get(
                            '_qqfarm_native_capture_fallback_allowed'
                        )
                        if callable(gate_fn) and not bool(gate_fn()):
                            recent_fn = globals().get(
                                '_qqfarm_recent_good_capture_frame'
                            )
                            return recent_fn() if callable(recent_fn) else None
                        note_fn = globals().get(
                            '_qqfarm_note_native_capture_fallback'
                        )
                        if callable(note_fn):
                            note_fn()
                    except BaseException:
                        pass
                result = __original(*args, **kwargs)
                if result is not None and qq_mode:
                    safe_fn = globals().get(
                        '_qqfarm_native_capture_frame_is_business_safe'
                    )
                    if callable(safe_fn) and not bool(safe_fn(result)):
                        return None
                if result is not None:
                    try:
                        remember_fn = globals().get(
                            '_qqfarm_remember_good_capture_frame'
                        )
                        if callable(remember_fn):
                            remember_fn(result)
                    except BaseException:
                        pass
                return result

            try:
                _visible_first.__name__ = getattr(
                    original, '__name__', method_name
                )
                _visible_first.__qualname__ = getattr(
                    original, '__qualname__', _visible_first.__name__
                )
                _visible_first.__qqfarm_visible_capture_priority__ = True
                _visible_first.__qqfarm_visible_capture_priority_orig__ = original
                setattr(owner, method_name, _visible_first)
                changed += 1
            except BaseException:
                continue
    if changed:
        try:
            log_fn = globals().get('_throttled_write')
            message = (
                'v311 visible QQ capture priority installed owners=' +
                str(len(owners)) + ' methods=' + str(changed)
            )
            if callable(log_fn):
                log_fn('v311-visible-capture-installed', message, 30.0)
            else:
                writer = globals().get('_write')
                if callable(writer):
                    writer(message)
        except BaseException:
            pass
    return changed


def _get_frame_from_bot(bot):
    qq_mode = False
    try:
        mode_fn = globals().get('_active_is_qq_mode')
        qq_mode = bool(callable(mode_fn) and bool(mode_fn()))
        if qq_mode:
            visible_fn = globals().get('_qqfarm_capture_visible_farm_frame')
            visible_frame = visible_fn() if callable(visible_fn) else None
            trusted_fn = globals().get(
                '_qqfarm_visible_capture_frame_is_trusted'
            )
            trusted = bool(
                visible_frame is not None and callable(trusted_fn) and
                bool(trusted_fn(visible_frame))
            )
            validator = globals().get('_qqfarm_visible_frame_has_farm_scene')
            visible_valid = bool(
                visible_frame is not None and (
                    trusted or not callable(validator) or
                    bool(validator(visible_frame))
                )
            )
            if visible_valid:
                return visible_frame
    except BaseException:
        pass
    gate_reserved = False
    if qq_mode:
        try:
            gate_fn = globals().get('_qqfarm_native_capture_fallback_allowed')
            if callable(gate_fn) and not bool(gate_fn()):
                recent_fn = globals().get('_qqfarm_recent_good_capture_frame')
                return recent_fn() if callable(recent_fn) else None
            if callable(gate_fn):
                note_fn = globals().get('_qqfarm_note_native_capture_fallback')
                if callable(note_fn):
                    note_fn()
                globals()['_QQFARM_NATIVE_CAPTURE_GATE_ACTIVE'] = True
                gate_reserved = True
        except BaseException:
            pass
    try:
        native_attempted = False
        native_budget_exhausted = False
        seen_owners = set()
        for owner_name in ('screen_capture','screen','capture','screenshotter'):
            try:
                owner = getattr(bot, owner_name, None)
            except BaseException:
                owner = None
            if owner is None or id(owner) in seen_owners:
                continue
            seen_owners.add(id(owner))
            for meth in ('get_window_frame','capture_window','get_frame','capture','screenshot'):
                try:
                    fn = getattr(owner, meth, None)
                    if callable(fn):
                        if qq_mode and native_attempted:
                            native_budget_exhausted = True
                            break
                        native_attempted = True
                        fr = fn()
                        if fr is not None and qq_mode:
                            safe_fn = globals().get(
                                '_qqfarm_native_capture_frame_is_business_safe'
                            )
                            if callable(safe_fn) and not bool(safe_fn(fr)):
                                native_budget_exhausted = True
                                break
                        if fr is not None:
                            remember_fn = globals().get(
                                '_qqfarm_remember_good_capture_frame'
                            )
                            if callable(remember_fn):
                                remember_fn(fr)
                            return fr
                        if qq_mode:
                            native_budget_exhausted = True
                            break
                except BaseException:
                    if qq_mode and native_attempted:
                        native_budget_exhausted = True
                        break
            if native_budget_exhausted:
                break
        if not (qq_mode and native_attempted):
            for meth in ('get_window_frame','capture_window','get_frame'):
                try:
                    fn = getattr(bot, meth, None)
                    if callable(fn):
                        native_attempted = True
                        fr = fn()
                        if fr is not None and qq_mode:
                            safe_fn = globals().get(
                                '_qqfarm_native_capture_frame_is_business_safe'
                            )
                            if callable(safe_fn) and not bool(safe_fn(fr)):
                                break
                        if fr is not None:
                            remember_fn = globals().get(
                                '_qqfarm_remember_good_capture_frame'
                            )
                            if callable(remember_fn):
                                remember_fn(fr)
                            return fr
                        if qq_mode:
                            break
                except BaseException:
                    if qq_mode and native_attempted:
                        break
    except BaseException:
        pass
    finally:
        if gate_reserved:
            globals()['_QQFARM_NATIVE_CAPTURE_GATE_ACTIVE'] = False
    if qq_mode:
        try:
            recent_fn = globals().get('_qqfarm_recent_good_capture_frame')
            return recent_fn() if callable(recent_fn) else None
        except BaseException:
            pass
    return None


def _qqfarm_friend_route_expected(context):
    """Return whether current runtime state expects a friend/list surface."""
    if context is None:
        return False
    for name in (
        '_qqfarm_friend_entry_pending',
        '_qqfarm_friend_chain_pending',
        '_qqfarm_friend_chain_active',
        '_qqfarm_friend_cycle_seen',
        '_last_friend_farm_go_home_present',
    ):
        try:
            if bool(getattr(context, name, False)):
                return True
        except BaseException:
            pass
    try:
        if str(getattr(
            context, '_qqfarm_cycle_branch_hint', ''
        ) or '').strip().lower() == 'friend':
            return True
    except BaseException:
        pass
    try:
        if float(getattr(
            context, '_qqfarm_friend_entry_clicked_ts', 0.0
        ) or 0.0) > 0.0:
            return True
    except BaseException:
        pass
    try:
        if float(getattr(
            context, '_qqfarm_friend_page_seen_ts', 0.0
        ) or 0.0) > 0.0:
            return True
    except BaseException:
        pass
    return False


def _qqfarm_get_physical_window_rect(hwnd, fallback_rect=None):
    """Return physical desktop bounds for visible QQ capture when DWM exposes them.

    ``GetWindowRect`` is virtualized for the packaged Python process at 150% DPI,
    while Pillow's ``ImageGrab`` uses physical desktop pixels.  DWM extended
    frame bounds bridge those coordinate spaces; a validated caller-provided
    logical rectangle remains the compatibility fallback for DWM-unavailable
    environments.
    """
    def _valid_rect(value):
        try:
            if value is None or len(value) < 4:
                return None
            left, top, right, bottom = [int(item) for item in value[:4]]
            if right <= left or bottom <= top:
                return None
            if (right - left) < 120 or (bottom - top) < 120:
                return None
            return (left, top, right, bottom)
        except BaseException:
            return None

    fallback = _valid_rect(fallback_rect)
    try:
        window = int(hwnd or 0)
    except BaseException:
        window = 0
    if not window:
        return fallback
    try:
        import ctypes
        from ctypes import wintypes

        class RECT(ctypes.Structure):
            _fields_ = [
                ('left', ctypes.c_long), ('top', ctypes.c_long),
                ('right', ctypes.c_long), ('bottom', ctypes.c_long),
            ]

        # DWMWA_EXTENDED_FRAME_BOUNDS is documented in physical screen pixels,
        # unlike the DPI-virtualized GetWindowRect seen by ImageGrab callers.
        bounds = RECT()
        result = ctypes.windll.dwmapi.DwmGetWindowAttribute(
            wintypes.HWND(window), wintypes.DWORD(9), ctypes.byref(bounds),
            ctypes.sizeof(bounds),
        )
        if int(result) == 0:
            physical = _valid_rect((
                bounds.left, bounds.top, bounds.right, bounds.bottom,
            ))
            if physical is not None:
                return physical
    except BaseException:
        pass
    return fallback


def _qqfarm_capture_printwindow_farm_frame(hwnd, expected_rect=None):
    """Return one raw physical BGR QQ frame without desktop-compositor pixels.

    Strict self-frame arbitration calls this only for a current desktop retry.
    Its physical dimensions are intentionally preserved: the 24-slot observer
    then treats any full-board confirmation as observation-only rather than
    exposing normalized-frame click coordinates.
    """
    window_dc = None
    memory_dc = None
    bitmap = None
    previous_bitmap = None
    try:
        import ctypes
        from ctypes import wintypes

        np_module = globals().get('np') or __import__('numpy')
        window = int(hwnd or 0)
        if window <= 0:
            return None
        try:
            left, top, right, bottom = [
                int(value) for value in tuple(expected_rect or ())[:4]
            ]
        except BaseException:
            return None
        width = int(right - left)
        height = int(bottom - top)
        if width < 120 or height < 120 or width > 4096 or height > 4096:
            return None
        byte_count = int(width * height * 4)
        if byte_count <= 0 or byte_count > (96 * 1024 * 1024):
            return None

        class BITMAPINFOHEADER(ctypes.Structure):
            _fields_ = [
                ('biSize', wintypes.DWORD),
                ('biWidth', ctypes.c_long),
                ('biHeight', ctypes.c_long),
                ('biPlanes', wintypes.WORD),
                ('biBitCount', wintypes.WORD),
                ('biCompression', wintypes.DWORD),
                ('biSizeImage', wintypes.DWORD),
                ('biXPelsPerMeter', ctypes.c_long),
                ('biYPelsPerMeter', ctypes.c_long),
                ('biClrUsed', wintypes.DWORD),
                ('biClrImportant', wintypes.DWORD),
            ]

        class RGBQUAD(ctypes.Structure):
            _fields_ = [
                ('rgbBlue', ctypes.c_ubyte),
                ('rgbGreen', ctypes.c_ubyte),
                ('rgbRed', ctypes.c_ubyte),
                ('rgbReserved', ctypes.c_ubyte),
            ]

        class BITMAPINFO(ctypes.Structure):
            _fields_ = [
                ('bmiHeader', BITMAPINFOHEADER),
                ('bmiColors', RGBQUAD * 1),
            ]

        user32 = ctypes.windll.user32
        gdi32 = ctypes.windll.gdi32
        user32.GetWindowDC.argtypes = [wintypes.HWND]
        user32.GetWindowDC.restype = wintypes.HDC
        user32.ReleaseDC.argtypes = [wintypes.HWND, wintypes.HDC]
        user32.ReleaseDC.restype = ctypes.c_int
        user32.PrintWindow.argtypes = [wintypes.HWND, wintypes.HDC, wintypes.UINT]
        user32.PrintWindow.restype = wintypes.BOOL
        gdi32.CreateCompatibleDC.argtypes = [wintypes.HDC]
        gdi32.CreateCompatibleDC.restype = wintypes.HDC
        gdi32.CreateCompatibleBitmap.argtypes = [
            wintypes.HDC, ctypes.c_int, ctypes.c_int,
        ]
        gdi32.CreateCompatibleBitmap.restype = wintypes.HBITMAP
        gdi32.SelectObject.argtypes = [wintypes.HDC, wintypes.HGDIOBJ]
        gdi32.SelectObject.restype = wintypes.HGDIOBJ
        gdi32.DeleteObject.argtypes = [wintypes.HGDIOBJ]
        gdi32.DeleteObject.restype = wintypes.BOOL
        gdi32.DeleteDC.argtypes = [wintypes.HDC]
        gdi32.DeleteDC.restype = wintypes.BOOL
        gdi32.GetDIBits.argtypes = [
            wintypes.HDC, wintypes.HBITMAP, wintypes.UINT, wintypes.UINT,
            ctypes.c_void_p, ctypes.POINTER(BITMAPINFO), wintypes.UINT,
        ]
        gdi32.GetDIBits.restype = ctypes.c_int

        window_dc = user32.GetWindowDC(wintypes.HWND(window))
        if not window_dc:
            return None
        memory_dc = gdi32.CreateCompatibleDC(window_dc)
        if not memory_dc:
            return None
        bitmap = gdi32.CreateCompatibleBitmap(window_dc, width, height)
        if not bitmap:
            return None
        previous_bitmap = gdi32.SelectObject(memory_dc, bitmap)
        if not previous_bitmap:
            return None
        # PW_RENDERFULLCONTENT preserves the app window surface even when another
        # desktop window crosses it; no input is generated by this capture.
        if not bool(user32.PrintWindow(
                wintypes.HWND(window), memory_dc, wintypes.UINT(0x00000002))):
            return None
        bitmap_info = BITMAPINFO()
        bitmap_info.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        bitmap_info.bmiHeader.biWidth = int(width)
        bitmap_info.bmiHeader.biHeight = -int(height)
        bitmap_info.bmiHeader.biPlanes = 1
        bitmap_info.bmiHeader.biBitCount = 32
        bitmap_info.bmiHeader.biCompression = 0
        raw = (ctypes.c_ubyte * byte_count)()
        copied_rows = int(gdi32.GetDIBits(
            memory_dc, bitmap, 0, int(height), ctypes.byref(raw),
            ctypes.byref(bitmap_info), 0,
        ) or 0)
        if copied_rows != int(height):
            return None
        bgra = np_module.ctypeslib.as_array(raw).reshape(height, width, 4)
        return np_module.ascontiguousarray(bgra[:, :, :3]).copy()
    except BaseException:
        return None
    finally:
        try:
            if memory_dc and previous_bitmap:
                gdi32.SelectObject(memory_dc, previous_bitmap)
        except BaseException:
            pass
        try:
            if bitmap:
                gdi32.DeleteObject(bitmap)
        except BaseException:
            pass
        try:
            if memory_dc:
                gdi32.DeleteDC(memory_dc)
        except BaseException:
            pass
        try:
            if window_dc:
                user32.ReleaseDC(wintypes.HWND(int(hwnd or 0)), window_dc)
        except BaseException:
            pass

def _qqfarm_capture_visible_farm_frame(prefer_desktop=False, allow_overlay=False):
    """Capture QQ farm pixels; strict retries may bypass a stale WGC frame."""
    try:
        # Provenance is per returned frame: size alone never labels an arbitrary
        # portrait image as raw PrintWindow input.
        globals()['_QQFARM_LAST_PHYSICAL_PRINTWINDOW_FRAME_ID'] = 0
        if not bool(prefer_desktop):
            wgc_fn = globals().get('_qqfarm_capture_wgc_farm_frame')
            wgc_frame = wgc_fn() if callable(wgc_fn) else None
            if wgc_frame is not None:
                return wgc_frame
        blank_ts = float(globals().get('_QQFARM_WGC_BLANK_TS', 0.0) or 0.0)
        if blank_ts > 0.0 and not bool(prefer_desktop):
            visible_fn = globals().get('_qqfarm_farm_window_is_visible')
            if not callable(visible_fn) or not bool(visible_fn()):
                return None
        find_fn = globals().get('_share_find_farm_window_hwnd')
        rect_fn = globals().get('_share_get_rect')
        physical_rect_fn = globals().get('_qqfarm_get_physical_window_rect')
        hwnd = int(find_fn() or 0) if callable(find_fn) else 0
        fallback_rect = rect_fn(hwnd) if hwnd and callable(rect_fn) else None
        try:
            rect = (
                physical_rect_fn(hwnd, fallback_rect)
                if hwnd and callable(physical_rect_fn) else fallback_rect
            )
        except BaseException:
            rect = fallback_rect
        if not rect:
            rect = fallback_rect
        if not rect or len(rect) < 4:
            return None
        left, top, right, bottom = [int(value) for value in rect[:4]]
        if right <= left or bottom <= top:
            return None
        # The strict current-frame retry must observe QQ's own rendered surface,
        # not a desktop-composited copy.  Preserve raw physical dimensions so a
        # v413 full-board result remains observation-only with no click centers.
        if bool(prefer_desktop) and hwnd:
            printwindow_fn = globals().get('_qqfarm_capture_printwindow_farm_frame')
            printwindow_frame = None
            try:
                printwindow_frame = (
                    printwindow_fn(hwnd, rect) if callable(printwindow_fn) else None
                )
            except BaseException:
                printwindow_frame = None
            try:
                printwindow_shape = getattr(printwindow_frame, 'shape', ())
                printwindow_valid_shape = bool(
                    len(printwindow_shape) >= 3 and
                    int(printwindow_shape[0]) >= 120 and
                    int(printwindow_shape[1]) >= 120 and
                    int(printwindow_shape[2]) >= 3
                )
            except BaseException:
                printwindow_valid_shape = False
            if printwindow_valid_shape:
                validator = globals().get('_qqfarm_visible_frame_has_farm_scene')
                valid_printwindow = bool(
                    bool(allow_overlay) or not callable(validator) or
                    bool(validator(printwindow_frame))
                )
                if valid_printwindow:
                    try:
                        log_fn = globals().get('_throttled_write')
                        if callable(log_fn):
                            log_fn(
                                'v414-strict-printwindow-frame',
                                'v414 strict physical retry used raw PrintWindow frame; '
                                'full-board ledger remains observation-only',
                                2.0,
                            )
                    except BaseException:
                        pass
                    try:
                        globals()['_QQFARM_LAST_PHYSICAL_PRINTWINDOW_FRAME_ID'] = (
                            int(id(printwindow_frame))
                        )
                    except BaseException:
                        pass
                    return printwindow_frame
        image_grab = __import__('PIL.ImageGrab', fromlist=['ImageGrab'])
        image = image_grab.grab(
            bbox=(left, top, right, bottom), all_screens=True
        ).convert('RGB')
        np_module = globals().get('np') or __import__('numpy')
        cv2_module = globals().get('cv2') or __import__('cv2')
        rgb = np_module.asarray(image)
        if len(getattr(rgb, 'shape', ())) < 3 or int(rgb.shape[2]) < 3:
            return None
        frame = cv2_module.cvtColor(rgb[:, :, :3], cv2_module.COLOR_RGB2BGR)
        height, width = int(frame.shape[0]), int(frame.shape[1])
        if width != 428 or height != 800:
            frame = cv2_module.resize(
                frame, (428, 800), interpolation=cv2_module.INTER_AREA
            )
        validator = globals().get('_qqfarm_visible_frame_has_farm_scene')
        friend_list_route_frame = False
        if (
            not bool(allow_overlay) and callable(validator) and
            not bool(validator(frame))
        ):
            # The in-game friend list is a valid route surface even though it
            # intentionally hides the ordinary farm canvas.  Admit it only
            # with several visible green "visit" controls; generic overlays
            # such as the task page remain occluded.
            rows_fn = globals().get('_friend_list_visit_button_rows')
            try:
                route_rows = rows_fn(frame) if callable(rows_fn) else []
                friend_list_route_frame = bool(len(list(route_rows or [])) >= 3)
            except BaseException:
                friend_list_route_frame = False
            if not friend_list_route_frame:
                globals()['_QQFARM_VISIBLE_CAPTURE_OCCLUDED_TS'] = float(
                    __import__('time').monotonic()
                )
                try:
                    log_fn = globals().get('_throttled_write')
                    if callable(log_fn):
                        log_fn(
                            'v311-visible-farm-occluded',
                            'v311 visible QQ rectangle contains non-farm/occluding pixels; '
                            'using native capture fallback',
                            10.0,
                        )
                except BaseException:
                    pass
                return None
        if friend_list_route_frame:
            try:
                log_fn = globals().get('_throttled_write')
                if callable(log_fn):
                    log_fn(
                        'v422-visible-friend-list-route',
                        'v422 visible QQ friend list accepted for ordered visit routing',
                        4.0,
                    )
            except BaseException:
                pass
        remember_fn = globals().get('_qqfarm_remember_good_capture_frame')
        if callable(remember_fn):
            remember_fn(frame)
        return frame
    except BaseException as error:
        try:
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                log_fn(
                    'v283-visible-farm-capture-error',
                    'v283 visible farm capture error=' + repr(error)[:220],
                    10.0,
                )
        except BaseException:
            pass
        return None


def _qqfarm_resolve_friend_route_frame(context, frame):
    """Replace a stale bot frame with visible QQ pixels while friend work is pending."""
    state_fn = globals().get('_friend_guard_friend_ui_state')
    try:
        state = state_fn(frame) if callable(state_fn) and frame is not None else None
    except BaseException:
        state = None
    try:
        force_visible = bool(
            context is not None
            and (
                bool(getattr(
                    context, '_qqfarm_friend_list_resume_pending', False
                ))
                or bool(getattr(
                    context, '_qqfarm_friend_entry_pending', False
                ))
                or bool(getattr(
                    context, '_qqfarm_friend_guard_empty_latched', False
                ))
            )
        )
    except BaseException:
        force_visible = False
    # A bot-owned frame may still show the previous friend after a home click,
    # after selecting another list row, or after the completed patrol has been
    # latched.  In those states, visible QQ pixels are authoritative even when
    # the stale frame itself looks like a perfectly valid friend page.
    if state is True and not force_visible:
        return frame, state
    expected_fn = globals().get('_qqfarm_friend_route_expected')
    try:
        expected = bool(
            expected_fn(context) if callable(expected_fn) else False
        )
    except BaseException:
        expected = False
    expected = bool(expected or force_visible)
    if not expected:
        mode_fn = globals().get('_active_is_qq_mode')
        try:
            if not callable(mode_fn) or not bool(mode_fn()):
                return frame, state
        except BaseException:
            return frame, state
    capture_fn = globals().get('_qqfarm_capture_visible_farm_frame')
    try:
        visible_frame = capture_fn() if callable(capture_fn) else None
    except BaseException:
        visible_frame = None
    if visible_frame is None:
        return frame, state
    try:
        visible_state = (
            state_fn(visible_frame) if callable(state_fn) else None
        )
    except BaseException:
        visible_state = None
    if visible_state is True:
        try:
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                log_fn(
                    'v283-visible-friend-frame-recovery',
                    'v283 visible QQ frame recovered pending friend routing from stale bot frame',
                    4.0,
                )
        except BaseException:
            pass
        return visible_frame, True
    if force_visible:
        try:
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                log_fn(
                    'v301-visible-transition-frame-authoritative',
                    'v301 visible QQ frame replaced stale friend pixels during '
                    'list-entry/resume/empty-latch transition state=' +
                    repr(visible_state),
                    2.0,
                )
        except BaseException:
            pass
        return visible_frame, visible_state
    return frame, state


def _call_func_best_effort(fn, candidates):
    last = None
    for args in candidates:
        try:
            return True, fn(*args)
        except TypeError as e:
            last = e
            continue
        except BaseException as e:
            return False, e
    return False, last



def _warehouse_done_ts():
    global _VIP_WAREHOUSE_LAST_DONE_TS
    try:
        if _VIP_WAREHOUSE_LAST_DONE_TS > 0:
            return _VIP_WAREHOUSE_LAST_DONE_TS
        try:
            txt = open(_VIP_WAREHOUSE_STATE_PATH, 'r').read().strip()
            if txt:
                _VIP_WAREHOUSE_LAST_DONE_TS = float(txt)
        except BaseException:
            pass
        return _VIP_WAREHOUSE_LAST_DONE_TS
    except BaseException:
        return 0.0


def _warehouse_cooldown_seconds():
    try:
        iid = _active_instance_id()
        sec = ['instance.' + str(iid) + '.self', 'self']
        v = _cfg_get(sec, 'auto_sell_fruit_interval_hours', '0.10')
        seconds = float(str(v).strip()) * 3600.0
        if seconds < _VIP_WAREHOUSE_MIN_COOLDOWN_SECONDS:
            seconds = _VIP_WAREHOUSE_MIN_COOLDOWN_SECONDS
        return seconds
    except BaseException:
        return _VIP_WAREHOUSE_MIN_COOLDOWN_SECONDS


def _warehouse_recently_done():
    try:
        ts = _warehouse_done_ts()
        if ts <= 0:
            return False
        return (time.time() - ts) < _warehouse_cooldown_seconds()
    except BaseException:
        return False


def _warehouse_mark_done(reason=''):
    global _VIP_WAREHOUSE_LAST_DONE_TS
    try:
        _VIP_WAREHOUSE_LAST_DONE_TS = time.time()
        try:
            open(_VIP_WAREHOUSE_STATE_PATH, 'w').write(str(_VIP_WAREHOUSE_LAST_DONE_TS))
        except BaseException:
            pass
        _write('v28 warehouse cooldown mark reason=' + str(reason) + ' seconds=' + str(int(_warehouse_cooldown_seconds())))
    except BaseException:
        pass


def _qqfarm_post_escape_to_farm():
    """Post one Escape key to the visible QQ farm client without moving the mouse."""
    try:
        win32gui = __import__('win32gui')
        candidates = []

        def _cb(hwnd, extra):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return True
                if str(win32gui.GetWindowText(hwnd) or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = win32gui.GetClientRect(hwnd)
                width = int(rect[2] - rect[0])
                height = int(rect[3] - rect[1])
                if width >= 300 and height >= 500:
                    candidates.append((-width * height, int(hwnd), width, height))
            except BaseException:
                pass
            return True

        win32gui.EnumWindows(_cb, None)
        if candidates:
            candidates.sort()
            _, root_hwnd, width, height = candidates[0]
            point = win32gui.ClientToScreen(root_hwnd, (width // 2, height // 2))
            target_hwnd = int(win32gui.WindowFromPoint(point) or root_hwnd)
            if target_hwnd != root_hwnd and not win32gui.IsChild(root_hwnd, target_hwnd):
                target_hwnd = root_hwnd
            win32gui.PostMessage(target_hwnd, 0x0100, 0x1B, 0)
            win32gui.PostMessage(target_hwnd, 0x0101, 0x1B, 0xC0000001)
            return True
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        candidates = []
        enum_proc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        class RECT(ctypes.Structure):
            _fields_ = [
                ('left', ctypes.c_long), ('top', ctypes.c_long),
                ('right', ctypes.c_long), ('bottom', ctypes.c_long),
            ]

        def _cb(hwnd, lparam):
            try:
                if not user32.IsWindowVisible(hwnd):
                    return True
                title = ctypes.create_unicode_buffer(256)
                user32.GetWindowTextW(hwnd, title, 255)
                if str(title.value or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = RECT()
                if user32.GetClientRect(hwnd, ctypes.byref(rect)):
                    width = int(rect.right - rect.left)
                    height = int(rect.bottom - rect.top)
                    if width >= 300 and height >= 500:
                        candidates.append((-width * height, int(hwnd)))
            except BaseException:
                pass
            return True

        user32.EnumWindows(enum_proc(_cb), 0)
        if candidates:
            candidates.sort()
            hwnd = int(candidates[0][1])
            down_ok = user32.PostMessageW(ctypes.c_void_p(hwnd), 0x0100, 0x1B, 0)
            up_ok = user32.PostMessageW(
                ctypes.c_void_p(hwnd), 0x0101, 0x1B, 0xC0000001
            )
            return bool(down_ok and up_ok)
    except BaseException:
        pass
    return False


def _qqfarm_resolve_warehouse_close_after_failure(
    bot, *, source_globals=None, name=''
):
    """Bound warehouse cleanup to one native close and one Escape fallback."""
    if bot is None:
        return False
    try:
        source = source_globals if isinstance(source_globals, dict) else {}
        capture_fn = source.get('_capture_frame')
        if not callable(capture_fn):
            try:
                capture_fn = getattr(bot, '_capture_frame', None)
            except BaseException:
                capture_fn = None
        if not callable(capture_fn):
            capture_fn = globals().get('_get_frame_from_bot')
        close_fn = source.get('_close_current_panel')
        if not callable(close_fn):
            try:
                close_fn = getattr(bot, '_close_current_panel', None)
            except BaseException:
                close_fn = None
        detector_fn = source.get('check_close_x_icon')
        if not callable(detector_fn):
            try:
                detector_fn = getattr(bot, 'check_close_x_icon', None)
            except BaseException:
                detector_fn = None
        escape_fn = globals().get('_qqfarm_post_escape_to_farm')
        time_module = globals().get('time') or __import__('time')
        if not callable(capture_fn):
            return False

        def _call_capture():
            for invoke in (
                lambda: capture_fn(bot),
                lambda: capture_fn(),
            ):
                try:
                    frame = invoke()
                    if frame is not None:
                        return frame
                except TypeError:
                    continue
                except BaseException:
                    return None
            return None

        def _close_visible(frame):
            if frame is None or not callable(detector_fn):
                return None
            for invoke in (
                lambda: detector_fn(frame),
                lambda: detector_fn(bot, frame),
                lambda: detector_fn(bot),
            ):
                try:
                    return bool(invoke())
                except TypeError:
                    continue
                except BaseException:
                    return None
            return None

        def _frames_changed(before, after):
            if before is None or after is None:
                return False
            if before is after:
                return False
            try:
                np = __import__('numpy')
                a = np.asarray(before)
                b = np.asarray(after)
                if getattr(a, 'shape', None) == getattr(b, 'shape', None) and getattr(a, 'size', 0) > 0:
                    step_y = max(1, int(a.shape[0]) // 80)
                    step_x = max(1, int(a.shape[1]) // 50)
                    sample_a = a[::step_y, ::step_x, :3].astype(np.float32)
                    sample_b = b[::step_y, ::step_x, :3].astype(np.float32)
                    return float(np.mean(np.abs(sample_a - sample_b))) >= 2.0
            except BaseException:
                pass
            try:
                return before != after
            except BaseException:
                return False

        before_frame = _call_capture()
        before_visible = _close_visible(before_frame)
        if before_visible is False:
            return True
        native_close_sent = False
        if callable(close_fn):
            for invoke in (
                lambda: close_fn(bot),
                lambda: close_fn(),
            ):
                try:
                    native_close_sent = bool(invoke())
                    break
                except TypeError:
                    continue
                except BaseException:
                    break
        try:
            time_module.sleep(0.18)
        except BaseException:
            pass
        after_native = _call_capture()
        after_native_visible = _close_visible(after_native)
        if after_native_visible is False or (
            native_close_sent and after_native_visible is not True and
            _frames_changed(before_frame, after_native)
        ):
            try:
                _write(
                    'v343 warehouse panel closed by native helper name=' + str(name)
                )
            except BaseException:
                pass
            return True

        escape_sent = False
        if callable(escape_fn):
            try:
                escape_sent = bool(escape_fn())
            except BaseException:
                escape_sent = False
        try:
            time_module.sleep(0.18)
        except BaseException:
            pass
        after_escape = _call_capture()
        after_escape_visible = _close_visible(after_escape)
        recovered = bool(
            after_escape_visible is False or (
                escape_sent and after_escape_visible is not True and
                _frames_changed(after_native or before_frame, after_escape)
            )
        )
        try:
            _write(
                'v343 warehouse close recovery native=' + repr(native_close_sent) +
                ' escape=' + repr(escape_sent) + ' recovered=' + repr(recovered) +
                ' name=' + str(name)
            )
        except BaseException:
            pass
        return recovered
    except BaseException:
        return False

def _warehouse_classify_result(res):
    try:
        if res is True:
            return 'completed'
        status = res[0] if isinstance(res, (tuple, list)) and len(res) > 0 else res
        text = str(status).lower()
        if 'completed' in text:
            return 'completed'
        if any(token in text for token in ('warehouse_empty', 'nothing_to_sell', 'no_sellable', 'no_items', 'empty_warehouse')):
            return 'empty'
    except BaseException:
        pass
    return 'failed'


def _warehouse_zero_retry_state():
    return {'fail_count': 0, 'last_fail_ts': 0.0, 'blocked_until': 0.0, 'last_reason': ''}


def _warehouse_prepare_retry_memory_path():
    global _VIP_WAREHOUSE_RETRY_MEMORY_STATE, _VIP_WAREHOUSE_RETRY_MEMORY_PATH, _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY
    current_path = str(_VIP_WAREHOUSE_RETRY_STATE_PATH)
    if _VIP_WAREHOUSE_RETRY_MEMORY_PATH != current_path:
        _VIP_WAREHOUSE_RETRY_MEMORY_STATE = _warehouse_zero_retry_state()
        _VIP_WAREHOUSE_RETRY_MEMORY_PATH = current_path
        _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY = False
    return current_path


def _warehouse_sanitize_retry_state(loaded):
    state = _warehouse_zero_retry_state()
    if not isinstance(loaded, dict):
        return state
    math = __import__('math')
    try:
        value = loaded.get('fail_count', 0)
        if isinstance(value, bool):
            raise ValueError('bool is not a retry count')
        count = int(value)
        if (isinstance(value, float) and not value.is_integer()) or count < 0 or count >= _VIP_WAREHOUSE_RETRY_LIMIT:
            raise ValueError('retry count out of range')
        state['fail_count'] = count
    except BaseException:
        pass
    for key in ('last_fail_ts', 'blocked_until'):
        try:
            value = float(loaded.get(key, 0.0))
            if math.isfinite(value) and value >= 0.0:
                state[key] = value
        except BaseException:
            pass
    try:
        state['last_reason'] = str(loaded.get('last_reason', ''))[:160]
    except BaseException:
        pass
    return state


def _warehouse_load_retry_state():
    global _VIP_WAREHOUSE_RETRY_MEMORY_STATE
    _warehouse_prepare_retry_memory_path()
    fallback = _warehouse_sanitize_retry_state(_VIP_WAREHOUSE_RETRY_MEMORY_STATE)
    _VIP_WAREHOUSE_RETRY_MEMORY_STATE = dict(fallback)
    if _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY:
        return dict(fallback)
    try:
        raw = open(_VIP_WAREHOUSE_RETRY_STATE_PATH, 'r').read()
        loaded = __import__('json').loads(raw)
        if not isinstance(loaded, dict):
            return dict(fallback)
        state = _warehouse_sanitize_retry_state(loaded)
        _VIP_WAREHOUSE_RETRY_MEMORY_STATE = dict(state)
        return state
    except BaseException:
        return dict(fallback)


def _warehouse_write_retry_state(state, action='update'):
    global _VIP_WAREHOUSE_RETRY_MEMORY_STATE, _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY
    final_path = _warehouse_prepare_retry_memory_path()
    sanitized = _warehouse_sanitize_retry_state(state)
    _VIP_WAREHOUSE_RETRY_MEMORY_STATE = dict(sanitized)
    temp_path = final_path + '.tmp-' + __import__('uuid').uuid4().hex
    persisted = False
    write_error = None
    try:
        handle = open(temp_path, 'w', encoding='utf-8')
        try:
            handle.write(__import__('json').dumps(sanitized, sort_keys=True))
            handle.flush()
        finally:
            handle.close()
        os.replace(temp_path, final_path)
        persisted = True
        _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY = False
    except BaseException as e:
        write_error = e
        _VIP_WAREHOUSE_RETRY_MEMORY_DIRTY = True
    finally:
        try:
            os.remove(temp_path)
        except BaseException:
            pass
    try:
        status = 'persisted' if persisted else 'memory fallback'
        message = 'v35 warehouse retry ' + str(action) + ' ' + status + ' fail_count=' + str(sanitized['fail_count']) + ' blocked_until=' + str(int(sanitized['blocked_until']))
        if write_error is not None:
            message += ' error=' + repr(write_error)
        _throttled_write('warehouse-retry-persistence-' + ('ok-' if persisted else 'failure-') + str(action), message, 30.0)
    except BaseException:
        pass
    return sanitized


def _warehouse_retry_blocked(now=None):
    try:
        if now is None:
            now = time.time()
        return _warehouse_load_retry_state()['blocked_until'] > float(now)
    except BaseException:
        return False


def _warehouse_mark_failed(reason='', now=None):
    try:
        if now is None:
            now = time.time()
        now = float(now)
        state = _warehouse_load_retry_state()
        count = state['fail_count']
        count += 1
        state['last_fail_ts'] = now
        state['last_reason'] = str(reason)[:160]
        if count >= _VIP_WAREHOUSE_RETRY_LIMIT:
            state['fail_count'] = 0
            state['blocked_until'] = now + _VIP_WAREHOUSE_BACKOFF_SECONDS
        else:
            state['fail_count'] = count
            state['blocked_until'] = now + _VIP_WAREHOUSE_RETRY_SECONDS
        return _warehouse_write_retry_state(state, 'failed')
    except BaseException:
        return _warehouse_zero_retry_state()


def _warehouse_reset_retry_state():
    return _warehouse_write_retry_state(_warehouse_zero_retry_state(), 'reset')


def _force_warehouse_after_self(args, kwargs):
    # v27: disabled.  The original app already calls _handle_home_auto_sell_fruit
    # from its own self-farm flow.  Forcing it after every self patrol caused
    # endless warehouse open/close loops after fruits were already sold.
    return False


def _business_bot_from_args(args, kwargs):
    try:
        direct = (kwargs or {}).get('bot')
        if direct is not None and not isinstance(direct, (str, bytes, int, float, bool, list, tuple, dict, set)):
            return direct
    except BaseException:
        pass
    state_names = (
        'auto_fertilize_one', 'planting_auto_fertilize_one',
        'auto_fertilize_more', 'planting_auto_fertilize_more',
        'auto_fill_fertilizer_container', 'enable_daily_radish_exp',
        'daily_radish_exp', '_qqfarm_planting_crop_context',
        '_qqfarm_radish_mode_context',
    )
    try:
        values = list(args or ()) + list((kwargs or {}).values())
    except BaseException:
        values = []
    for value in values:
        try:
            if value is None or isinstance(value, (str, bytes, int, float, bool, list, tuple, dict, set)):
                continue
            if any(hasattr(value, attr) for attr in state_names):
                return value
        except BaseException:
            pass
    return None


def _crop_name_from_bound_call(fn, args, kwargs):
    try:
        import inspect
        bound = inspect.signature(fn).bind_partial(*(args or ()), **(kwargs or {}))
        items = list(bound.arguments.items())
    except BaseException:
        try:
            items = list((kwargs or {}).items()) + [('', value) for value in (args or ())]
        except BaseException:
            items = []
    preferred = ('crop_name', 'crop', 'seed_name', 'plant_name')
    for wanted in preferred:
        for param_name, value in items:
            try:
                if str(param_name).lower() == wanted and isinstance(value, str) and value.strip():
                    return value.strip()
            except BaseException:
                pass
    for param_name, value in items:
        try:
            low = str(param_name).lower()
            if any(token in low for token in ('crop', 'seed', 'plant')):
                if isinstance(value, str) and value.strip():
                    return value.strip()
        except BaseException:
            pass
    for _, value in items:
        try:
            if isinstance(value, str) and value.strip() == '\u767d\u841d\u535c':
                return '\u767d\u841d\u535c'
        except BaseException:
            pass
    return ''


def _daily_radish_state(module, bot):
    try:
        checker = getattr(module, '_is_daily_radish_exp_active', None)
        if callable(checker):
            return 'active' if bool(checker(bot)) else 'inactive'
    except BaseException:
        pass
    # Some protected runtime builds do not export the native predicate even
    # though the public planting setting is present.  Treat the persisted UI
    # setting as the authority in that case instead of silently disabling the
    # complete radish-exp branch as ``unknown``.
    try:
        configured_fn = globals().get('_configured_bool')
        sections_fn = globals().get('_active_planting_sections')
        sections = sections_fn() if callable(sections_fn) else ('planting',)
        if callable(configured_fn):
            enabled = bool(configured_fn(
                sections, 'enable_daily_radish_exp', False
            ))
            return 'active' if enabled else 'inactive'
    except BaseException:
        pass
    return 'unknown'


def _daily_radish_active(module, bot):
    return _daily_radish_state(module, bot) == 'active'


def _wrap_planting_crop_context_func(fn, module, name=''):
    try:
        if not callable(fn):
            return fn, False
        if getattr(fn, '__qqfarm_planting_crop_context_wrapped__', False):
            return fn, False
        def _wrapped(*a, **k):
            bot = None
            try:
                import inspect
                bound = inspect.signature(fn).bind_partial(*a, **k)
                if 'bot' in bound.arguments:
                    bot = _business_bot_from_args((), {'bot': bound.arguments.get('bot')})
            except BaseException:
                pass
            if bot is None:
                bot = _business_bot_from_args(a, k)
            if bot is None:
                return fn(*a, **k)
            crop_name = _crop_name_from_bound_call(fn, a, k)
            try:
                backpack_profile_active = bool(getattr(
                    bot, '_qqfarm_backpack_profile_active', False
                ))
            except BaseException:
                backpack_profile_active = False
            fertilizer_name = str(crop_name or '').strip().lower()
            fertilizer_terms = (
                '\u5316\u80a5', '\u80a5\u6599', 'fertilizer',
                'fertiliser', 'manure',
            )
            if (
                backpack_profile_active and
                str(name or '').endswith('._plant_seed_over_lands') and
                any(term in fertilizer_name for term in fertilizer_terms)
            ):
                # The native backpack loop can OCR a fertilizer card after a
                # generic quantity-badge candidate and route it through the seed
                # planting helper.  Reject it before any drag/click; the separate
                # post-planting fertilizer routine remains untouched.
                try:
                    setattr(
                        bot, '_qqfarm_backpack_round_no_progress_attempts',
                        max(0, int(getattr(
                            bot, '_qqfarm_backpack_round_no_progress_attempts', 0
                        ) or 0)) + 1,
                    )
                except BaseException:
                    pass
                try:
                    _write(
                        'v461 fertilizer candidate blocked before planting helper '
                        'crop=' + fertilizer_name + ' name=' + str(name)
                    )
                except BaseException:
                    pass
                return False
            radish_state = _daily_radish_state(module, bot)
            missing = object()
            try:
                old_crop = getattr(bot, '_qqfarm_planting_crop_context')
            except BaseException:
                old_crop = missing
            try:
                old_mode = getattr(bot, '_qqfarm_radish_mode_context')
            except BaseException:
                old_mode = missing
            try:
                setattr(bot, '_qqfarm_planting_crop_context', crop_name)
                setattr(bot, '_qqfarm_radish_mode_context', radish_state)
                return fn(*a, **k)
            finally:
                try:
                    if old_crop is missing:
                        delattr(bot, '_qqfarm_planting_crop_context')
                    else:
                        setattr(bot, '_qqfarm_planting_crop_context', old_crop)
                except BaseException:
                    pass
                try:
                    if old_mode is missing:
                        delattr(bot, '_qqfarm_radish_mode_context')
                    else:
                        setattr(bot, '_qqfarm_radish_mode_context', old_mode)
                except BaseException:
                    pass
        try:
            _wrapped.__name__ = getattr(fn, '__name__', 'planting_crop_context_wrapper')
            _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
            _wrapped.__doc__ = getattr(fn, '__doc__', None)
            _wrapped.__qqfarm_planting_crop_context_wrapped__ = True
            _wrapped.__qqfarm_planting_crop_context_orig__ = fn
        except BaseException:
            pass
        return _wrapped, True
    except BaseException:
        return fn, False


def _qqfarm_emit_verified_planting_log(
        context, before, after, delta, now_ts=None, name=''):
    """Publish a user-visible planting success only after fresh visual proof."""
    try:
        before_count = max(0, int(before or 0))
        after_count = max(0, int(after or 0))
        delta_count = max(0, int(delta or 0))
    except BaseException:
        return False
    if delta_count <= 0:
        return False
    message = (
        '\u2714 \u64ad\u79cd\u5df2\u786e\u8ba4\uff1a\u5b9e\u9645\u51cf\u5c11\u7a7a\u5730 ' +
        str(delta_count) + '\u5757\uff08' + str(before_count) +
        '\u2192' + str(after_count) + '\uff09'
    )
    try:
        logger = globals().get('_QQFARM_PENDING_PLANTING_LOGGER')
        orig_info = globals().get('_QQFARM_RUNTIME_LOG_ORIG_INFO')
        if logger is not None and callable(orig_info):
            orig_info(logger, message)
            return True
    except BaseException:
        pass
    try:
        logger = getattr(context, 'logger', None) if context is not None else None
        info_fn = getattr(logger, 'info', None)
        if callable(info_fn):
            info_fn(message)
            return True
    except BaseException:
        pass
    try:
        _write('v373 ' + message + ' name=' + str(name))
        return True
    except BaseException:
        return False


def _qqfarm_fit_24_plot_lattice_from_candidates(
        empty_candidates, frame_shape, previous_transform=None,
        occupied_candidates=None):
    """Align explicit plot evidence to the fixed 24-slot farm lattice.

    Candidate totals are never treated as board truth.  A transform is accepted
    only when current-frame evidence supports one unambiguous translation (or a
    previously signed transform is supplied); every unobserved slot remains
    ``unknown``.
    """
    canonical_points = (
        (202, 424),
        (172, 439), (231, 439),
        (143, 454), (202, 454), (260, 454),
        (114, 469), (172, 469), (231, 469), (289, 466),
        (85, 484), (143, 484), (201, 481), (260, 484),
        (55, 499), (114, 499), (172, 499), (230, 496),
        (85, 514), (143, 514), (202, 514),
        (114, 529), (173, 529),
        (144, 544),
    )
    slot_ids = tuple('L%02d' % index for index in range(1, 25))
    accepted_states = {'empty', 'occupied-1x1', 'occupied-2x2'}

    def _unknown(reason):
        observations = {
            slot_id: {'state': 'unknown'} for slot_id in slot_ids
        }
        return {
            'status': 'unknown',
            'reason': str(reason),
            'transform': None,
            'empty_slots': (),
            'occupied_slots': (),
            'matched_count': 0,
            'unknown_count': 24,
            'slot_observations': observations,
            'slot_centers': {},
            'board_signature': 'qqfarm-24-lattice-v1|unknown',
        }

    try:
        frame_height = int(frame_shape[0])
        frame_width = int(frame_shape[1])
    except BaseException:
        return _unknown('invalid-frame-shape')
    if frame_height <= 0 or frame_width <= 0:
        return _unknown('invalid-frame-shape')

    def _records(raw_candidates, default_state):
        records = []
        try:
            iterator = iter(raw_candidates or ())
        except BaseException:
            iterator = iter(())
        for raw_candidate in iterator:
            if not isinstance(raw_candidate, dict):
                continue
            try:
                center = raw_candidate.get('center')
                raw_x = float(center[0])
                raw_y = float(center[1])
            except BaseException:
                continue
            try:
                state = str(
                    raw_candidate.get('state', default_state) or default_state
                )
            except BaseException:
                state = default_state
            if state == 'occupied':
                state = 'occupied-1x1'
            if state not in accepted_states:
                continue
            try:
                confidence = float(raw_candidate.get('confidence', 0.0) or 0.0)
            except BaseException:
                confidence = 0.0
            records.append({
                'x': raw_x,
                'y': raw_y,
                'nx': raw_x * 428.0 / float(frame_width),
                'ny': raw_y * 800.0 / float(frame_height),
                'state': state,
                'confidence': confidence,
            })
        return records

    evidence = _records(empty_candidates, 'empty')
    evidence.extend(_records(occupied_candidates, 'occupied-1x1'))
    # Fewer than four points have neither a 2x2 shape nor enough independent
    # anchors to establish camera translation safely.
    if len(evidence) < 4:
        return _unknown('insufficient-evidence')

    tolerance_squared = 16.0

    def _fit_transform(transform_x, transform_y):
        matches = {}
        residual = 0.0
        for record in evidence:
            local_x = record['nx'] - float(transform_x)
            local_y = record['ny'] - float(transform_y)
            nearest_index = -1
            nearest_distance = None
            for index, point in enumerate(canonical_points):
                dx = local_x - float(point[0])
                dy = local_y - float(point[1])
                distance = dx * dx + dy * dy
                if nearest_distance is None or distance < nearest_distance:
                    nearest_distance = distance
                    nearest_index = index
            if nearest_index < 0 or nearest_distance is None:
                continue
            if nearest_distance > tolerance_squared:
                continue
            slot_id = slot_ids[nearest_index]
            existing = matches.get(slot_id)
            if existing is None:
                matches[slot_id] = record
                residual += float(nearest_distance)
                continue
            if existing.get('state') != record.get('state'):
                # Opposing evidence is unknown, not a guessed occupancy.
                matches[slot_id] = {'state': 'unknown', 'confidence': 0.0}
                continue
            if record.get('confidence', 0.0) > existing.get('confidence', 0.0):
                matches[slot_id] = record
        accepted_matches = {
            slot_id: record for slot_id, record in matches.items()
            if record.get('state') in accepted_states
        }
        return accepted_matches, residual

    accepted_previous = None
    if isinstance(previous_transform, dict):
        try:
            accepted_previous = {
                'x': int(round(float(previous_transform.get('x')))),
                'y': int(round(float(previous_transform.get('y')))),
            }
        except BaseException:
            accepted_previous = None

    matches = None
    transform_x = None
    transform_y = None
    if accepted_previous is not None:
        previous_x = accepted_previous['x']
        previous_y = accepted_previous['y']
        previous_matches, _ = _fit_transform(previous_x, previous_y)
        # Camera position is allowed to move between fresh frames. A stale
        # accepted transform is only a hint: if it no longer anchors four
        # current-frame slots, re-fit from current evidence instead of marking
        # the whole board unknown.
        if len(previous_matches) >= 4:
            transform_x = previous_x
            transform_y = previous_y
            matches = previous_matches
    if matches is None:
        candidate_transforms = set()
        for record in evidence:
            for canonical_x, canonical_y in canonical_points:
                candidate_transforms.add((
                    int(round(record['nx'] - float(canonical_x))),
                    int(round(record['ny'] - float(canonical_y))),
                ))
        scored = []
        for candidate_x, candidate_y in candidate_transforms:
            candidate_matches, residual = _fit_transform(
                candidate_x, candidate_y
            )
            if len(candidate_matches) >= 4:
                scored.append((
                    len(candidate_matches), float(residual), candidate_x,
                    candidate_y, candidate_matches,
                ))
        if not scored:
            return _unknown('insufficient-evidence')
        maximum_matches = max(item[0] for item in scored)
        best = [item for item in scored if item[0] == maximum_matches]
        minimum_residual = min(item[1] for item in best)
        best = [
            item for item in best
            if abs(item[1] - minimum_residual) <= 0.000001
        ]
        if len(best) != 1:
            return _unknown('ambiguous-transform')
        _, _, transform_x, transform_y, matches = best[0]

    observations = {
        slot_id: {'state': 'unknown'} for slot_id in slot_ids
    }
    for slot_id, record in matches.items():
        observations[slot_id] = {
            'state': record['state'],
            'confidence': record.get('confidence', 0.0),
        }

    centers = {}
    for slot_id, point in zip(slot_ids, canonical_points):
        projected_x = (float(point[0]) + float(transform_x)) * frame_width / 428.0
        projected_y = (float(point[1]) + float(transform_y)) * frame_height / 800.0
        # X uses nearest pixel; Y retains the CV slice row convention.
        centers[slot_id] = (int(round(projected_x)), int(projected_y))

    empty_slots = tuple(
        slot_id for slot_id in slot_ids
        if observations[slot_id].get('state') == 'empty'
    )
    occupied_slots = tuple(
        slot_id for slot_id in slot_ids
        if observations[slot_id].get('state') in
        ('occupied-1x1', 'occupied-2x2')
    )
    matched_count = len(empty_slots) + len(occupied_slots)
    unknown_count = 24 - matched_count
    signature = 'qqfarm-24-lattice-v1|' + '|'.join(
        '%s=%s' % (slot_id, observations[slot_id].get('state', 'unknown'))
        for slot_id in slot_ids
    )
    return {
        'status': 'aligned',
        'reason': 'matched-all-24' if matched_count == 24 else 'matched-partial',
        'transform': {'x': int(transform_x), 'y': int(transform_y)},
        'empty_slots': empty_slots,
        'occupied_slots': occupied_slots,
        'matched_count': int(matched_count),
        'unknown_count': int(unknown_count),
        'slot_observations': observations,
        'slot_centers': centers,
        'board_signature': signature,
    }

def _qqfarm_build_24_plot_ledger(
        slot_observations, *, frame_id='', board_signature='', captured_at=None,
        seed_panel_visible=False, land_popup_visible=False,
        quad_overlay_visible=False, quad_groups=None):
    """Build the only accepted 24-slot planting truth from explicit slot evidence.

    Occupancy is supplied per fixed slot; gold/purple land quality is preserved
    as metadata only and never changes the state.  Missing or malformed slots
    remain ``unknown`` rather than being guessed from template-hit totals.
    """
    slot_ids = tuple('L%02d' % index for index in range(1, 25))
    # Fixed 4 columns x 6 rows logical board projected into the farm's
    # isometric screen lattice.  These are the fifteen adjacent 2x2 blocks;
    # sequential L01..L04 chunks are not physical ???s.
    default_quad_groups = (
        ('L01', 'L03', 'L02', 'L05'),
        ('L03', 'L06', 'L05', 'L09'),
        ('L06', 'L10', 'L09', 'L14'),
        ('L02', 'L05', 'L04', 'L08'),
        ('L05', 'L09', 'L08', 'L13'),
        ('L09', 'L14', 'L13', 'L18'),
        ('L04', 'L08', 'L07', 'L12'),
        ('L08', 'L13', 'L12', 'L17'),
        ('L13', 'L18', 'L17', 'L21'),
        ('L07', 'L12', 'L11', 'L16'),
        ('L12', 'L17', 'L16', 'L20'),
        ('L17', 'L21', 'L20', 'L23'),
        ('L11', 'L16', 'L15', 'L19'),
        ('L16', 'L20', 'L19', 'L22'),
        ('L20', 'L23', 'L22', 'L24'),
    )
    valid_states = {
        'empty', 'occupied-1x1', 'occupied-2x2', 'unknown',
    }
    try:
        raw_slots = slot_observations if isinstance(
            slot_observations, dict
        ) else {}
    except BaseException:
        raw_slots = {}

    slots = {}
    invalid_slot_ids = []
    try:
        for raw_slot_id in raw_slots:
            if str(raw_slot_id) not in slot_ids:
                invalid_slot_ids.append(str(raw_slot_id))
    except BaseException:
        invalid_slot_ids = []

    for slot_id in slot_ids:
        try:
            observation = raw_slots.get(slot_id, {})
        except BaseException:
            observation = {}
        if isinstance(observation, str):
            observation = {'state': observation}
        if not isinstance(observation, dict):
            observation = {}
        try:
            state = str(observation.get('state', 'unknown') or 'unknown')
        except BaseException:
            state = 'unknown'
        if state not in valid_states:
            state = 'unknown'
        entry = {'state': state}
        # This field is intentionally copied after the state has already been
        # fixed.  It remains display/business metadata, never CV truth.
        try:
            if 'land_quality' in observation:
                entry['land_quality'] = observation.get('land_quality')
        except BaseException:
            pass
        try:
            if 'evidence' in observation:
                entry['evidence'] = observation.get('evidence')
        except BaseException:
            pass
        slots[slot_id] = entry

    try:
        supplied_groups = (
            default_quad_groups if quad_groups is None else quad_groups
        )
    except BaseException:
        supplied_groups = default_quad_groups
    normalized_quad_groups = []
    invalid_quad_groups = []
    try:
        group_iterator = iter(supplied_groups)
    except BaseException:
        group_iterator = iter(())
    for raw_group in group_iterator:
        try:
            group = tuple(str(slot_id) for slot_id in raw_group)
        except BaseException:
            invalid_quad_groups.append(repr(raw_group)[:120])
            continue
        if (
                len(group) != 4 or len(set(group)) != 4 or
                any(slot_id not in slot_ids for slot_id in group)):
            invalid_quad_groups.append(repr(raw_group)[:120])
            continue
        if any(set(group) == set(existing) for existing in normalized_quad_groups):
            continue
        normalized_quad_groups.append(group)
    normalized_quad_groups = tuple(normalized_quad_groups)

    occupied_slots = tuple(
        slot_id for slot_id in slot_ids
        if slots[slot_id].get('state') in ('occupied-1x1', 'occupied-2x2')
    )
    empty_slots = tuple(
        slot_id for slot_id in slot_ids
        if slots[slot_id].get('state') == 'empty'
    )
    unknown_slots = tuple(
        slot_id for slot_id in slot_ids
        if slots[slot_id].get('state') == 'unknown'
    )
    occupied_count = len(occupied_slots)
    empty_count = len(empty_slots)
    unknown_count = len(unknown_slots)
    complete_2x2_groups = tuple(
        group for group in normalized_quad_groups
        if all(slots[slot_id].get('state') == 'occupied-2x2'
               for slot_id in group)
    )
    ui_blocked = bool(
        seed_panel_visible or land_popup_visible or quad_overlay_visible
    )
    full_board_confirmed = bool(
        unknown_count == 0 and
        empty_count == 0 and
        occupied_count == 24 and
        not ui_blocked
    )
    try:
        captured_value = float(captured_at) if captured_at is not None else 0.0
    except BaseException:
        captured_value = 0.0
    return {
        'slot_ids': slot_ids,
        'slots': slots,
        'occupied_count': int(occupied_count),
        'empty_count': int(empty_count),
        'unknown_count': int(unknown_count),
        # Fixed-order slot lists are the canonical actionable form of the counts.
        # Callers must never derive a transaction from a template-hit aggregate.
        'occupied_slots': occupied_slots,
        'empty_slots': empty_slots,
        'unknown_slots': unknown_slots,
        'quad_groups': normalized_quad_groups,
        'complete_2x2_groups': complete_2x2_groups,
        'frame_id': str(frame_id or ''),
        'board_signature': str(board_signature or ''),
        'captured_at': captured_value,
        'ui': {
            'seed_panel_visible': bool(seed_panel_visible),
            'land_popup_visible': bool(land_popup_visible),
            'quad_overlay_visible': bool(quad_overlay_visible),
        },
        # Keep direct aliases for runtime call sites and diagnostics while the
        # nested ui mapping remains available for structured consumers.
        'seed_panel_visible': bool(seed_panel_visible),
        'land_popup_visible': bool(land_popup_visible),
        'quad_overlay_visible': bool(quad_overlay_visible),
        'ui_blocked': ui_blocked,
        'full_board_confirmed': full_board_confirmed,
        'invalid_slot_ids': tuple(sorted(set(invalid_slot_ids))),
        'invalid_quad_groups': tuple(sorted(set(invalid_quad_groups))),
    }


def _qqfarm_validate_24_plot_transaction(
        before_ledger, after_ledger, *, attempted_slots, planting_mode):
    """Commit only an aligned, fresh, exact 1x1 or 2x2 slot transaction.

    Legacy aggregate counts are deliberately not read.  The result is derived
    only from the fixed slot states in two explicit ledgers.
    """
    result = {
        'committed': False,
        'delta': 0,
        'committed_slots': (),
        'attempted_slots': (),
        'observed_changed_slots': (),
        'external_changed_slots': (),
        'reason': 'invalid-ledger',
    }
    if not isinstance(before_ledger, dict) or not isinstance(after_ledger, dict):
        return result
    expected_slot_ids = tuple('L%02d' % index for index in range(1, 25))
    valid_states = {
        'empty', 'occupied-1x1', 'occupied-2x2', 'unknown',
    }

    try:
        attempted = tuple(str(slot_id) for slot_id in attempted_slots)
    except BaseException:
        return result
    result['attempted_slots'] = attempted
    if not attempted or len(set(attempted)) != len(attempted):
        result['reason'] = 'invalid-attempted-slots'
        return result

    try:
        before_slot_ids = tuple(before_ledger.get('slot_ids', ()))
        after_slot_ids = tuple(after_ledger.get('slot_ids', ()))
        before_slots = before_ledger.get('slots', {})
        after_slots = after_ledger.get('slots', {})
    except BaseException:
        return result
    if (
            before_slot_ids != expected_slot_ids or
            after_slot_ids != expected_slot_ids or
            not isinstance(before_slots, dict) or
            not isinstance(after_slots, dict) or
            any(slot_id not in before_slots or slot_id not in after_slots
                for slot_id in expected_slot_ids) or
            bool(before_ledger.get('invalid_slot_ids')) or
            bool(after_ledger.get('invalid_slot_ids'))):
        return result

    def _state(ledger_slots, slot_id):
        try:
            entry = ledger_slots.get(slot_id, {})
            state = entry.get('state') if isinstance(entry, dict) else entry
            state = str(state or 'unknown')
        except BaseException:
            state = 'unknown'
        return state if state in valid_states else 'unknown'

    before_states = {
        slot_id: _state(before_slots, slot_id) for slot_id in expected_slot_ids
    }
    after_states = {
        slot_id: _state(after_slots, slot_id) for slot_id in expected_slot_ids
    }

    if bool(before_ledger.get('ui_blocked')) or bool(after_ledger.get('ui_blocked')):
        result['reason'] = 'ui-overlay-visible'
        return result
    try:
        before_frame_id = str(before_ledger.get('frame_id', '') or '')
        after_frame_id = str(after_ledger.get('frame_id', '') or '')
        before_capture = float(before_ledger.get('captured_at', 0.0) or 0.0)
        after_capture = float(after_ledger.get('captured_at', 0.0) or 0.0)
    except BaseException:
        before_frame_id = after_frame_id = ''
        before_capture = after_capture = 0.0
    if (
            not before_frame_id or not after_frame_id or
            before_frame_id == after_frame_id or
            after_capture <= before_capture):
        result['reason'] = 'not-two-fresh-frames'
        return result
    try:
        before_signature = str(before_ledger.get('board_signature', '') or '')
        after_signature = str(after_ledger.get('board_signature', '') or '')
    except BaseException:
        before_signature = after_signature = ''
    if (
            not before_signature or not after_signature or
            before_signature != after_signature):
        result['reason'] = 'board-not-aligned'
        return result
    if (
            any(state == 'unknown' for state in before_states.values()) or
            any(state == 'unknown' for state in after_states.values())):
        result['reason'] = 'unknown-slot-state'
        return result

    try:
        mode = str(planting_mode or '').strip().lower().replace('×', 'x')
    except BaseException:
        mode = ''
    expected_count = 1 if mode == '1x1' else 4 if mode == '2x2' else 0
    expected_state = (
        'occupied-1x1' if mode == '1x1' else
        'occupied-2x2' if mode == '2x2' else ''
    )
    if not expected_count:
        result['reason'] = 'unsupported-planting-mode'
        return result
    if len(attempted) != expected_count or any(
            slot_id not in expected_slot_ids for slot_id in attempted):
        result['reason'] = 'invalid-attempted-slots'
        return result

    if mode == '2x2':
        def _valid_group_set(ledger):
            groups = []
            try:
                raw_groups = ledger.get('quad_groups', ())
            except BaseException:
                raw_groups = ()
            for raw_group in raw_groups or ():
                try:
                    group = tuple(str(slot_id) for slot_id in raw_group)
                except BaseException:
                    continue
                if (
                        len(group) == 4 and len(set(group)) == 4 and
                        all(slot_id in expected_slot_ids for slot_id in group)):
                    groups.append(frozenset(group))
            return set(groups)
        attempted_set = frozenset(attempted)
        if (
                attempted_set not in _valid_group_set(before_ledger) or
                attempted_set not in _valid_group_set(after_ledger)):
            result['reason'] = 'incomplete-quad-group'
            return result

    observed_changed = tuple(
        slot_id for slot_id in expected_slot_ids
        if before_states[slot_id] != after_states[slot_id]
    )
    external_changed = tuple(
        slot_id for slot_id in observed_changed if slot_id not in attempted
    )
    result['observed_changed_slots'] = observed_changed
    result['external_changed_slots'] = external_changed
    if external_changed:
        result['reason'] = 'target-external-change'
        return result
    if not observed_changed:
        result['reason'] = 'attempted-slots-unchanged'
        return result
    # ``attempted`` preserves the declared physical 2x2 group order.  The
    # fixed L01..L24 scan order can differ for an isometric diamond, so compare
    # membership rather than reordering the attempted transaction by slot name.
    if (
            len(observed_changed) != expected_count or
            set(observed_changed) != set(attempted)):
        result['reason'] = 'attempted-slot-transition-invalid'
        return result
    if any(
            before_states[slot_id] != 'empty' or
            after_states[slot_id] != expected_state
            for slot_id in attempted):
        result['reason'] = 'attempted-slot-transition-invalid'
        return result
    if mode == '2x2':
        try:
            after_complete_groups = {
                frozenset(group)
                for group in after_ledger.get('complete_2x2_groups', ())
            }
        except BaseException:
            after_complete_groups = set()
        if frozenset(attempted) not in after_complete_groups:
            result['reason'] = 'incomplete-quad-group'
            return result

    result.update({
        'committed': True,
        'delta': int(expected_count),
        'committed_slots': attempted,
        'reason': 'committed',
    })
    return result

def _qqfarm_mark_visual_planting_success(context, before, after, now_ts=None, name=''):
    """Persist planting progress only from an exact committed slot transaction."""
    global _LAST_SUCCESSFUL_FULL_PLANTING_TS
    try:
        transaction = getattr(
            context, '_qqfarm_last_planting_transaction', None
        ) if context is not None else None
    except BaseException:
        transaction = None
    if not isinstance(transaction, dict) or not bool(
            transaction.get('committed', False)):
        return False
    try:
        committed_slots = tuple(
            str(slot_id) for slot_id in transaction.get('committed_slots', ())
        )
        confirmed_delta = int(transaction.get('delta', 0) or 0)
    except BaseException:
        return False
    if (
            confirmed_delta <= 0 or len(committed_slots) != confirmed_delta or
            len(set(committed_slots)) != len(committed_slots)):
        return False
    try:
        before_count = max(0, int(before or 0))
        after_count = max(0, int(after or 0))
    except BaseException:
        return False
    # Count fields are display/priority context only.  They cannot create a
    # commit; the exact L-slot transaction above is the only authority.
    try:
        transaction_before = transaction.get('before_empty_count')
        transaction_after = transaction.get('after_empty_count')
        if transaction_before is not None:
            before_count = max(0, int(transaction_before))
        if transaction_after is not None:
            after_count = max(0, int(transaction_after))
    except BaseException:
        pass
    try:
        now_value = float(
            now_ts if now_ts is not None else __import__('time').time()
        )
    except BaseException:
        now_value = 0.0
    post_snapshot_active = False
    if context is not None:
        try:
            post_snapshot_active = bool(getattr(
                context, '_qqfarm_post_harvest_snapshot_locked', False
            ))
        except BaseException:
            post_snapshot_active = False
        if post_snapshot_active:
            try:
                attempted_lands = list(getattr(
                    context, '_qqfarm_last_planting_attempt_lands', []
                ) or [])
            except BaseException:
                attempted_lands = []
            consume_fn = globals().get(
                '_qqfarm_consume_post_harvest_pending_lands'
            )
            if callable(consume_fn) and attempted_lands:
                try:
                    remaining_lands = list(consume_fn(
                        context, attempted_lands, now_ts=now_value
                    ) or [])
                    after_count = len(remaining_lands)
                except BaseException:
                    pass
    _LAST_SUCCESSFUL_FULL_PLANTING_TS = now_value
    if context is not None:
        try:
            setattr(context, '_qqfarm_last_planting_outcome_verified', True)
            setattr(context, '_qqfarm_last_planting_outcome_before', before_count)
            setattr(context, '_qqfarm_last_planting_outcome_after', after_count)
        except BaseException:
            pass
        # A native \"completed planting\" log is held as a claim until this
        # visual record exists.  Apply at most the visually observed decrease,
        # then allow the next panel OCR to be the inventory authority.
        try:
            pending_radish = max(0, int(getattr(
                context, '_qqfarm_pending_radish_planting_claim_count', 0
            ) or 0))
        except BaseException:
            pending_radish = 0
        if pending_radish > 0:
            confirmed_radish = min(pending_radish, confirmed_delta)
            try:
                previous_qty = max(0, int(getattr(
                    context, '_qqfarm_radish_inventory_qty', 0
                ) or 0))
                setattr(
                    context, '_qqfarm_radish_inventory_qty',
                    max(0, previous_qty - confirmed_radish),
                )
                setattr(context, '_qqfarm_radish_inventory_seen_ts', now_value)
                setattr(context, '_qqfarm_pending_radish_planting_claim_count', 0)
                setattr(context, '_qqfarm_pending_radish_planting_claim_ts', 0.0)
            except BaseException:
                pass
        # The ledger validator, not an aggregate template-count delta, set this.
        confirmed_delta = int(confirmed_delta)
        if confirmed_delta > 0:
            try:
                attempt_ts = float(getattr(
                    context, '_qqfarm_last_planting_attempt_ts', now_value
                ) or now_value)
            except BaseException:
                attempt_ts = now_value
            metric_key = (
                round(attempt_ts, 3), tuple(committed_slots),
                before_count, after_count, str(name or '')
            )
            try:
                previous_metric_key = getattr(
                    context, '_qqfarm_last_visual_planting_metric_key', None
                )
            except BaseException:
                previous_metric_key = None
            if previous_metric_key != metric_key:
                try:
                    day_fn = globals().get('_daily_business_date')
                    day = str(
                        day_fn() if callable(day_fn)
                        else __import__('time').strftime('%Y-%m-%d')
                    )
                except BaseException:
                    day = ''
                try:
                    instance_id = str(
                        getattr(context, 'current_instance_id', '')
                        or getattr(context, 'instance_id', '')
                        or '1'
                    )
                except BaseException:
                    instance_id = '1'
                try:
                    gui_metrics = getattr(context, 'gui_metrics', None)
                    if not isinstance(gui_metrics, dict):
                        gui_metrics = {}
                        setattr(context, 'gui_metrics', gui_metrics)
                    if str(gui_metrics.get('date', '') or '') != day:
                        gui_metrics['planting_count'] = 0
                    gui_metrics['date'] = day
                    gui_metrics['planting_count'] = max(0, int(
                        gui_metrics.get('planting_count', 0) or 0
                    )) + confirmed_delta
                except BaseException:
                    pass
                try:
                    live_metrics = getattr(context, '_instance_metrics', None)
                    if not isinstance(live_metrics, dict):
                        live_metrics = {}
                        setattr(context, '_instance_metrics', live_metrics)
                    instance_metrics = live_metrics.get(instance_id)
                    if not isinstance(instance_metrics, dict):
                        instance_metrics = {}
                        live_metrics[instance_id] = instance_metrics
                    if str(instance_metrics.get('date', '') or '') != day:
                        instance_metrics['planting_count'] = 0
                    instance_metrics['date'] = day
                    instance_metrics['planting_count'] = max(0, int(
                        instance_metrics.get('planting_count', 0) or 0
                    )) + confirmed_delta
                except BaseException:
                    pass
                try:
                    setattr(
                        context, '_qqfarm_last_visual_planting_metric_key',
                        metric_key,
                    )
                except BaseException:
                    pass
                try:
                    sync_fn = globals().get('_daily_metrics_sync_runtime')
                    if callable(sync_fn):
                        sync_fn(
                            context=context, force=True,
                            trusted_context_fields=('planting_count',),
                        )
                except BaseException as metric_error:
                    try:
                        _write(
                            'v373 planting metric sync error ' +
                            repr(metric_error)[:180]
                        )
                    except BaseException:
                        pass
                try:
                    emit_fn = globals().get(
                        '_qqfarm_emit_verified_planting_log'
                    )
                    if callable(emit_fn):
                        emit_fn(
                            context, before_count, after_count, confirmed_delta,
                            now_ts=now_value, name=name,
                        )
                except BaseException:
                    pass
        if not post_snapshot_active:
            try:
                setattr(context, '_qqfarm_single_harvest_planting_pending', False)
            except BaseException:
                pass
        priority_fn = globals().get('_qqfarm_update_home_priority')
        if callable(priority_fn):
            try:
                priority_fn(
                    context, after_count, now_ts=now_value,
                    reason='visual-planting-empty-land-decrease',
                )
            except BaseException:
                pass
        try:
            if _qqfarm_home_priority_active(context):
                setattr(context, '_qqfarm_force_self_cycle_next', True)
                setattr(context, '_qqfarm_cycle_branch_hint', 'self')
        except BaseException:
            pass
    try:
        _write(
            'v181 full-land planting cooldown armed visual=true before=' +
            str(before_count) + ' after=' + str(after_count) +
            ' ts=' + ('%.3f' % now_value) + ' name=' + str(name)
        )
    except BaseException:
        pass
    return True



def _qqfarm_capture_current_frame_24_slot_ledger(
        frame, frame_id='', captured_at=None):
    """Build a fresh 24-slot planting ledger from one current farm frame.

    The observation deliberately starts from fixed L01..L24 geometry.  Terrain
    colour is kept as ``land_quality`` only; no candidate count or gold/purple
    appearance can create a planting success.  A panel, placement overlay,
    clipped board, or failed lattice fit returns a non-clickable ledger.
    """
    slot_ids = tuple('L%02d' % index for index in range(1, 25))

    def _now_value():
        if captured_at is not None:
            try:
                return float(captured_at)
            except BaseException:
                pass
        try:
            return float(__import__('time').time())
        except BaseException:
            return 0.0

    def _unknown(reason, *, status='unknown', seed_panel=False,
                 land_popup=False, quad_overlay=False):
        observations = {
            slot_id: {'state': 'unknown'} for slot_id in slot_ids
        }
        ledger = _qqfarm_build_24_plot_ledger(
            observations,
            frame_id=str(frame_id or ''),
            board_signature='qqfarm-current-24-v1|unavailable',
            captured_at=_now_value(),
            seed_panel_visible=bool(seed_panel),
            land_popup_visible=bool(land_popup),
            quad_overlay_visible=bool(quad_overlay),
        )
        ledger.update({
            'click_safe': False,
            'observation_only': False,
            'capture_status': str(status),
            'capture_reason': str(reason),
            'slot_centers': {},
            'complete_2x2_groups': (),
            'geometry_anchor_slots': (),
            'matched_anchor_count': 0,
            'unmatched_anchor_count': 0,
            'ignored_geometry_anchor_count': 0,
        })
        return ledger

    try:
        np_module = globals().get('np') or __import__('numpy')
        cv_module = globals().get('cv2') or __import__('cv2')
        image = np_module.asarray(frame)
        shape = getattr(image, 'shape', ())
        if len(shape) < 3 or int(shape[0]) < 120 or int(shape[1]) < 120:
            return _unknown('invalid-frame')
        if int(shape[2]) < 3:
            return _unknown('invalid-frame')
        image = image[:, :, :3]
        height, width = int(image.shape[0]), int(image.shape[1])
        # A direct desktop capture can reach this observer before the normal
        # visible-frame capture has reduced the physical QQ window to 428x800.
        # Capture provenance, not portrait dimensions by themselves, decides
        # whether a full board loses coordinate authority.  The explicit label
        # branch keeps the isolated physical-frame diagnostics reproducible.
        frame_label = str(frame_id or '').strip().lower()
        try:
            marked_physical_window_frame = bool(
                int(globals().get(
                    '_QQFARM_LAST_PHYSICAL_PRINTWINDOW_FRAME_ID', 0
                ) or 0) == int(id(frame))
            )
        except BaseException:
            marked_physical_window_frame = False
        explicit_physical_window_frame = bool(
            'printwindow' in frame_label or
            'physical-window' in frame_label or
            '-physical-' in frame_label or
            frame_label.startswith('physical-')
        )
        physical_window_full_board_retry = bool(
            (marked_physical_window_frame or explicit_physical_window_frame) and
            int(width) >= 500 and
            int(height) >= 900 and
            0.50 <= (float(width) / float(height)) <= 0.60
        )
    except BaseException:
        return _unknown('invalid-frame')

    # The seed shelf fills a portrait QQ mini-app viewport.  Check that narrow
    # capture shape before geometry: a shelf can hide enough lower-board anchors
    # that a click-safe lattice no longer fits.  Do not apply this detector to a
    # landscape crop because bare farm highlights can mimic its badge ratios.
    preflight_seed_panel_visible = False
    try:
        portrait_capture = float(height) >= (float(width) * 1.20)
        panel_detector = globals().get('_seed_panel_strip_visible')
        if portrait_capture and callable(panel_detector):
            preflight_seed_panel_visible = bool(panel_detector(image))
    except BaseException:
        preflight_seed_panel_visible = False
    if preflight_seed_panel_visible:
        return _unknown(
            'ui-overlay-visible', status='blocked',
            seed_panel=True,
        )

    try:
        terrain_anchors = _qqfarm_dynamic_viewport_plot_anchor_candidates(
            image, minimum_matches=4
        )
        crop_anchor_fn = globals().get(
            '_qqfarm_dynamic_viewport_crop_geometry_anchor_candidates'
        )
        crop_anchors = crop_anchor_fn(image) if callable(crop_anchor_fn) else []
        anchors = tuple(terrain_anchors or ()) + tuple(crop_anchors or ())
        fit = _qqfarm_fit_dynamic_24_slot_lattice_from_geometry_anchors(
            anchors, image.shape, frame=image
        )
    except BaseException:
        return _unknown('viewport-not-full-board')
    if not isinstance(fit, dict) or fit.get('status') != 'aligned':
        # Geometry-fitting detail is diagnostic only.  The public observer
        # contract uses one click-safe reason for every incomplete viewport.
        return _unknown('viewport-not-full-board')

    fit_reason = str(fit.get('reason') or '')
    cropped_full_board_observation = bool(
        fit.get('observation_only') and
        fit.get('cropped_full_board_observation') and
        fit.get('crop_only_full_board') and
        fit_reason == 'cropped-full-board-observation'
    )
    mixed_seedling_platform_full_board_observation = bool(
        fit.get('observation_only') and
        fit.get('crop_only_full_board') and
        fit_reason == 'mixed-seedling-platform-full-board-observation'
    )
    observation_only_full_board = bool(
        cropped_full_board_observation or
        mixed_seedling_platform_full_board_observation
    )
    try:
        centers = dict(fit.get('slot_centers') or {})
        if tuple(centers) != slot_ids:
            return _unknown('viewport-not-full-board')
        for slot_id in slot_ids:
            center = centers.get(slot_id)
            if not isinstance(center, (tuple, list)) or len(center) < 2:
                return _unknown('viewport-not-full-board')
            center_x = int(round(float(center[0])))
            center_y = int(round(float(center[1])))
            if observation_only_full_board:
                in_bounds = (
                    -12 <= center_x < width + 12 and
                    -12 <= center_y < height + 12
                )
            else:
                in_bounds = 0 <= center_x < width and 0 <= center_y < height
            if not in_bounds:
                return _unknown('viewport-not-full-board')
            centers[slot_id] = (center_x, center_y)
    except BaseException:
        return _unknown('viewport-not-full-board')

    # ``crop-geometry-full-board-only`` is allowed to confirm an already full
    # board, never to create click authority for a candidate empty slot.
    crop_only_full_board = bool(fit.get('crop_only_full_board'))

    # Establish the current full-board geometry before looking for overlays.
    # A cropped farm can contain pixels resembling seed badges; it remains an
    # unknown viewport rather than being reclassified as a blocked full board.
    seed_panel_visible = False
    try:
        panel_detector = globals().get('_seed_panel_strip_visible')
        if callable(panel_detector):
            seed_panel_visible = bool(panel_detector(image))
    except BaseException:
        seed_panel_visible = False
    quad_overlay_visible = False
    try:
        overlay_detector = globals().get('_qqfarm_quad_overlay_observation')
        if callable(overlay_detector):
            overlay = overlay_detector(image)
            quad_overlay_visible = bool(
                isinstance(overlay, dict) and overlay.get('present')
            )
    except BaseException:
        quad_overlay_visible = False
    if seed_panel_visible or quad_overlay_visible:
        return _unknown(
            'ui-overlay-visible',
            status='blocked',
            seed_panel=seed_panel_visible,
            quad_overlay=quad_overlay_visible,
        )

    try:
        hsv = cv_module.cvtColor(image, cv_module.COLOR_BGR2HSV)
    except BaseException:
        return _unknown('invalid-frame')

    # Use direct terrain anchors where available, then a tight center sample for
    # all other slots.  The resulting quality is metadata and is intentionally
    # written after the state decision below.
    anchor_quality = {}
    try:
        terrain_slot_map = fit.get('terrain_anchor_slot_map')
        if isinstance(terrain_slot_map, dict):
            for raw_index, slot_id in terrain_slot_map.items():
                try:
                    anchor = tuple(terrain_anchors or ())[int(raw_index)]
                except BaseException:
                    continue
                if not isinstance(anchor, dict) or slot_id not in slot_ids:
                    continue
                quality = str(anchor.get('land_quality') or '')
                if quality in ('gold', 'purple'):
                    anchor_quality[slot_id] = quality
        else:
            geometry_slots = tuple(fit.get('geometry_anchor_slots') or ())
            for anchor, slot_id in zip(tuple(terrain_anchors or ()), geometry_slots):
                if not isinstance(anchor, dict) or slot_id not in slot_ids:
                    continue
                quality = str(anchor.get('land_quality') or '')
                if quality in ('gold', 'purple'):
                    anchor_quality[slot_id] = quality
    except BaseException:
        pass

    def _quality_at(center):
        try:
            x, y = int(center[0]), int(center[1])
            x1, x2 = max(0, x - 12), min(width, x + 13)
            y1, y2 = max(0, y - 7), min(height, y + 8)
            roi = hsv[y1:y2, x1:x2]
            if getattr(roi, 'size', 0) <= 0:
                return None
            hue, saturation, value = roi[:, :, 0], roi[:, :, 1], roi[:, :, 2]
            gold = (
                (hue >= 10) & (hue <= 45) &
                (saturation >= 75) & (value >= 110)
            )
            purple = (
                (hue >= 120) & (hue <= 179) &
                (saturation >= 25) & (value >= 100)
            )
            gold_ratio = float(np_module.mean(gold))
            purple_ratio = float(np_module.mean(purple))
            if gold_ratio >= 0.50 and gold_ratio > purple_ratio:
                return 'gold'
            if purple_ratio >= 0.50 and purple_ratio > gold_ratio:
                return 'purple'
        except BaseException:
            pass
        return None

    # The crop marker is scored only at the expected top edge of each real 2x2
    # group.  A nearby crop can give an overlapping candidate a weak score; the
    # final non-overlapping maximum selection below is what preserves the three
    # complete real groups instead of inventing partial 2x2 occupancy.
    try:
        lattice_scale = max(
            0.35,
            min(3.50, abs(float(centers['L03'][0]) - float(centers['L02'][0])) / 100.0),
        )
    except BaseException:
        lattice_scale = 1.0
    min_x = max(0, min(point[0] for point in centers.values()) - int(round(45 * lattice_scale)))
    max_x = min(width, max(point[0] for point in centers.values()) + int(round(55 * lattice_scale)))
    min_y = max(0, min(point[1] for point in centers.values()) - int(round(45 * lattice_scale)))
    max_y = min(height, max(point[1] for point in centers.values()) + int(round(35 * lattice_scale)))
    board_mask = np_module.zeros((height, width), dtype=np_module.uint8)
    board_mask[min_y:max_y, min_x:max_x] = 1
    foliage_mask = (
        (hsv[:, :, 0] >= 30) & (hsv[:, :, 0] <= 100) &
        (hsv[:, :, 1] >= 45) & (hsv[:, :, 2] >= 35)
    ).astype(np_module.uint8)
    foliage_mask = foliage_mask * board_mask
    crop_components = []
    try:
        component_count, _labels, stats, centroids = (
            cv_module.connectedComponentsWithStats(foliage_mask, 8)
        )
        component_min_area = max(8, int(round(45.0 * lattice_scale * lattice_scale)))
        component_max_area = max(component_min_area + 1, int(round(800.0 * lattice_scale * lattice_scale)))
        max_component_width = max(8, int(round(55.0 * lattice_scale)))
        max_component_height = max(8, int(round(45.0 * lattice_scale)))
        for component_index in range(1, int(component_count)):
            left = int(stats[component_index, cv_module.CC_STAT_LEFT])
            top = int(stats[component_index, cv_module.CC_STAT_TOP])
            component_width = int(stats[component_index, cv_module.CC_STAT_WIDTH])
            component_height = int(stats[component_index, cv_module.CC_STAT_HEIGHT])
            area = int(stats[component_index, cv_module.CC_STAT_AREA])
            if not (
                component_min_area <= area <= component_max_area and
                4 <= component_width <= max_component_width and
                4 <= component_height <= max_component_height
            ):
                continue
            crop_components.append({
                'area': area,
                'center': (
                    float(centroids[component_index][0]),
                    float(centroids[component_index][1]),
                ),
            })
    except BaseException:
        crop_components = []

    provisional = _qqfarm_build_24_plot_ledger(
        {slot_id: {'state': 'empty'} for slot_id in slot_ids},
        frame_id=str(frame_id or ''),
        board_signature='',
        captured_at=_now_value(),
    )
    quad_scores = []
    marker_left = 0.0
    marker_right = max(18.0, 52.0 * lattice_scale)
    marker_top = -max(10.0, 21.0 * lattice_scale)
    marker_bottom = max(7.0, 11.0 * lattice_scale)
    for group in tuple(provisional.get('quad_groups') or ()):
        if not isinstance(group, (tuple, list)) or len(group) != 4:
            continue
        try:
            top_slot = str(group[0])
            top_x, top_y = centers[top_slot]
        except BaseException:
            continue
        matched = [
            component for component in crop_components
            if (
                float(top_x) + marker_left <= component['center'][0] <= float(top_x) + marker_right and
                float(top_y) + marker_top <= component['center'][1] <= float(top_y) + marker_bottom
            )
        ]
        score = int(sum(int(component['area']) for component in matched))
        if score >= max(8, int(round(45.0 * lattice_scale * lattice_scale))):
            quad_scores.append((tuple(group), score))

    # At most fifteen candidates exist, so a tiny exhaustive selection is more
    # explicit and safer than a greedy choice around overlapping isometric tiles.
    best_score = -1
    best_groups = ()

    def _select(index, selected, used_slots, score):
        nonlocal best_score, best_groups
        if index >= len(quad_scores):
            normalized = tuple(group for group, _value in selected)
            candidate_key = tuple(str(group) for group in normalized)
            best_key = tuple(str(group) for group in best_groups)
            if (
                score > best_score or
                (score == best_score and len(normalized) > len(best_groups)) or
                (score == best_score and len(normalized) == len(best_groups) and candidate_key < best_key)
            ):
                best_score = score
                best_groups = normalized
            return
        _select(index + 1, selected, used_slots, score)
        group, group_score = quad_scores[index]
        group_slots = set(group)
        if group_slots.isdisjoint(used_slots):
            _select(
                index + 1,
                selected + ((group, group_score),),
                used_slots | group_slots,
                score + int(group_score),
            )

    _select(0, (), set(), 0)

    # In the narrow mature-only full-board route, large flower platforms can
    # obscure the small foliage components used by the generic 2x2 scorer.
    # Accept this known three-platform geometry only from a normalized current
    # frame when every platform root has independent, local crop/flower pixels.
    # Terrain quality is deliberately not sampled here.  A physical-window
    # caller must still recurse through the normalized observation path below,
    # which strips all click authority before it can return a full-board result.
    if (
            crop_only_full_board and
            fit_reason == 'mature-mixed-full-board-only' and
            not physical_window_full_board_retry):
        mature_platform_groups = (
            ('L01', 'L03', 'L02', 'L05'),
            ('L06', 'L10', 'L09', 'L14'),
            ('L04', 'L08', 'L07', 'L12'),
        )
        try:
            transform = fit.get('transform') or {}
            crop_offset_normalized = float(
                transform.get('crop_anchor_offset_y', 0.0) or 0.0
            )
            valid_quad_groups = {
                tuple(str(slot_id) for slot_id in group)
                for group in tuple(provisional.get('quad_groups') or ())
                if isinstance(group, (tuple, list)) and len(group) == 4
            }

            def _mature_platform_root_has_current_frame_evidence(root_slot):
                if not (8.0 <= crop_offset_normalized <= 60.0):
                    return False
                root_x, root_y = centers[root_slot]
                crop_x = int(round(float(root_x)))
                crop_y = int(round(
                    float(root_y) +
                    crop_offset_normalized * float(height) / 800.0
                ))
                scale_x = float(width) / 428.0
                scale_y = float(height) / 800.0
                half_width = max(14, int(round(23.0 * scale_x)))
                half_height = max(16, int(round(29.0 * scale_y)))
                left = max(0, crop_x - half_width)
                right = min(width, crop_x + half_width + 1)
                top = max(0, crop_y - half_height)
                bottom = min(height, crop_y + half_height + 1)
                root_roi = hsv[top:bottom, left:right]
                if getattr(root_roi, 'size', 0) <= 0:
                    return False
                value = root_roi[:, :, 2]
                saturation = root_roi[:, :, 1]
                hue = root_roi[:, :, 0]
                visible = value >= 30
                saturated = (saturation >= 70) & (value >= 90)
                bright = value >= 170
                foliage = (
                    (hue >= 30) & (hue <= 100) &
                    (saturation >= 45) & (value >= 35)
                )
                flower = (
                    (hue >= 14) & (hue <= 39) &
                    (saturation >= 150) & (value >= 130)
                )
                crop_or_flower = foliage | flower
                return bool(
                    float(np_module.mean(visible)) >= 0.75 and
                    float(np_module.mean(saturated)) >= 0.35 and
                    float(np_module.mean(bright)) >= 0.40 and
                    float(np_module.mean(foliage)) >= 0.06 and
                    float(np_module.mean(flower)) >= 0.07 and
                    float(np_module.mean(crop_or_flower)) >= 0.16
                )

            if (
                    all(group in valid_quad_groups for group in mature_platform_groups) and
                    all(
                        _mature_platform_root_has_current_frame_evidence(group[0])
                        for group in mature_platform_groups
                    )):
                best_groups = mature_platform_groups
        except BaseException:
            pass

    # The seedling-only fitter is narrower than ordinary crop sampling: it
    # carries an explicit, complete proof made of valid 2x2 fruit groups plus
    # every remaining 1x1 seed mark.  Consume that proof verbatim only after
    # independently validating its slot identities and exact twenty-four-slot
    # union.  A malformed or incomplete proof stays unknown and cannot produce
    # a land-click candidate.
    seedling_observation_marker_slots = set()
    if fit_reason in (
            'seedling-only-full-board-observation',
            'mixed-seedling-platform-full-board-observation',
    ):
        try:
            transform = fit.get('transform') or {}
            raw_marker_slots = transform.get('seed_marker_slots') or ()
            raw_fruit_groups = transform.get('fruit_quad_groups') or ()
            if isinstance(raw_marker_slots, str) or isinstance(raw_fruit_groups, str):
                raise ValueError('invalid-observation-evidence')
            valid_quad_groups = {
                tuple(str(slot_id) for slot_id in group)
                for group in tuple(provisional.get('quad_groups') or ())
                if isinstance(group, (tuple, list)) and len(group) == 4
            }
            normalized_groups = []
            occupied_by_fruit = set()
            for raw_group in raw_fruit_groups:
                if not isinstance(raw_group, (tuple, list)) or len(raw_group) != 4:
                    raise ValueError('invalid-fruit-group')
                group = tuple(str(slot_id) for slot_id in raw_group)
                group_slots = set(group)
                if group not in valid_quad_groups or len(group_slots) != 4:
                    raise ValueError('unknown-fruit-group')
                if not group_slots.isdisjoint(occupied_by_fruit):
                    raise ValueError('overlapping-fruit-group')
                occupied_by_fruit.update(group_slots)
                normalized_groups.append(group)
            marker_slots = tuple(str(slot_id) for slot_id in raw_marker_slots)
            marker_slot_set = set(marker_slots)
            if (
                    len(normalized_groups) < 2 or
                    len(marker_slot_set) != len(marker_slots) or
                    not marker_slot_set.issubset(set(slot_ids)) or
                    not marker_slot_set.isdisjoint(occupied_by_fruit) or
                    marker_slot_set | occupied_by_fruit != set(slot_ids)):
                raise ValueError('incomplete-observation-evidence')
            best_groups = tuple(normalized_groups)
            seedling_observation_marker_slots = marker_slot_set
        except BaseException:
            return _unknown('crop-only-full-board-unconfirmed')

    occupied_2x2_slots = {
        slot_id for group in best_groups for slot_id in group
    }

    observations = {}
    for slot_id in slot_ids:
        observation = {'state': 'empty'}
        quality = anchor_quality.get(slot_id) or _quality_at(centers[slot_id])
        if quality in ('gold', 'purple'):
            observation['land_quality'] = quality
        if slot_id in occupied_2x2_slots:
            observation['state'] = 'occupied-2x2'
        elif slot_id in seedling_observation_marker_slots:
            observation['state'] = 'occupied-1x1'
        observations[slot_id] = observation

    # Mature crop geometry may prove an individual slot even when the usual
    # centre foliage sampler is covered by a timer, flower, or harvest-ready
    # animation.  Restrict this evidence to the mature full-board observer
    # reason; it is never reusable as empty-land click authority.
    mature_mixed_full_board = str(fit.get('reason') or '') in (
        'mature-mixed-full-board-only',
        'cropped-full-board-observation',
    )
    if mature_mixed_full_board:
        try:
            geometry_anchor_slots = {
                str(slot_id) for slot_id in tuple(
                    fit.get('geometry_anchor_slots') or ()
                ) if str(slot_id) in slot_ids
            }
        except BaseException:
            geometry_anchor_slots = set()
        for slot_id in geometry_anchor_slots:
            if observations[slot_id]['state'] == 'empty':
                observations[slot_id]['state'] = 'occupied-1x1'

    def _mature_warm_flower_evidence(center):
        """Detect a compact mature yellow flower at the fitted crop anchor."""
        if not mature_mixed_full_board:
            return False
        try:
            transform = fit.get('transform') or {}
            offset_normalized = float(transform.get('crop_anchor_offset_y', 0.0) or 0.0)
            if not (8.0 <= offset_normalized <= 60.0):
                return False
            center_x = int(round(float(center[0])))
            center_y = int(round(
                float(center[1]) + offset_normalized * float(height) / 800.0
            ))
            scale_x = float(width) / 428.0
            scale_y = float(height) / 800.0
            half_width = max(16, int(round(15.0 * scale_x)))
            half_height = max(16, int(round(15.0 * scale_y)))
            left = max(0, center_x - half_width)
            right = min(width, center_x + half_width + 1)
            top = max(0, center_y - half_height)
            bottom = min(height, center_y + half_height + 1)
            roi = hsv[top:bottom, left:right]
            if getattr(roi, 'size', 0) <= 0:
                return False
            warm_mask = (
                (roi[:, :, 0] >= 14) & (roi[:, :, 0] <= 39) &
                (roi[:, :, 1] >= 150) & (roi[:, :, 2] >= 130)
            ).astype(np_module.uint8)
            component_count, _labels, stats, _centroids = (
                cv_module.connectedComponentsWithStats(warm_mask, 8)
            )
            minimum_area = max(48, int(round(90.0 * scale_x * scale_y)))
            maximum_area = max(minimum_area + 1, int(round(360.0 * scale_x * scale_y)))
            maximum_width = max(10, int(round(32.0 * scale_x)))
            maximum_height = max(10, int(round(40.0 * scale_y)))
            roi_height, roi_width = int(roi.shape[0]), int(roi.shape[1])
            for component_index in range(1, int(component_count)):
                component_left = int(stats[component_index, cv_module.CC_STAT_LEFT])
                component_top = int(stats[component_index, cv_module.CC_STAT_TOP])
                component_width = int(stats[component_index, cv_module.CC_STAT_WIDTH])
                component_height = int(stats[component_index, cv_module.CC_STAT_HEIGHT])
                component_area = int(stats[component_index, cv_module.CC_STAT_AREA])
                if (
                        component_left <= 0 or component_top <= 0 or
                        component_left + component_width >= roi_width or
                        component_top + component_height >= roi_height):
                    continue
                if (
                        minimum_area <= component_area <= maximum_area and
                        5 <= component_width <= maximum_width and
                        5 <= component_height <= maximum_height):
                    return True
        except BaseException:
            return False
        return False

    # Existing 1x1 detection stays deliberately local.  It is evaluated only on
    # slots not already assigned to a complete 2x2 group, so crop fragments on a
    # merged platform cannot turn its neighbours into independent 1x1 plots.
    single_seedling_fn = globals().get('_empty_land_candidate_has_seedling_occupancy')
    single_cover_fn = globals().get('_empty_land_candidate_has_crop_cover')
    for slot_id in slot_ids:
        if observations[slot_id]['state'] != 'empty':
            continue
        occupied_1x1 = False
        try:
            if callable(single_seedling_fn) and bool(single_seedling_fn(image, centers[slot_id])):
                occupied_1x1 = True
            elif callable(single_cover_fn) and bool(single_cover_fn(image, centers[slot_id])):
                occupied_1x1 = True
            elif mature_mixed_full_board:
                transform = fit.get('transform') or {}
                offset_normalized = float(
                    transform.get('crop_anchor_offset_y', 0.0) or 0.0
                )
                crop_anchor_center = (
                    int(round(float(centers[slot_id][0]))),
                    int(round(
                        float(centers[slot_id][1]) +
                        offset_normalized * float(height) / 800.0
                    )),
                )
                if callable(single_cover_fn) and bool(
                        single_cover_fn(image, crop_anchor_center)):
                    occupied_1x1 = True
                elif _mature_warm_flower_evidence(centers[slot_id]):
                    occupied_1x1 = True
        except BaseException:
            occupied_1x1 = False
        if occupied_1x1:
            observations[slot_id]['state'] = 'occupied-1x1'

    if crop_only_full_board:
        all_slots_confirmed_occupied = all(
            str(observations.get(slot_id, {}).get('state') or '').startswith(
                'occupied-'
            )
            for slot_id in slot_ids
        )
        if not all_slots_confirmed_occupied:
            # The ordinary desktop capture path already performs this resize.
            # Apply a narrowly gated second observation when a full physical QQ
            # window reached the ledger directly.  This retry cannot authorize
            # planting: it is accepted only for an exact 24 occupied / 0 empty /
            # 0 unknown result and is downgraded to observation-only below.
            if physical_window_full_board_retry:
                try:
                    normalized_image = cv_module.resize(
                        image, (428, 800), interpolation=cv_module.INTER_AREA
                    )
                    normalized_ledger = (
                        _qqfarm_capture_current_frame_24_slot_ledger(
                            normalized_image,
                            frame_id=frame_id,
                            captured_at=captured_at,
                        )
                    )
                    normalized_full_board = bool(
                        isinstance(normalized_ledger, dict) and
                        str(normalized_ledger.get('capture_status') or '') ==
                        'aligned' and
                        not bool(normalized_ledger.get('ui_blocked')) and
                        bool(normalized_ledger.get('full_board_confirmed')) and
                        int(normalized_ledger.get('occupied_count') or 0) == 24 and
                        int(normalized_ledger.get('empty_count') or 0) == 0 and
                        int(normalized_ledger.get('unknown_count') or 0) == 0
                    )
                    if normalized_full_board:
                        normalized_ledger.update({
                            'capture_reason': (
                                'physical-window-normalized-full-board-observation'
                            ),
                            'click_safe': False,
                            'observation_only': True,
                            'slot_centers': {},
                            'complete_2x2_groups': (),
                            'physical_window_normalized': True,
                        })
                        return normalized_ledger
                except BaseException:
                    pass
            return _unknown('crop-only-full-board-unconfirmed')

    # The board signature is geometry-only and intentionally ignores crop pixels.
    # Two fresh frames can compare only when their refitted current camera grid
    # resolves to the same quantized geometry.
    quantizer = max(2, int(round(4.0 * lattice_scale)))
    signature_parts = []
    for slot_id in slot_ids:
        center_x, center_y = centers[slot_id]
        signature_parts.append(
            '%s:%d,%d' % (
                slot_id,
                int(round(float(center_x) / float(quantizer))),
                int(round(float(center_y) / float(quantizer))),
            )
        )
    board_signature = 'qqfarm-current-24-v1|' + '|'.join(signature_parts)
    if not frame_id:
        frame_id = 'current-frame-%d-%d' % (
            int(id(image)), int(round(_now_value() * 1000000.0))
        )
    ledger = _qqfarm_build_24_plot_ledger(
        observations,
        frame_id=str(frame_id),
        board_signature=board_signature,
        captured_at=_now_value(),
    )
    if observation_only_full_board and not bool(ledger.get('full_board_confirmed')):
        return _unknown('crop-only-full-board-unconfirmed')
    ledger.update({
        'capture_status': 'aligned',
        'capture_reason': str(fit_reason or 'geometry-anchors'),
        'click_safe': not bool(observation_only_full_board),
        'observation_only': bool(observation_only_full_board),
        'cropped_full_board_observation': bool(cropped_full_board_observation),
        'mixed_seedling_platform_full_board_observation': bool(
            mixed_seedling_platform_full_board_observation
        ),
        'slot_centers': {} if observation_only_full_board else centers,
        'complete_2x2_groups': (
            () if observation_only_full_board else tuple(best_groups)
        ),
        'geometry_anchor_slots': tuple(fit.get('geometry_anchor_slots') or ()),
        'matched_anchor_count': int(fit.get('matched_anchor_count') or 0),
        'unmatched_anchor_count': int(fit.get('unmatched_anchor_count') or 0),
        'ignored_geometry_anchor_count': int(
            fit.get('ignored_geometry_anchor_count') or 0
        ),
    })
    # A raw portrait PrintWindow frame can prove an already-full board, but it
    # is never a coordinate authority.  This also covers seedling geometry
    # which may fit directly before the legacy crop-only resize retry runs.
    if physical_window_full_board_retry:
        physical_full_board = bool(
            not bool(ledger.get('ui_blocked')) and
            bool(ledger.get('full_board_confirmed')) and
            int(ledger.get('occupied_count') or 0) == 24 and
            int(ledger.get('empty_count') or 0) == 0 and
            int(ledger.get('unknown_count') or 0) == 0
        )
        if physical_full_board:
            ledger.update({
                'capture_reason': (
                    'physical-window-normalized-full-board-observation'
                ),
                'click_safe': False,
                'observation_only': True,
                'slot_centers': {},
                'complete_2x2_groups': (),
                'physical_window_normalized': True,
            })
    return ledger

def _qqfarm_resolve_attempted_slot_ids(
        ledger, attempted_lands, *, planting_mode=''):
    """Resolve one current 1x1 plot or one complete physical 2x2 group."""
    result = {
        'resolved': False,
        'reason': 'invalid-ledger',
        'attempted_slots': (),
        'mapped_slots': (),
        'planting_mode': '',
    }
    expected_slot_ids = tuple('L%02d' % index for index in range(1, 25))
    try:
        mode = str(planting_mode or '').strip().lower().replace('×', 'x')
    except BaseException:
        mode = ''
    if mode not in ('1x1', '2x2'):
        result['reason'] = 'unsupported-planting-mode'
        return result
    result['planting_mode'] = mode
    if not isinstance(ledger, dict):
        result['reason'] = 'missing-before-ledger'
        return result
    if bool(ledger.get('ui_blocked')):
        result['reason'] = 'ui-overlay-visible'
        return result
    try:
        capture_status = str(ledger.get('capture_status', 'aligned') or 'aligned')
        capture_reason = str(ledger.get('capture_reason', '') or '')
    except BaseException:
        capture_status = 'unknown'
        capture_reason = ''
    if capture_status != 'aligned':
        result['reason'] = capture_reason or 'viewport-not-full-board'
        return result
    try:
        slots = ledger.get('slots', {})
        slot_ids = tuple(ledger.get('slot_ids', ()))
        centers = ledger.get('slot_centers', {})
    except BaseException:
        slots = {}
        slot_ids = ()
        centers = {}
    if slot_ids != expected_slot_ids or not isinstance(slots, dict) or not isinstance(centers, dict):
        return result
    if bool(ledger.get('invalid_slot_ids')) or bool(ledger.get('invalid_quad_groups')):
        return result
    try:
        unknown_count = int(ledger.get('unknown_count', 0) or 0)
    except BaseException:
        unknown_count = 24
    if unknown_count or any(
            str((slots.get(slot_id) or {}).get('state', 'unknown')) == 'unknown'
            for slot_id in expected_slot_ids):
        result['reason'] = 'unknown-slot-state'
        return result

    def _as_center(value):
        try:
            if isinstance(value, dict):
                value = value.get('center', value.get('land_center'))
            elif not isinstance(value, (tuple, list)):
                value = getattr(value, 'center', None)
            if not isinstance(value, (tuple, list)) or len(value) < 2:
                return None
            x_value = float(value[0])
            y_value = float(value[1])
            math_module = __import__('math')
            if not math_module.isfinite(x_value) or not math_module.isfinite(y_value):
                return None
            return (x_value, y_value)
        except BaseException:
            return None

    center_by_slot = {}
    for slot_id in expected_slot_ids:
        center = _as_center(centers.get(slot_id))
        if center is None:
            result['reason'] = 'missing-slot-center'
            return result
        center_by_slot[slot_id] = center
    try:
        raw_lands = list(attempted_lands or ())
    except BaseException:
        raw_lands = []
    expected_count = 1 if mode == '1x1' else 4
    if len(raw_lands) != expected_count:
        result['reason'] = 'invalid-attempted-land-count'
        return result
    projected_centers = []
    for land in raw_lands:
        center = _as_center(land)
        if center is None:
            result['reason'] = 'missing-attempted-land-center'
            return result
        projected_centers.append(center)
    pair_distances = []
    center_values = list(center_by_slot.values())
    for left_index, left_center in enumerate(center_values):
        for right_center in center_values[left_index + 1:]:
            dx = float(left_center[0]) - float(right_center[0])
            dy = float(left_center[1]) - float(right_center[1])
            distance = (dx * dx + dy * dy) ** 0.5
            if distance > 0.0:
                pair_distances.append(distance)
    minimum_spacing = min(pair_distances) if pair_distances else 0.0
    maximum_distance = max(6.0, min(26.0, minimum_spacing * 0.45))
    mapped = []
    for center in projected_centers:
        nearest_slot, nearest_distance = min(
            ((slot_id, ((center[0] - point[0]) ** 2 + (center[1] - point[1]) ** 2) ** 0.5)
             for slot_id, point in center_by_slot.items()),
            key=lambda item: (item[1], item[0]),
        )
        if nearest_distance > maximum_distance:
            result['reason'] = 'attempted-land-not-on-current-grid'
            return result
        mapped.append(nearest_slot)
    mapped_slots = tuple(mapped)
    result['mapped_slots'] = mapped_slots
    if len(set(mapped_slots)) != expected_count:
        result['reason'] = 'duplicate-attempted-slot'
        return result
    if any(
            str((slots.get(slot_id) or {}).get('state', 'unknown')) != 'empty'
            for slot_id in mapped_slots):
        result['reason'] = 'attempted-slot-not-empty'
        return result
    if mode == '1x1':
        result.update({
            'resolved': True,
            'reason': 'resolved',
            'attempted_slots': mapped_slots,
        })
        return result
    try:
        raw_groups = ledger.get('quad_groups', ())
    except BaseException:
        raw_groups = ()
    mapped_set = frozenset(mapped_slots)
    for raw_group in raw_groups or ():
        try:
            group = tuple(str(slot_id) for slot_id in raw_group)
        except BaseException:
            continue
        if len(group) == 4 and len(set(group)) == 4 and frozenset(group) == mapped_set:
            result.update({
                'resolved': True,
                'reason': 'resolved',
                'attempted_slots': group,
            })
            return result
    result['reason'] = 'incomplete-quad-group'
    return result


def _qqfarm_commit_current_frame_planting_transaction(
        context, before_ledger, after_ledger=None, *, attempted_slots=(),
        planting_mode='', rejection_reason=''):
    """Validate and retain a fixed-slot planting transaction for one action."""
    try:
        attempted = tuple(str(slot_id) for slot_id in attempted_slots)
    except BaseException:
        attempted = ()
    try:
        mode = str(planting_mode or '').strip().lower().replace('×', 'x')
    except BaseException:
        mode = ''

    def _ledger_fields(ledger):
        if not isinstance(ledger, dict):
            return 0, '', ''
        try:
            slots = ledger.get('slots', {})
            empty_count = sum(
                1 for slot_id in tuple('L%02d' % index for index in range(1, 25))
                if isinstance(slots.get(slot_id), dict) and
                str(slots[slot_id].get('state', 'unknown')) == 'empty'
            )
        except BaseException:
            empty_count = 0
        try:
            frame_id = str(ledger.get('frame_id', '') or '')
            reason = str(ledger.get('capture_reason', '') or '')
        except BaseException:
            frame_id = ''
            reason = ''
        return int(empty_count), frame_id, reason

    before_empty_count, before_frame_id, before_capture_reason = _ledger_fields(before_ledger)
    after_empty_count, after_frame_id, after_capture_reason = _ledger_fields(after_ledger)
    result = {
        'committed': False,
        'delta': 0,
        'committed_slots': (),
        'attempted_slots': attempted,
        'planting_mode': mode,
        'before_empty_count': before_empty_count,
        'after_empty_count': after_empty_count,
        'before_frame_id': before_frame_id,
        'after_frame_id': after_frame_id,
        'reason': 'missing-before-ledger',
    }

    def _preflight_reason(ledger, missing_reason):
        if not isinstance(ledger, dict):
            return missing_reason
        if bool(ledger.get('ui_blocked')):
            return 'ui-overlay-visible'
        try:
            capture_status = str(ledger.get('capture_status', 'aligned') or 'aligned')
            capture_reason = str(ledger.get('capture_reason', '') or '')
        except BaseException:
            capture_status = 'unknown'
            capture_reason = ''
        if capture_status != 'aligned':
            return capture_reason or 'viewport-not-full-board'
        try:
            if int(ledger.get('unknown_count', 0) or 0) > 0:
                return 'unknown-slot-state'
            slots = ledger.get('slots', {})
            if any(
                    str((slots.get(slot_id) or {}).get('state', 'unknown')) == 'unknown'
                    for slot_id in tuple('L%02d' % index for index in range(1, 25))):
                return 'unknown-slot-state'
        except BaseException:
            return 'unknown-slot-state'
        return ''

    try:
        requested_rejection = str(rejection_reason or '').strip()
    except BaseException:
        requested_rejection = ''
    if requested_rejection:
        reason = requested_rejection
    else:
        reason = _preflight_reason(before_ledger, 'missing-before-ledger')
        if not reason:
            reason = _preflight_reason(after_ledger, 'missing-after-ledger')
    if reason:
        result['reason'] = reason
    else:
        try:
            validated = _qqfarm_validate_24_plot_transaction(
                before_ledger, after_ledger, attempted_slots=attempted,
                planting_mode=mode,
            )
        except BaseException:
            validated = {'committed': False, 'reason': 'invalid-ledger'}
        if isinstance(validated, dict):
            result.update({
                'committed': bool(validated.get('committed', False)),
                'delta': int(validated.get('delta', 0) or 0),
                'committed_slots': tuple(validated.get('committed_slots', ()) or ()),
                'attempted_slots': tuple(validated.get('attempted_slots', attempted) or ()),
                'reason': str(validated.get('reason', 'invalid-ledger') or 'invalid-ledger'),
            })
    def _sync_exact_pending_slots(ledger):
        """Copy only one aligned, fully-known ledger into the actionable queue."""
        if context is None or not isinstance(ledger, dict):
            return False
        try:
            if _preflight_reason(ledger, 'invalid-pending-ledger'):
                return False
            slots = ledger.get('slots', {})
            slot_centers = ledger.get('slot_centers', {})
            if not isinstance(slots, dict) or not isinstance(slot_centers, dict):
                return False
        except BaseException:
            return False
        slot_ids = tuple(
            'L%02d' % index for index in range(1, 25)
            if str((slots.get('L%02d' % index) or {}).get(
                'state', 'unknown'
            )) == 'empty'
        )
        pending_lands = []
        for slot_id in slot_ids:
            try:
                raw_center = tuple(slot_centers.get(slot_id))
                if len(raw_center) < 2:
                    return False
                center = (
                    int(round(float(raw_center[0]))),
                    int(round(float(raw_center[1]))),
                )
            except BaseException:
                return False
            pending_lands.append({'slot_id': slot_id, 'center': center})
        try:
            captured_at = float(ledger.get('captured_at', 0.0) or 0.0)
        except BaseException:
            captured_at = 0.0
        try:
            setattr(context, '_qqfarm_fixed_slot_pending_slot_ids', slot_ids)
            setattr(context, '_qqfarm_fixed_slot_pending_lands', list(pending_lands))
            setattr(context, '_qqfarm_recent_empty_lands', list(pending_lands))
            setattr(context, '_qqfarm_recent_empty_land_count', len(pending_lands))
            setattr(context, '_qqfarm_recent_empty_land_centers', [
                tuple(item['center']) for item in pending_lands
            ])
            setattr(context, '_qqfarm_recent_empty_land_ts', captured_at)
        except BaseException:
            return False
        return True

    try:
        if context is not None:
            setattr(context, '_qqfarm_last_planting_transaction', result)
            source_ledger = after_ledger if bool(result.get('committed')) else before_ledger
            _sync_exact_pending_slots(source_ledger)
    except BaseException:
        pass
    return result


def _wrap_planting_outcome_verify_func(fn, name=''):
    """Require a fresh empty-land decrease before trusting a planting success."""
    try:
        if not callable(fn):
            return fn, False
        if bool(getattr(fn, '__qqfarm_planting_outcome_verify_wrapped__', False)):
            return fn, False

        def _wrapped(*args, **kwargs):
            bot = kwargs.get('bot')
            if bot is None:
                try:
                    bot = getattr(fn, '__self__', None)
                except BaseException:
                    bot = None
            if bot is None:
                for value in args:
                    try:
                        if value is None or isinstance(
                            value, (str, bytes, int, float, bool, list, tuple, dict, set)
                        ):
                            continue
                        if any(hasattr(value, attr) for attr in (
                            '_qqfarm_recent_empty_land_count',
                            '_qqfarm_recent_empty_lands',
                            'planting_auto_fertilize_one',
                            'auto_fertilize_one',
                        )):
                            bot = value
                            break
                    except BaseException:
                        pass
            if bot is None:
                return fn(*args, **kwargs)
            try:
                if bool(getattr(bot, '_qqfarm_planting_outcome_verify_active', False)):
                    return fn(*args, **kwargs)
            except BaseException:
                pass

            input_land_count = 0
            input_lands = []
            action_frame = None
            bound_arguments = {}
            try:
                inspect_module = __import__('inspect')
                inspect_target = getattr(
                    fn, '__qqfarm_planting_crop_context_orig__', fn
                )
                bound = inspect_module.signature(inspect_target).bind_partial(
                    *args, **kwargs
                )
                bound_arguments = dict(bound.arguments)
                for parameter_name, value in bound_arguments.items():
                    if 'land' not in str(parameter_name).lower():
                        continue
                    if isinstance(value, (str, bytes, dict)):
                        continue
                    try:
                        input_land_count = max(input_land_count, len(list(value or [])))
                    except BaseException:
                        pass
            except BaseException:
                bound_arguments = dict(kwargs or {})
                for parameter_name, value in bound_arguments.items():
                    if 'land' not in str(parameter_name).lower():
                        continue
                    if isinstance(value, (str, bytes, dict)):
                        continue
                    try:
                        input_land_count = max(input_land_count, len(list(value or [])))
                    except BaseException:
                        pass
            for parameter_name, value in bound_arguments.items():
                parameter_key = str(parameter_name or '').strip().lower()
                try:
                    if (
                        action_frame is None and
                        any(token in parameter_key for token in (
                            'frame', 'screenshot', 'image', 'img'
                        )) and
                        len(getattr(value, 'shape', ())) >= 2
                    ):
                        action_frame = value
                except BaseException:
                    pass
                if 'land' not in parameter_key or isinstance(
                    value, (str, bytes, dict)
                ):
                    continue
                try:
                    candidate_lands = list(value or [])
                except BaseException:
                    candidate_lands = []
                if len(candidate_lands) > len(input_lands):
                    input_lands = candidate_lands
            action_seed_center = None
            action_seed_candidate = None
            for parameter_name, value in bound_arguments.items():
                parameter_key = str(parameter_name or '').strip().lower()
                if 'seed' not in parameter_key and 'candidate' not in parameter_key:
                    continue
                center = None
                try:
                    if isinstance(value, dict):
                        center = value.get('center', value.get('seed_center'))
                    else:
                        center = getattr(value, 'center', None)
                        if center is None:
                            center = getattr(value, 'seed_center', None)
                    if isinstance(center, (tuple, list)) and len(center) >= 2:
                        action_seed_center = (
                            int(round(float(center[0]))),
                            int(round(float(center[1]))),
                        )
                        action_seed_candidate = value if isinstance(value, dict) else {
                            'center': action_seed_center
                        }
                        break
                except BaseException:
                    action_seed_center = None
                    action_seed_candidate = None
            quad_candidate_fn = globals().get('_qqfarm_candidate_is_quad_seed')
            explicit_quad_candidate = bool(
                callable(quad_candidate_fn) and
                quad_candidate_fn(action_seed_candidate, bot=bot)
            )
            if explicit_quad_candidate and input_land_count < 4:
                quarantine_fn = globals().get(
                    '_qqfarm_quarantine_backpack_candidate'
                )
                if callable(quarantine_fn) and action_seed_center is not None:
                    try:
                        quarantine_fn(
                            bot, action_seed_center, ttl=180.0,
                            reason='quad-seed-without-complete-group',
                            candidate=action_seed_candidate, frame=action_frame,
                            fingerprint_label='quad-seed',
                        )
                    except BaseException:
                        pass
                try:
                    setattr(bot, '_qqfarm_quad_skip_and_continue', True)
                    if bool(getattr(
                        bot, '_qqfarm_backpack_profile_active', False
                    )):
                        setattr(
                            bot, '_qqfarm_backpack_round_no_progress_attempts',
                            max(0, int(getattr(
                                bot, '_qqfarm_backpack_round_no_progress_attempts', 0
                            ) or 0)) + 1,
                        )
                    _write(
                        'v361 blocked 2x2 backpack seed on incomplete plot group '
                        'empty=' + str(input_land_count) + ' center=' +
                        repr(action_seed_center) + ' name=' + str(name)
                    )
                except BaseException:
                    pass
                return False
            if action_seed_center is not None:
                try:
                    time_module = globals().get('time') or __import__('time')
                    now_value = float(time_module.time())
                    raw_skipped = getattr(
                        bot, '_qqfarm_backpack_skip_candidate_until', {}
                    )
                    skipped_until = float(
                        raw_skipped.get(action_seed_center, 0.0)
                        if isinstance(raw_skipped, dict) else 0.0
                    )
                    quarantine_check = globals().get(
                        '_qqfarm_backpack_candidate_is_quarantined'
                    )
                    is_quarantined = bool(
                        quarantine_check(
                            bot,
                            action_seed_candidate or {'center': action_seed_center},
                            frame=action_frame, now_ts=now_value,
                        )
                        if callable(quarantine_check) else
                        skipped_until > now_value
                    )
                    if is_quarantined:
                        _write(
                            'v351 skipped quarantined backpack seed inside native '
                            'candidate loop center=' + repr(action_seed_center) +
                            ' until=' + ('%.3f' % skipped_until) +
                            ' name=' + str(name)
                        )
                        return False
                except BaseException:
                    pass
            if action_seed_center is not None and action_frame is not None:
                try:
                    popup_fn = globals().get('_qqfarm_backpack_nonseed_popup')
                    popup_proof = (
                        popup_fn(action_frame) if callable(popup_fn) else None
                    )
                except BaseException:
                    popup_proof = None
                if isinstance(popup_proof, dict):
                    try:
                        popup_candidate = popup_proof.get('candidate_center')
                        popup_matches_candidate = bool(
                            isinstance(popup_candidate, (tuple, list)) and
                            len(popup_candidate) >= 2 and
                            abs(int(action_seed_center[0]) - int(popup_candidate[0])) <= 24 and
                            abs(int(action_seed_center[1]) - int(popup_candidate[1])) <= 48
                        )
                    except BaseException:
                        popup_matches_candidate = False
                    if not popup_matches_candidate:
                        popup_proof = None
                if isinstance(popup_proof, dict):
                    quarantine_fn = globals().get(
                        '_qqfarm_quarantine_backpack_candidate'
                    )
                    if callable(quarantine_fn):
                        try:
                            quarantine_fn(
                                bot, action_seed_center, ttl=900.0,
                                reason='visible-' + str(
                                    popup_proof.get('kind', 'nonseed')
                                ),
                                candidate=action_seed_candidate,
                                frame=action_frame,
                                fingerprint_label=str(
                                    popup_proof.get('label', '') or
                                    popup_proof.get('kind', 'nonseed')
                                ),
                            )
                        except BaseException:
                            pass
                    try:
                        if bool(getattr(
                            bot, '_qqfarm_backpack_profile_active', False
                        )):
                            setattr(
                                bot, '_qqfarm_backpack_round_no_progress_attempts',
                                max(0, int(getattr(
                                    bot, '_qqfarm_backpack_round_no_progress_attempts', 0
                                ) or 0)) + 1,
                            )
                    except BaseException:
                        pass
                    try:
                        _write(
                            'v360 nonseed backpack item rejected before planting '
                            'kind=' + str(popup_proof.get('kind', '')) +
                            ' score=' + ('%.4f' % float(
                                popup_proof.get('score', 0.0) or 0.0
                            )) + ' center=' + repr(action_seed_center) +
                            ' name=' + str(name)
                        )
                    except BaseException:
                        pass
                    return False
            try:
                round_active = bool(getattr(
                    bot, '_qqfarm_backpack_profile_active', False
                ))
            except BaseException:
                round_active = False
            if round_active:
                try:
                    time_module = globals().get('time') or __import__('time')
                    round_now = float(time_module.time())
                    round_deadline = float(getattr(
                        bot, '_qqfarm_backpack_round_deadline_ts', 0.0
                    ) or 0.0)
                    round_started = float(getattr(
                        bot, '_qqfarm_backpack_round_started_ts', 0.0
                    ) or 0.0)
                    round_actions = max(0, int(getattr(
                        bot, '_qqfarm_backpack_round_action_attempts', 0
                    ) or 0))
                    round_no_progress = max(0, int(getattr(
                        bot, '_qqfarm_backpack_round_no_progress_attempts', 0
                    ) or 0))
                    fixed_slot_chain_active = bool(getattr(
                        bot, '_qqfarm_fixed_slot_chain_active', False
                    ))
                    fixed_slot_chain_deadline = float(getattr(
                        bot, '_qqfarm_fixed_slot_chain_deadline_ts', 0.0
                    ) or 0.0)
                    fixed_slot_chain_started = float(getattr(
                        bot, '_qqfarm_fixed_slot_chain_started_ts', 0.0
                    ) or 0.0)
                except BaseException:
                    round_now = 0.0
                    round_deadline = 0.0
                    round_started = 0.0
                    round_actions = 0
                    round_no_progress = 0
                    fixed_slot_chain_active = False
                    fixed_slot_chain_deadline = 0.0
                    fixed_slot_chain_started = 0.0
                if fixed_slot_chain_active and fixed_slot_chain_deadline > 0.0:
                    # v382: the 24-slot transaction chain owns one absolute 120s
                    # deadline.  A per-card wrapper must never replace it with a
                    # fresh 60s backpack-round budget.
                    round_deadline = fixed_slot_chain_deadline
                    if fixed_slot_chain_started > 0.0:
                        round_started = fixed_slot_chain_started
                    try:
                        setattr(
                            bot, '_qqfarm_backpack_round_deadline_ts', round_deadline
                        )
                        if round_started > 0.0:
                            setattr(
                                bot, '_qqfarm_backpack_round_started_ts', round_started
                            )
                    except BaseException:
                        pass
                elif (
                    round_actions <= 0 and
                    (
                        round_started <= 0.0 or
                        round_deadline <= 0.0 or
                        round_now >= round_deadline
                    )
                ):
                    round_started = round_now
                    round_deadline = round_now + 60.0
                    try:
                        setattr(
                            bot, '_qqfarm_backpack_round_started_ts', round_started
                        )
                        setattr(
                            bot, '_qqfarm_backpack_round_deadline_ts', round_deadline
                        )
                        _write(
                            'v363 backpack action budget started after inventory scan '
                            'deadline=' + ('%.3f' % round_deadline) +
                            ' center=' + repr(action_seed_center) +
                            ' name=' + str(name)
                        )
                    except BaseException:
                        pass
                try:
                    fast_candidate_round = bool(getattr(
                        bot, '_qqfarm_backpack_fast_candidate_round_active', False
                    ))
                except BaseException:
                    fast_candidate_round = False
                round_no_progress_limit = 5 if fast_candidate_round else 2
                if (
                    round_no_progress >= round_no_progress_limit or
                    (round_deadline > 0.0 and round_now >= round_deadline)
                ):
                    quarantine_fn = globals().get(
                        '_qqfarm_quarantine_backpack_candidate'
                    )
                    if callable(quarantine_fn) and action_seed_center is not None:
                        try:
                            quarantine_fn(
                                bot, action_seed_center, ttl=30.0,
                                reason='round-action-budget',
                            )
                        except BaseException:
                            pass
                    try:
                        _write(
                            'v360 backpack round action budget exhausted '
                            'no_progress=' + str(round_no_progress) +
                            ' deadline=' + ('%.3f' % round_deadline) +
                            ' center=' + repr(action_seed_center) +
                            ' name=' + str(name)
                        )
                    except BaseException:
                        pass
                    return False
                try:
                    setattr(
                        bot, '_qqfarm_backpack_round_action_attempts',
                        max(0, int(getattr(
                            bot, '_qqfarm_backpack_round_action_attempts', 0
                        ) or 0)) + 1,
                    )
                except BaseException:
                    pass
            try:
                cached_empty_count = max(0, int(getattr(
                    bot, '_qqfarm_recent_empty_land_count', 0
                ) or 0))
            except BaseException:
                cached_empty_count = 0
            baseline_empty_count = max(input_land_count, cached_empty_count)
            invoke_args = list(args or ())
            invoke_kwargs = dict(kwargs or {})
            try:
                nested_single_land_mode = bool(getattr(
                    bot, '_qqfarm_backpack_single_land_mode', False
                ))
            except BaseException:
                nested_single_land_mode = False
            if nested_single_land_mode and input_land_count > 1:
                try:
                    inspect_module = __import__('inspect')
                    inspect_target = getattr(
                        fn, '__qqfarm_planting_crop_context_orig__', fn
                    )
                    signature = inspect_module.signature(inspect_target)
                    positional_names = [
                        parameter_name
                        for parameter_name, parameter in signature.parameters.items()
                        if parameter.kind in (
                            inspect_module.Parameter.POSITIONAL_ONLY,
                            inspect_module.Parameter.POSITIONAL_OR_KEYWORD,
                        )
                    ]
                    target_center = getattr(
                        bot, '_qqfarm_backpack_single_land_attempt_center', None
                    )
                    if isinstance(target_center, (tuple, list)) and len(target_center) >= 2:
                        target_center = (
                            int(target_center[0]), int(target_center[1])
                        )
                    else:
                        target_center = None
                    for parameter_name, value in bound_arguments.items():
                        if 'lands' not in str(parameter_name).lower():
                            continue
                        if isinstance(value, (str, bytes, dict)):
                            continue
                        current_lands = list(value or [])
                        if len(current_lands) <= 1:
                            continue

                        def _nested_land_center(land):
                            try:
                                center = land.get('center') if isinstance(land, dict) else None
                                if isinstance(center, (tuple, list)) and len(center) >= 2:
                                    return (int(center[0]), int(center[1]))
                            except BaseException:
                                pass
                            return None

                        candidate_indices = list(range(len(current_lands)))
                        if target_center is not None:
                            selected_index = min(
                                candidate_indices,
                                key=lambda index: (
                                    (
                                        (_nested_land_center(current_lands[index])[0] - target_center[0]) ** 2 +
                                        (_nested_land_center(current_lands[index])[1] - target_center[1]) ** 2
                                    )
                                    if _nested_land_center(current_lands[index]) is not None
                                    else 10 ** 12,
                                    index,
                                ),
                            )
                        else:
                            selected_index = min(
                                candidate_indices,
                                key=lambda index: (
                                    _nested_land_center(current_lands[index])[1]
                                    if _nested_land_center(current_lands[index]) is not None
                                    else 10 ** 9,
                                    index,
                                ),
                            )
                        selected_land = current_lands[selected_index]
                        selected_center = _nested_land_center(selected_land)
                        narrowed_lands = [selected_land]
                        if parameter_name in invoke_kwargs:
                            invoke_kwargs[parameter_name] = narrowed_lands
                        elif parameter_name in positional_names:
                            position = positional_names.index(parameter_name)
                            if position < len(invoke_args):
                                invoke_args[position] = narrowed_lands
                            else:
                                invoke_kwargs[parameter_name] = narrowed_lands
                        else:
                            invoke_kwargs[parameter_name] = narrowed_lands
                        try:
                            if selected_center is not None:
                                setattr(
                                    bot,
                                    '_qqfarm_backpack_single_land_attempt_center',
                                    selected_center,
                                )
                        except BaseException:
                            pass
                        _write(
                            'v307 nested single-land planting selected=' +
                            repr(selected_center) + ' original=' +
                            str(len(current_lands)) + ' name=' + str(name)
                        )
                        break
                except BaseException as e:
                    try:
                        _write(
                            'v307 nested single-land planting narrow error ' +
                            repr(e) + ' name=' + str(name)
                        )
                    except BaseException:
                        pass
            # Native planting handlers may optimistically consume a periodic or
            # harvest queue before this wrapper sees the post-action frame.  Keep
            # only the small, hook-owned scheduling/inventory state needed to
            # retry self-farm work when the visual outcome is rejected.  Never
            # roll back the current empty-land observation itself: it remains the
            # authority for the next verification pass.
            pre_action_state = {}
            for attr_name in (
                'planting_periodic_quota',
                'planting_harvest_quota',
                '_qqfarm_single_harvest_planting_pending',
                '_qqfarm_pending_radish_planting_claim_count',
                '_qqfarm_pending_radish_planting_claim_ts',
                '_qqfarm_radish_inventory_qty',
                '_qqfarm_radish_inventory_seen_ts',
                '_qqfarm_radish_inventory_retry_count',
                '_qqfarm_buy_seed_return_empty_lands',
                '_qqfarm_buy_seed_return_direct_land',
            ):
                present = False
                value = None
                try:
                    value = getattr(bot, attr_name)
                    present = True
                    if isinstance(value, list):
                        value = list(value)
                    elif isinstance(value, dict):
                        value = dict(value)
                    elif isinstance(value, set):
                        value = set(value)
                except BaseException:
                    present = False
                    value = None
                pre_action_state[attr_name] = (present, value)

            def _restore_unverified_planting_state():
                restored = []
                for attr_name, saved in pre_action_state.items():
                    present, value = saved
                    try:
                        if present:
                            if isinstance(value, list):
                                restored_value = list(value)
                            elif isinstance(value, dict):
                                restored_value = dict(value)
                            elif isinstance(value, set):
                                restored_value = set(value)
                            else:
                                restored_value = value
                            setattr(bot, attr_name, restored_value)
                        elif hasattr(bot, attr_name):
                            delattr(bot, attr_name)
                        restored.append(attr_name)
                    except BaseException:
                        pass
                try:
                    if restored:
                        _write(
                            'v264 restored unverified planting business state attrs=' +
                            ','.join(restored) + ' name=' + str(name)
                        )
                except BaseException:
                    pass

            def _mark_strict_outcome_unverified(transaction=None):
                """Clear stale planting-success proof after any strict rejection."""
                try:
                    if not isinstance(transaction, dict):
                        transaction = getattr(
                            bot, '_qqfarm_last_planting_transaction', None
                        )
                except BaseException:
                    transaction = None
                if not isinstance(transaction, dict):
                    transaction = {}
                try:
                    before_empty_count = max(0, int(
                        transaction.get('before_empty_count', 0) or 0
                    ))
                except BaseException:
                    before_empty_count = 0
                try:
                    after_empty_value = transaction.get(
                        'after_empty_count', before_empty_count
                    )
                    if after_empty_value is None:
                        after_empty_value = before_empty_count
                    after_empty_count = max(0, int(after_empty_value))
                except BaseException:
                    after_empty_count = before_empty_count
                try:
                    setattr(bot, '_qqfarm_last_planting_outcome_verified', False)
                    setattr(
                        bot, '_qqfarm_last_planting_outcome_before',
                        before_empty_count,
                    )
                    setattr(
                        bot, '_qqfarm_last_planting_outcome_after',
                        after_empty_count,
                    )
                except BaseException:
                    pass

            try:
                started_ts = __import__('time').time()
            except BaseException:
                started_ts = 0.0
            quad_overlay_confirmed_this_action = False
            post_action_nonseed_rejected = False

            def _record_backpack_no_progress(reason, ttl=180.0):
                if action_seed_center is not None:
                    quarantine_fn = globals().get(
                        '_qqfarm_quarantine_backpack_candidate'
                    )
                    if callable(quarantine_fn):
                        try:
                            quarantine_fn(
                                bot, action_seed_center, ttl=ttl, reason=reason,
                                candidate=action_seed_candidate,
                                frame=action_frame,
                            )
                        except BaseException:
                            pass
                try:
                    if bool(getattr(
                        bot, '_qqfarm_backpack_profile_active', False
                    )):
                        setattr(
                            bot, '_qqfarm_backpack_round_no_progress_attempts',
                            max(0, int(getattr(
                                bot,
                                '_qqfarm_backpack_round_no_progress_attempts',
                                0,
                            ) or 0)) + 1,
                        )
                except BaseException:
                    pass
                try:
                    _write(
                        'v360 no-progress backpack candidate quarantined center=' +
                        repr(action_seed_center) + ' reason=' + str(reason) +
                        ' name=' + str(name)
                    )
                except BaseException:
                    pass

            def _read_empty_observation():
                try:
                    count = max(0, int(getattr(
                        bot, '_qqfarm_recent_empty_land_count', baseline_empty_count
                    ) or 0))
                    observed_ts = float(getattr(
                        bot, '_qqfarm_recent_empty_land_ts', 0.0
                    ) or 0.0)
                    return count, observed_ts
                except BaseException:
                    return baseline_empty_count, 0.0

            def _post_planting_frame():
                # The bound and cached frames are often screenshots captured
                # before the click/drag.  Ask the live bot capture path first so
                # verification observes the frame produced by the action.
                try:
                    capture_fn = globals().get('_get_frame_from_bot')
                    fresh_frame = capture_fn(bot) if callable(capture_fn) else None
                    if fresh_frame is not None:
                        return fresh_frame
                except BaseException:
                    pass
                for attr_name in (
                    '_qqfarm_current_frame', '_qqfarm_last_frame',
                    '_last_frame', 'current_frame', 'last_frame',
                ):
                    try:
                        value = getattr(bot, attr_name)
                    except BaseException:
                        value = None
                    if value is not None:
                        return value
                for key in ('frame', 'screenshot', 'image', 'img'):
                    try:
                        value = bound_arguments.get(key)
                    except BaseException:
                        value = None
                    if value is not None:
                        return value
                    try:
                        value = kwargs.get(key)
                    except BaseException:
                        value = None
                    if value is not None:
                        return value
                return None

            def _refresh_empty_lands_after_success():
                nonlocal quad_overlay_confirmed_this_action
                nonlocal post_action_nonseed_rejected
                current_count, current_ts = _read_empty_observation()
                if current_ts > 0.0 and current_ts >= (started_ts - 0.01):
                    return False
                try:
                    detector = getattr(bot, '_detect_empty_lands', None)
                except BaseException:
                    detector = None
                if not callable(detector):
                    # Released planting helpers keep the detector as a module
                    # global.  The first callable here can itself be a hook
                    # wrapper, so follow its original-function metadata until
                    # the business module globals become visible.
                    queue = [fn]
                    seen_targets = set()
                    while queue and not callable(detector):
                        target = queue.pop(0)
                        try:
                            target_id = id(target)
                        except BaseException:
                            target_id = 0
                        if target_id in seen_targets:
                            continue
                        seen_targets.add(target_id)
                        try:
                            target_globals = getattr(target, '__globals__', {})
                            candidate = target_globals.get('_detect_empty_lands') if isinstance(
                                target_globals, dict
                            ) else None
                            if callable(candidate):
                                detector = candidate
                                break
                        except BaseException:
                            pass
                        for attr_name in (
                            '__qqfarm_planting_crop_context_orig__',
                            '__qqfarm_planting_outcome_verify_orig__',
                            '__wrapped__',
                        ):
                            try:
                                original = getattr(target, attr_name, None)
                            except BaseException:
                                original = None
                            if callable(original):
                                queue.append(original)
                if not callable(detector):
                    return False
                try:
                    delay = float(getattr(
                        bot, 'planting_visual_verify_delay_seconds', 0.45
                    ) or 0.0)
                except BaseException:
                    delay = 0.45
                delay = min(max(0.0, delay), 1.5)
                probe_count = 0
                # Empty-land state deliberately holds the first lower reading to
                # reject partial screenshots.  A real plant therefore needs one
                # immediate confirmation probe before this wrapper can decide it
                # made no progress.  Stop as soon as the stable count decreases.
                for probe_index in range(2):
                    probe_delay = delay if probe_index == 0 else min(delay, 0.25)
                    if probe_delay > 0.0:
                        try:
                            __import__('time').sleep(probe_delay)
                        except BaseException:
                            pass
                    frame = _post_planting_frame()
                    if frame is None:
                        break
                    try:
                        nonseed_fn = globals().get(
                            '_qqfarm_backpack_nonseed_popup'
                        )
                        nonseed_proof = (
                            nonseed_fn(frame) if callable(nonseed_fn) else None
                        )
                    except BaseException:
                        nonseed_proof = None
                    if isinstance(nonseed_proof, dict):
                        post_action_nonseed_rejected = True
                        _record_backpack_no_progress(
                            'post-action-visible-' + str(
                                nonseed_proof.get('kind', 'nonseed')
                            ),
                            ttl=900.0,
                        )
                        close_fn = globals().get(
                            '_qqfarm_close_seed_panel_for_board_refresh'
                        )
                        close_result = (False, None, 'close-unavailable')
                        if callable(close_fn):
                            try:
                                close_result = close_fn(bot, panel_settle=0.25)
                            except TypeError:
                                try:
                                    close_result = close_fn(bot)
                                except BaseException:
                                    close_result = (False, None, 'close-error')
                            except BaseException:
                                close_result = (False, None, 'close-error')
                        try:
                            _write(
                                'v373 post-action nonseed panel rejected kind=' +
                                str(nonseed_proof.get('kind', '')) +
                                ' score=' + ('%.4f' % float(
                                    nonseed_proof.get('score', 0.0) or 0.0
                                )) + ' closed=' + str(bool(
                                    close_result[0]
                                    if isinstance(close_result, (tuple, list)) and close_result
                                    else close_result
                                )).lower() + ' center=' +
                                repr(action_seed_center) + ' name=' + str(name)
                            )
                        except BaseException:
                            pass
                        return False
                    # A 2x2 placement layer can cover the farm and make the empty-
                    # land detector report a fake confirmed zero.  Resolve the
                    # green/grey check layer first, then require the next fresh
                    # unobscured board frame before accepting any decrease.
                    try:
                        overlay_observer = globals().get(
                            '_qqfarm_quad_overlay_observation'
                        )
                        overlay_observation = (
                            overlay_observer(frame)
                            if callable(overlay_observer) else {}
                        )
                    except BaseException:
                        overlay_observation = {}
                    if bool((overlay_observation or {}).get('present', False)):
                        overlay_id = str((overlay_observation or {}).get(
                            'overlay_id', ''
                        ) or '')
                        confirm_enabled = bool(
                            (overlay_observation or {}).get(
                                'confirm_enabled', False
                            )
                        )
                        invalid_quad_seed = bool(not confirm_enabled)
                        if invalid_quad_seed and action_seed_center is not None:
                            try:
                                time_module = globals().get('time') or __import__('time')
                                cooldown_until = float(time_module.time()) + 180.0
                                raw_skipped = getattr(
                                    bot, '_qqfarm_backpack_skip_candidate_until', {}
                                )
                                skipped = dict(raw_skipped) if isinstance(
                                    raw_skipped, dict
                                ) else {}
                                skipped[action_seed_center] = max(
                                    float(skipped.get(action_seed_center, 0.0) or 0.0),
                                    cooldown_until,
                                )
                                setattr(
                                    bot, '_qqfarm_backpack_skip_candidate_until', skipped
                                )
                                setattr(
                                    bot, '_qqfarm_quad_failure_cooldown_until',
                                    cooldown_until,
                                )
                                _write(
                                    'v351 quarantined backpack seed after invalid grey '
                                    '2x2 placement center=' + repr(action_seed_center) +
                                    ' until=' + ('%.3f' % cooldown_until) +
                                    ' name=' + str(name)
                                )
                            except BaseException:
                                pass
                        resolver_fn = globals().get(
                            '_qqfarm_resolve_quad_overlay_before_fallback'
                        )
                        overlay_released = False
                        if callable(resolver_fn):
                            try:
                                overlay_released = bool(resolver_fn(
                                    bot,
                                    overlay_id=overlay_id,
                                    initial_frame=frame,
                                    before_lands=list(getattr(
                                        bot, '_qqfarm_recent_empty_lands', []
                                    ) or []),
                                    result=None,
                                    name=str(name) + '-post-action-proof',
                                ))
                            except BaseException:
                                overlay_released = False
                        try:
                            _write(
                                'v350 post-action 2x2 overlay ' +
                                ('resolved' if overlay_released else 'unresolved') +
                                ' before empty-land proof id=' + overlay_id +
                                ' name=' + str(name)
                            )
                        except BaseException:
                            pass
                        if overlay_released:
                            if confirm_enabled:
                                quad_overlay_confirmed_this_action = True
                            if invalid_quad_seed and action_seed_center is not None:
                                try:
                                    setattr(bot, '_qqfarm_quad_skip_and_continue', True)
                                except BaseException:
                                    pass
                            continue
                        try:
                            setattr(bot, '_qqfarm_quad_overlay_block_fallback', True)
                        except BaseException:
                            pass
                        break
                    try:
                        detector(frame)
                    except TypeError:
                        try:
                            detector(bot, frame)
                        except BaseException:
                            break
                    except BaseException:
                        break
                    probe_count += 1
                    observed_count, observed_ts = _read_empty_observation()
                    try:
                        observed_board_state = str(getattr(
                            bot, '_qqfarm_empty_land_board_gate_state', 'bypass'
                        ) or 'bypass').strip().lower()
                    except BaseException:
                        observed_board_state = 'bypass'
                    bypass_zero_needs_fresh_probe = bool(
                        observed_count == 0 and
                        observed_board_state != 'confirmed'
                    )
                    if bypass_zero_needs_fresh_probe and probe_index == 0:
                        close_fn = globals().get(
                            '_collapse_wechat_outer_panel_if_needed'
                        )
                        if not callable(close_fn):
                            try:
                                close_fn = getattr(
                                    bot, '_tap_top_left_to_reset_panel', None
                                )
                            except BaseException:
                                close_fn = None
                        if not callable(close_fn):
                            try:
                                runtime_globals = getattr(fn, '__globals__', {})
                                close_fn = runtime_globals.get(
                                    '_tap_top_left_to_reset_panel'
                                ) if isinstance(runtime_globals, dict) else None
                            except BaseException:
                                close_fn = None
                        close_sent = False
                        if callable(close_fn):
                            for close_args in (
                                (bot, frame), (bot,), (frame,), (),
                            ):
                                try:
                                    close_result = close_fn(*close_args)
                                    if close_result is not False:
                                        close_sent = True
                                    break
                                except TypeError:
                                    continue
                                except BaseException:
                                    break
                        try:
                            _write(
                                'v337 bypass zero requested panel close + fresh board probe '
                                'closed=' + str(bool(close_sent)).lower() +
                                ' name=' + str(name)
                            )
                        except BaseException:
                            pass
                        continue
                    if (
                        observed_ts > 0.0 and
                        observed_ts >= (started_ts - 0.01) and
                        observed_count < baseline_empty_count
                    ):
                        break
                if probe_count <= 0:
                    return False
                try:
                    _write(
                        'v247 planting outcome requested fresh empty-land probe name=' +
                        str(name) + ' before=' + str(baseline_empty_count) +
                        ' probes=' + str(probe_count)
                    )
                except BaseException:
                    pass
                return True
            marker = object()
            try:
                old_active = getattr(bot, '_qqfarm_planting_outcome_verify_active')
            except BaseException:
                old_active = marker
            try:
                setattr(bot, '_qqfarm_planting_outcome_verify_active', True)
            except BaseException:
                pass
            strict_preopened_baseline_consumed = False
            try:
                attempted_lands = []
                inspect_module = __import__('inspect')
                inspect_target = getattr(
                    fn, '__qqfarm_planting_crop_context_orig__', fn
                )
                attempted_bound = inspect_module.signature(
                    inspect_target
                ).bind_partial(*tuple(invoke_args), **invoke_kwargs)
                for parameter_name, value in attempted_bound.arguments.items():
                    if 'land' not in str(parameter_name).lower():
                        continue
                    if isinstance(value, (str, bytes, dict)):
                        continue
                    try:
                        candidates = list(value or [])
                    except BaseException:
                        candidates = []
                    normalized = []
                    for item in candidates:
                        try:
                            raw_center = item.get('center') if isinstance(item, dict) else None
                            if isinstance(raw_center, (tuple, list)) and len(raw_center) >= 2:
                                item_copy = dict(item) if isinstance(item, dict) else {}
                                item_copy['center'] = (
                                    int(round(float(raw_center[0]))),
                                    int(round(float(raw_center[1]))),
                                )
                                normalized.append(item_copy)
                        except BaseException:
                            continue
                    if len(normalized) > len(attempted_lands):
                        attempted_lands = normalized
                if not attempted_lands:
                    fallback_center = getattr(
                        bot, '_qqfarm_backpack_single_land_attempt_center', None
                    )
                    if isinstance(fallback_center, (tuple, list)) and len(fallback_center) >= 2:
                        attempted_lands = [{
                            'center': (int(fallback_center[0]), int(fallback_center[1]))
                        }]
                setattr(bot, '_qqfarm_last_planting_attempt_lands', list(attempted_lands))
                setattr(
                    bot, '_qqfarm_last_planting_attempt_ts',
                    __import__('time').time(),
                )
            except BaseException:
                try:
                    setattr(bot, '_qqfarm_last_planting_attempt_lands', [])
                except BaseException:
                    pass
            # v378: every normal planting call is a fresh fixed-slot transaction.
            # This branch returns in every outcome so the aggregate empty-count
            # success path below is diagnostic-only and cannot consume pending work.
            try:
                strict_mode = (
                    '2x2' if (
                        bool(explicit_quad_candidate) or bool(getattr(
                            bot, '_qqfarm_quad_transaction_active', False
                        ))
                    ) else '1x1'
                )
                strict_capture_fn = globals().get(
                    '_qqfarm_capture_current_frame_24_slot_ledger'
                )
                strict_resolver_fn = globals().get(
                    '_qqfarm_resolve_attempted_slot_ids'
                )
                strict_commit_fn = globals().get(
                    '_qqfarm_commit_current_frame_planting_transaction'
                )
                if not (
                        callable(strict_capture_fn) and
                        callable(strict_resolver_fn) and
                        callable(strict_commit_fn)):
                    strict_transaction = {
                        'committed': False, 'delta': 0,
                        'committed_slots': (), 'attempted_slots': (),
                        'planting_mode': strict_mode,
                        'before_empty_count': 0, 'after_empty_count': 0,
                        'before_frame_id': '', 'after_frame_id': '',
                        'reason': 'strict-ledger-unavailable',
                    }
                    setattr(bot, '_qqfarm_last_planting_transaction', strict_transaction)
                    _mark_strict_outcome_unverified()
                    return False
                strict_now = float(__import__('time').time())
                # v383: an open seed shelf is never a before-ledger source.  The
                # preflight opener may hand us one short-lived no-panel ledger;
                # consume it for this one action and clear it in the enclosing
                # finally block.  Ordinary paths still capture a fresh frame here.
                strict_before_frame = None
                strict_before_ledger = None
                strict_preopened_baseline_used = False
                try:
                    strict_preopened_ledger = getattr(
                        bot, '_qqfarm_preopened_strict_before_ledger', None
                    )
                    strict_preopened_ts = float(getattr(
                        bot, '_qqfarm_preopened_strict_before_ledger_ts', 0.0
                    ) or 0.0)
                except BaseException:
                    strict_preopened_ledger = None
                    strict_preopened_ts = 0.0
                try:
                    strict_preopened_age = strict_now - strict_preopened_ts
                    strict_preopened_fresh = bool(
                        strict_preopened_ts > 0.0 and
                        strict_preopened_age >= -0.25 and
                        strict_preopened_age <= 5.0
                    )
                except BaseException:
                    strict_preopened_fresh = False
                if isinstance(strict_preopened_ledger, dict) and strict_preopened_fresh:
                    strict_before_ledger = strict_preopened_ledger
                    strict_preopened_baseline_used = True
                    strict_preopened_baseline_consumed = True
                    # A new strict action owns its close marker.  Do not let a
                    # completed older action reopen a later shelf transaction.
                    for _strict_attr_name in (
                            '_qqfarm_preopened_strict_shelf_closed_after_transaction',
                            '_qqfarm_preopened_strict_shelf_closed_after_transaction_ts',
                    ):
                        try:
                            delattr(bot, _strict_attr_name)
                        except BaseException:
                            pass
                if strict_before_ledger is None:
                    # A bound function argument can be a pre-click screenshot.  It
                    # is never click authority; ordinary transactions start with a
                    # new bot capture.  The preopened path above deliberately skips
                    # this capture because it would see the shelf.
                    try:
                        live_capture_fn = globals().get('_get_frame_from_bot')
                        strict_before_frame = (
                            live_capture_fn(bot) if callable(live_capture_fn) else None
                        )
                    except BaseException:
                        strict_before_frame = None
                    if strict_before_frame is None:
                        strict_transaction = strict_commit_fn(
                            bot, None, None, attempted_slots=(),
                            planting_mode=strict_mode,
                            rejection_reason='fresh-before-frame-unavailable',
                        )
                        _restore_unverified_planting_state()
                        _mark_strict_outcome_unverified()
                        return False
                    strict_before_ledger = strict_capture_fn(
                        strict_before_frame,
                        frame_id='planting-before-%d-%d' % (
                            int(id(strict_before_frame)),
                            int(round(strict_now * 1000000.0)),
                        ),
                        captured_at=strict_now,
                    )
                strict_preflight_blocked = False
                try:
                    strict_capture_status = str(
                        strict_before_ledger.get('capture_status', 'aligned') or
                        'aligned'
                    )
                    strict_unknown_count = int(
                        strict_before_ledger.get('unknown_count', 0) or 0
                    )
                    strict_preflight_blocked = bool(
                        strict_before_ledger.get('ui_blocked') or
                        strict_capture_status != 'aligned' or
                        strict_unknown_count > 0
                    )
                except BaseException:
                    strict_preflight_blocked = True
                if strict_preflight_blocked:
                    strict_transaction = strict_commit_fn(
                        bot, strict_before_ledger, None, attempted_slots=(),
                        planting_mode=strict_mode,
                    )
                    _restore_unverified_planting_state()
                    _mark_strict_outcome_unverified()
                    return False
                strict_resolution = strict_resolver_fn(
                    strict_before_ledger, attempted_lands,
                    planting_mode=strict_mode,
                )
                if not isinstance(strict_resolution, dict) or not bool(
                        strict_resolution.get('resolved', False)):
                    try:
                        strict_reason = str(
                            strict_resolution.get('reason', 'attempted-slot-unresolved')
                        )
                        strict_slots = tuple(
                            strict_resolution.get('attempted_slots', ()) or ()
                        )
                    except BaseException:
                        strict_reason = 'attempted-slot-unresolved'
                        strict_slots = ()
                    strict_transaction = strict_commit_fn(
                        bot, strict_before_ledger, None,
                        attempted_slots=strict_slots, planting_mode=strict_mode,
                        rejection_reason=strict_reason,
                    )
                    _restore_unverified_planting_state()
                    _mark_strict_outcome_unverified()
                    return False
                strict_attempted_slots = tuple(
                    strict_resolution.get('attempted_slots', ()) or ()
                )
                strict_direct_single_land = bool(
                    action_seed_center is not None and
                    strict_mode == '1x1' and len(attempted_lands) == 1
                )
                if strict_direct_single_land:
                    try:
                        strict_land_center = attempted_lands[0].get('center')
                    except BaseException:
                        strict_land_center = None
                    strict_direct_fn = globals().get(
                        '_qqfarm_drag_single_backpack_seed'
                    )
                    try:
                        strict_source_target = getattr(
                            fn, '__qqfarm_planting_crop_context_orig__', fn
                        )
                        strict_source_globals = getattr(
                            strict_source_target, '__globals__', {}
                        ) or {}
                    except BaseException:
                        strict_source_globals = {}
                    strict_native_result = bool(strict_direct_fn(
                        bot, action_seed_center, strict_land_center,
                        source_globals=strict_source_globals, name=name,
                    )) if callable(strict_direct_fn) else False
                else:
                    strict_native_result = fn(
                        *tuple(invoke_args), **invoke_kwargs
                    )
                if isinstance(strict_native_result, (tuple, list)):
                    strict_native_success = bool(
                        strict_native_result[0] if strict_native_result else False
                    )
                else:
                    strict_native_success = bool(strict_native_result)
                if not strict_native_success:
                    strict_transaction = strict_commit_fn(
                        bot, strict_before_ledger, None,
                        attempted_slots=strict_attempted_slots,
                        planting_mode=strict_mode,
                        rejection_reason='native-action-failed',
                    )
                    # A real candidate action was issued but did not report success.
                    # Isolate that card before the scheduler can re-enter it.
                    if action_seed_center is not None:
                        _record_backpack_no_progress(
                            'single-land-direct-input-failed'
                            if strict_direct_single_land else 'native-action-failed',
                            ttl=90.0,
                        )
                    _restore_unverified_planting_state()
                    _mark_strict_outcome_unverified()
                    return False
                try:
                    strict_delay = float(getattr(
                        bot, 'planting_visual_verify_delay_seconds', 0.45
                    ) or 0.0)
                except BaseException:
                    strict_delay = 0.45
                strict_delay = min(max(0.0, strict_delay), 1.5)
                if strict_delay > 0.0:
                    __import__('time').sleep(strict_delay)
                strict_after_frame = None
                if strict_preopened_baseline_used:
                    close_seed_panel_fn = globals().get(
                        '_qqfarm_close_seed_panel_for_board_refresh'
                    )
                    close_seed_panel_result = (False, None, 'close-unavailable')
                    if callable(close_seed_panel_fn):
                        try:
                            close_seed_panel_result = close_seed_panel_fn(
                                bot, panel_settle=0.35
                            )
                        except TypeError:
                            try:
                                close_seed_panel_result = close_seed_panel_fn(bot)
                            except BaseException:
                                close_seed_panel_result = (False, None, 'close-error')
                        except BaseException:
                            close_seed_panel_result = (False, None, 'close-error')
                    try:
                        if (
                            isinstance(close_seed_panel_result, (tuple, list)) and
                            len(close_seed_panel_result) >= 2 and
                            bool(close_seed_panel_result[0])
                        ):
                            strict_after_frame = close_seed_panel_result[1]
                    except BaseException:
                        strict_after_frame = None
                else:
                    try:
                        live_capture_fn = globals().get('_get_frame_from_bot')
                        strict_after_frame = (
                            live_capture_fn(bot) if callable(live_capture_fn) else None
                        )
                    except BaseException:
                        strict_after_frame = None
                if strict_after_frame is None:
                    strict_transaction = strict_commit_fn(
                        bot, strict_before_ledger, None,
                        attempted_slots=strict_attempted_slots,
                        planting_mode=strict_mode,
                        rejection_reason='fresh-after-frame-unavailable',
                    )
                    _restore_unverified_planting_state()
                    _mark_strict_outcome_unverified()
                    return False
                strict_after_now = float(__import__('time').time())
                strict_after_ledger = strict_capture_fn(
                    strict_after_frame,
                    frame_id='planting-after-%d-%d' % (
                        int(id(strict_after_frame)),
                        int(round(strict_after_now * 1000000.0)),
                    ),
                    captured_at=strict_after_now,
                )
                strict_transaction = strict_commit_fn(
                    bot, strict_before_ledger, strict_after_ledger,
                    attempted_slots=strict_attempted_slots,
                    planting_mode=strict_mode,
                )
                if not bool(strict_transaction.get('committed', False)):
                    # The input path reported success, but the fresh fixed-slot
                    # ledger did not confirm the exact requested slots.  The same
                    # visible card must not receive another physical action in this
                    # transaction chain.
                    if action_seed_center is not None:
                        _record_backpack_no_progress(
                            'strict-ledger-' + str(
                                strict_transaction.get('reason', '') or 'unconfirmed'
                            ),
                            ttl=90.0,
                        )
                    _restore_unverified_planting_state()
                    _mark_strict_outcome_unverified()
                    try:
                        _write(
                            'v378 fixed-slot planting rejected reason=' +
                            str(strict_transaction.get('reason', '')) +
                            ' attempted=' + repr(strict_attempted_slots) +
                            ' name=' + str(name)
                        )
                    except BaseException:
                        pass
                    return False
                strict_mark_fn = globals().get(
                    '_qqfarm_mark_visual_planting_success'
                )
                strict_marked = bool(strict_mark_fn(
                    bot, strict_transaction.get('before_empty_count', 0),
                    strict_transaction.get('after_empty_count', 0),
                    now_ts=strict_after_now, name=name,
                )) if callable(strict_mark_fn) else False
                try:
                    setattr(bot, '_qqfarm_last_planting_outcome_verified', True)
                    setattr(
                        bot, '_qqfarm_last_planting_outcome_before',
                        strict_transaction.get('before_empty_count', 0),
                    )
                    setattr(
                        bot, '_qqfarm_last_planting_outcome_after',
                        strict_transaction.get('after_empty_count', 0),
                    )
                    if strict_preopened_baseline_used:
                        # The scheduler must reopen and rescan before it can use
                        # another card.  This is set only after a strict commit.
                        setattr(
                            bot,
                            '_qqfarm_preopened_strict_shelf_closed_after_transaction',
                            True,
                        )
                        setattr(
                            bot,
                            '_qqfarm_preopened_strict_shelf_closed_after_transaction_ts',
                            strict_after_now,
                        )
                except BaseException:
                    pass
                try:
                    _write(
                        'v378 fixed-slot planting committed before=' +
                        str(strict_transaction.get('before_empty_count', 0)) +
                        ' after=' + str(strict_transaction.get('after_empty_count', 0)) +
                        ' slots=' + repr(strict_attempted_slots) +
                        ' metric=' + str(strict_marked).lower() +
                        ' name=' + str(name)
                    )
                except BaseException:
                    pass
                return strict_native_result
            except BaseException as strict_error:
                try:
                    strict_transaction = strict_commit_fn(
                        bot, locals().get('strict_before_ledger'), None,
                        attempted_slots=locals().get('strict_attempted_slots', ()),
                        planting_mode=locals().get('strict_mode', '1x1'),
                        rejection_reason='strict-ledger-bridge-error',
                    ) if callable(locals().get('strict_commit_fn')) else {
                        'committed': False, 'delta': 0,
                        'committed_slots': (), 'attempted_slots': (),
                        'planting_mode': '1x1',
                        'before_empty_count': 0, 'after_empty_count': 0,
                        'before_frame_id': '', 'after_frame_id': '',
                        'reason': 'strict-ledger-bridge-error',
                    }
                    setattr(bot, '_qqfarm_last_planting_transaction', strict_transaction)
                except BaseException:
                    pass
                _restore_unverified_planting_state()
                _mark_strict_outcome_unverified()
                try:
                    _write(
                        'v378 fixed-slot planting bridge error ' +
                        repr(strict_error)[:180] + ' name=' + str(name)
                    )
                except BaseException:
                    pass
                return False
            finally:
                if strict_preopened_baseline_consumed:
                    for _strict_attr_name in (
                        '_qqfarm_preopened_strict_before_ledger',
                        '_qqfarm_preopened_strict_before_ledger_ts',
                    ):
                        try:
                            delattr(bot, _strict_attr_name)
                        except BaseException:
                            pass
                try:
                    if old_active is marker:
                        delattr(bot, '_qqfarm_planting_outcome_verify_active')
                    else:
                        setattr(
                            bot, '_qqfarm_planting_outcome_verify_active', old_active
                        )
                except BaseException:
                    pass

            try:
                direct_single_land = bool(
                    action_seed_center is not None and len(attempted_lands) == 1 and
                    not explicit_quad_candidate and
                    not bool(getattr(
                        bot, '_qqfarm_quad_transaction_active', False
                    ))
                )
                if direct_single_land:
                    try:
                        direct_land_center = attempted_lands[0].get('center')
                    except BaseException:
                        direct_land_center = None
                    direct_fn = globals().get(
                        '_qqfarm_drag_single_backpack_seed'
                    )
                    try:
                        source_target = getattr(
                            fn, '__qqfarm_planting_crop_context_orig__', fn
                        )
                        source_globals = getattr(
                            source_target, '__globals__', {}
                        ) or {}
                    except BaseException:
                        source_globals = {}
                    result = bool(direct_fn(
                        bot, action_seed_center, direct_land_center,
                        source_globals=source_globals, name=name,
                    )) if callable(direct_fn) else False
                else:
                    result = fn(*tuple(invoke_args), **invoke_kwargs)
                if isinstance(result, (tuple, list)):
                    reported_success = bool(result[0]) if result else False
                else:
                    reported_success = bool(result)
                if not reported_success and action_seed_center is not None:
                    _record_backpack_no_progress(
                        'single-land-direct-input-failed'
                        if direct_single_land else 'native-action-failed',
                        ttl=90.0,
                    )
                if reported_success and baseline_empty_count > 0:
                    _refresh_empty_lands_after_success()
                current_empty_count, current_empty_ts = _read_empty_observation()
                fresh_empty_observation = bool(
                    current_empty_ts > 0.0 and
                    current_empty_ts >= (started_ts - 0.01)
                )
                try:
                    post_action_board_state = str(getattr(
                        bot, '_qqfarm_empty_land_board_gate_state', 'bypass'
                    ) or 'bypass').strip().lower()
                except BaseException:
                    post_action_board_state = 'bypass'
                post_action_board_usable = bool(
                    post_action_board_state == 'confirmed'
                    if current_empty_count == 0
                    else post_action_board_state != 'unknown'
                )
                if reported_success and baseline_empty_count > 0 and fresh_empty_observation:
                    observed_empty_decrease = max(
                        0, baseline_empty_count - current_empty_count
                    )
                    implausible_quad_decrease = bool(
                        (explicit_quad_candidate or quad_overlay_confirmed_this_action)
                        and observed_empty_decrease > 4
                    )
                    verified = bool(
                        current_empty_count < baseline_empty_count
                        and post_action_board_usable
                        and not implausible_quad_decrease
                        and not post_action_nonseed_rejected
                    )
                    try:
                        setattr(bot, '_qqfarm_last_planting_outcome_verified', verified)
                        setattr(bot, '_qqfarm_last_planting_outcome_before', baseline_empty_count)
                        setattr(bot, '_qqfarm_last_planting_outcome_after', current_empty_count)
                    except BaseException:
                        pass
                    if verified:
                        committed = False
                        try:
                            commit_fn = globals().get('_qqfarm_mark_visual_planting_success')
                            if callable(commit_fn):
                                committed = bool(commit_fn(
                                    bot, baseline_empty_count, current_empty_count,
                                    now_ts=__import__('time').time(), name=name,
                                ))
                        except BaseException:
                            committed = False
                        try:
                            _write(
                                'v247 planting action visually verified before=' +
                                str(baseline_empty_count) + ' after=' +
                                str(current_empty_count) + ' committed=' +
                                str(bool(committed)).lower() + ' name=' + str(name)
                            )
                        except BaseException:
                            pass
                    else:
                        if not implausible_quad_decrease:
                            _record_backpack_no_progress(
                                'no-visual-empty-land-decrease', ttl=180.0
                            )
                        _restore_unverified_planting_state()
                        priority_fn = globals().get('_qqfarm_update_home_priority')
                        if callable(priority_fn):
                            try:
                                priority_fn(
                                    bot, baseline_empty_count, now_ts=started_ts,
                                    reason=(
                                        'planting-implausible-quad-empty-land-decrease'
                                        if implausible_quad_decrease else
                                        'planting-no-visual-empty-land-decrease'
                                    ),
                                )
                            except BaseException:
                                pass
                        try:
                            if implausible_quad_decrease:
                                _write(
                                    'v371 planting action rejected: implausible 2x2 empty-land decrease ' +
                                    'before=' + str(baseline_empty_count) + ' after=' +
                                    str(current_empty_count) + ' decrease=' +
                                    str(observed_empty_decrease) + ' max=4 name=' + str(name)
                                )
                            elif not post_action_board_usable:
                                _write(
                                    'v335 planting action rejected: post-action board gate unknown ' +
                                    'before=' + str(baseline_empty_count) + ' after=' +
                                    str(current_empty_count) + ' name=' + str(name)
                                )
                            else:
                                _write(
                                    'v247 planting action rejected: no visual empty-land decrease ' +
                                    'before=' + str(baseline_empty_count) + ' after=' +
                                    str(current_empty_count) + ' name=' + str(name)
                                )
                        except BaseException:
                            pass
                        if isinstance(result, tuple):
                            normalized = list(result)
                            if normalized:
                                normalized[0] = False
                            result = tuple(normalized)
                        elif isinstance(result, list):
                            normalized = list(result)
                            if normalized:
                                normalized[0] = False
                            result = normalized
                        else:
                            result = False
                if (
                    reported_success and baseline_empty_count > 0
                    and not fresh_empty_observation
                ):
                    # A successful input event without a fresh post-action
                    # empty-land observation is unproven.  Keeping it as a
                    # success caused blind drags to consume planting work and
                    # unlock friend patrols while the home plots stayed empty.
                    try:
                        setattr(bot, '_qqfarm_last_planting_outcome_verified', False)
                        setattr(bot, '_qqfarm_last_planting_outcome_before', baseline_empty_count)
                        setattr(bot, '_qqfarm_last_planting_outcome_after', current_empty_count)
                    except BaseException:
                        pass
                    _record_backpack_no_progress(
                        'missing-fresh-empty-land-observation', ttl=180.0
                    )
                    _restore_unverified_planting_state()
                    priority_fn = globals().get('_qqfarm_update_home_priority')
                    if callable(priority_fn):
                        try:
                            priority_fn(
                                bot, baseline_empty_count, now_ts=started_ts,
                                reason='planting-missing-fresh-empty-land-observation',
                            )
                        except BaseException:
                            pass
                    try:
                        _write(
                            'v252 planting action rejected: missing fresh empty-land observation ' +
                            'before=' + str(baseline_empty_count) + ' after=' +
                            str(current_empty_count) + ' name=' + str(name)
                        )
                    except BaseException:
                        pass
                    if isinstance(result, tuple):
                        normalized = list(result)
                        if normalized:
                            normalized[0] = False
                        result = tuple(normalized)
                    elif isinstance(result, list):
                        normalized = list(result)
                        if normalized:
                            normalized[0] = False
                        result = normalized
                    else:
                        result = False
                return result
            finally:
                try:
                    if old_active is marker:
                        delattr(bot, '_qqfarm_planting_outcome_verify_active')
                    else:
                        setattr(bot, '_qqfarm_planting_outcome_verify_active', old_active)
                except BaseException:
                    pass

        _wrapped.__name__ = getattr(fn, '__name__', 'planting_outcome_verify_wrapper')
        _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
        _wrapped.__doc__ = getattr(fn, '__doc__', None)
        try:
            _qqfarm_preserve_wrapper_metadata(_wrapped, fn)
        except BaseException:
            pass
        _wrapped.__qqfarm_planting_outcome_verify_wrapped__ = True
        _wrapped.__qqfarm_planting_outcome_verify_orig__ = fn
        return _wrapped, True
    except BaseException:
        return fn, False


def _land_center_xy(land):
    try:
        import math
        import numbers
        seen = set()
        def _number(value):
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                return None
            result = float(value)
            if not math.isfinite(result):
                return None
            return result
        def _pair(value):
            marker = id(value)
            if marker in seen:
                return None
            seen.add(marker)
            if isinstance(value, (tuple, list)):
                if len(value) != 2:
                    return None
                x = _number(value[0])
                y = _number(value[1])
                return (x, y) if x is not None and y is not None else None
            if isinstance(value, dict):
                for key in ('center', 'land_center'):
                    if key in value:
                        result = _pair(value.get(key))
                        if result is not None:
                            return result
                for x_name, y_name in (('x', 'y'), ('cx', 'cy')):
                    if x_name in value and y_name in value:
                        x = _number(value.get(x_name))
                        y = _number(value.get(y_name))
                        if x is not None and y is not None:
                            return (x, y)
                return None
            for attr in ('center', 'land_center'):
                try:
                    if hasattr(value, attr):
                        result = _pair(getattr(value, attr))
                        if result is not None:
                            return result
                except BaseException:
                    pass
            for x_name, y_name in (('x', 'y'), ('cx', 'cy')):
                try:
                    if hasattr(value, x_name) and hasattr(value, y_name):
                        x = _number(getattr(value, x_name))
                        y = _number(getattr(value, y_name))
                        if x is not None and y is not None:
                            return (x, y)
                except BaseException:
                    pass
            return None
        return _pair(land)
    except BaseException:
        return None


def _group_safe_fertilizer_lands(lands, row_tolerance_px=45.0, max_horizontal_gap_px=120.0):
    try:
        values = list(lands or [])
    except BaseException:
        return None
    if not values:
        return []
    decorated = []
    for land in values:
        xy = _land_center_xy(land)
        if xy is None:
            if len(values) == 1:
                return [[land]]
            return None
        decorated.append((xy[1], xy[0], land))
    try:
        row_tolerance = float(row_tolerance_px)
        max_gap = float(max_horizontal_gap_px)
    except BaseException:
        return None
    decorated.sort(key=lambda item: (item[0], item[1]))
    rows = []
    current = []
    current_row_y = None
    for y, x, land in decorated:
        if current and abs(y - current_row_y) > row_tolerance:
            rows.append(current)
            current = []
            current_row_y = None
        if not current:
            current_row_y = y
        current.append((x, land))
    if current:
        rows.append(current)
    groups = []
    for row in rows:
        group = []
        previous_x = None
        for x, land in row:
            if group and (x - previous_x) > max_gap:
                groups.append(group)
                group = []
            group.append(land)
            previous_x = x
        if group:
            groups.append(group)
    return groups


def _wrap_radish_fertilizer_func(fn, module, name=''):
    try:
        if not callable(fn):
            return fn, False
        if getattr(fn, '__qqfarm_radish_fertilizer_wrapped__', False):
            return fn, False
        def _wrapped(*a, **k):
            bot = None
            bound = None
            lands_name = ''
            try:
                import inspect
                bound = inspect.signature(fn).bind_partial(*a, **k)
                if 'bot' in bound.arguments:
                    bot = _business_bot_from_args((), {'bot': bound.arguments.get('bot')})
                if 'lands' in bound.arguments:
                    lands_name = 'lands'
                else:
                    for param_name in bound.arguments:
                        if 'land' in str(param_name).lower():
                            lands_name = param_name
                            break
            except BaseException:
                bound = None
            if bot is None:
                bot = _business_bot_from_args(a, k)
            if bot is None:
                return fn(*a, **k)
            # Auto-fertilizer is a post-planting action.  A drag/click event is
            # only transport telemetry; the plot must first be visually proven
            # to have changed by the planting-outcome wrapper.
            try:
                planting_verified = (
                    getattr(bot, '_qqfarm_last_planting_outcome_verified', False) is True
                )
            except BaseException:
                planting_verified = False
            if not planting_verified:
                try:
                    _throttled_write(
                        'v263-radish-fertilizer-unverified-' + str(name),
                        'v263 radish fertilizer skipped planting outcome unverified',
                        30.0,
                    )
                except BaseException:
                    pass
                return False
            missing = object()
            try:
                mode_context = getattr(bot, '_qqfarm_radish_mode_context')
            except BaseException:
                mode_context = missing
            if mode_context is missing:
                radish_state = _daily_radish_state(module, bot)
            elif mode_context in ('active', 'inactive', 'unknown'):
                radish_state = mode_context
            elif isinstance(mode_context, bool):
                radish_state = 'active' if mode_context else 'inactive'
            else:
                radish_state = 'unknown'
            if radish_state == 'inactive':
                return fn(*a, **k)
            if radish_state != 'active':
                try:
                    _throttled_write('v35-radish-fertilizer-state-unknown-' + str(name), 'v35 radish fertilizer skipped radish state unknown', 30.0)
                except BaseException:
                    pass
                return False
            try:
                crop_context = getattr(bot, '_qqfarm_planting_crop_context')
            except BaseException:
                crop_context = missing
            crop_name = crop_context.strip() if isinstance(crop_context, str) else ''
            if crop_name != '\u767d\u841d\u535c':
                try:
                    _throttled_write('v35-radish-fertilizer-non-radish-' + str(name), 'v35 radish fertilizer skipped non-radish crop=' + crop_name, 30.0)
                except BaseException:
                    pass
                return False
            if bound is None or not lands_name:
                groups = None
            else:
                groups = _group_safe_fertilizer_lands(bound.arguments.get(lands_name))
            if groups is None:
                try:
                    _throttled_write('v35-radish-fertilizer-unsafe-' + str(name), 'v35 radish fertilizer skipped unsafe sparse lands', 30.0)
                except BaseException:
                    pass
                return False
            land_count = sum(len(group) for group in groups)
            try:
                _throttled_write(
                    'v35-radish-fertilizer-exec-' + str(name),
                    'v35 radish fertilizer crop=' + crop_name + ' lands=' + str(land_count) +
                    ' groups=' + str(len(groups)) + ' normal-fertilizer-only=True',
                    30.0,
                )
            except BaseException:
                pass
            overrides = (
                ('auto_fertilize_one', True),
                ('planting_auto_fertilize_one', True),
                ('auto_fertilize_more', False),
                ('planting_auto_fertilize_more', False),
                ('auto_fill_fertilizer_container', False),
            )
            saved = []
            def _restore_saved_aliases():
                first_error = None
                for attr, prior in reversed(saved):
                    try:
                        setattr(bot, attr, prior)
                        restored = getattr(bot, attr)
                        if restored is not prior:
                            try:
                                same_value = type(restored) is type(prior) and restored == prior
                            except BaseException:
                                same_value = False
                            if not same_value:
                                raise RuntimeError('v35 fertilizer restore verification failed attr=' + str(attr))
                    except BaseException as e:
                        if first_error is None:
                            first_error = e
                return first_error
            setup_error = None
            setup_attr = ''
            for attr, temporary in overrides:
                declared = False
                try:
                    declared = attr in vars(bot)
                except BaseException:
                    pass
                if not declared:
                    try:
                        declared = any(attr in vars(cls) for cls in type(bot).__mro__)
                    except BaseException:
                        pass
                try:
                    prior = getattr(bot, attr)
                except AttributeError as e:
                    if declared:
                        setup_error = e
                        setup_attr = attr
                        break
                    continue
                except BaseException as e:
                    setup_error = e
                    setup_attr = attr
                    break
                saved.append((attr, prior))
                try:
                    setattr(bot, attr, temporary)
                    if getattr(bot, attr) is not temporary:
                        raise RuntimeError('v35 fertilizer override verification failed attr=' + str(attr))
                except BaseException as e:
                    setup_error = e
                    setup_attr = attr
                    break
            if setup_error is not None:
                restore_error = _restore_saved_aliases()
                try:
                    _throttled_write(
                        'v35-radish-fertilizer-override-unsafe-' + str(name),
                        'v35 radish fertilizer skipped unsafe overrides attr=' + str(setup_attr),
                        30.0,
                    )
                except BaseException:
                    pass
                if restore_error is not None:
                    raise restore_error
                return False
            original_error = None
            original_traceback = None
            final_result = True
            try:
                for group in groups:
                    bound.arguments[lands_name] = group
                    result = fn(*bound.args, **bound.kwargs)
                    if not result:
                        final_result = False
                        break
            except BaseException as e:
                original_error = e
                original_traceback = e.__traceback__
            restore_error = _restore_saved_aliases()
            if original_error is not None:
                if restore_error is not None:
                    try:
                        original_error.add_note('v35 fertilizer restoration failure: ' + repr(restore_error))
                    except BaseException:
                        pass
                    try:
                        _throttled_write('v35-radish-fertilizer-restore-error-' + str(name), 'v35 radish fertilizer restoration failure after original error ' + repr(restore_error), 30.0)
                    except BaseException:
                        pass
                raise original_error.with_traceback(original_traceback)
            if restore_error is not None:
                raise restore_error
            return final_result
        try:
            _wrapped.__name__ = getattr(fn, '__name__', 'radish_fertilizer_wrapper')
            _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
            _wrapped.__doc__ = getattr(fn, '__doc__', None)
            _wrapped.__qqfarm_radish_fertilizer_wrapped__ = True
            _wrapped.__qqfarm_radish_fertilizer_orig__ = fn
        except BaseException:
            pass
        return _wrapped, True
    except BaseException:
        return fn, False


