def _wrap_first_party_friend_troublemaker_entry(fn, name=''):
    """Run the complete native-runtime batch under a temporary VIP context.

    The native routine owns its normal user-facing logs, one popup selection,
    multi-land drag path, bounded result handling, and return-home behavior.
    This wrapper changes only the entitlement probes for the duration of that
    call; it must not replace the batch with repeated single-land clicks.
    """
    if not callable(fn):
        return fn, False
    if bool(getattr(fn, '__qqfarm_first_party_troublemaker_wrapped__', False)):
        return fn, False

    def _wrapped(*args, **kwargs):
        vip_context = []
        enter_fn = globals().get('_enter_vip_entitlement_context')
        restore_fn = globals().get('_restore_vip_entitlement_context')
        context_fn = globals().get('_friend_guard_context')
        try:
            context = context_fn(args, kwargs) if callable(context_fn) else None
        except BaseException:
            context = None
        if context is None and args:
            context = args[0]
        snapshot_fn = globals().get('_friend_trouble_counter_snapshot')
        try:
            before_count = int(
                snapshot_fn(context) if callable(snapshot_fn) and context is not None
                else getattr(context, 'friend_trouble_daily_count', 0)
            )
        except BaseException:
            before_count = 0
        try:
            if callable(enter_fn):
                vip_context = list(enter_fn(fn, args, kwargs) or ())
            result = fn(*args, **kwargs)
        finally:
            restored = 0
            if callable(restore_fn):
                try:
                    restored = int(restore_fn(vip_context) or 0)
                except BaseException:
                    restored = 0
            try:
                _write(
                    'native-v225 troublemaker batch entitlement restored=' +
                    str(restored) + '/' + str(len(vip_context)) +
                    ' method=' + str(name)
                )
            except BaseException:
                pass
        try:
            after_count = int(
                snapshot_fn(context) if callable(snapshot_fn) and context is not None
                else getattr(context, 'friend_trouble_daily_count', before_count)
            )
        except BaseException:
            after_count = before_count
        if context is not None and after_count <= before_count and not bool(result):
            try:
                now_value = float(__import__('time').time())
            except BaseException:
                now_value = 0.0
            try:
                cooldown_until = float(getattr(
                    context, '_qqfarm_trouble_visual_fallback_cooldown_until', 0.0
                ) or 0.0)
            except BaseException:
                cooldown_until = 0.0
            if now_value >= cooldown_until:
                capture_fn = globals().get('_get_frame_from_bot')
                fallback_fn = globals().get('_run_first_party_friend_troublemaker')
                try:
                    fresh_frame = capture_fn(context) if callable(capture_fn) else None
                except BaseException:
                    fresh_frame = None
                fallback_ok = False
                if fresh_frame is not None and callable(fallback_fn):
                    try:
                        fallback_ok = bool(fallback_fn(context, fresh_frame))
                    except BaseException as error:
                        try:
                            _write('v457 trouble visual fallback error=' + repr(error)[:220])
                        except BaseException:
                            pass
                try:
                    setattr(
                        context, '_qqfarm_trouble_visual_fallback_cooldown_until',
                        now_value + (90.0 if fallback_ok else 300.0),
                    )
                except BaseException:
                    pass
                if fallback_ok:
                    result = True
                    try:
                        after_count = int(
                            snapshot_fn(context) if callable(snapshot_fn)
                            else getattr(context, 'friend_trouble_daily_count', before_count + 1)
                        )
                    except BaseException:
                        after_count = max(after_count, before_count + 1)
                    try:
                        _write(
                            'v457 native zero result recovered by bounded visual SeedLand '
                            'fallback count=' + str(before_count) + '->' + str(after_count)
                        )
                    except BaseException:
                        pass

        if context is not None and after_count > before_count:
            day_fn = globals().get('_daily_business_date')
            try:
                business_day = str(
                    day_fn() if callable(day_fn)
                    else __import__('time').strftime('%Y-%m-%d')
                )
            except BaseException:
                business_day = __import__('time').strftime('%Y-%m-%d')
            sync_fn = globals().get('_daily_metrics_sync_runtime')
            if callable(sync_fn):
                try:
                    sync_fn(
                        context,
                        today=business_day,
                        force=True,
                        exact_context_fields=(
                            'friend_trouble_daily_count',
                        ),
                    )
                except BaseException as error:
                    try:
                        _write(
                            'native-v225 troublemaker batch durable sync error=' +
                            repr(error)[:220]
                        )
                    except BaseException:
                        pass
        try:
            _write(
                'native-v225 troublemaker batch result=' + repr(result)[:180] +
                ' count=' + str(before_count) + '->' + str(after_count) +
                ' method=' + str(name)
            )
        except BaseException:
            pass
        return result

    try:
        _wrapped.__name__ = getattr(fn, '__name__', '_run_friend_daily_troublemaker')
        _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
        _wrapped.__module__ = getattr(fn, '__module__', '')
        _wrapped.__qqfarm_first_party_troublemaker_wrapped__ = True
        _wrapped.__qqfarm_native_v225_troublemaker_batch_wrapped__ = True
        _wrapped.__qqfarm_first_party_troublemaker_original__ = fn
    except BaseException:
        pass
    return _wrapped, True


