def _native_v225_daily_home_ready(context):
    """Authorize daily-entry clicks only from a current home-scene runtime hint."""
    if context is None:
        return False
    try:
        stop_fn = globals().get('_stop_requested_in_args')
        if callable(stop_fn) and bool(stop_fn((context,), {})):
            return False
    except BaseException:
        pass
    try:
        hint = str(getattr(context, '_qqfarm_live_scene_hint', '') or '').strip().lower()
    except BaseException:
        hint = ''
    if hint != 'home':
        due_fn = globals().get('_native_v225_daily_any_due')
        try:
            if callable(due_fn) and not bool(due_fn(context)):
                return False
        except BaseException:
            return False
        frame_fn = globals().get('_get_frame_from_bot')
        state_fn = globals().get('_qqfarm_strict_self_scene_state')
        try:
            frame = frame_fn(context) if callable(frame_fn) else None
            visual_state = state_fn(frame) if callable(state_fn) and frame is not None else None
        except BaseException:
            visual_state = None
        if visual_state is not False:
            return False
        scene_hint_fn = globals().get('_qqfarm_set_live_scene_hint')
        try:
            if callable(scene_hint_fn):
                scene_hint_fn(context, scene_hint='home')
            else:
                setattr(context, '_qqfarm_live_scene_hint', 'home')
        except BaseException:
            try:
                setattr(context, '_qqfarm_live_scene_hint', 'home')
            except BaseException:
                pass
    try:
        setattr(context, '_qqfarm_cycle_branch_hint', 'home')
    except BaseException:
        pass
    try:
        if any(bool(getattr(context, name, False)) for name in (
            '_qqfarm_post_harvest_pending',
            '_qqfarm_single_harvest_planting_pending',
            '_qqfarm_planting_transaction_active',
        )):
            return False
    except BaseException:
        return False
    return True


