def _native_v225_daily_schedule_due(config_key, time_key, default_time='00:00'):
    """Return a side-effect-free enabled-and-time-due decision."""
    try:
        sections_fn = globals().get('_active_bot_sections')
        cfg_fn = globals().get('_cfg_get')
        truthy_fn = globals().get('_truthy')
        sections = sections_fn() if callable(sections_fn) else ('bot',)
        enabled_raw = (
            cfg_fn(sections, config_key, 'False') if callable(cfg_fn) else 'False'
        )
        enabled = bool(
            truthy_fn(enabled_raw, False)
            if callable(truthy_fn) else
            str(enabled_raw or '').strip().lower() in ('1', 'true', 'yes', 'on')
        )
        if not enabled:
            return False
        schedule = str(
            cfg_fn(sections, time_key, default_time)
            if callable(cfg_fn) else default_time
        ).strip()
        parse_fn = globals().get('_parse_hhmm')
        due_minute = parse_fn(schedule) if callable(parse_fn) else None
        if due_minute is None:
            pieces = schedule.split(':', 1)
            if len(pieces) != 2:
                return False
            hour = int(pieces[0].strip())
            minute = int(pieces[1].strip())
            if not (0 <= hour <= 23 and 0 <= minute <= 59):
                return False
            due_minute = hour * 60 + minute
        clock_fn = globals().get('_daily_shanghai_clock')
        if callable(clock_fn):
            local = clock_fn()
        else:
            time_module = globals().get('time') or __import__('time')
            local = time_module.localtime()
        now_minute = int(local.tm_hour) * 60 + int(local.tm_min)
        return now_minute >= int(due_minute)
    except BaseException:
        return False


def _native_v225_daily_candidate_due(context, flow, require_home=True):
    """Side-effect-free due gate shared by home execution and friend return-home."""
    flow_key = str(flow or '').strip().lower()
    if flow_key not in ('freebenefits', 'share'):
        return False
    # Daily popups must not preempt an active friend visit or friend-list chain.
    try:
        scene_hint = str(getattr(context, '_qqfarm_live_scene_hint', '') or '').lower()
        friend_busy = bool(
            scene_hint in ('friend', 'friend_farm', 'friend-list', 'friend_list')
            or getattr(context, '_qqfarm_friend_chain_pending', False)
            or getattr(context, '_qqfarm_friend_list_resume_pending', False)
            or getattr(context, '_qqfarm_friend_entry_pending', False)
        )
    except BaseException:
        friend_busy = False
    if friend_busy:
        return False
    if require_home and not _native_v225_daily_home_ready(context):
        return False
    if flow_key == 'freebenefits':
        if not _native_v225_daily_schedule_due(
            'enable_daily_freebenefits', 'daily_freebenefits_time', '00:10'
        ):
            return False
    else:
        if not _native_v225_daily_schedule_due(
            'enable_daily_share', 'daily_share_time', '00:31'
        ):
            return False
        config_fn = globals().get('_share_target_guard_config')
        try:
            share_cfg = config_fn() if callable(config_fn) else {}
        except BaseException:
            share_cfg = {}
        if not isinstance(share_cfg, dict) or not bool(share_cfg.get('enabled', False)):
            return False
    success_fn = globals().get('_daily_flow_success_today')
    target = ''
    if flow_key == 'share':
        target_fn = globals().get('_daily_flow_target')
        try:
            target = str(target_fn('share') if callable(target_fn) else '')
        except BaseException:
            target = ''
    flow_success = False
    try:
        if callable(success_fn):
            flow_success = bool(success_fn(flow_key, target=target))
    except TypeError:
        try:
            flow_success = bool(success_fn(flow_key)) if callable(success_fn) else False
        except BaseException:
            flow_success = False
    except BaseException:
        flow_success = False
    if flow_success:
        if flow_key != 'share':
            return False
        # Direct send completion must gate every send phase, while the
        # independent reward remains due until its current-page proof exists.
        reward_success = False
        try:
            if callable(success_fn):
                reward_success = bool(success_fn(
                    'share_reward', target=target
                ))
        except TypeError:
            try:
                reward_success = bool(success_fn('share_reward'))
            except BaseException:
                reward_success = False
        except BaseException:
            reward_success = False
        if reward_success:
            return False
    blocked_fn = globals().get('_daily_flow_retry_blocked')
    try:
        blocked = bool(callable(blocked_fn) and blocked_fn(flow_key))
    except BaseException:
        blocked = False
    if blocked:
        # Free benefits has a strict same-day cap: no red-dot/coordinate override.
        if flow_key == 'freebenefits':
            return False
        coordinate_override = False
        if flow_key == 'share':
            day_fn = globals().get('_daily_business_date')
            try:
                day = str(
                    day_fn() if callable(day_fn)
                    else __import__('time').strftime('%Y-%m-%d')
                )
            except BaseException:
                day = ''
            marker_name = (
                '_qqfarm_native_v225_daily_coordinate_override_day_' + flow_key
            )
            try:
                already_used = str(getattr(context, marker_name, '') or '') == day
            except BaseException:
                already_used = True
            if not require_home:
                # The friend/unknown-scene gate only requests a return home.
                # Fresh home-scene red-dot proof is still required before clicking.
                coordinate_override = bool(day and not already_used)
            else:
                red_fn = globals().get('_daily_flow_entry_red_dot_state')
                try:
                    red_state = red_fn(context, flow_key) if callable(red_fn) else None
                except BaseException:
                    red_state = None
                coordinate_override = bool(
                    day and not already_used and red_state is True
                )
        if not coordinate_override:
            return False
    return True


def _native_v225_daily_flow_due(context, flow):
    """Decide whether a missed native daily route needs one home-scene catch-up."""
    return _native_v225_daily_candidate_due(
        context, flow, require_home=True
    )


def _native_v225_daily_any_due(context):
    """Return true when home-only daily work is due while the bot is elsewhere."""
    if context is None:
        return False
    try:
        stop_fn = globals().get('_stop_requested_in_args')
        if callable(stop_fn) and bool(stop_fn((context,), {})):
            return False
    except BaseException:
        pass
    for flow in ('freebenefits', 'share'):
        try:
            if _native_v225_daily_candidate_due(
                context, flow, require_home=False
            ):
                return True
        except BaseException:
            continue
    return False


def _native_v225_request_home_for_daily(context):
    """Use the native home action once so due daily UI never expires on a friend page."""
    if context is None:
        return False
    time_module = globals().get('time') or __import__('time')
    try:
        now_value = float(time_module.monotonic())
    except BaseException:
        now_value = float(time_module.time())
    try:
        last_value = float(getattr(
            context, '_qqfarm_native_v225_daily_home_requested_ts', 0.0
        ) or 0.0)
    except BaseException:
        last_value = 0.0
    if last_value > 0.0 and (now_value - last_value) < 8.0:
        return False
    frame = None
    frame_fn = globals().get('_get_frame_from_bot')
    try:
        frame = frame_fn(context) if callable(frame_fn) else None
    except BaseException:
        frame = None
    for method_name in ('go_home', 'check_go_home_icon', 'return_home', '_return_home'):
        try:
            action = getattr(context, method_name, None)
        except BaseException:
            action = None
        if not callable(action):
            continue
        try:
            signature = __import__('inspect').signature(action)
            positional = [
                parameter for parameter in signature.parameters.values()
                if parameter.kind in (
                    parameter.POSITIONAL_ONLY,
                    parameter.POSITIONAL_OR_KEYWORD,
                )
            ]
            use_frame = len(positional) >= 1 or any(
                parameter.kind == parameter.VAR_POSITIONAL
                for parameter in signature.parameters.values()
            )
        except BaseException:
            use_frame = False
        try:
            result = action(frame) if use_frame else action()
        except BaseException as error:
            try:
                _write(
                    'v450 native-v225 daily return-home error method=' +
                    method_name + ' error=' + repr(error)[:180]
                )
            except BaseException:
                pass
            continue
        accepted = bool(result is not False)
        if not accepted:
            continue
        try:
            setattr(
                context, '_qqfarm_native_v225_daily_home_requested_ts', now_value
            )
        except BaseException:
            pass
        try:
            _write(
                'v450 native-v225 daily due requested home method=' +
                method_name
            )
        except BaseException:
            pass
        return True
    return False


def _qqfarm_unwrap_daily_callable(fn):
    """Resolve a wrapper chain to its deepest callable without following cycles."""
    current = fn
    seen = set()
    attrs = (
        '__qqfarm_daily_flow_status_orig__',
        '__qqfarm_share_entry_settle_orig__',
        '__qqfarm_daily_claim_orig__',
        '__qqfarm_native_daily_orig__',
        '__wrapped__',
    )
    while callable(current) and id(current) not in seen:
        seen.add(id(current))
        next_callable = None
        for attr in attrs:
            try:
                candidate = getattr(current, attr, None)
            except BaseException:
                candidate = None
            if callable(candidate) and id(candidate) not in seen:
                next_callable = candidate
                break
        if next_callable is None:
            break
        current = next_callable
    return current if callable(current) else fn


def _native_v225_call_daily(fn, context):
    """Invoke the native daily leaf while avoiding cyclic runtime wrappers."""
    if not callable(fn):
        return False
    unwrap_fn = globals().get('_qqfarm_unwrap_daily_callable')
    if callable(unwrap_fn):
        try:
            fn = unwrap_fn(fn)
        except BaseException:
            pass
    frame = None
    frame_fn = globals().get('_get_frame_from_bot')
    try:
        frame = frame_fn(context) if callable(frame_fn) else None
    except BaseException:
        frame = None
    call_with_frame = False
    try:
        signature = __import__('inspect').signature(fn)
        positional = [
            parameter for parameter in signature.parameters.values()
            if parameter.kind in (
                parameter.POSITIONAL_ONLY,
                parameter.POSITIONAL_OR_KEYWORD,
            )
        ]
        call_with_frame = len(positional) >= 2 or any(
            parameter.kind == parameter.VAR_POSITIONAL
            for parameter in signature.parameters.values()
        )
    except BaseException:
        call_with_frame = False
    if call_with_frame:
        return fn(context, frame)
    try:
        return fn(context)
    except TypeError as error:
        message = str(error or '').lower()
        if frame is not None and (
            'required positional argument' in message
            or 'game_frame' in message
        ):
            return fn(context, frame)
        raise


def _run_native_v225_daily_catchup(context):
    """Run at most one due daily transaction, preserving native runtime ownership."""
    if not _native_v225_daily_home_ready(context):
        return ''
    try:
        if bool(getattr(context, '_qqfarm_native_v225_daily_catchup_running', False)):
            return ''
        setattr(context, '_qqfarm_native_v225_daily_catchup_running', True)
    except BaseException:
        return ''
    try:
        success_fn = globals().get('_daily_flow_success_today')
        attempted_fn = globals().get('_daily_flow_attempted_today')
        red_fn = globals().get('_daily_flow_entry_red_dot_state')
        try:
            already_success = bool(
                success_fn('freebenefits') if callable(success_fn) else False
            )
        except BaseException:
            already_success = False
        try:
            attempted = bool(
                attempted_fn(context, 'freebenefits')
                if callable(attempted_fn) else False
            )
        except BaseException:
            attempted = False
        try:
            red_state = (
                red_fn(context, 'freebenefits') if callable(red_fn) else None
            )
        except BaseException:
            red_state = None
        day_fn = globals().get('_daily_business_date')
        try:
            current_day = str(
                day_fn() if callable(day_fn)
                else __import__('time').strftime('%Y-%m-%d')
            )
        except BaseException:
            current_day = ''
        try:
            current_dispatch = bool(
                current_day and str(getattr(
                    context,
                    '_qqfarm_native_v225_daily_dispatch_day_freebenefits',
                    '',
                ) or '') == current_day
            )
        except BaseException:
            current_dispatch = False
        try:
            visual_verified = bool(
                current_day and str(getattr(
                    context,
                    '_qqfarm_freebenefits_claim_verified_day',
                    '',
                ) or '') == current_day
            )
        except BaseException:
            visual_verified = False
        if not already_success and visual_verified:
            mark_fn = globals().get('_daily_flow_mark_status')
            if callable(mark_fn):
                try:
                    mark_fn(
                        'freebenefits', 'success',
                        reason='verified-freebenefits-claim-v2',
                    )
                except BaseException:
                    pass
            apply_fn = globals().get('_daily_flow_apply_success_context')
            if callable(apply_fn):
                try:
                    apply_fn(context, 'freebenefits')
                except BaseException:
                    pass
            return 'freebenefits-confirmed'
        # The catch-up route may be polled many times while the marketplace
        # remains visible.  Once today's transaction was already dispatched,
        # skip only this native runner and continue to later daily transactions;
        # repeated entry can recurse through runtime wrappers and repeat clicks.
        module = _native_v225_daily_flow_module()
        if (
            not current_dispatch
            and _native_v225_daily_flow_due(context, 'freebenefits')
        ):
            run_free = getattr(module, 'run_daily_freebenefits', None) if module is not None else None
            if not callable(run_free):
                try:
                    _write('v450 native-v225 daily catch-up missing run_daily_freebenefits')
                except BaseException:
                    pass
                return ''
            try:
                setattr(
                    context,
                    '_qqfarm_native_v225_daily_catchup_last_freebenefits_ts',
                    float((globals().get('time') or __import__('time')).time()),
                )
            except BaseException:
                pass
            try:
                day_fn = globals().get('_daily_business_date')
                day = str(
                    day_fn() if callable(day_fn)
                    else __import__('time').strftime('%Y-%m-%d')
                )
                setattr(
                    context,
                    '_qqfarm_native_v225_daily_coordinate_override_day_freebenefits',
                    day,
                )
                setattr(
                    context,
                    '_qqfarm_native_v225_daily_dispatch_day_freebenefits',
                    day,
                )
            except BaseException:
                pass
            try:
                _native_v225_call_daily(run_free, context)
            except BaseException as error:
                try:
                    _write(
                        'v450 native-v225 freebenefits catch-up error=' +
                        repr(error)[:240]
                    )
                except BaseException:
                    pass
            return 'freebenefits'
        # A verified direct-recipient send and its reward are separate daily
        # transactions.  Once sending is complete, keep one reward-only catch-up
        # route alive even though the normal share scheduler is correctly gated.
        success_fn = globals().get('_daily_flow_success_today')
        share_success = False
        reward_success = False
        target_fn = globals().get('_daily_flow_target')
        target = target_fn('share') if callable(target_fn) else ''
        if callable(success_fn):
            try:
                share_success = bool(success_fn('share', target=target))
            except TypeError:
                share_success = bool(success_fn('share'))
            except BaseException:
                share_success = False
            try:
                reward_success = bool(success_fn(
                    'share_reward', target=target
                ))
            except TypeError:
                reward_success = bool(success_fn('share_reward'))
            except BaseException:
                reward_success = False
        if share_success and not reward_success:
            reward_fn = globals().get('_run_share_prompt_recovery')
            if callable(reward_fn):
                try:
                    reward_fn(context)
                    return 'share-reward'
                except BaseException as error:
                    try:
                        _write(
                            'v454 share reward-only catch-up error=' +
                            repr(error)[:240]
                        )
                    except BaseException:
                        pass
        if _native_v225_daily_flow_due(context, 'share'):
            share_fn = globals().get('_run_share_prompt_recovery')
            if not callable(share_fn):
                return ''
            try:
                day_fn = globals().get('_daily_business_date')
                day = str(
                    day_fn() if callable(day_fn)
                    else __import__('time').strftime('%Y-%m-%d')
                )
                setattr(
                    context,
                    '_qqfarm_native_v225_daily_coordinate_override_day_share',
                    day,
                )
            except BaseException:
                pass
            try:
                share_fn(context)
            except BaseException as error:
                try:
                    _write(
                        'v450 native-v225 exact-target share catch-up error=' +
                        repr(error)[:240]
                    )
                except BaseException:
                    pass
            return 'share'
        return ''
    finally:
        try:
            setattr(context, '_qqfarm_native_v225_daily_catchup_running', False)
        except BaseException:
            pass


def _qqfarm_native_friend_idle_home_recovery(context):
    """Return a stable actionless native friend page home with bounded retries."""
    if context is None:
        return False
    try:
        if bool(getattr(context, '_qqfarm_friend_entry_pending', False)):
            setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
            return False
        if bool(getattr(context, '_qqfarm_friend_chain_active', False)):
            setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
            return False
    except BaseException:
        return False
    capture_fn = globals().get('_get_frame_from_bot')
    try:
        frame = capture_fn(context) if callable(capture_fn) else None
    except BaseException:
        frame = None
    state_fn = globals().get('_friend_guard_friend_ui_state')
    try:
        friend_state = state_fn(frame) if callable(state_fn) and frame is not None else None
    except BaseException:
        friend_state = None
    if friend_state is not True:
        try:
            setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
            setattr(context, '_qqfarm_native_friend_idle_home_attempts', 0)
        except BaseException:
            pass
        return False
    for matcher_name in (
        '_friend_guard_steal_button_match',
        '_friend_guard_help_button_match',
    ):
        matcher = globals().get(matcher_name)
        if not callable(matcher):
            continue
        try:
            match = matcher(frame)
        except BaseException:
            match = None
        if isinstance(match, dict) and bool(match.get('matched')):
            try:
                setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
            except BaseException:
                pass
            return False
    try:
        rounds = int(getattr(
            context, '_qqfarm_native_friend_idle_rounds', 0
        ) or 0) + 1
        setattr(context, '_qqfarm_native_friend_idle_rounds', rounds)
    except BaseException:
        rounds = 1
    if rounds < 2:
        return False
    now_fn = globals().get('_friend_watchdog_now')
    try:
        now_value = float(now_fn()) if callable(now_fn) else float(__import__('time').time())
    except BaseException:
        now_value = 0.0
    try:
        last_attempt = float(getattr(
            context, '_qqfarm_native_friend_idle_home_last_ts', 0.0
        ) or 0.0)
        attempts = max(0, int(getattr(
            context, '_qqfarm_native_friend_idle_home_attempts', 0
        ) or 0))
    except BaseException:
        last_attempt, attempts = 0.0, 0
    if last_attempt > 0.0 and (now_value - last_attempt) < 8.0:
        return False
    if attempts >= 3:
        # Release the burst, then permit a later fresh bounded recovery instead
        # of clicking the same coordinate continuously.
        if last_attempt > 0.0 and (now_value - last_attempt) < 45.0:
            return False
        attempts = 0
    click_fn = globals().get('_invoke_friend_guard_home_coordinate_click')
    clicked = bool(click_fn(context, frame)) if callable(click_fn) else False
    next_attempts = attempts + (1 if clicked else 0)
    try:
        setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
        setattr(context, '_qqfarm_native_friend_idle_home_last_ts', now_value)
        setattr(context, '_qqfarm_native_friend_idle_home_attempts', next_attempts)
    except BaseException:
        pass
    if not clicked:
        return False

    sleep_fn = globals().get('_friend_guard_sleep')
    try:
        if callable(sleep_fn):
            sleep_fn(0.55)
        else:
            __import__('time').sleep(0.55)
    except BaseException:
        pass
    try:
        post_frame = capture_fn(context) if callable(capture_fn) else None
    except BaseException:
        post_frame = None
    try:
        post_state = (
            state_fn(post_frame)
            if callable(state_fn) and post_frame is not None
            else None
        )
    except BaseException:
        post_state = None

    writer = globals().get('_write')
    if post_state is False:
        try:
            setattr(context, '_qqfarm_native_friend_idle_home_attempts', 0)
            setattr(context, '_qqfarm_native_friend_idle_rounds', 0)
            setattr(context, '_qqfarm_live_scene_hint', 'home')
            setattr(context, '_qqfarm_cycle_branch_hint', 'home')
            setattr(context, '_qqfarm_friend_cycle_seen', False)
        except BaseException:
            pass
        try:
            if callable(writer):
                writer('v465 native friend idle home transition verified state=False')
        except BaseException:
            pass
        return True
    try:
        if callable(writer):
            writer(
                'v465 native friend idle home click delivered but transition '
                'unverified state=' + repr(post_state) + ' attempt=' +
                str(next_attempts) + '/3'
            )
    except BaseException:
        pass
    return False


def _wrap_native_v225_daily_catchup_run_cycle(fn, name=''):
    """Give the native run cycle one narrow daily catch-up point on home frames."""
    if not callable(fn):
        return fn, False
    if bool(getattr(fn, '__qqfarm_native_v225_daily_catchup_wrapped__', False)):
        return fn, False

    def _home_ready(context):
        ready_fn = globals().get('_native_v225_daily_home_ready')
        if callable(ready_fn):
            try:
                return bool(ready_fn(context))
            except BaseException:
                return False
        try:
            return str(getattr(
                context, '_qqfarm_live_scene_hint', ''
            ) or '').strip().lower() == 'home'
        except BaseException:
            return False

    def _wrapped(*args, **kwargs):
        context = args[0] if args else kwargs.get('self')
        catchup_fn = globals().get('_run_native_v225_daily_catchup')
        if _home_ready(context) and callable(catchup_fn):
            try:
                if catchup_fn(context):
                    return True
            except BaseException as error:
                try:
                    _write('v450 native-v225 daily pre-cycle error=' + repr(error)[:240])
                except BaseException:
                    pass
        if not _home_ready(context):
            any_due_fn = globals().get('_native_v225_daily_any_due')
            home_fn = globals().get('_native_v225_request_home_for_daily')
            try:
                if (
                    callable(any_due_fn) and bool(any_due_fn(context))
                    and callable(home_fn) and bool(home_fn(context))
                ):
                    return True
            except BaseException as error:
                try:
                    _write(
                        'v450 native-v225 daily return-home gate error=' +
                        repr(error)[:240]
                    )
                except BaseException:
                    pass
        result = fn(*args, **kwargs)
        if not _home_ready(context):
            recover_fn = globals().get(
                '_qqfarm_native_friend_idle_home_recovery'
            )
            try:
                if callable(recover_fn) and bool(recover_fn(context)):
                    return True
            except BaseException as error:
                try:
                    _write(
                        'v465 native friend idle home recovery error=' +
                        repr(error)[:240]
                    )
                except BaseException:
                    pass
        if _home_ready(context) and callable(catchup_fn):
            try:
                if catchup_fn(context):
                    return True
            except BaseException as error:
                try:
                    _write('v450 native-v225 daily post-cycle error=' + repr(error)[:240])
                except BaseException:
                    pass
        return result

    try:
        _wrapped.__name__ = getattr(fn, '__name__', 'run_cycle')
        _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
        _wrapped.__module__ = getattr(fn, '__module__', '')
        _wrapped.__doc__ = getattr(fn, '__doc__', None)
        _wrapped.__qqfarm_native_v225_daily_catchup_wrapped__ = True
        _wrapped.__qqfarm_native_v225_daily_catchup_original__ = fn
        _wrapped.__qqfarm_native_v225_daily_catchup_name__ = str(name)
    except BaseException:
        pass
    return _wrapped, True


def _patch_native_v225_daily_catchup_for_module(module, tag=''):
    """Patch the native cycle and active friend processor without legacy wrappers."""
    if module is None:
        return 0
    module_name = str(getattr(module, '__name__', '') or tag or '')
    targets = []
    try:
        cls = getattr(module, 'FarmBotCV', None)
        if isinstance(cls, type):
            targets.append((cls, module_name + '.FarmBotCV', True))
    except BaseException:
        pass
    targets.append((module, module_name, False))
    changed = 0
    for owner, prefix, is_class_target in targets:
        for method_name in (
            'run_cycle', 'process_friend_farm', 'process_self_farm'
        ):
            try:
                descriptor_type = ''
                if is_class_target:
                    raw = None
                    for base in getattr(owner, '__mro__', (owner,)):
                        if method_name in vars(base):
                            raw = vars(base)[method_name]
                            break
                    if isinstance(raw, staticmethod):
                        original = raw.__func__
                        descriptor_type = 'staticmethod'
                    elif isinstance(raw, classmethod):
                        original = raw.__func__
                        descriptor_type = 'classmethod'
                    else:
                        original = raw
                else:
                    original = getattr(owner, method_name, None)
                if not callable(original):
                    continue
                wrapped, installed = _wrap_native_v225_daily_catchup_run_cycle(
                    original, prefix + '.' + method_name
                )
                if not installed:
                    continue
                if descriptor_type == 'staticmethod':
                    setattr(owner, method_name, staticmethod(wrapped))
                elif descriptor_type == 'classmethod':
                    setattr(owner, method_name, classmethod(wrapped))
                else:
                    setattr(owner, method_name, wrapped)
                changed += 1
            except BaseException:
                continue
    return changed


def _patch_native_v225_daily_catchup_loaded(tag=''):
    """Install the daily bridge even when native runtime owns run_cycle."""
    changed = []
    try:
        sys_module = globals().get('sys') or __import__('sys')
        module_items = list(getattr(sys_module, 'modules', {}).items())
    except BaseException:
        module_items = []
    for module_name, module in module_items:
        try:
            if module is None or not str(module_name or '').startswith('bot.'):
                continue
            count = _patch_native_v225_daily_catchup_for_module(
                module, str(module_name)
            )
            if count:
                changed.append(str(module_name) + ':' + str(count))
        except BaseException:
            continue
    if changed:
        signature = ', '.join(changed[:80])
        if signature not in _NATIVE_V225_DAILY_CATCHUP_PATCH_LOG_SEEN:
            _NATIVE_V225_DAILY_CATCHUP_PATCH_LOG_SEEN.add(signature)
            try:
                _write(
                    'v450 native-v225 daily catch-up patched ' + str(tag) + ' ' +
                    signature
                )
            except BaseException:
                pass
    return changed

def _run_deferred_friend_troublemaker(context, frame):
    """Run deferred troublemaker work across adjacent friends and verify persistence."""
    if context is None:
        return False
    try:
        if bool(getattr(context, '_qqfarm_friend_chain_pending', False)):
            return False
        if not bool(getattr(context, '_qqfarm_friend_chain_exhausted', False)):
            return False
        if bool(getattr(context, '_qqfarm_friend_chain_troublemaker_ran', False)):
            return False
        now_fn = globals().get('_friend_watchdog_now')
        try:
            now_ts = (
                float(now_fn())
                if callable(now_fn)
                else float(__import__('time').time())
            )
        except BaseException:
            now_ts = 0.0
        try:
            full_miss_until = float(getattr(
                context, '_qqfarm_troublemaker_full_miss_until', 0.0
            ) or 0.0)
        except BaseException:
            full_miss_until = 0.0
        if full_miss_until > now_ts:
            try:
                _write(
                    'v187 troublemaker full-miss cooldown active remaining=' +
                    ('%.1f' % max(0.0, full_miss_until - now_ts)) + 's'
                )
            except BaseException:
                pass
            return False
        # The clean native runtime owns the complete batch transaction:
        # select one planted land, choose the trouble item once, then drag the
        # selected item across every planned land.  The old first-party helper
        # clicked several candidate lands while searching for a popup and is
        # intentionally excluded from the live route.
        action = getattr(context, '_run_friend_daily_troublemaker', None)
        first_party_action = False
        cached_action = False
        if not callable(action):
            action = getattr(
                context, '_qqfarm_friend_chain_deferred_troublemaker', None
            )
            cached_action = callable(action)
        if not callable(action):
            try:
                for module_name, module in list(sys.modules.items()):
                    if module is None or not str(module_name).startswith('bot.'):
                        continue
                    candidate = getattr(
                        module, '_run_friend_daily_troublemaker', None
                    )
                    if not callable(candidate):
                        continue
                    action = candidate
                    cached_action = True
                    setattr(
                        context,
                        '_qqfarm_friend_chain_deferred_troublemaker',
                        candidate,
                    )
                    setattr(
                        context,
                        '_qqfarm_friend_chain_deferred_troublemaker_args',
                        (context, frame),
                    )
                    setattr(
                        context,
                        '_qqfarm_friend_chain_deferred_troublemaker_kwargs',
                        {},
                    )
                    _write(
                        'v175 deferred daily troublemaker resolved runtime callable ' +
                        str(module_name) + '._run_friend_daily_troublemaker'
                    )
                    break
            except BaseException as error:
                try:
                    _write(
                        'v175 deferred troublemaker runtime resolver error=' +
                        repr(error)[:220]
                    )
                except BaseException:
                    pass
        if not callable(action):
            try:
                _write('v175 deferred daily troublemaker callable missing; retryable=True')
            except BaseException:
                pass
            return False

        try:
            retry_limit = int(getattr(
                context, 'friend_troublemaker_adjacent_retry_limit', 3
            ) or 3)
        except BaseException:
            retry_limit = 3
        retry_limit = max(1, min(12, retry_limit))
        snapshot_fn = globals().get('_friend_trouble_counter_snapshot')
        snapshot_available = callable(snapshot_fn)
        invoke_fn = globals().get('_invoke_friend_guard_action')
        adjacent_fn = globals().get('_invoke_friend_adjacent_card_navigation')
        capture_fn = globals().get('_get_frame_from_bot')
        state_fn = globals().get('_friend_guard_friend_ui_state')
        sleep_fn = globals().get('_friend_guard_sleep')
        marker = object()

        def _pause(seconds):
            try:
                if callable(sleep_fn):
                    sleep_fn(seconds)
                else:
                    __import__('time').sleep(seconds)
            except BaseException:
                pass

        def _restore_attr(name, previous):
            try:
                if previous is marker:
                    delattr(context, name)
                else:
                    setattr(context, name, previous)
            except BaseException:
                pass

        def _invoke_on_frame(current_frame):
            if first_party_action:
                return action(context, current_frame)
            if cached_action:
                try:
                    cached_args = list(getattr(
                        context,
                        '_qqfarm_friend_chain_deferred_troublemaker_args',
                        (),
                    ) or ())
                except BaseException:
                    cached_args = []
                try:
                    cached_kwargs = dict(getattr(
                        context,
                        '_qqfarm_friend_chain_deferred_troublemaker_kwargs',
                        {},
                    ) or {})
                except BaseException:
                    cached_kwargs = {}
                for index, value in enumerate(list(cached_args)):
                    try:
                        if value is not context and hasattr(value, 'shape'):
                            cached_args[index] = current_frame
                    except BaseException:
                        pass
                for key, value in list(cached_kwargs.items()):
                    try:
                        if value is not context and hasattr(value, 'shape'):
                            cached_kwargs[key] = current_frame
                    except BaseException:
                        pass
                if not cached_args:
                    cached_args = [context]
                if callable(invoke_fn):
                    return invoke_fn(
                        action, None, tuple(cached_args), cached_kwargs
                    )
                return action(*tuple(cached_args), **cached_kwargs)
            try:
                if callable(invoke_fn):
                    return invoke_fn(action, None, (context, current_frame), {})
                return action(current_frame)
            except TypeError:
                return action()

        current_frame = frame
        last_result = False
        for attempt in range(retry_limit):
            before_count = None
            if snapshot_available:
                try:
                    before_count = int(snapshot_fn(context))
                except BaseException:
                    before_count = 0

            previous_allow_home = getattr(
                context, '_qqfarm_friend_chain_allow_home', marker
            )
            previous_retry_active = getattr(
                context, '_qqfarm_troublemaker_retry_scan_active', marker
            )
            setattr(context, '_qqfarm_friend_chain_allow_home', True)
            setattr(context, '_qqfarm_troublemaker_retry_scan_active', True)
            try:
                last_result = _invoke_on_frame(current_frame)
            finally:
                _restore_attr(
                    '_qqfarm_troublemaker_retry_scan_active',
                    previous_retry_active,
                )
                _restore_attr(
                    '_qqfarm_friend_chain_allow_home', previous_allow_home
                )

            after_count = None
            if snapshot_available:
                try:
                    after_count = int(snapshot_fn(context))
                except BaseException:
                    after_count = int(before_count or 0)
                success = bool(after_count > int(before_count or 0))
            else:
                success = bool(last_result)
            try:
                _write(
                    'v150 deferred daily troublemaker attempt=' +
                    str(attempt + 1) + '/' + str(retry_limit) +
                    ' raw=' + repr(last_result)[:180] +
                    ' count=' + repr(before_count) + '->' + repr(after_count) +
                    ' success=' + repr(success) +
                    ' cached=' + repr(cached_action)
                )
            except BaseException:
                pass
            if success:
                setattr(context, '_qqfarm_friend_chain_troublemaker_ran', True)
                try:
                    setattr(context, '_qqfarm_troublemaker_full_miss_until', 0.0)
                except BaseException:
                    pass
                finalize_fn = globals().get(
                    '_finalize_friend_chain_after_troublemaker'
                )
                if callable(finalize_fn):
                    finalize_fn(context)
                try:
                    _write('v158 troublemaker success finalized friend chain')
                except BaseException:
                    pass
                return last_result
            debug_frame_fn = globals().get('_save_troublemaker_debug_frame')
            if callable(debug_frame_fn):
                try:
                    debug_path = debug_frame_fn(current_frame, attempt + 1)
                    if debug_path:
                        _write(
                            'v151 troublemaker debug frame saved=' + str(debug_path)
                        )
                except BaseException:
                    pass
            if attempt + 1 >= retry_limit or not callable(adjacent_fn):
                break

            try:
                moved_raw = adjacent_fn(context, current_frame)
                moved = bool(moved_raw[0]) if isinstance(moved_raw, tuple) else bool(moved_raw)
            except BaseException as error:
                moved = False
                try:
                    _write('v150 troublemaker adjacent navigation error=' + repr(error)[:220])
                except BaseException:
                    pass
            if not moved:
                break
            _pause(0.14)

            next_frame = None
            for poll in range(12):
                try:
                    candidate = capture_fn(context) if callable(capture_fn) else None
                except BaseException:
                    candidate = None
                if candidate is not None:
                    try:
                        ready = state_fn(candidate) if callable(state_fn) else True
                    except BaseException:
                        ready = None
                    if ready is True:
                        next_frame = candidate
                        break
                if poll < 11:
                    _pause(min(0.24, 0.08 + (0.015 * poll)))
            if next_frame is None:
                try:
                    _write(
                        'v150 troublemaker next friend surface not ready; '
                        'leaving retryable state'
                    )
                except BaseException:
                    pass
                break
            current_frame = next_frame

        setattr(context, '_qqfarm_friend_chain_troublemaker_ran', False)
        try:
            cooldown_seconds = float(getattr(
                context, 'friend_troublemaker_full_miss_cooldown_seconds', 90.0
            ) or 90.0)
        except BaseException:
            cooldown_seconds = 90.0
        cooldown_seconds = max(10.0, min(900.0, cooldown_seconds))
        try:
            cooldown_now = (
                float(now_fn())
                if callable(now_fn)
                else float(__import__('time').time())
            )
        except BaseException:
            cooldown_now = now_ts
        try:
            setattr(
                context, '_qqfarm_troublemaker_full_miss_until',
                float(cooldown_now) + cooldown_seconds,
            )
        except BaseException:
            pass
        try:
            _write(
                'v187 deferred daily troublemaker full miss; cooldown=' +
                ('%.1f' % cooldown_seconds) + 's'
            )
        except BaseException:
            pass
        try:
            _write(
                'v150 deferred daily troublemaker exhausted attempts; '
                'success=False retryable=True'
            )
        except BaseException:
            pass
        return False
    except BaseException as error:
        try:
            setattr(context, '_qqfarm_friend_chain_troublemaker_ran', False)
        except BaseException:
            pass
        try:
            _write('v150 deferred daily troublemaker error=' + repr(error)[:220])
        except BaseException:
            pass
        return False

def _run_friend_continuation_chain(
    context, start_frame, last_action_label='', action_provenance=''
):
    """Visit and process successive friends before allowing home recovery."""
    result = {
        'moves': 0,
        'actions': 0,
        'last_label': str(last_action_label or ''),
        'frame': start_frame,
        'exhausted': False,
        'reason': 'not-started',
    }
    if context is None or start_frame is None:
        result['reason'] = 'invalid-context-or-frame'
        return result
    try:
        quota_fn = globals().get('_friend_help_quota_active')
        quota_active = bool(
            quota_fn(context) if callable(quota_fn)
            else getattr(context, '_qqfarm_friend_help_quota_exhausted', False)
        )
    except BaseException:
        quota_active = False
    if quota_active:
        result['exhausted'] = True
        result['reason'] = 'friend-help-quota-exhausted'
        try:
            setattr(context, '_qqfarm_friend_chain_pending', False)
            setattr(context, '_qqfarm_friend_chain_exhausted', True)
            setattr(context, '_qqfarm_friend_chain_allow_home', True)
        except BaseException:
            pass
        return result
    try:
        guard_enabled_fn = globals().get('_guard_dog_ui_config_enabled')
        guard_mode_fn = globals().get('_guard_dog_detection_mode_config')
        guard_enabled = bool(guard_enabled_fn()) if callable(guard_enabled_fn) else False
        guard_mode = str(
            guard_mode_fn() if callable(guard_mode_fn) else 'avatar_frame'
        )
    except BaseException:
        guard_enabled, guard_mode = False, 'avatar_frame'
    try:
        verified_fn = globals().get('_friend_guard_verified_entry_active')
        verified_guard_row = bool(
            guard_enabled
            and guard_mode == 'avatar_frame'
            and callable(verified_fn)
            and verified_fn(context)
        )
    except BaseException:
        verified_guard_row = False
    move_fn = globals().get('_invoke_friend_next_actionable_entry')
    adjacent_fn = globals().get('_invoke_friend_adjacent_card_navigation')
    action_fn = globals().get('_invoke_friend_actions_before_home')
    fast_action_fn = globals().get('_invoke_friend_visual_actions_before_home')
    try:
        native_action_fallback_enabled = bool(
            not callable(fast_action_fn)
            or getattr(context, 'friend_chain_allow_native_action_fallback', False)
        )
    except BaseException:
        native_action_fallback_enabled = not callable(fast_action_fn)
    initial_native_action_fallback_enabled = bool(
        native_action_fallback_enabled
        or (guard_enabled and guard_mode == 'friend_guard_list')
    )
    capture_fn = globals().get('_get_frame_from_bot')
    state_fn = globals().get('_friend_guard_friend_ui_state')
    sleep_fn = globals().get('_friend_guard_sleep')
    write_fn = globals().get('_write')
    if not callable(move_fn) or not callable(action_fn) or not callable(capture_fn):
        result['reason'] = 'missing-chain-helper'
        return result
    try:
        setattr(context, '_qqfarm_friend_chain_active', True)
        setattr(context, '_qqfarm_friend_chain_pending', True)
        setattr(context, '_qqfarm_friend_chain_exhausted', False)
    except BaseException:
        pass
    try:
        restore_fn = globals().get('_restore_runtime_business_switches')
        if callable(restore_fn):
            restore_fn(context)
    except BaseException:
        pass
    try:
        fast_fn = globals().get('_set_friend_chain_fast_interval')
        if callable(fast_fn):
            fast_fn(context, True)
    except BaseException:
        pass
    try:
        limit = int(getattr(context, 'bottom_friend_list_help_all_limit', 12) or 12)
    except BaseException:
        limit = 12
    limit = max(1, min(50, limit))
    try:
        known_actionable_count = max(0, int(getattr(
            context, '_qqfarm_friend_list_visible_candidate_count', 0
        ) or 0))
    except BaseException:
        known_actionable_count = 0
    try:
        friend_list_start_cursor = max(0, int(getattr(
            context, '_qqfarm_friend_list_visit_cursor', 0
        ) or 0))
    except BaseException:
        friend_list_start_cursor = 0
    ordered_friend_patrol = bool(
        guard_enabled
        and guard_mode == 'friend_guard_list'
        and known_actionable_count > 0
    )
    ordered_friend_move_budget = (
        max(0, known_actionable_count - friend_list_start_cursor - 1)
        if ordered_friend_patrol else 0
    )
    try:
        configured_guard_gap_budget = int(getattr(
            context, 'friend_chain_guard_gap_scan_budget', 6
        ) or 6)
    except BaseException:
        configured_guard_gap_budget = 6
    configured_guard_gap_budget = max(2, min(limit, configured_guard_gap_budget))
    guard_gap_scan_budget = min(
        limit,
        max(
            configured_guard_gap_budget
            if guard_enabled and guard_mode == 'friend_guard_list'
            else 1,
            known_actionable_count * 2,
        ),
    )
    try:
        action_poll_limit = int(getattr(context, 'friend_chain_action_poll_limit', 16) or 16)
    except BaseException:
        action_poll_limit = 16
    action_poll_limit = max(24, min(36, action_poll_limit))
    try:
        primary_navigation_poll_limit = int(
            getattr(context, 'friend_chain_primary_navigation_poll_limit', 4) or 4
        )
    except BaseException:
        primary_navigation_poll_limit = 4
    primary_navigation_poll_limit = max(
        2, min(action_poll_limit - 1, primary_navigation_poll_limit)
    )
    try:
        idle_confirmations = int(
            getattr(context, 'friend_chain_idle_confirmations', 3) or 3
        )
    except BaseException:
        idle_confirmations = 3
    idle_confirmations = max(2, min(6, idle_confirmations))
    try:
        initial_idle_poll_min = int(getattr(
            context, 'friend_chain_initial_idle_poll_min', 8
        ) or 8)
    except BaseException:
        initial_idle_poll_min = 8
    initial_idle_poll_min = max(
        idle_confirmations, min(action_poll_limit, initial_idle_poll_min)
    )
    if guard_enabled and guard_mode == 'friend_guard_list':
        try:
            extended_entry_grace = bool(getattr(
                context, '_qqfarm_friend_entry_extended_action_grace', False
            ))
        except BaseException:
            extended_entry_grace = False
        try:
            guard_initial_idle_poll_min = int(getattr(
                context, 'friend_chain_guard_initial_idle_poll_min', 12
            ) or 12)
        except BaseException:
            guard_initial_idle_poll_min = 12
        if extended_entry_grace:
            guard_initial_idle_poll_min = max(20, guard_initial_idle_poll_min)
        initial_idle_poll_min = max(
            initial_idle_poll_min,
            min(action_poll_limit, max(idle_confirmations, guard_initial_idle_poll_min)),
        )
    try:
        preference_marker = object()
        prefer_adjacent_raw = getattr(
            context, 'friend_chain_prefer_adjacent_navigation', preference_marker
        )
        if prefer_adjacent_raw is preference_marker:
            cfg_fn = globals().get('_cfg_get')
            sections_fn = globals().get('_active_bot_sections')
            if callable(cfg_fn):
                sections = sections_fn() if callable(sections_fn) else ('bot',)
                prefer_adjacent_raw = cfg_fn(
                    sections,
                    'friend_chain_prefer_adjacent_navigation',
                    'False',
                )
            else:
                prefer_adjacent_raw = False
        prefer_adjacent_navigation = str(prefer_adjacent_raw).strip().lower() in (
            '1', 'true', 'yes', 'on', 'enabled'
        )
    except BaseException:
        prefer_adjacent_navigation = False

    def _pause(seconds):
        try:
            if callable(sleep_fn):
                sleep_fn(seconds)
            else:
                __import__('time').sleep(seconds)
        except BaseException:
            pass

    def _adjacent_move(frame_value):
        navigation_callable = adjacent_fn
        if not callable(navigation_callable):
            # Compatibility for isolated/unit-loaded helpers; the production
            # module always supplies the in-farm adjacent-card navigator.
            navigation_callable = move_fn
        if not callable(navigation_callable):
            return False, ''
        try:
            if navigation_callable is move_fn:
                raw = navigation_callable(context, frame_value, last_label)
            else:
                raw = navigation_callable(context, frame_value)
        except BaseException as error:
            if callable(write_fn):
                try:
                    write_fn('v85 friend adjacent navigation error=' + repr(error)[:220])
                except BaseException:
                    pass
            return False, ''
        if isinstance(raw, tuple):
            return bool(raw[0]), str(raw[1] if len(raw) > 1 else '')
        return bool(raw), ('visual.adjacent-friend-card' if raw else '')

    last_guard_dog_help_skip_reason = ''

    def _consume_guard_dog_help_skip():
        nonlocal last_guard_dog_help_skip_reason
        last_guard_dog_help_skip_reason = ''
        try:
            skipped = bool(getattr(
                context, '_qqfarm_guard_dog_help_skipped', False
            ))
            if skipped:
                last_guard_dog_help_skip_reason = str(getattr(
                    context, '_qqfarm_guard_dog_help_skip_reason', ''
                ) or '')
                setattr(context, '_qqfarm_guard_dog_help_skipped', False)
                setattr(context, '_qqfarm_guard_dog_help_skip_reason', '')
            return skipped
        except BaseException:
            return False

    def _consume_native_action_unverified():
        try:
            unverified = bool(getattr(
                context, '_qqfarm_friend_native_action_unverified', False
            ))
            if unverified:
                setattr(context, '_qqfarm_friend_native_action_unverified', False)
            return unverified
        except BaseException:
            return False

    def _drain_current_friend_actions(
        frame_value, handled_label='', initial_friend=False
    ):
        """Finish remaining visual actions on one friend before moving right."""
        if not callable(fast_action_fn):
            return frame_value, 0, '', True, 1

        def _action_kind(label_value):
            lowered = str(label_value or '').lower()
            if 'steal' in lowered or 'harvest' in lowered:
                return 'steal'
            if 'help' in lowered or 'farm' in lowered:
                return 'help'
            return lowered

        handled_kinds = set()
        seed_kind = _action_kind(handled_label)
        if seed_kind and not bool(initial_friend):
            handled_kinds.add(seed_kind)
        current_frame = frame_value
        added_actions = 0
        newest_label = ''
        idle_streak = 0
        surface_hits = 0
        repeated_action_counts = {}
        for drain_attempt in range(action_poll_limit):
            try:
                captured = capture_fn(context)
            except BaseException:
                captured = None
            if captured is not None:
                current_frame = captured
            try:
                current_state = (
                    state_fn(current_frame) if callable(state_fn) else True
                )
            except BaseException:
                current_state = None
            if current_state is not True:
                idle_streak = 0
                if drain_attempt < action_poll_limit - 1:
                    _pause(min(0.22, 0.08 + (0.015 * drain_attempt)))
                continue
            surface_hits += 1
            try:
                acted_now, label_now = fast_action_fn(context, current_frame)
            except BaseException as error:
                acted_now = False
                label_now = ''
                if callable(write_fn):
                    try:
                        write_fn(
                            'v116 friend current-card drain error=' +
                            repr(error)[:220]
                        )
                    except BaseException:
                        pass
            if _consume_guard_dog_help_skip():
                if callable(write_fn):
                    try:
                        write_fn(
                            'v131 guard dog rejected help; current friend is drained ' +
                            'without counting a help action'
                        )
                    except BaseException:
                        pass
                return current_frame, added_actions, newest_label, True, surface_hits
            if acted_now:
                action_kind = _action_kind(label_now)
                if action_kind and action_kind not in handled_kinds:
                    handled_kinds.add(action_kind)
                    added_actions += 1
                    newest_label = str(label_now or newest_label)
                    idle_streak = 0
                    if action_kind == 'help':
                        try:
                            setattr(
                                context,
                                '_qqfarm_post_steal_help_retry_pending',
                                False,
                            )
                        except BaseException:
                            pass
                    if callable(write_fn):
                        try:
                            write_fn(
                                'v116 friend current-card action drained action=' +
                                str(newest_label) + ' total=' + str(added_actions)
                            )
                        except BaseException:
                            pass
                    _pause(0.18)
                    continue
                # The same action being detected again means it has not yet
                # disappeared.  Keep this friend active and retry instead of
                # counting stale visibility as proof that the card is idle.
                idle_streak = 0
                repeated_key = str(action_kind or label_now or handled_label or 'action')
                repeated_count = int(repeated_action_counts.get(repeated_key, 0) or 0) + 1
                repeated_action_counts[repeated_key] = repeated_count
                if callable(write_fn):
                    try:
                        write_fn(
                            'v124 friend current-card action still visible action=' +
                            str(label_now or handled_label) +
                            ' retry=' + str(repeated_count) + '/3'
                        )
                    except BaseException:
                        pass
                if repeated_count >= 3:
                    return current_frame, added_actions, newest_label, False, surface_hits
                if drain_attempt < action_poll_limit - 1:
                    _pause(min(0.24, 0.09 + (0.015 * drain_attempt)))
                continue
            idle_streak += 1
            post_steal_grace_active = bool(
                seed_kind == 'steal' and int(added_actions or 0) <= 0
            )
            minimum_idle_polls = (
                initial_idle_poll_min
                if bool(initial_friend) or post_steal_grace_active
                else idle_confirmations
            )
            if (
                idle_streak >= idle_confirmations
                and (drain_attempt + 1) >= minimum_idle_polls
            ):
                try:
                    hold_initial_post_steal = bool(
                        post_steal_grace_active
                        and getattr(
                            context,
                            '_qqfarm_friend_entry_extended_action_grace',
                            False,
                        )
                    )
                except BaseException:
                    hold_initial_post_steal = False
                if hold_initial_post_steal:
                    try:
                        retry_pending = bool(getattr(
                            context,
                            '_qqfarm_post_steal_help_retry_pending',
                            False,
                        ))
                    except BaseException:
                        retry_pending = False
                    if not retry_pending:
                        try:
                            setattr(
                                context,
                                '_qqfarm_post_steal_help_retry_pending',
                                True,
                            )
                            if callable(write_fn):
                                write_fn(
                                    'v219 compiled steal completed; keeping the same '
                                    'friend for one more help probe before navigation'
                                )
                        except BaseException:
                            pass
                        return (
                            current_frame, added_actions, newest_label, False, surface_hits
                        )
                    try:
                        setattr(
                            context,
                            '_qqfarm_post_steal_help_retry_pending',
                            False,
                        )
                        if callable(write_fn):
                            write_fn(
                                'v219 post-steal help absence confirmed twice; '
                                'adjacent navigation may continue'
                            )
                    except BaseException:
                        pass
                return (
                    current_frame, added_actions, newest_label, True, surface_hits
                )
            if drain_attempt < action_poll_limit - 1:
                _pause(min(0.22, 0.08 + (0.015 * drain_attempt)))
        try:
            hold_initial_post_steal = bool(
                seed_kind == 'steal'
                and int(added_actions or 0) <= 0
                and getattr(
                    context,
                    '_qqfarm_friend_entry_extended_action_grace',
                    False,
                )
            )
        except BaseException:
            hold_initial_post_steal = False
        if hold_initial_post_steal:
            try:
                retry_pending = bool(getattr(
                    context, '_qqfarm_post_steal_help_retry_pending', False
                ))
            except BaseException:
                retry_pending = False
            if not retry_pending:
                try:
                    setattr(context, '_qqfarm_post_steal_help_retry_pending', True)
                    if callable(write_fn):
                        write_fn(
                            'v219 compiled steal probe exhausted; keeping the same '
                            'friend for one more help probe before navigation'
                        )
                except BaseException:
                    pass
                return current_frame, added_actions, newest_label, False, surface_hits
            try:
                setattr(context, '_qqfarm_post_steal_help_retry_pending', False)
            except BaseException:
                pass
            return current_frame, added_actions, newest_label, True, surface_hits
        return current_frame, added_actions, newest_label, False, surface_hits

    frame = start_frame
    last_label = str(last_action_label or '')

    def _carousel_card_key(bounds):
        try:
            if isinstance(bounds, dict):
                values = tuple(
                    int(bounds.get(key, 0) or 0)
                    for key in ('left', 'right', 'top', 'bottom')
                )
            elif isinstance(bounds, (tuple, list)) and len(bounds) >= 4:
                values = tuple(int(bounds[index] or 0) for index in range(4))
            else:
                return None
            if values[1] <= values[0] or values[3] <= values[2]:
                return None
            return values
        except BaseException:
            return None

    def _same_carousel_card(recorded_card, current_card):
        try:
            if recorded_card is None or current_card is None:
                return False
            recorded_width = max(1, int(recorded_card[1]) - int(recorded_card[0]))
            current_width = max(1, int(current_card[1]) - int(current_card[0]))
            recorded_height = max(1, int(recorded_card[3]) - int(recorded_card[2]))
            current_height = max(1, int(current_card[3]) - int(current_card[2]))
            recorded_center_x = (int(recorded_card[0]) + int(recorded_card[1])) / 2.0
            current_center_x = (int(current_card[0]) + int(current_card[1])) / 2.0
            recorded_center_y = (int(recorded_card[2]) + int(recorded_card[3])) / 2.0
            current_center_y = (int(current_card[2]) + int(current_card[3])) / 2.0
            horizontal_tolerance = max(
                8.0, min(20.0, max(recorded_width, current_width) * 0.22)
            )
            vertical_tolerance = max(
                5.0, min(12.0, max(recorded_height, current_height) * 0.18)
            )
            width_tolerance = max(
                6.0, min(18.0, max(recorded_width, current_width) * 0.22)
            )
            height_tolerance = max(
                5.0, min(14.0, max(recorded_height, current_height) * 0.18)
            )
            return bool(
                abs(current_center_x - recorded_center_x) <= horizontal_tolerance
                and abs(current_center_y - recorded_center_y) <= vertical_tolerance
                and abs(current_width - recorded_width) <= width_tolerance
                and abs(current_height - recorded_height) <= height_tolerance
            )
        except BaseException:
            return False

    if last_label:
        provenance_marker = object()
        try:
            live_action_provenance = (
                str(action_provenance or '').strip().lower() == 'live'
            )
        except BaseException:
            live_action_provenance = False
        try:
            raw_recorded_action_card = getattr(
                context, '_qqfarm_friend_action_last_card', provenance_marker
            )
            context_action_label = str(getattr(
                context, '_qqfarm_friend_action_last_label', ''
            ) or '')
            action_ts = float(getattr(
                context, '_qqfarm_friend_action_last_ts', 0.0
            ) or 0.0)
            current_bounds_fn = globals().get(
                '_friend_selected_carousel_card_bounds'
            )
            current_action_card = _carousel_card_key(
                current_bounds_fn(frame) if callable(current_bounds_fn) else None
            )
            recorded_action_card = _carousel_card_key(raw_recorded_action_card)
            # Context action metadata is only a compatibility bridge for the
            # immediate hand-off from a verified click.  It must never revive
            # a later patrol cycle just because the selected carousel card did
            # not move yet.  Normal verified callers pass action_provenance=
            # 'live'; this short window exists only for older call paths.
            now_fn = globals().get('_friend_guard_poll_now')
            now_ts = float(now_fn()) if callable(now_fn) else float(
                __import__('time').time()
            )
            context_action_max_age_seconds = 8.0
            context_action_age = now_ts - action_ts
            has_context_action_provenance = bool(
                context_action_label == last_label
                and action_ts > 0.0
                and 0.0 <= context_action_age <= context_action_max_age_seconds
                and _same_carousel_card(recorded_action_card, current_action_card)
            )
        except BaseException:
            raw_recorded_action_card = provenance_marker
            recorded_action_card = None
            current_action_card = None
            has_context_action_provenance = False
        if not (live_action_provenance or has_context_action_provenance):
            if callable(write_fn):
                try:
                    write_fn(
                        'v249 ignored unverified or stale friend action label; '
                        'ending this friend if no current action is found recorded=' +
                        repr(recorded_action_card) + ' current=' +
                        repr(current_action_card)
                    )
                except BaseException:
                    pass
            last_label = ''
            result['last_label'] = ''
            try:
                setattr(context, '_qqfarm_friend_action_last_ts', 0.0)
                setattr(context, '_qqfarm_friend_action_last_label', '')
                setattr(context, '_qqfarm_friend_action_last_card', None)
            except BaseException:
                pass
    try:
        compiled_home_blocked = bool(getattr(
            context, '_qqfarm_friend_chain_native_home_blocked', False
        ))
    except BaseException:
        compiled_home_blocked = False
    result['reason'] = 'limit-reached'
    loop_limit = limit
    if ordered_friend_patrol:
        # The visible list is an ordered, finite patrol manifest.  The selected
        # row is already the current friend, so only the remaining rows may be
        # reached through the in-farm adjacent-card control.
        loop_limit = min(loop_limit, ordered_friend_move_budget)
    try:
        guard_mode_fn = globals().get('_guard_dog_ui_config_enabled')
        guard_dog_list_filter_required = bool(
            callable(guard_mode_fn) and guard_mode_fn()
        )
    except BaseException:
        guard_dog_list_filter_required = False
    if guard_dog_list_filter_required:
        # The bottom carousel is already ordered by visible one-click actions.
        # Continue to the next card and stop only after the first confirmed
        # friend without an action; returning home immediately after one friend
        # skips the remaining actionable cards shown in the carousel.
        prefer_adjacent_navigation = True

    # Once the first friend has been entered, the list/menu route is forbidden.
    # It can open the friend list or appearance catalogue and can also skip the
    # immediately adjacent friend.  Continuation always stays on the in-farm
    # bottom carousel regardless of stale compiled/config preferences.
    prefer_adjacent_navigation = True

    # A friend-list visit can arrive before the first friend's one-click button
    # has finished rendering.  Never advance until the current friend surface is
    # stable and every visible steal/help action on that same friend is finished.
    if last_label:
        try:
            extended_entry_grace = bool(getattr(
                context, '_qqfarm_friend_entry_extended_action_grace', False
            ))
        except BaseException:
            extended_entry_grace = False
        try:
            guard_entry_still_prequalified = bool(
                guard_enabled
                and guard_mode == 'friend_guard_list'
                and callable(globals().get(
                    '_friend_guard_list_prequalified_entry_active'
                ))
                and globals()['_friend_guard_list_prequalified_entry_active'](context)
            )
        except BaseException:
            guard_entry_still_prequalified = False
        initial_friend_recheck = bool(
            extended_entry_grace or guard_entry_still_prequalified
        )
        (
            frame,
            drained_actions,
            drained_label,
            current_idle_confirmed,
            current_surface_hits,
        ) = _drain_current_friend_actions(
            frame, last_label, initial_friend=initial_friend_recheck
        )
        result['frame'] = frame
        result['actions'] += int(drained_actions or 0)
        if drained_label:
            last_label = str(drained_label)
            result['last_label'] = last_label
        if not current_idle_confirmed:
            result['reason'] = (
                'friend-surface-not-ready'
                if int(current_surface_hits or 0) <= 0
                else 'current-friend-not-idle'
            )
            loop_limit = 0
    else:
        initial_acted = False
        initial_action_label = ''
        initial_full_probe_done = False
        initial_ready_streak = 0
        initial_guard_help_skipped = False
        initial_guard_help_skip_reason = ''
        initial_native_action_unverified = False
        initial_fresh_frame_seen = False
        initial_signature_fn = globals().get('_friend_navigation_signature')
        initial_change_fn = globals().get('_friend_navigation_change_score')
        try:
            initial_start_signature = (
                initial_signature_fn(start_frame)
                if callable(initial_signature_fn) else None
            )
        except BaseException:
            initial_start_signature = None
        try:
            initial_freshness_threshold = float(getattr(
                context, 'friend_chain_initial_freshness_threshold', 0.004
            ) or 0.004)
        except BaseException:
            initial_freshness_threshold = 0.004
        initial_freshness_threshold = max(
            0.001, min(0.08, initial_freshness_threshold)
        )
        strict_initial_freshness = bool(
            ordered_friend_patrol
            and friend_list_start_cursor == 0
            and initial_start_signature is not None
        )
        initial_fresh_frame_seen = not strict_initial_freshness
        for initial_attempt in range(action_poll_limit):
            try:
                initial_frame = (
                    frame if initial_attempt == 0 else capture_fn(context)
                )
            except BaseException:
                initial_frame = None
            if initial_frame is not None:
                frame = initial_frame
                result['frame'] = frame
                try:
                    initial_state = (
                        state_fn(frame) if callable(state_fn) else True
                    )
                except BaseException:
                    initial_state = None
                if initial_state is not True:
                    initial_ready_streak = 0
                    if initial_attempt < action_poll_limit - 1:
                        _pause(min(0.22, 0.08 + (0.015 * initial_attempt)))
                    continue
                if not initial_fresh_frame_seen and initial_attempt > 0:
                    changed_score = None
                    try:
                        changed_score = (
                            initial_change_fn(initial_start_signature, initial_frame)
                            if callable(initial_change_fn) else None
                        )
                    except BaseException:
                        changed_score = None
                    initial_fresh_frame_seen = bool(
                        initial_frame is not start_frame
                        or (
                            changed_score is not None
                            and float(changed_score) >= initial_freshness_threshold
                        )
                    )
                    if initial_fresh_frame_seen:
                        try:
                            setattr(
                                context, '_qqfarm_first_friend_fresh_frame_seen', True
                            )
                        except BaseException:
                            pass
                if not initial_fresh_frame_seen:
                    initial_ready_streak = 0
                    if initial_attempt < action_poll_limit - 1:
                        _pause(min(0.22, 0.08 + (0.015 * initial_attempt)))
                    continue
                try:
                    if callable(fast_action_fn):
                        initial_acted, initial_action_label = fast_action_fn(
                            context, frame
                        )
                        if _consume_guard_dog_help_skip():
                            initial_guard_help_skipped = True
                            initial_guard_help_skip_reason = str(
                                last_guard_dog_help_skip_reason or ''
                            )
                            break
                    if (
                        not initial_acted
                        and initial_native_action_fallback_enabled
                        and not initial_full_probe_done
                        and (initial_attempt + 1) >= primary_navigation_poll_limit
                    ):
                        initial_full_probe_done = True
                        initial_acted, initial_action_label = action_fn(context, frame)
                        if _consume_native_action_unverified():
                            initial_native_action_unverified = True
                            initial_acted = False
                            initial_action_label = ''
                            break
                        if _consume_guard_dog_help_skip():
                            initial_guard_help_skipped = True
                            initial_guard_help_skip_reason = str(
                                last_guard_dog_help_skip_reason or ''
                            )
                            break
                except BaseException as error:
                    initial_acted = False
                    initial_action_label = ''
                    if callable(write_fn):
                        try:
                            write_fn(
                                'v116 friend initial ordered action error=' +
                                repr(error)[:220]
                            )
                        except BaseException:
                            pass
                if initial_acted:
                    break
                initial_ready_streak += 1
                if (
                    initial_ready_streak >= idle_confirmations
                    and (initial_attempt + 1) >= initial_idle_poll_min
                ):
                    break
            if initial_attempt < action_poll_limit - 1:
                _pause(min(0.22, 0.08 + (0.015 * initial_attempt)))
        if initial_acted:
            try:
                setattr(context, '_qqfarm_initial_guard_approval_pending_count', 0)
            except BaseException:
                pass
            result['actions'] += 1
            last_label = str(initial_action_label or '')
            result['last_label'] = last_label
            result['reason'] = 'initial-action-complete'
            _pause(0.18)
            (
                frame,
                drained_actions,
                drained_label,
                current_idle_confirmed,
                current_surface_hits,
            ) = _drain_current_friend_actions(frame, last_label)
            result['frame'] = frame
            result['actions'] += int(drained_actions or 0)
            if drained_label:
                last_label = str(drained_label)
                result['last_label'] = last_label
            if not current_idle_confirmed:
                result['reason'] = (
                    'friend-surface-not-ready'
                    if int(current_surface_hits or 0) <= 0
                    else 'current-friend-not-idle'
                )
                loop_limit = 0
        elif initial_native_action_unverified:
            result['reason'] = 'initial-native-action-unverified'
            loop_limit = 0
            if callable(write_fn):
                try:
                    write_fn(
                        'v212 unverified native help claim; keeping the first '
                        'friend active without carousel navigation'
                    )
                except BaseException:
                    pass
        elif initial_guard_help_skipped:
            # A missing guard identity can be transient while the first friend is
            # settling.  A stable footer-assisted soft texture is different: it
            # was already clicked and verified as static, so pinning the same card
            # would only repeat a false action instead of visiting later friends.
            definitive_soft_false_positive = bool(
                initial_guard_help_skip_reason ==
                'stable-soft-false-positive'
            )
            try:
                pending_limit = int(getattr(
                    context, 'friend_chain_guard_pending_retry_limit', 3
                ) or 3)
            except BaseException:
                pending_limit = 3
            pending_limit = max(1, min(8, pending_limit))
            if definitive_soft_false_positive:
                pending_count = pending_limit
            else:
                try:
                    pending_count = int(getattr(
                        context, '_qqfarm_initial_guard_approval_pending_count', 0
                    ) or 0) + 1
                except BaseException:
                    pending_count = 1
            try:
                setattr(
                    context, '_qqfarm_initial_guard_approval_pending_count',
                    pending_count,
                )
            except BaseException:
                pass
            if pending_count < pending_limit:
                result['reason'] = 'initial-guard-approval-pending'
                loop_limit = 0
                if callable(write_fn):
                    try:
                        write_fn(
                            'v188 initial guard approval pending; keeping the first '
                            'friend active retry=' + str(pending_count) + '/' +
                            str(pending_limit)
                        )
                    except BaseException:
                        pass
            else:
                result['reason'] = (
                    'initial-soft-false-positive-advance'
                    if definitive_soft_false_positive
                    else 'initial-guard-rejected-advance'
                )
                try:
                    setattr(
                        context, '_qqfarm_initial_guard_approval_pending_count', 0
                    )
                except BaseException:
                    pass
                clear_fn = globals().get('_friend_guard_clear_prequalification')
                if callable(clear_fn):
                    try:
                        clear_fn(context)
                    except BaseException:
                        pass
                if callable(write_fn):
                    try:
                        if definitive_soft_false_positive:
                            write_fn(
                                'v311 stable soft help false-positive released the '
                                'current friend immediately; advancing adjacent patrol'
                            )
                        else:
                            write_fn(
                                'v188 initial guard approval rejected after bounded '
                                'retries; advancing to the next adjacent friend'
                            )
                    except BaseException:
                        pass
        elif not initial_fresh_frame_seen:
            result['reason'] = 'friend-surface-not-ready'
            loop_limit = 0
            if callable(write_fn):
                try:
                    write_fn(
                        'v357 first friend frame remained stale; keeping cursor=' +
                        str(friend_list_start_cursor) + ' pending without navigation'
                    )
                except BaseException:
                    pass
        elif initial_ready_streak >= idle_confirmations:
            try:
                guard_list_initial_approved = bool(
                    guard_enabled
                    and guard_mode == 'friend_guard_list'
                    and callable(globals().get(
                        '_friend_guard_list_prequalified_entry_active'
                    ))
                    and globals()[
                        '_friend_guard_list_prequalified_entry_active'
                    ](context)
                )
            except BaseException:
                guard_list_initial_approved = False
            if compiled_home_blocked:
                # The compiled friend flow already completed its current-card
                # action and tried to return home.  The home gate is therefore
                # positive completion evidence even though the visual button has
                # disappeared before the Hook can record an action label.
                try:
                    setattr(
                        context, '_qqfarm_friend_chain_native_home_blocked', False
                    )
                except BaseException:
                    pass
                result['reason'] = 'compiled-current-friend-complete'
            elif ordered_friend_move_budget > 0:
                # Starting from row one is only half of ordered patrol.  A stable
                # no-action first friend must yield to row two rather than hiding
                # harvest/help work on later visible friends.
                result['reason'] = 'initial-friend-no-action-continue'
                clear_fn = globals().get('_friend_guard_clear_prequalification')
                if callable(clear_fn):
                    try:
                        clear_fn(context)
                    except BaseException:
                        pass
                if callable(write_fn):
                    try:
                        write_fn(
                            'v277 ordered friend patrol continuing after empty first '
                            'friend cursor=' + str(friend_list_start_cursor) + '/' +
                            str(known_actionable_count)
                        )
                    except BaseException:
                        pass
            else:
                result['exhausted'] = True
                result['reason'] = 'initial-friend-no-action'
                loop_limit = 0
        else:
            result['reason'] = 'friend-surface-not-ready'
            loop_limit = 0
    if verified_guard_row:
        pending_reasons = ('friend-surface-not-ready', 'current-friend-not-idle')
        if str(result.get('reason', '')) not in pending_reasons:
            result['exhausted'] = True
            result['reason'] = 'verified-guard-row-complete'
            try:
                setattr(context, '_qqfarm_guard_row_verified', False)
            except BaseException:
                pass
            if callable(write_fn):
                try:
                    write_fn(
                        'v135 verified dog-badge friend drained; '
                        'returning to list before selecting another friend'
                    )
                except BaseException:
                    pass
        loop_limit = 0
    for index in range(loop_limit):
        try:
            stop_fn = globals().get('_is_stop_requested_like')
            if callable(stop_fn) and stop_fn(context):
                result['reason'] = 'stop-requested'
                break
        except BaseException:
            pass
        # `frame` already belongs to the friend just fully drained.  Capturing
        # again here can advance the synthetic/live frame stream before the click
        # and makes the chain skip the immediately adjacent card.
        signature_fn = globals().get('_friend_navigation_signature')
        score_fn = globals().get('_friend_navigation_change_score')
        selected_bounds_fn = globals().get('_friend_selected_carousel_card_bounds')
        selection_changed_fn = globals().get('_friend_carousel_selection_changed')
        try:
            before_navigation_signature = (
                signature_fn(frame) if callable(signature_fn) else None
            )
        except BaseException:
            before_navigation_signature = None
        try:
            before_selected_bounds = (
                selected_bounds_fn(frame) if callable(selected_bounds_fn) else None
            )
        except BaseException:
            before_selected_bounds = None
        fallback_attempted = False
        fallback_succeeded = False
        moved = False
        navigation_label = ''
        if prefer_adjacent_navigation:
            # Stay inside the current friend's farm.  Never open the friend list,
            # appearance/menu pages, or a native list-entry fallback from this chain.
            moved, navigation_label = _adjacent_move(frame)
            fallback_attempted = bool(moved)
            fallback_succeeded = bool(moved)
            if not moved:
                result['exhausted'] = True
                result['reason'] = 'no-next-bottom-card'
                break
        else:
            try:
                moved, navigation_label = move_fn(context, frame, last_label)
            except BaseException as error:
                moved, navigation_label = False, ''
                result['reason'] = 'navigation-error'
                if callable(write_fn):
                    try:
                        write_fn('v89 friend continuation navigation error=' + repr(error)[:220])
                    except BaseException:
                        pass
            if not moved:
                moved, navigation_label = _adjacent_move(frame)
                fallback_attempted = bool(moved)
                fallback_succeeded = bool(moved)
            if not moved:
                result['exhausted'] = True
                result['reason'] = 'no-next-entry'
                break
        _pause(0.12)

        next_frame = None
        friend_state = None
        acted = False
        action_label = ''
        guard_help_skipped = False
        native_action_unverified = False
        blocked_next_friend_returned_home = False
        # Synthetic/unreadable captures may not expose a usable signature.  Keep
        # the legacy bounded path for those cases; real farm frames provide the
        # signature and/or selected-card geometry used by the strict stale-frame gate.
        navigation_confirmed = before_navigation_signature is None
        navigation_change_hits = 0
        move_counted = False
        full_action_probed = False
        friend_ready_streak = 0
        use_fast_action_probe = callable(fast_action_fn)
        guard_identity_refreshed = False
        try:
            navigation_threshold = float(
                getattr(context, 'friend_chain_navigation_change_threshold', 0.012) or 0.012
            )
        except BaseException:
            navigation_threshold = 0.012
        navigation_threshold = max(0.004, min(0.12, navigation_threshold))
        for action_attempt in range(action_poll_limit):
            try:
                candidate = capture_fn(context)
            except BaseException:
                candidate = None
            if candidate is not None:
                next_frame = candidate
                action_probed = False
                try:
                    friend_state = (
                        state_fn(candidate) if callable(state_fn) else True
                    )
                except BaseException:
                    friend_state = None
                if friend_state is True:
                    friend_ready_streak += 1
                else:
                    friend_ready_streak = 0
                    try:
                        blocked_hint_fn = globals().get(
                            '_friend_blocked_visit_visual_hint'
                        )
                        blocked_next_friend_returned_home = bool(
                            blocked_hint_fn(candidate)
                        ) if callable(blocked_hint_fn) else False
                    except BaseException:
                        blocked_next_friend_returned_home = False
                    if blocked_next_friend_returned_home:
                        navigation_confirmed = True
                        if not move_counted:
                            result['moves'] += 1
                            move_counted = True
                        frame = candidate
                        result['frame'] = frame
                        if callable(write_fn):
                            try:
                                write_fn(
                                    'v219 blocked next friend returned home; '
                                    'finishing adjacent friend chain normally'
                                )
                            except BaseException:
                                pass
                        break
                # Never use a visible action from the first post-click frames as
                # navigation proof.  The previous friend's button can remain on
                # screen during the carousel transition; clicking it here advances
                # again from stale geometry and skips the immediately adjacent friend.
                # Wait for an independent carousel-selection or page-signature
                # confirmation first, then probe actions on the confirmed friend.
                if not navigation_confirmed and isinstance(before_selected_bounds, dict):
                    try:
                        after_selected_bounds = (
                            selected_bounds_fn(candidate)
                            if callable(selected_bounds_fn) else None
                        )
                    except BaseException:
                        after_selected_bounds = None
                    try:
                        selection_changed = bool(
                            selection_changed_fn(
                                before_selected_bounds,
                                after_selected_bounds,
                                getattr(candidate, 'shape', (0, 428))[1]
                                if getattr(candidate, 'shape', None) is not None
                                else 428,
                            )
                        ) if callable(selection_changed_fn) else False
                    except BaseException:
                        selection_changed = False
                    if selection_changed:
                        navigation_confirmed = True
                        if callable(write_fn):
                            try:
                                write_fn(
                                    'v120 friend navigation confirmed by carousel selection ' +
                                    repr(before_selected_bounds)[:120] + ' -> ' +
                                    repr(after_selected_bounds)[:120]
                                )
                            except BaseException:
                                pass
                if not navigation_confirmed and before_navigation_signature is not None:
                    try:
                        change_score = (
                            score_fn(before_navigation_signature, candidate)
                            if callable(score_fn) else None
                        )
                    except BaseException:
                        change_score = None
                    if change_score is None:
                        navigation_confirmed = True
                    elif float(change_score) >= navigation_threshold:
                        navigation_change_hits += 1
                        if navigation_change_hits >= 2:
                            navigation_confirmed = True
                    else:
                        navigation_change_hits = 0
                    if not navigation_confirmed:
                        if (
                            not fallback_attempted
                            and (action_attempt + 1) >= primary_navigation_poll_limit
                        ):
                            fallback_moved, fallback_label = _adjacent_move(frame)
                            fallback_attempted = True
                            if fallback_moved:
                                fallback_succeeded = True
                                navigation_label = fallback_label or navigation_label
                                navigation_change_hits = 0
                                _pause(0.10)
                                continue
                        if action_attempt < action_poll_limit - 1:
                            _pause(min(0.18, 0.06 + (0.012 * action_attempt)))
                        continue
                if not move_counted:
                    result['moves'] += 1
                    move_counted = True
                if (
                    guard_enabled
                    and guard_mode == 'friend_guard_list'
                    and not guard_identity_refreshed
                ):
                    refresh_fn = globals().get(
                        '_friend_guard_list_refresh_prequalification'
                    )
                    if callable(refresh_fn):
                        try:
                            refresh_fn(context, candidate)
                        except BaseException:
                            pass
                    guard_identity_refreshed = True
                frame = candidate
                result['frame'] = frame
                if friend_state is True:
                    try:
                        if use_fast_action_probe:
                            if not action_probed:
                                acted, action_label = fast_action_fn(context, frame)
                                action_probed = True
                                if _consume_guard_dog_help_skip():
                                    guard_help_skipped = True
                                    break
                            if (
                                not acted
                                and native_action_fallback_enabled
                                and not full_action_probed
                            ):
                                full_action_probed = True
                                acted, action_label = action_fn(context, frame)
                                if _consume_native_action_unverified():
                                    native_action_unverified = True
                                    acted = False
                                    action_label = ''
                                    break
                                if _consume_guard_dog_help_skip():
                                    guard_help_skipped = True
                                    break
                        elif not action_probed:
                            acted, action_label = action_fn(context, frame)
                            if _consume_native_action_unverified():
                                native_action_unverified = True
                                acted = False
                                action_label = ''
                                break
                            if _consume_guard_dog_help_skip():
                                guard_help_skipped = True
                                break
                    except BaseException as error:
                        acted = False
                        action_label = ''
                        if callable(write_fn):
                            try:
                                write_fn('v116 friend continuation action error=' + repr(error)[:220])
                            except BaseException:
                                pass
                if acted:
                    break
            if action_attempt < action_poll_limit - 1:
                _pause(min(0.24, 0.08 + (0.020 * action_attempt)))
        if next_frame is None:
            result['reason'] = 'missing-frame-after-navigation'
            break
        if blocked_next_friend_returned_home:
            result['exhausted'] = True
            result['reason'] = 'blocked-next-friend-returned-home'
            break
        if not navigation_confirmed:
            result['reason'] = 'navigation-not-confirmed'
            break
        if native_action_unverified:
            result['reason'] = 'native-action-unverified'
            if callable(write_fn):
                try:
                    write_fn(
                        'v212 unverified native help claim; keeping the current '
                        'friend active without carousel navigation'
                    )
                except BaseException:
                    pass
            break
        if guard_help_skipped:
            result['reason'] = 'guard-dog-help-skipped'
            if callable(write_fn):
                try:
                    write_fn(
                        'v131 guard dog rejected help; advancing to next adjacent friend'
                    )
                except BaseException:
                    pass
            continue
        if not acted:
            if friend_ready_streak < idle_confirmations:
                # A transition, overlay, or unreadable frame is not proof that
                # the friend has no work.  Stop in place so the next cycle can
                # retry this same friend instead of skipping to later cards.
                result['reason'] = 'friend-surface-not-ready'
                break
            current_ordered_cursor = friend_list_start_cursor + int(
                result.get('moves', 0) or 0
            )
            if (
                ordered_friend_patrol
                and current_ordered_cursor < (known_actionable_count - 1)
            ):
                result['reason'] = 'ordered-friend-no-action-continue'
                clear_fn = globals().get('_friend_guard_clear_prequalification')
                if callable(clear_fn):
                    try:
                        clear_fn(context)
                    except BaseException:
                        pass
                if callable(write_fn):
                    try:
                        write_fn(
                            'v277 ordered friend patrol continuing after no-action '
                            'cursor=' + str(current_ordered_cursor) + '/' +
                            str(known_actionable_count)
                        )
                    except BaseException:
                        pass
                continue
            result['exhausted'] = True
            result['reason'] = 'first-no-action-friend'
            clear_fn = globals().get('_friend_guard_clear_prequalification')
            if callable(clear_fn):
                try:
                    clear_fn(context)
                except BaseException:
                    pass
            if callable(write_fn):
                try:
                    write_fn(
                        'v277 ordered friend patrol reached its final visible friend; '
                        'ending after stable no-action'
                    )
                except BaseException:
                    pass
            break
        if acted:
            result['actions'] += 1
            if action_label:
                last_label = str(action_label)
                result['last_label'] = last_label
            result['reason'] = 'action-complete'
            _pause(0.18)
            (
                frame,
                drained_actions,
                drained_label,
                current_idle_confirmed,
                current_surface_hits,
            ) = _drain_current_friend_actions(frame, last_label)
            result['frame'] = frame
            result['actions'] += int(drained_actions or 0)
            if drained_label:
                last_label = str(drained_label)
                result['last_label'] = last_label
            if not current_idle_confirmed:
                result['reason'] = (
                    'friend-surface-not-ready'
                    if int(current_surface_hits or 0) <= 0
                    else 'current-friend-not-idle'
                )
                break
    result['frame'] = frame
    if int(result.get('moves', 0) or 0) > 0:
        try:
            branch_now = float(time.time())
        except BaseException:
            try:
                branch_now = float(__import__('time').time())
            except BaseException:
                branch_now = 0.0
        try:
            setattr(context, '_qqfarm_friend_branch_last_ts', branch_now)
            setattr(context, '_qqfarm_visual_friend_count', 1)
            setattr(context, '_last_friend_farm_go_home_present', True)
        except BaseException:
            pass
    try:
        moved_count = int(result.get('moves', 0) or 0)
        visible_count = int(getattr(
            context, '_qqfarm_friend_list_visible_candidate_count', 0
        ) or 0)
        if moved_count > 0 and visible_count > 0:
            snapshot_fn = globals().get('_friend_progress_state_snapshot')
            progress_snapshot = (
                snapshot_fn(context) if callable(snapshot_fn) else None
            )
            current_cursor = max(0, int(getattr(
                context, '_qqfarm_friend_list_visit_cursor', 0
            ) or 0))
            setattr(
                context,
                '_qqfarm_friend_list_visit_cursor',
                current_cursor + moved_count,
            )
            commit_fn = globals().get('_friend_progress_journal_commit')
            cursor_committed = True
            if callable(commit_fn):
                cursor_committed = bool(commit_fn(
                    context,
                    snapshot=progress_snapshot,
                    reason='carousel-cursor-advance',
                ))
            if not cursor_committed:
                result['reason'] = 'carousel-cursor-journal-retry'
                result['exhausted'] = True
            elif callable(write_fn):
                write_fn(
                    'v203 friend list cursor advanced by carousel moves=' +
                    str(moved_count) + ' cursor=' +
                    str(current_cursor + moved_count) + '/' + str(visible_count)
                )
    except BaseException:
        pass
    if callable(write_fn):
        try:
            write_fn('v85 friend continuation summary moves=' + str(result['moves']) +
                     ' actions=' + str(result['actions']) +
                     ' exhausted=' + repr(result['exhausted']) +
                     ' reason=' + str(result['reason']) +
                     ' last=' + str(result['last_label']))
        except BaseException:
            pass
    try:
        terminal = bool(result.get('exhausted', False))
        setattr(context, '_qqfarm_friend_chain_exhausted', terminal)
        setattr(context, '_qqfarm_friend_chain_pending', not terminal)
        setattr(context, '_qqfarm_friend_chain_active', False)
        setattr(context, '_qqfarm_friend_entry_extended_action_grace', False)
    except BaseException:
        pass
    return result

def _set_friend_chain_fast_interval(context, active):
    if context is None:
        return False
    try:
        active = bool(active)
        if active:
            if not hasattr(context, '_qqfarm_friend_chain_original_interval'):
                current = float(getattr(context, 'check_interval', 15.0) or 15.0)
                setattr(context, '_qqfarm_friend_chain_original_interval', current)
            current = float(getattr(context, 'check_interval', 15.0) or 15.0)
            setattr(context, 'check_interval', min(current, 0.75))
            setattr(context, '_qqfarm_friend_chain_active', True)
        else:
            original = getattr(context, '_qqfarm_friend_chain_original_interval', None)
            if original is not None:
                setattr(context, 'check_interval', float(original))
                try:
                    delattr(context, '_qqfarm_friend_chain_original_interval')
                except BaseException:
                    pass
            setattr(context, '_qqfarm_friend_chain_active', False)
            setattr(context, '_qqfarm_friend_chain_count', 0)
        return True
    except BaseException:
        return False

def _invoke_friend_guard_relaxed_home_check(
    action, target, context, original_args=(), original_kwargs=None
):
    marker = object()
    old_threshold = getattr(context, 'go_home_frame_threshold', marker)
    try:
        current = 0.70 if old_threshold is marker else float(old_threshold)
        setattr(context, 'go_home_frame_threshold', min(current, 0.52))
        return _invoke_friend_guard_action(
            action, target, original_args, original_kwargs
        )
    finally:
        if old_threshold is marker:
            try:
                delattr(context, 'go_home_frame_threshold')
            except BaseException:
                pass
        else:
            try:
                setattr(context, 'go_home_frame_threshold', old_threshold)
            except BaseException:
                pass


def _friend_guard_scale_point_to_client(
    frame_x, frame_y, frame_width, frame_height, client_width, client_height
):
    """Map normalized capture pixels to the real DPI-aware client surface."""
    try:
        fw = max(1.0, float(frame_width))
        fh = max(1.0, float(frame_height))
        cw = max(1, int(client_width))
        ch = max(1, int(client_height))
        client_x = int(round(float(frame_x) * float(cw) / fw))
        client_y = int(round(float(frame_y) * float(ch) / fh))
        return (
            max(0, min(cw - 1, client_x)),
            max(0, min(ch - 1, client_y)),
        )
    except BaseException:
        return int(frame_x), int(frame_y)


def _friend_guard_screen_point_owned_by_farm(screen_x, screen_y):
    """Return True only when the screen point currently belongs to QQ classic farm."""
    try:
        win32gui = __import__('win32gui')
        target_hwnd = int(win32gui.WindowFromPoint((int(screen_x), int(screen_y))) or 0)
        if not target_hwnd:
            return False
        candidates = []

        def _cb(hwnd, extra):
            try:
                if not win32gui.IsWindowVisible(hwnd) or win32gui.IsIconic(hwnd):
                    return True
                if str(win32gui.GetWindowText(hwnd) or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                candidates.append(int(hwnd))
            except BaseException:
                pass
            return True

        win32gui.EnumWindows(_cb, None)
        for root_hwnd in candidates:
            if target_hwnd == root_hwnd or win32gui.IsChild(root_hwnd, target_hwnd):
                return True
        return False
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        class POINT(ctypes.Structure):
            _fields_ = [('x', ctypes.c_long), ('y', ctypes.c_long)]

        point = POINT(int(screen_x), int(screen_y))
        target_hwnd = int(user32.WindowFromPoint(point) or 0)
        if not target_hwnd:
            return False
        candidates = []
        enum_proc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        def _cb(hwnd, lparam):
            try:
                if not user32.IsWindowVisible(hwnd) or user32.IsIconic(hwnd):
                    return True
                title_buf = ctypes.create_unicode_buffer(256)
                user32.GetWindowTextW(hwnd, title_buf, 255)
                if str(title_buf.value or '').strip() == '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    candidates.append(int(hwnd))
            except BaseException:
                pass
            return True

        user32.EnumWindows(enum_proc(_cb), 0)
        for root_hwnd in candidates:
            if target_hwnd == root_hwnd or user32.IsChild(
                ctypes.c_void_p(root_hwnd), ctypes.c_void_p(target_hwnd)
            ):
                return True
    except BaseException:
        pass
    return False


def _friend_guard_post_client_click(
    frame_x, frame_y, frame_width=428, frame_height=800
):
    """Post a click to the DPI-aware QQ farm render surface."""
    try:
        win32gui = __import__('win32gui')
        candidates = []

        def _cb(hwnd, extra):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return True
                if str(win32gui.GetWindowText(hwnd) or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = win32gui.GetClientRect(hwnd)
                width = int(rect[2] - rect[0])
                height = int(rect[3] - rect[1])
                if width < 300 or height < 500:
                    return True
                scale_x = float(width) / max(1.0, float(frame_width))
                scale_y = float(height) / max(1.0, float(frame_height))
                candidates.append((abs(scale_x - scale_y), -width * height, int(hwnd), width, height))
            except BaseException:
                pass
            return True

        win32gui.EnumWindows(_cb, None)
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            _, _, root_hwnd, client_width, client_height = candidates[0]
            client_x, client_y = _friend_guard_scale_point_to_client(
                frame_x, frame_y, frame_width, frame_height,
                client_width, client_height,
            )
            screen_point = win32gui.ClientToScreen(root_hwnd, (client_x, client_y))
            target_hwnd = int(win32gui.WindowFromPoint(screen_point) or 0)
            if not target_hwnd or (
                target_hwnd != root_hwnd
                and not win32gui.IsChild(root_hwnd, target_hwnd)
            ):
                target_hwnd = root_hwnd
            target_point = win32gui.ScreenToClient(target_hwnd, screen_point)
            lparam = ((int(target_point[1]) & 0xffff) << 16) | (int(target_point[0]) & 0xffff)
            win32gui.PostMessage(target_hwnd, 0x0200, 0, lparam)
            win32gui.PostMessage(target_hwnd, 0x0201, 0x0001, lparam)
            win32gui.PostMessage(target_hwnd, 0x0202, 0, lparam)
            return True
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        candidates = []
        enum_proc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        class RECT(ctypes.Structure):
            _fields_ = [
                ('left', ctypes.c_long), ('top', ctypes.c_long),
                ('right', ctypes.c_long), ('bottom', ctypes.c_long),
            ]

        class POINT(ctypes.Structure):
            _fields_ = [('x', ctypes.c_long), ('y', ctypes.c_long)]

        def _cb(hwnd, lparam):
            try:
                if not user32.IsWindowVisible(hwnd):
                    return True
                title_buf = ctypes.create_unicode_buffer(256)
                user32.GetWindowTextW(hwnd, title_buf, 255)
                if str(title_buf.value or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = RECT()
                if not user32.GetClientRect(hwnd, ctypes.byref(rect)):
                    return True
                width = int(rect.right - rect.left)
                height = int(rect.bottom - rect.top)
                if width >= 300 and height >= 500:
                    scale_x = float(width) / max(1.0, float(frame_width))
                    scale_y = float(height) / max(1.0, float(frame_height))
                    candidates.append((abs(scale_x - scale_y), -width * height, int(hwnd), width, height))
            except BaseException:
                pass
            return True

        user32.EnumWindows(enum_proc(_cb), 0)
        if not candidates:
            return False
        candidates.sort(key=lambda item: (item[0], item[1]))
        _, _, root_hwnd, client_width, client_height = candidates[0]
        client_x, client_y = _friend_guard_scale_point_to_client(
            frame_x, frame_y, frame_width, frame_height,
            client_width, client_height,
        )
        screen_point = POINT(int(client_x), int(client_y))
        if not user32.ClientToScreen(ctypes.c_void_p(root_hwnd), ctypes.byref(screen_point)):
            return False
        target_hwnd = int(user32.WindowFromPoint(screen_point) or 0)
        if not target_hwnd or (
            target_hwnd != root_hwnd
            and not user32.IsChild(ctypes.c_void_p(root_hwnd), ctypes.c_void_p(target_hwnd))
        ):
            target_hwnd = root_hwnd
        client_point = POINT(int(screen_point.x), int(screen_point.y))
        if not user32.ScreenToClient(ctypes.c_void_p(target_hwnd), ctypes.byref(client_point)):
            return False
        lparam = ((int(client_point.y) & 0xffff) << 16) | (int(client_point.x) & 0xffff)
        user32.PostMessageW(ctypes.c_void_p(target_hwnd), 0x0200, 0, lparam)
        down_ok = user32.PostMessageW(ctypes.c_void_p(target_hwnd), 0x0201, 0x0001, lparam)
        up_ok = user32.PostMessageW(ctypes.c_void_p(target_hwnd), 0x0202, 0, lparam)
        return bool(down_ok and up_ok)
    except BaseException:
        return False

def _friend_guard_frame_to_screen(
    frame_x, frame_y, frame_width=428, frame_height=800
):
    """Translate capture coordinates to DPI-aware absolute screen pixels."""
    try:
        win32gui = __import__('win32gui')
        candidates = []

        def _cb(hwnd, extra):
            try:
                if not win32gui.IsWindowVisible(hwnd):
                    return True
                if str(win32gui.GetWindowText(hwnd) or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = win32gui.GetClientRect(hwnd)
                width = int(rect[2] - rect[0])
                height = int(rect[3] - rect[1])
                if width < 300 or height < 500:
                    return True
                scale_x = float(width) / max(1.0, float(frame_width))
                scale_y = float(height) / max(1.0, float(frame_height))
                candidates.append((abs(scale_x - scale_y), -width * height, int(hwnd), width, height))
            except BaseException:
                pass
            return True

        win32gui.EnumWindows(_cb, None)
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            _, _, hwnd, client_width, client_height = candidates[0]
            client_x, client_y = _friend_guard_scale_point_to_client(
                frame_x, frame_y, frame_width, frame_height,
                client_width, client_height,
            )
            point = win32gui.ClientToScreen(hwnd, (client_x, client_y))
            return int(point[0]), int(point[1])
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        candidates = []
        enum_proc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        class RECT(ctypes.Structure):
            _fields_ = [
                ('left', ctypes.c_long), ('top', ctypes.c_long),
                ('right', ctypes.c_long), ('bottom', ctypes.c_long),
            ]

        class POINT(ctypes.Structure):
            _fields_ = [('x', ctypes.c_long), ('y', ctypes.c_long)]

        def _cb(hwnd, lparam):
            try:
                if not user32.IsWindowVisible(hwnd):
                    return True
                title_buf = ctypes.create_unicode_buffer(256)
                user32.GetWindowTextW(hwnd, title_buf, 255)
                if str(title_buf.value or '').strip() != '\u0051\u0051\u7ecf\u5178\u519c\u573a':
                    return True
                rect = RECT()
                if not user32.GetClientRect(hwnd, ctypes.byref(rect)):
                    return True
                width = int(rect.right - rect.left)
                height = int(rect.bottom - rect.top)
                if width < 300 or height < 500:
                    return True
                scale_x = float(width) / max(1.0, float(frame_width))
                scale_y = float(height) / max(1.0, float(frame_height))
                candidates.append((abs(scale_x - scale_y), -width * height, int(hwnd), width, height))
            except BaseException:
                pass
            return True

        user32.EnumWindows(enum_proc(_cb), 0)
        if not candidates:
            return None
        candidates.sort(key=lambda item: (item[0], item[1]))
        _, _, hwnd, client_width, client_height = candidates[0]
        client_x, client_y = _friend_guard_scale_point_to_client(
            frame_x, frame_y, frame_width, frame_height,
            client_width, client_height,
        )
        point = POINT(int(client_x), int(client_y))
        if not user32.ClientToScreen(ctypes.c_void_p(hwnd), ctypes.byref(point)):
            return None
        return int(point.x), int(point.y)
    except BaseException:
        return None


_FRIEND_GUARD_TEMPLATE_CACHE = {}
_FRIEND_HOME_TEMPLATE_PATH = os.path.join(os.getcwd(), 'friend_home_button.png')
_FRIEND_LIST_TEMPLATE_PATH = os.path.join(os.getcwd(), 'friend_list_tabs.png')
_FRIEND_GUARD_DOG_AVATAR_TEMPLATE_PATH = os.path.join(
    os.getcwd(), 'friend_guard_dog_avatar_frame.png'
)


def _friend_guard_read_template(path):
    try:
        key = str(path or '')
        if not key:
            return None
        cache = globals().get('_FRIEND_GUARD_TEMPLATE_CACHE')
        if not isinstance(cache, dict):
            cache = {}
            globals()['_FRIEND_GUARD_TEMPLATE_CACHE'] = cache
        if key in cache:
            return cache.get(key)
        np = __import__('numpy')
        cv2 = __import__('cv2')
        raw = np.fromfile(key, dtype=np.uint8)
        template = cv2.imdecode(raw, cv2.IMREAD_COLOR) if raw.size else None
        cache[key] = template
        return template
    except BaseException:
        return None


def _friend_guard_match_template(
    frame, template_path, roi_bounds,
    gray_threshold=0.68, edge_threshold=0.30,
):
    try:
        np = __import__('numpy')
        cv2 = __import__('cv2')
        arr = np.asarray(frame)
        shape = getattr(arr, 'shape', None)
        if not shape or len(shape) < 3 or int(shape[2]) < 3:
            return {'matched': False, 'gray': 0.0, 'edge': 0.0, 'center': None}
        height, width = int(shape[0]), int(shape[1])
        x0r, y0r, x1r, y1r = tuple(roi_bounds)
        x0 = max(0, min(width - 1, int(round(width * float(x0r)))))
        x1 = max(x0 + 1, min(width, int(round(width * float(x1r)))))
        y0 = max(0, min(height - 1, int(round(height * float(y0r)))))
        y1 = max(y0 + 1, min(height, int(round(height * float(y1r)))))
        roi = arr[y0:y1, x0:x1, :3]
        template = _friend_guard_read_template(template_path)
        if template is None or getattr(roi, 'size', 0) <= 0:
            return {'matched': False, 'gray': 0.0, 'edge': 0.0, 'center': None}
        scale_x = max(0.25, float(width) / 428.0)
        scale_y = max(0.25, float(height) / 800.0)
        target_w = max(8, int(round(int(template.shape[1]) * scale_x)))
        target_h = max(8, int(round(int(template.shape[0]) * scale_y)))
        if target_w != int(template.shape[1]) or target_h != int(template.shape[0]):
            template = cv2.resize(template, (target_w, target_h), interpolation=cv2.INTER_AREA)
        if target_h > int(roi.shape[0]) or target_w > int(roi.shape[1]):
            return {'matched': False, 'gray': 0.0, 'edge': 0.0, 'center': None}
        roi_gray = np.mean(roi.astype(np.float32), axis=2).astype(np.uint8)
        template_gray = np.mean(template.astype(np.float32), axis=2).astype(np.uint8)
        gray_result = cv2.matchTemplate(roi_gray, template_gray, cv2.TM_CCOEFF_NORMED)
        _, gray_score, _, gray_location = cv2.minMaxLoc(gray_result)
        roi_edge = cv2.Canny(roi_gray, 50, 150)
        template_edge = cv2.Canny(template_gray, 50, 150)
        edge_result = cv2.matchTemplate(roi_edge, template_edge, cv2.TM_CCOEFF_NORMED)
        _, edge_score, _, _ = cv2.minMaxLoc(edge_result)
        center = (
            int(x0 + gray_location[0] + target_w // 2),
            int(y0 + gray_location[1] + target_h // 2),
        )
        return {
            'matched': bool(
                float(gray_score) >= float(gray_threshold)
                and float(edge_score) >= float(edge_threshold)
            ),
            'gray': float(gray_score),
            'edge': float(edge_score),
            'center': center,
        }
    except BaseException:
        return {'matched': False, 'gray': 0.0, 'edge': 0.0, 'center': None}



def _friend_list_visit_button_rows(frame):
    """Return visible friend-list visit buttons ordered from top to bottom."""
    try:
        np = __import__('numpy')
        cv2 = __import__('cv2')
        arr = np.asarray(frame)
        shape = getattr(arr, 'shape', None)
        if not shape or len(shape) < 3 or int(shape[2]) < 3:
            return []
        height, width = int(shape[0]), int(shape[1])
        if height < 120 or width < 120:
            return []
        bgr = arr[:, :, :3]
        hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(
            hsv,
            np.array([25, 100, 80], dtype=np.uint8),
            np.array([95, 255, 255], dtype=np.uint8),
        )
        x_gate = max(0, min(width, int(round(width * 0.70))))
        y_gate = max(0, min(height, int(round(height * 0.24))))
        y_end = max(y_gate + 1, min(height, int(round(height * 0.93))))
        mask[:y_gate, :] = 0
        mask[y_end:, :] = 0
        mask[:, :x_gate] = 0
        kernel = np.ones((3, 3), dtype=np.uint8)
        mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel, iterations=1)
        count, labels, stats, centers = cv2.connectedComponentsWithStats(mask, 8)
        min_width = max(24, int(round(width * 0.11)))
        max_width = max(min_width + 1, int(round(width * 0.26)))
        min_height = max(12, int(round(height * 0.025)))
        max_height = max(min_height + 1, int(round(height * 0.075)))
        min_area = max(120, int(round(width * height * 0.0015)))
        max_area = max(min_area + 1, int(round(width * height * 0.015)))
        rows = []
        for index in range(1, int(count)):
            x, y, component_width, component_height, area = [
                int(value) for value in stats[index]
            ]
            if not (min_width <= component_width <= max_width):
                continue
            if not (min_height <= component_height <= max_height):
                continue
            if not (min_area <= area <= max_area):
                continue
            fill_ratio = float(area) / float(max(1, component_width * component_height))
            if fill_ratio < 0.42:
                continue
            center_x = int(round(float(centers[index][0])))
            center_y = int(round(float(centers[index][1])))
            if center_x < int(round(width * 0.76)) or center_x > int(round(width * 0.97)):
                continue
            rows.append({
                'center': (center_x, center_y),
                'rect': (x, y, x + component_width, y + component_height),
                'area': area,
                'fill': fill_ratio,
            })
        rows.sort(key=lambda item: (int(item['center'][1]), int(item['center'][0])))
        merged = []
        merge_distance = max(6, int(round(height * 0.018)))
        for row in rows:
            if merged and abs(int(row['center'][1]) - int(merged[-1]['center'][1])) <= merge_distance:
                if int(row.get('area', 0)) > int(merged[-1].get('area', 0)):
                    merged[-1] = row
                continue
            merged.append(row)
        return merged
    except BaseException:
        return []


def _friend_list_guard_dog_score(frame, row_y):
    """Match the 19x19 guard-dog badge overlay; it is independent of avatar frame style."""
    try:
        np = __import__('numpy')
        cv2 = __import__('cv2')
        arr = np.asarray(frame)
        shape = getattr(arr, 'shape', None)
        if not shape or len(shape) < 3 or int(shape[2]) < 3:
            return 0.0
        height, width = int(shape[0]), int(shape[1])
        template_path = globals().get(
            '_FRIEND_GUARD_DOG_AVATAR_TEMPLATE_PATH',
            'friend_guard_dog_avatar_frame.png',
        )
        reader = globals().get('_friend_guard_read_template')
        template = reader(template_path) if callable(reader) else None
        if template is None:
            raw = np.fromfile(str(template_path), dtype=np.uint8)
            template = cv2.imdecode(raw, cv2.IMREAD_COLOR) if raw.size else None
        if template is None:
            return 0.0
        scale_x = max(0.25, float(width) / 428.0)
        scale_y = max(0.25, float(height) / 800.0)
        target_width = max(8, int(round(int(template.shape[1]) * scale_x)))
        target_height = max(8, int(round(int(template.shape[0]) * scale_y)))
        if target_width != int(template.shape[1]) or target_height != int(template.shape[0]):
            interpolation = cv2.INTER_AREA if scale_x < 1.0 or scale_y < 1.0 else cv2.INTER_LINEAR
            template = cv2.resize(
                template, (target_width, target_height), interpolation=interpolation
            )
        x0 = max(0, min(width - 1, int(round(width * 0.12))))
        x1 = max(x0 + 1, min(width, int(round(width * 0.21))))
        y0 = max(0, min(height - 1, int(round(float(row_y) + height * 0.003))))
        y1 = max(y0 + 1, min(height, int(round(float(row_y) + height * 0.046))))
        roi = arr[y0:y1, x0:x1, :3]
        if target_height > int(roi.shape[0]) or target_width > int(roi.shape[1]):
            return 0.0
        roi_gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
        template_gray = cv2.cvtColor(template, cv2.COLOR_BGR2GRAY)
        result = cv2.matchTemplate(roi_gray, template_gray, cv2.TM_CCOEFF_NORMED)
        _, score, _, _ = cv2.minMaxLoc(result)
        return float(score)
    except BaseException:
        return 0.0



def _friend_blocked_visit_visual_hint(frame, threshold=0.70):
    """Match blocked-visit list text or the in-farm blocked toast."""
    try:
        cv2 = __import__('cv2')
        np = __import__('numpy')
        os_module = __import__('os')
        arr = np.asarray(frame)
        shape = getattr(arr, 'shape', None)
        if not shape or len(shape) < 2:
            return False
        height, width = int(shape[0]), int(shape[1])
        if height < 120 or width < 120:
            return False
        hook_file = globals().get('__file__', 'hook.py')
        base = os_module.path.dirname(os_module.path.abspath(hook_file))
        template_paths = [
            (
                'row',
                globals().get('_FRIEND_BLOCKED_VISIT_TEMPLATE_PATH')
                or os_module.path.join(base, 'friend_blocked_visit_text.png'),
            ),
            (
                'toast',
                globals().get('_FRIEND_BLOCKED_VISIT_TOAST_TEMPLATE_PATH')
                or os_module.path.join(base, 'friend_blocked_visit_toast.png'),
            ),
        ]
        x0 = max(0, min(width - 1, int(round(width * 0.08))))
        x1 = max(x0 + 1, min(width, int(round(width * 0.92))))
        y0 = max(0, min(height - 1, int(round(height * 0.12))))
        y1 = max(y0 + 1, min(height, int(round(height * 0.88))))
        roi = arr[y0:y1, x0:x1, :3]
        if getattr(roi, 'size', 0) <= 0:
            return False
        roi_gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
        cache = globals().setdefault('_FRIEND_BLOCKED_VISIT_TEMPLATE_CACHE', {})
        runtime_scale = max(0.65, min(1.65, float(width) / 428.0))
        best = -1.0
        best_label = ''
        for label, template_path in template_paths:
            cache_key = str(template_path)
            template = cache.get(cache_key) if isinstance(cache, dict) else None
            if template is None:
                try:
                    encoded = np.fromfile(cache_key, dtype=np.uint8)
                    template = cv2.imdecode(encoded, cv2.IMREAD_COLOR)
                except BaseException:
                    template = None
                if template is not None and isinstance(cache, dict):
                    cache[cache_key] = template
            if template is None or getattr(template, 'size', 0) <= 0:
                continue
            for local_scale in (0.90, 0.96, 1.0, 1.04, 1.10):
                scale = runtime_scale * float(local_scale)
                target_width = max(8, int(round(template.shape[1] * scale)))
                target_height = max(6, int(round(template.shape[0] * scale)))
                if (
                    target_width > int(roi_gray.shape[1])
                    or target_height > int(roi_gray.shape[0])
                ):
                    continue
                resized = cv2.resize(
                    template,
                    (target_width, target_height),
                    interpolation=(
                        cv2.INTER_AREA if scale < 1.0 else cv2.INTER_CUBIC
                    ),
                )
                template_gray = cv2.cvtColor(resized, cv2.COLOR_BGR2GRAY)
                matched = cv2.matchTemplate(
                    roi_gray, template_gray, cv2.TM_CCOEFF_NORMED
                )
                _, score, _, _ = cv2.minMaxLoc(matched)
                score = float(score)
                if score > best:
                    best = score
                    best_label = str(label)
        matched = bool(best >= max(0.55, min(0.92, float(threshold))))
        if matched:
            try:
                _write(
                    'v222 blocked visit status matched kind=' + best_label +
                    ' score=' + ('%.4f' % best)
                )
            except BaseException:
                pass
        return matched
    except BaseException:
        return False


def _friend_list_blocked_row_visual_hint(frame, row_y, threshold=0.70):
    """Match the fixed ?account blocked, visit unavailable? text on one row."""
    try:
        cv2 = __import__('cv2')
        np = __import__('numpy')
        os_module = __import__('os')
        arr = np.asarray(frame)
        shape = getattr(arr, 'shape', None)
        if not shape or len(shape) < 2:
            return False
        height, width = int(shape[0]), int(shape[1])
        if height < 120 or width < 120:
            return False
        template_path = globals().get('_FRIEND_BLOCKED_VISIT_TEMPLATE_PATH')
        if not template_path:
            hook_file = globals().get('__file__', 'hook.py')
            template_path = os_module.path.join(
                os_module.path.dirname(os_module.path.abspath(hook_file)),
                'friend_blocked_visit_text.png',
            )
        try:
            encoded = np.fromfile(str(template_path), dtype=np.uint8)
            template = cv2.imdecode(encoded, cv2.IMREAD_COLOR)
        except BaseException:
            template = None
        if template is None or getattr(template, 'size', 0) <= 0:
            return False
        x0 = max(0, min(width - 1, int(round(width * 0.22))))
        x1 = max(x0 + 1, min(width, int(round(width * 0.82))))
        y0 = max(0, min(height - 1, int(round(float(row_y) - height * 0.034))))
        y1 = max(y0 + 1, min(height, int(round(float(row_y) + height * 0.034))))
        roi = arr[y0:y1, x0:x1, :3]
        if getattr(roi, 'size', 0) <= 0:
            return False
        roi_gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
        best = -1.0
        runtime_scale = max(0.65, min(1.65, float(width) / 428.0))
        for local_scale in (0.90, 0.96, 1.0, 1.04, 1.10):
            scale = runtime_scale * float(local_scale)
            target_width = max(8, int(round(template.shape[1] * scale)))
            target_height = max(6, int(round(template.shape[0] * scale)))
            if target_width > int(roi_gray.shape[1]) or target_height > int(roi_gray.shape[0]):
                continue
            resized = cv2.resize(
                template,
                (target_width, target_height),
                interpolation=(cv2.INTER_AREA if scale < 1.0 else cv2.INTER_CUBIC),
            )
            template_gray = cv2.cvtColor(resized, cv2.COLOR_BGR2GRAY)
            matched = cv2.matchTemplate(roi_gray, template_gray, cv2.TM_CCOEFF_NORMED)
            _, score, _, _ = cv2.minMaxLoc(matched)
            best = max(best, float(score))
        matched = bool(best >= max(0.55, min(0.92, float(threshold))))
        if matched:
            try:
                _write(
                    'v219 blocked friend row text matched row_y=' + str(int(row_y)) +
                    ' score=' + ('%.4f' % best)
                )
            except BaseException:
                pass
        return matched
    except BaseException:
        return False

def _friend_progress_journal_record(context, *, journal_path=None, today=None):
    """Atomically persist friend-list traversal state for restart recovery."""
    if context is None:
        return False
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    try:
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        path = str(journal_path or os_module.environ.get(
            'QQFARM_FRIEND_PROGRESS_JOURNAL_PATH', ''
        ) or '').strip()
        if not path:
            base = str(os_module.environ.get('APPDATA', '') or '').strip()
            if not base:
                base = str(os_module.environ.get('LOCALAPPDATA', '') or '').strip()
            path = os_module.path.join(
                base, 'QQFarmCopilot', 'friend_traversal_journal.json'
            )
        parent = os_module.path.dirname(path)
        if parent:
            os_module.makedirs(parent, exist_ok=True)
    except BaseException:
        return False

    lock_path = path + '.lock'
    lock_fd = None
    deadline = time_module.time() + 2.0
    while lock_fd is None:
        try:
            lock_fd = os_module.open(
                lock_path,
                os_module.O_CREAT | os_module.O_EXCL | os_module.O_WRONLY,
            )
            try:
                os_module.write(lock_fd, str(os_module.getpid()).encode('ascii'))
            except BaseException:
                pass
        except FileExistsError:
            try:
                if time_module.time() - os_module.path.getmtime(lock_path) > 10.0:
                    os_module.unlink(lock_path)
                    continue
            except BaseException:
                pass
            if time_module.time() >= deadline:
                return False
            time_module.sleep(0.02)
        except BaseException:
            return False
    try:
        payload = {}
        try:
            with open(path, 'r', encoding='utf-8-sig') as handle:
                loaded = json_module.load(handle)
            if isinstance(loaded, dict):
                payload = loaded
        except BaseException:
            payload = {}
        if str(payload.get('business_date', '') or '') != today_value:
            payload = {
                'version': 1,
                'business_date': today_value,
                'instances': {},
            }
        instances = payload.get('instances')
        if not isinstance(instances, dict):
            instances = {}
            payload['instances'] = instances
        try:
            cursor = max(0, int(getattr(
                context, '_qqfarm_friend_list_visit_cursor', 0
            ) or 0))
        except BaseException:
            cursor = 0
        try:
            pending_cursor = max(0, int(getattr(
                context, '_qqfarm_friend_list_pending_cursor', cursor
            ) or cursor))
        except BaseException:
            pending_cursor = cursor
        resume_pending = bool(getattr(
            context, '_qqfarm_friend_list_resume_pending', False
        ))
        entry_pending = bool(getattr(
            context, '_qqfarm_friend_entry_pending', False
        ))
        chain_pending = bool(getattr(
            context, '_qqfarm_friend_chain_pending', False
        ))
        try:
            visible_count = max(0, int(getattr(
                context, '_qqfarm_friend_list_visible_candidate_count', 0
            ) or 0))
        except BaseException:
            visible_count = 0
        if resume_pending:
            phase = 'returned-home'
        elif entry_pending:
            phase = 'entry-pending'
        elif chain_pending:
            phase = 'in-friend'
        elif visible_count > 0 and cursor >= visible_count:
            phase = 'terminal'
        else:
            phase = 'active'
        instances[instance_id] = {
            'cursor': cursor,
            'pending_cursor': pending_cursor,
            'resume_pending': resume_pending,
            'entry_pending': entry_pending,
            'chain_pending': chain_pending,
            'visible_count': visible_count,
            'entry_retry_count': max(0, int(getattr(
                context, '_qqfarm_friend_entry_retry_count', 0
            ) or 0)),
            'last_row_fallback_tried': bool(getattr(
                context, '_qqfarm_friend_last_row_card_fallback_tried', False
            )),
            'phase': phase,
            'updated_at': float(time_module.time()),
        }
        payload['version'] = 1
        payload['business_date'] = today_value
        temp_path = path + '.tmp.' + str(os_module.getpid()) + '.' + str(
            __import__('threading').get_ident()
        )
        encoded = json_module.dumps(
            payload, ensure_ascii=False, sort_keys=True, indent=2
        )
        with open(temp_path, 'w', encoding='utf-8', newline='') as handle:
            handle.write(encoded)
            handle.flush()
            try:
                os_module.fsync(handle.fileno())
            except BaseException:
                pass
        replaced = False
        for attempt in range(3):
            try:
                os_module.replace(temp_path, path)
                replaced = True
                break
            except (PermissionError, OSError):
                if attempt >= 2:
                    break
                time_module.sleep(0.03 * float(attempt + 1))
        if not replaced:
            try:
                os_module.unlink(temp_path)
            except BaseException:
                pass
        return replaced
    except BaseException:
        return False
    finally:
        try:
            if lock_fd is not None:
                os_module.close(lock_fd)
        except BaseException:
            pass
        try:
            os_module.unlink(lock_path)
        except BaseException:
            pass


def _friend_progress_state_snapshot(context):
    """Capture every in-memory field represented by the traversal journal."""
    if context is None:
        return {}
    fields = (
        '_qqfarm_friend_list_visit_cursor',
        '_qqfarm_friend_list_pending_cursor',
        '_qqfarm_friend_list_resume_pending',
        '_qqfarm_friend_entry_pending',
        '_qqfarm_friend_chain_pending',
        '_qqfarm_friend_list_visible_candidate_count',
        '_qqfarm_friend_entry_retry_count',
        '_qqfarm_friend_entry_last_retry_ts',
        '_qqfarm_friend_entry_clicked_ts',
        '_qqfarm_friend_last_row_card_fallback_tried',
        '_qqfarm_friend_chain_active',
        '_qqfarm_friend_chain_exhausted',
        '_qqfarm_friend_chain_allow_home',
        '_qqfarm_friend_chain_native_home_blocked',
        '_qqfarm_guard_list_prequalified',
        '_qqfarm_guard_list_prequalified_ts',
        '_qqfarm_guard_list_row_y',
        '_qqfarm_guard_list_row_score',
    )
    snapshot = {}
    for field in fields:
        try:
            snapshot[field] = (hasattr(context, field), getattr(context, field, None))
        except BaseException:
            pass
    return snapshot


def _friend_progress_state_restore(context, snapshot):
    if context is None or not isinstance(snapshot, dict):
        return False
    restored = False
    for field, state in snapshot.items():
        try:
            existed, value = state
            if existed:
                setattr(context, field, value)
            elif hasattr(context, field):
                delattr(context, field)
            restored = True
        except BaseException:
            pass
    return restored


def _friend_progress_journal_commit(context, snapshot=None, reason=''):
    """Commit one traversal transition or roll back its in-memory state."""
    if context is None:
        return False
    committed = True
    try:
        journal_fn = globals().get('_friend_progress_journal_record')
        if callable(journal_fn):
            committed = bool(journal_fn(context))
    except BaseException:
        committed = False
    if committed:
        try:
            setattr(context, '_qqfarm_friend_progress_journal_retry_pending', False)
        except BaseException:
            pass
        return True
    try:
        restore_fn = globals().get('_friend_progress_state_restore')
        if isinstance(snapshot, dict) and callable(restore_fn):
            restore_fn(context, snapshot)
    except BaseException:
        pass
    try:
        setattr(context, '_qqfarm_friend_progress_journal_retry_pending', True)
    except BaseException:
        pass
    try:
        writer = globals().get('_write')
        if callable(writer):
            writer(
                'v342 friend progress journal commit failed reason=' +
                str(reason or 'unknown')
            )
    except BaseException:
        pass
    return False


def _friend_progress_journal_restore(
        context, *, row_count=None, journal_path=None, today=None):
    """Restore same-day traversal state into a fresh runtime context."""
    if context is None:
        return False
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    try:
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        path = str(journal_path or os_module.environ.get(
            'QQFARM_FRIEND_PROGRESS_JOURNAL_PATH', ''
        ) or '').strip()
        if not path:
            base = str(os_module.environ.get('APPDATA', '') or '').strip()
            if not base:
                base = str(os_module.environ.get('LOCALAPPDATA', '') or '').strip()
            path = os_module.path.join(
                base, 'QQFarmCopilot', 'friend_traversal_journal.json'
            )
        with open(path, 'r', encoding='utf-8-sig') as handle:
            payload = json_module.load(handle)
        if not isinstance(payload, dict):
            return False
        if str(payload.get('business_date', '') or '') != today_value:
            return False
        instances = payload.get('instances')
        if not isinstance(instances, dict):
            return False
        state = instances.get(instance_id)
        if not isinstance(state, dict):
            return False
        count = max(0, int(row_count or state.get('visible_count', 0) or 0))
        cursor = max(0, int(state.get('cursor', 0) or 0))
        pending_cursor = max(0, int(
            state.get('pending_cursor', cursor) or cursor
        ))
        resume_pending = bool(state.get('resume_pending', False))
        phase = str(state.get('phase', '') or '')
        if count > 0:
            highest = count - 1 if resume_pending or phase != 'terminal' else count
            cursor = min(cursor, highest)
            pending_cursor = min(pending_cursor, highest)
        setattr(context, '_qqfarm_friend_list_visit_cursor', cursor)
        setattr(context, '_qqfarm_friend_list_pending_cursor', pending_cursor)
        setattr(context, '_qqfarm_friend_list_resume_pending', resume_pending)
        setattr(context, '_qqfarm_friend_entry_pending', bool(
            state.get('entry_pending', False)
        ))
        setattr(context, '_qqfarm_friend_chain_pending', bool(
            state.get('chain_pending', False) or resume_pending
        ))
        setattr(context, '_qqfarm_friend_entry_retry_count', max(
            0, int(state.get('entry_retry_count', 0) or 0)
        ))
        setattr(context, '_qqfarm_friend_last_row_card_fallback_tried', bool(
            state.get('last_row_fallback_tried', False)
        ))
        if count > 0:
            setattr(context, '_qqfarm_friend_list_visible_candidate_count', count)
        setattr(context, '_qqfarm_friend_progress_journal_restored', True)
        setattr(context, '_qqfarm_friend_progress_journal_phase', phase)
        return True
    except BaseException:
        return False


def _friend_action_stable_fingerprint(context, fresh_frame):
    """Return a durable friend identity without using carousel slot geometry."""
    try:
        hashlib_module = __import__('hashlib')
        re_module = __import__('re')
        template_path = str(getattr(
            context, '_qqfarm_guard_list_carousel_template', ''
        ) or '').strip()
        template_name = template_path.replace('\\', '/').rsplit('/', 1)[-1]
        template_stem = template_name.rsplit('.', 1)[0].strip().lower()
        identity_stem = re_module.sub(r'_[0-9]+$', '', template_stem)
        if identity_stem:
            return 'friend:guard-template:' + identity_stem
        for attr_name in (
            '_qqfarm_current_friend_id', 'current_friend_id', 'friend_id',
            '_qqfarm_current_friend_name', 'current_friend_name',
            'selected_friend_name', 'friend_name',
        ):
            try:
                raw_value = str(getattr(context, attr_name, '') or '').strip()
            except BaseException:
                raw_value = ''
            if not raw_value:
                continue
            normalized = ' '.join(raw_value.lower().split())
            digest = hashlib_module.sha256(
                normalized.encode('utf-8', errors='ignore')
            ).hexdigest()[:24]
            return 'friend:profile:' + digest
        if fresh_frame is None:
            return ''
        numpy_module = __import__('numpy')
        array = numpy_module.asarray(fresh_frame)
        if getattr(array, 'ndim', 0) < 2:
            return ''
        height = int(array.shape[0])
        width = int(array.shape[1])
        if height < 120 or width < 120:
            return ''
        top = max(0, min(height - 1, int(round(height * 0.10))))
        bottom = max(top + 1, min(height, int(round(height * 0.37))))
        left = max(0, min(width - 1, int(round(width * 0.08))))
        right = max(left + 1, min(width, int(round(width * 0.78))))
        crop = array[top:bottom, left:right]
        if getattr(crop, 'ndim', 0) == 3:
            crop = crop[:, :, :3]
        samples = []
        for row_index in range(16):
            y0 = int((row_index * crop.shape[0]) / 16)
            y1 = max(y0 + 1, int(((row_index + 1) * crop.shape[0]) / 16))
            for col_index in range(16):
                x0 = int((col_index * crop.shape[1]) / 16)
                x1 = max(x0 + 1, int(((col_index + 1) * crop.shape[1]) / 16))
                block = crop[y0:y1, x0:x1]
                mean_value = float(
                    numpy_module.asarray(block, dtype='float32').mean()
                )
                samples.append(max(0, min(15, int(round(mean_value / 17.0)))))
        payload = bytes(samples) + (
            str(height) + 'x' + str(width)
        ).encode('ascii', errors='ignore')
        digest = hashlib_module.sha256(payload).hexdigest()[:32]
        return 'friend:visual:' + digest
    except BaseException:
        return ''


def _friend_action_ledger_has_confirmed_proof(
        context, *, key, ledger_path, today=None):
    """Return whether append-only fresh visual proof already completed this action."""
    if context is None:
        return False
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    try:
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        key_value = str(key or '').strip()
        path = str(ledger_path or '').strip() + '.confirmed-proof.jsonl'
        if not today_value or not key_value or not os_module.path.isfile(path):
            return False
        with open(path, 'rb') as handle:
            try:
                size = int(os_module.path.getsize(path) or 0)
            except BaseException:
                size = 0
            if size > 2097152:
                handle.seek(max(0, size - 2097152))
                handle.readline()
            raw = handle.read()
        lines = raw.decode('utf-8', errors='ignore').splitlines()
        for line in reversed(lines[-4096:]):
            try:
                row = json_module.loads(line)
            except BaseException:
                continue
            if not isinstance(row, dict):
                continue
            if str(row.get('business_date', '') or '') != today_value:
                continue
            if str(row.get('instance_id', '') or '') != instance_id:
                continue
            if str(row.get('key', '') or '') == key_value:
                return True
        return False
    except BaseException:
        return False


def _friend_action_ledger_record_confirmed_proof(
        context, lease, *, ledger_path=None, today=None, now=None):
    """Append fresh action proof before the replace-based ledger confirm.

    The compact append record is a restart-safe fallback for a transient Windows
    sharing violation on ``os.replace``.  It is scoped by business date,
    instance and the exact action key, so the next business day is unaffected.
    """
    if context is None or not isinstance(lease, dict):
        return False
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    try:
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or lease.get('business_date') or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        now_value = float(now if now is not None else time_module.time())
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        key = str(lease.get('key', '') or '').strip()
        lease_id = str(lease.get('lease_id', '') or '').strip()
        if not today_value or not key or not lease_id:
            return False
        path = str(ledger_path or os_module.environ.get(
            'QQFARM_FRIEND_ACTION_LEDGER_PATH', ''
        ) or '').strip()
        if not path:
            base = str(os_module.environ.get('APPDATA', '') or '').strip()
            if not base:
                base = str(os_module.environ.get('LOCALAPPDATA', '') or '').strip()
            path = os_module.path.join(
                base, 'QQFarmCopilot', 'friend_action_ledger.json'
            )
        proof_path = path + '.confirmed-proof.jsonl'
        parent = os_module.path.dirname(proof_path)
        if parent:
            os_module.makedirs(parent, exist_ok=True)
        row = {
            'version': 1,
            'business_date': today_value,
            'instance_id': instance_id,
            'key': key,
            'lease_id': lease_id,
            'proof_at': now_value,
        }
        data = (
            json_module.dumps(
                row, ensure_ascii=False, sort_keys=True, separators=(',', ':')
            ) + '\n'
        ).encode('utf-8')
        flags = os_module.O_CREAT | os_module.O_APPEND | os_module.O_WRONLY
        fd = os_module.open(proof_path, flags)
        try:
            offset = 0
            while offset < len(data):
                written = int(os_module.write(fd, data[offset:]) or 0)
                if written <= 0:
                    return False
                offset += written
            try:
                os_module.fsync(fd)
            except BaseException:
                pass
        finally:
            os_module.close(fd)
        return True
    except BaseException:
        return False


def _friend_action_ledger_claim(
        context, *, action, friend_fingerprint, ledger_path=None,
        today=None, now=None, lease_seconds=45.0):
    """Atomically claim a same-day friend action before any UI click."""
    if context is None:
        return None
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    uuid_module = __import__('uuid')
    try:
        action_value = str(action or '').strip().lower()
        fingerprint = str(friend_fingerprint or '').strip()
        if not action_value or not fingerprint:
            return None
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        now_value = float(now if now is not None else time_module.time())
        lease_value = max(5.0, min(300.0, float(lease_seconds or 45.0)))
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        path = str(ledger_path or os_module.environ.get(
            'QQFARM_FRIEND_ACTION_LEDGER_PATH', ''
        ) or '').strip()
        if not path:
            base = str(os_module.environ.get('APPDATA', '') or '').strip()
            if not base:
                base = str(os_module.environ.get('LOCALAPPDATA', '') or '').strip()
            path = os_module.path.join(
                base, 'QQFarmCopilot', 'friend_action_ledger.json'
            )
        parent = os_module.path.dirname(path)
        if parent:
            os_module.makedirs(parent, exist_ok=True)
    except BaseException:
        return None
    lock_path = path + '.lock'
    lock_fd = None
    deadline = time_module.time() + 2.0
    while lock_fd is None:
        try:
            lock_fd = os_module.open(
                lock_path,
                os_module.O_CREAT | os_module.O_EXCL | os_module.O_WRONLY,
            )
        except FileExistsError:
            try:
                if time_module.time() - os_module.path.getmtime(lock_path) > 10.0:
                    os_module.unlink(lock_path)
                    continue
            except BaseException:
                pass
            if time_module.time() >= deadline:
                return None
            time_module.sleep(0.02)
        except BaseException:
            return None
    try:
        payload = {}
        try:
            with open(path, 'r', encoding='utf-8-sig') as handle:
                loaded = json_module.load(handle)
            if isinstance(loaded, dict):
                payload = loaded
        except BaseException:
            payload = {}
        if str(payload.get('business_date', '') or '') != today_value:
            payload = {
                'version': 1,
                'business_date': today_value,
                'actions': {},
            }
        actions = payload.get('actions')
        if not isinstance(actions, dict):
            actions = {}
            payload['actions'] = actions
        key = instance_id + '|' + fingerprint + '|' + action_value
        proof_check = globals().get(
            '_friend_action_ledger_has_confirmed_proof'
        )
        if callable(proof_check):
            try:
                if proof_check(
                        context, key=key, ledger_path=path, today=today_value):
                    return None
            except BaseException:
                pass
        existing = actions.get(key)
        if isinstance(existing, dict):
            state = str(existing.get('state', '') or '').lower()
            if state == 'confirmed':
                return None
            if state == 'claimed' and float(
                    existing.get('lease_until', 0.0) or 0.0) > now_value:
                return None
        lease_id = str(uuid_module.uuid4())
        lease = {
            'key': key,
            'lease_id': lease_id,
            'business_date': today_value,
            'instance_id': instance_id,
            'friend_fingerprint': fingerprint,
            'action': action_value,
            'claimed_at': now_value,
            'lease_until': now_value + lease_value,
        }
        actions[key] = dict(lease, state='claimed')
        payload['version'] = 1
        payload['business_date'] = today_value
        temp_path = path + '.tmp.' + str(os_module.getpid()) + '.' + str(
            __import__('threading').get_ident()
        )
        with open(temp_path, 'w', encoding='utf-8', newline='') as handle:
            json_module.dump(
                payload, handle, ensure_ascii=False, sort_keys=True, indent=2
            )
            handle.flush()
            try:
                os_module.fsync(handle.fileno())
            except BaseException:
                pass
        replaced = False
        for attempt in range(3):
            try:
                os_module.replace(temp_path, path)
                replaced = True
                break
            except (PermissionError, OSError):
                if attempt >= 2:
                    break
                time_module.sleep(0.03 * float(attempt + 1))
        if not replaced:
            try:
                os_module.unlink(temp_path)
            except BaseException:
                pass
            return None
        return lease
    except BaseException:
        return None
    finally:
        try:
            if lock_fd is not None:
                os_module.close(lock_fd)
        except BaseException:
            pass
        try:
            os_module.unlink(lock_path)
        except BaseException:
            pass


def _friend_action_ledger_confirm(
        context, lease, *, ledger_path=None, today=None, now=None):
    """Finalize an owned friend-action lease only after visible confirmation."""
    if context is None or not isinstance(lease, dict):
        return False
    os_module = __import__('os')
    json_module = __import__('json')
    time_module = __import__('time')
    try:
        day_source = globals().get('_daily_business_date')
        today_value = str(
            today or (
                day_source() if callable(day_source)
                else time_module.strftime('%Y-%m-%d')
            )
        ).strip()
        now_value = float(now if now is not None else time_module.time())
        instance_id = str(getattr(context, 'instance_id', 'default') or 'default')
        path = str(ledger_path or os_module.environ.get(
            'QQFARM_FRIEND_ACTION_LEDGER_PATH', ''
        ) or '').strip()
        if not path:
            base = str(os_module.environ.get('APPDATA', '') or '').strip()
            if not base:
                base = str(os_module.environ.get('LOCALAPPDATA', '') or '').strip()
            path = os_module.path.join(
                base, 'QQFarmCopilot', 'friend_action_ledger.json'
            )
    except BaseException:
        return False
    lock_path = path + '.lock'
    lock_fd = None
    deadline = time_module.time() + 2.0
    while lock_fd is None:
        try:
            lock_fd = os_module.open(
                lock_path,
                os_module.O_CREAT | os_module.O_EXCL | os_module.O_WRONLY,
            )
        except FileExistsError:
            try:
                if time_module.time() - os_module.path.getmtime(lock_path) > 10.0:
                    os_module.unlink(lock_path)
                    continue
            except BaseException:
                pass
            if time_module.time() >= deadline:
                return False
            time_module.sleep(0.02)
        except BaseException:
            return False
    try:
        with open(path, 'r', encoding='utf-8-sig') as handle:
            payload = json_module.load(handle)
        if not isinstance(payload, dict):
            return False
        if str(payload.get('business_date', '') or '') != today_value:
            return False
        key = str(lease.get('key', '') or '')
        lease_id = str(lease.get('lease_id', '') or '')
        if not key or not lease_id:
            return False
        actions = payload.get('actions')
        if not isinstance(actions, dict):
            return False
        existing = actions.get(key)
        if not isinstance(existing, dict):
            return False
        if str(existing.get('instance_id', '') or '') != instance_id:
            return False
        if str(existing.get('lease_id', '') or '') != lease_id:
            return False
        if str(existing.get('state', '') or '').lower() == 'confirmed':
            return True
        if str(existing.get('state', '') or '').lower() != 'claimed':
            return False
        proof_recorded = False
        proof_recorder = globals().get(
            '_friend_action_ledger_record_confirmed_proof'
        )
        if callable(proof_recorder):
            try:
                proof_recorded = bool(proof_recorder(
                    context,
                    lease,
                    ledger_path=path,
                    today=today_value,
                    now=now_value,
                ))
            except BaseException:
                proof_recorded = False
        existing['state'] = 'confirmed'
        existing['confirmed_at'] = now_value
        existing['lease_until'] = now_value
        actions[key] = existing
        temp_path = path + '.tmp.' + str(os_module.getpid()) + '.' + str(
            __import__('threading').get_ident()
        )
        with open(temp_path, 'w', encoding='utf-8', newline='') as handle:
            json_module.dump(
                payload, handle, ensure_ascii=False, sort_keys=True, indent=2
            )
            handle.flush()
            try:
                os_module.fsync(handle.fileno())
            except BaseException:
                pass
        replaced = False
        for attempt in range(3):
            try:
                os_module.replace(temp_path, path)
                replaced = True
                break
            except (PermissionError, OSError):
                if attempt >= 2:
                    break
                time_module.sleep(0.03 * float(attempt + 1))
        if not replaced:
            try:
                os_module.unlink(temp_path)
            except BaseException:
                pass
        return bool(replaced or proof_recorded)
    except BaseException:
        return False
    finally:
        try:
            if lock_fd is not None:
                os_module.close(lock_fd)
        except BaseException:
            pass
        try:
            os_module.unlink(lock_path)
        except BaseException:
            pass


