def _share_close_share_page(context):
    """Close the claimed reward card, unless the exact click already returned home."""
    try:
        today = (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d'))
        frame_fn = globals().get('_get_frame_from_bot')
        frame = frame_fn(context) if callable(frame_fn) else None
        farm_fn = globals().get('_qqfarm_visible_frame_has_farm_scene')
        if frame is not None and callable(farm_fn):
            try:
                if bool(farm_fn(frame)):
                    if context is not None:
                        setattr(context, '_qqfarm_share_reward_page_closed_day', today)
                    return True
            except BaseException:
                pass
        shape = getattr(frame, 'shape', ())
        height = int(shape[0]) if len(shape) >= 2 else 800
        width = int(shape[1]) if len(shape) >= 2 else 428
        click_fn = globals().get('_friend_guard_post_client_click')
        if not callable(click_fn):
            return False
        closed = bool(click_fn(
            int(round(width * 0.945)), int(round(height * 0.19)),
            width, height,
        ))
        if closed:
            time.sleep(0.25)
            if context is not None:
                try:
                    setattr(context, '_qqfarm_share_reward_page_closed_day', today)
                except BaseException:
                    pass
        return closed
    except BaseException:
        return False


def _share_reward_claimed_visible(context):
    """Recognize a checked reward only on a page opened in this process."""
    try:
        if context is None:
            return False
        open_epoch = float(getattr(
            context, '_qqfarm_share_reward_open_attempt_epoch', 0.0
        ) or 0.0)
        claim_epoch = float(getattr(
            context, '_qqfarm_share_reward_claim_attempt_epoch', 0.0
        ) or 0.0)
        current_page_probe = bool(getattr(
            context, '_qqfarm_share_reward_current_page_probe', False
        ))
        if max(open_epoch, claim_epoch) <= 0.0 and not current_page_probe:
            return False
        frame = None
        visible_capture_fn = globals().get(
            '_qqfarm_capture_visible_farm_frame'
        )
        if callable(visible_capture_fn):
            try:
                frame = visible_capture_fn(
                    prefer_desktop=True, allow_overlay=True
                )
            except TypeError:
                try:
                    frame = visible_capture_fn(prefer_desktop=True)
                except BaseException:
                    frame = None
            except BaseException:
                frame = None
        if frame is None:
            frame_fn = globals().get('_get_frame_from_bot')
            frame = frame_fn(context) if callable(frame_fn) else None
        if frame is None:
            return False
        import numpy as np
        pixels = np.asarray(frame)
        if pixels.ndim != 3 or pixels.shape[2] < 3:
            return False
        height, width = pixels.shape[:2]
        if height < 120 or width < 120:
            return False
        # The share card is a modal over the farm, so the broad farm-scene
        # classifier remains true from the visible sky behind it.  Authority is
        # instead the process/adoption lease plus both reward-page green signals.
        pixels = pixels[:, :, :3].astype(np.int16, copy=False)

        def _crop(x0, y0, x1, y1):
            left = max(0, min(width - 1, int(round(width * x0))))
            top = max(0, min(height - 1, int(round(height * y0))))
            right = max(left + 1, min(width, int(round(width * x1))))
            bottom = max(top + 1, min(height, int(round(height * y1))))
            return pixels[top:bottom, left:right]

        def _green_count(area):
            if area.size == 0:
                return 0
            first = area[:, :, 0]
            green = area[:, :, 1]
            third = area[:, :, 2]
            mask = (
                (green >= 70)
                & (green >= first + 20)
                & (green >= third + 15)
            )
            return int(np.count_nonzero(mask))

        reward_area = _crop(0.08, 0.75, 0.34, 0.91)
        action_area = _crop(0.48, 0.74, 0.91, 0.91)
        reward_count = _green_count(reward_area)
        action_count = _green_count(action_area)
        reward_minimum = max(12, int(reward_area.shape[0] * reward_area.shape[1] * 0.004))
        action_minimum = max(30, int(action_area.shape[0] * action_area.shape[1] * 0.020))
        visible = reward_count >= reward_minimum and action_count >= action_minimum
        if visible:
            log_fn = globals().get('_throttled_write')
            if callable(log_fn):
                try:
                    log_fn(
                        'v244-share-reward-claimed-visible',
                        'v244 daily share reward checkmark detected; suppressing repeat share',
                        30.0,
                    )
                except BaseException:
                    pass
        return bool(visible)
    except BaseException:
        return False

def _share_reward_claimed_current_page_visible(context):
    """Adopt one already-visible checked reward page after a verified send."""
    if context is None:
        return False
    marker = '_qqfarm_share_reward_current_page_probe'
    had_marker = False
    previous = False
    try:
        had_marker = bool(hasattr(context, marker))
        previous = bool(getattr(context, marker, False))
        setattr(context, marker, True)
        return bool(_share_reward_claimed_visible(context))
    except BaseException:
        return False
    finally:
        try:
            if had_marker:
                setattr(context, marker, previous)
            else:
                delattr(context, marker)
        except BaseException:
            pass

def _share_mark_reward_claimed_success(context, cfg):
    """Persist reward completion without manufacturing direct-send proof."""
    try:
        target = ''
        if isinstance(cfg, dict):
            target = str(cfg.get('target_name', '') or '').strip()
        success_fn = globals().get('_daily_flow_success_today')
        share_already_success = False
        reward_already_success = False
        if callable(success_fn):
            try:
                share_already_success = bool(success_fn('share', target=target))
            except TypeError:
                try:
                    share_already_success = bool(success_fn('share'))
                except BaseException:
                    share_already_success = False
            except BaseException:
                share_already_success = False
            try:
                reward_already_success = bool(success_fn(
                    'share_reward', target=target
                ))
            except TypeError:
                try:
                    reward_already_success = bool(success_fn('share_reward'))
                except BaseException:
                    reward_already_success = False
            except BaseException:
                reward_already_success = False

        if not reward_already_success:
            persist_fn = globals().get('_daily_flow_mark_status')
            if not callable(persist_fn) or not bool(persist_fn(
                'share_reward', 'success', target=target,
                reason='verified-share-reward-current-page-v3',
            )):
                log_fn = globals().get('_share_log_runtime')
                if callable(log_fn):
                    log_fn(
                        'reward-claimed-persist-failed',
                        'daily share reward was verified but independent reward status write failed',
                        True,
                    )
                return False

        if context is not None:
            try:
                setattr(
                    context, '_qqfarm_share_reward_claimed_day',
                    (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d')),
                )
            except BaseException:
                pass

        # Reward proof and direct-recipient send proof are independent. Only a
        # previously verified direct send may close the share scheduler/backoff.
        if share_already_success:
            apply_fn = globals().get('_daily_flow_apply_success_context')
            if callable(apply_fn):
                apply_fn(context, 'share')
            clear_fn = globals().get('_share_clear_retry_backoff')
            if callable(clear_fn):
                clear_fn(context)

        if not reward_already_success:
            log_fn = globals().get('_share_log_runtime')
            if callable(log_fn):
                log_fn(
                    'reward-claimed-success-v2',
                    'daily share reward verified independently; direct send remains separately due',
                    False,
                )
        return True
    except BaseException:
        return False


def _share_action_blocked(context, phase='', cfg=None):
    """Hard-stop every automatic share UI action after a proven completion or pause.

    This is deliberately shared by recovery, template clicks, and recipient
    confirmation.  A daily share is a one-shot action: the first durable proof,
    visible claimed-reward checkmark, or pause signal wins over every later
    recovery/visual fallback route.
    """
    phase_value = str(phase or 'share-action').strip() or 'share-action'

    def _apply_success():
        apply_fn = globals().get('_daily_flow_apply_success_context')
        if callable(apply_fn):
            try:
                apply_fn(context, 'share')
            except BaseException:
                pass
        clear_fn = globals().get('_share_clear_retry_backoff')
        if callable(clear_fn):
            try:
                clear_fn(context)
            except BaseException:
                pass
        # The action gate may be reached by several stale callbacks in the
        # same run cycle. Once it has accepted any same-day completion proof,
        # mark the recovery scheduler itself as completed so later callbacks
        # return before touching the reward UI, retry state, or native sender.
        completion_day = (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d'))
        globals()['_QQFARM_SHARE_RECOVERY_COMPLETED_DAY'] = completion_day
        if context is not None:
            try:
                setattr(
                    context,
                    '_qqfarm_share_recovery_completed_day',
                    completion_day,
                )
            except BaseException:
                pass

    def _log(reason):
        try:
            log_fn = globals().get('_share_log_runtime')
            if callable(log_fn):
                log_fn(
                    'action-hard-gate-' + phase_value + '-' + str(reason),
                    'daily share action blocked phase=' + phase_value +
                    ' reason=' + str(reason),
                    False,
                )
        except BaseException:
            pass

    try:
        stop_fn = globals().get('_stop_requested_in_args')
        if callable(stop_fn) and stop_fn((context,), {}):
            _log('stop-requested')
            return True
    except BaseException:
        pass

    if not isinstance(cfg, dict):
        try:
            config_fn = globals().get('_share_target_guard_config')
            cfg = config_fn() if callable(config_fn) else {}
        except BaseException:
            cfg = {}
    if not isinstance(cfg, dict) or not cfg.get('enabled', False):
        return False

    target = str(cfg.get('target_name', '') or '').strip()
    reward_phase = phase_value.startswith('reward-claim')
    if reward_phase:
        day = (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d'))
        reward_success = False
        share_success = False
        success_fn = globals().get('_daily_flow_success_today')
        if callable(success_fn):
            try:
                reward_success = bool(success_fn(
                    'share_reward', target=target
                ))
            except TypeError:
                try:
                    reward_success = bool(success_fn('share_reward'))
                except BaseException:
                    reward_success = False
            except BaseException:
                reward_success = False
            try:
                share_success = bool(success_fn('share', target=target))
            except TypeError:
                try:
                    share_success = bool(success_fn('share'))
                except BaseException:
                    share_success = False
            except BaseException:
                share_success = False
        try:
            reward_success = reward_success or str(getattr(
                context, '_qqfarm_share_reward_claimed_day', ''
            ) or '').strip() == day
        except BaseException:
            pass
        if reward_success:
            _log('reward-already-claimed')
            return True
        claimed_fn = globals().get('_share_reward_claimed_visible')
        if context is not None and callable(claimed_fn):
            try:
                if bool(claimed_fn(context)):
                    persist_fn = globals().get(
                        '_share_mark_reward_claimed_success'
                    )
                    if callable(persist_fn):
                        try:
                            persist_fn(context, cfg)
                        except BaseException:
                            pass
                    _log('reward-visible-claimed')
                    return True
            except BaseException:
                pass
        if share_success:
            # The exact send is immutable, but its reward is a separate daily
            # action and remains eligible until visually verified.
            return False
        _log('reward-before-direct-send')
        return True

    unverified_share = False
    unverified_fn = globals().get('_daily_flow_unverified_today')
    if callable(unverified_fn):
        try:
            unverified_share = bool(unverified_fn('share'))
        except BaseException:
            unverified_share = False
    if unverified_share and context is not None:
        try:
            if str(getattr(context, 'share_last_date', '') or '').strip() == (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d')):
                setattr(context, 'share_last_date', '')
        except BaseException:
            pass
    try:
        native_recorded_day = str(
            getattr(context, 'share_last_date', '') or ''
        ).strip()
        if (not unverified_share and native_recorded_day == (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d'))):
            # `run_daily_share` records this field immediately after its first
            # completed send. It is a one-day dispatch latch: do not let the
            # recovery/template paths reopen the same share card just because
            # exact-recipient confirmation was observed late.
            claimed_fn = globals().get('_share_reward_claimed_visible')
            persist_fn = globals().get('_share_mark_reward_claimed_success')
            if (
                callable(claimed_fn) and callable(persist_fn)
                and claimed_fn(context)
            ):
                try:
                    persist_fn(context, cfg)
                except BaseException:
                    pass
            _apply_success()
            _log('native-share-completion-latch')
            return True
    except BaseException:
        pass

    # The native daily-share route latches `share_last_date` before all of
    # the visual/template callbacks receive a runtime context.  Read the
    # portable counter directly so an already-sent share remains a one-day
    # no-replay gate even when daily_flow_status.json is unavailable.
    try:
        counter_day = str((globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d')))
        os_module = __import__('os')
        json_module = __import__('json')
        counter_paths = []
        configured_counter = str(
            os_module.environ.get('QQFARM_DAILY_COUNTERS_PATH', '') or ''
        ).strip()
        if configured_counter:
            counter_paths.append(os_module.path.abspath(configured_counter))
        local_appdata = str(
            os_module.environ.get('LOCALAPPDATA', '') or ''
        ).strip()
        if local_appdata:
            counter_dir = os_module.path.join(
                local_appdata, 'qq-farm-bot-rev'
            )
            for counter_name in ('daily_counters.json', 'daily_counters.hook.json'):
                candidate = os_module.path.abspath(
                    os_module.path.join(counter_dir, counter_name)
                )
                if candidate not in counter_paths:
                    counter_paths.append(candidate)
        context_instance = str(
            getattr(context, 'instance_id', '') or ''
        ).strip()
        for counter_path in counter_paths:
            try:
                with open(counter_path, 'r', encoding='utf-8-sig') as handle:
                    counter_data = json_module.load(handle)
                if not isinstance(counter_data, dict):
                    continue
                counter_records = [counter_data]
                if context_instance:
                    instances = counter_data.get('instances')
                    instance_record = (
                        instances.get(context_instance)
                        if isinstance(instances, dict) else None
                    )
                    if isinstance(instance_record, dict):
                        counter_records.append(instance_record)
                if any(
                    str(record.get('share_last_date', '') or '').strip()
                    == counter_day
                    for record in counter_records
                    if isinstance(record, dict)
                ):
                    if unverified_share:
                        continue
                    _apply_success()
                    _log('daily-counter-latch')
                    return True
            except BaseException:
                continue
    except BaseException:
        pass

    success_fn = globals().get('_daily_flow_success_today')
    try:
        if callable(success_fn) and success_fn('share', target=target):
            _apply_success()
            _log('durable-success')
            return True
    except BaseException:
        pass

    pending_fn = globals().get('_share_direct_send_pending')
    pending_send = False
    if callable(pending_fn):
        try:
            pending_send = bool(pending_fn(target, max_age=86400.0))
        except TypeError:
            try:
                pending_send = bool(pending_fn(target))
            except BaseException:
                pending_send = False
        except BaseException:
            pending_send = False
    if pending_send:
        reconcile_fn = globals().get('_share_reconcile_pending_direct_send')
        reconciled = False
        if callable(reconcile_fn):
            try:
                reconciled = bool(reconcile_fn(target))
            except BaseException:
                reconciled = False
        if reconciled:
            _apply_success()
            _log('pending-direct-send-persisted')
        else:
            _log('pending-direct-send-no-replay')
        return True

    direct_fn = globals().get('_share_direct_success_recent')
    direct_verified = False
    if callable(direct_fn):
        try:
            direct_verified = bool(direct_fn(target, max_age=86400.0))
        except TypeError:
            try:
                direct_verified = bool(direct_fn(target))
            except BaseException:
                direct_verified = False
        except BaseException:
            direct_verified = False
    if direct_verified:
        mark_fn = globals().get('_daily_flow_mark_status')
        if callable(mark_fn):
            try:
                mark_fn(
                    'share', 'success', target=target,
                    reason='verified-direct-contact-send-v2',
                )
            except BaseException:
                pass
        _apply_success()
        _log('runtime-success')
        return True

    claimed_fn = globals().get('_share_reward_claimed_visible')
    if context is not None and callable(claimed_fn):
        try:
            if claimed_fn(context):
                persist_fn = globals().get('_share_mark_reward_claimed_success')
                if callable(persist_fn) and persist_fn(context, cfg):
                    _log('visible-claimed-reward-direct-send-still-due')
                return False
        except BaseException:
            pass
    return False

def _run_share_prompt_recovery(context):
    if context is None:
        return False

    def _blocked(phase, cfg=None):
        gate_fn = globals().get('_share_action_blocked')
        if callable(gate_fn):
            try:
                return bool(gate_fn(context, phase, cfg))
            except BaseException:
                return False
        try:
            stop_fn = globals().get('_stop_requested_in_args')
            return bool(callable(stop_fn) and stop_fn((context,), {}))
        except BaseException:
            return False

    def _apply_verified_success():
        apply_fn = globals().get('_daily_flow_apply_success_context')
        if callable(apply_fn):
            try:
                apply_fn(context, 'share')
            except BaseException:
                pass
        clear_fn = globals().get('_share_clear_retry_backoff')
        if callable(clear_fn):
            try:
                clear_fn(context)
            except BaseException:
                pass
        return True

    def _set_recovery_completed(day):
        globals()['_QQFARM_SHARE_RECOVERY_COMPLETED_DAY'] = day
        try:
            setattr(context, '_qqfarm_share_recovery_completed_day', day)
        except BaseException:
            pass

    def _close_stale_recipient_dialog():
        """Close a recipient picker left behind by an earlier false reward click."""
        try:
            module_fn = globals().get('_share_target_module')
            module = module_fn() if callable(module_fn) else None
            find_fn = globals().get('_share_find_dialog_hwnd')
            dialog = int(find_fn(module) or 0) if callable(find_fn) else 0
            if not dialog:
                return True
            close_fn = globals().get('_share_close_dialog')
            wait_fn = globals().get('_share_wait_dialog_closed')
            close_requested = bool(
                callable(close_fn) and close_fn(module, dialog)
            )
            if not close_requested:
                return False
            if callable(wait_fn):
                return bool(wait_fn(module, timeout_ms=1200))
            if callable(find_fn):
                return not bool(find_fn(module))
            return True
        except BaseException:
            return False

    try:
        today = (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d'))
        config_fn = globals().get('_share_target_guard_config')
        available_fn = globals().get(
            '_share_reward_claim_available_visible'
        )
        reward_capable = bool(
            callable(config_fn) and callable(available_fn)
        )
        recovery_latched = bool(
            str(globals().get(
                '_QQFARM_SHARE_RECOVERY_COMPLETED_DAY', ''
            ) or '') == today
            or str(getattr(
                context, '_qqfarm_share_recovery_completed_day', ''
            ) or '') == today
        )
        # Legacy/unit-loaded recovery namespaces have no reward subsystem.  In
        # that case the historical one-shot latch remains completely silent.
        if recovery_latched and not reward_capable:
            return False

        success_fn = globals().get('_daily_flow_success_today')
        durable_success = False
        if callable(success_fn):
            try:
                durable_success = bool(success_fn('share'))
            except BaseException:
                durable_success = False
        if recovery_latched and not durable_success:
            return False

        cfg = config_fn() if callable(config_fn) else {}
        if not isinstance(cfg, dict):
            cfg = {}
        target = str(cfg.get('target_name', '') or '').strip()
        reward_success = False
        if callable(success_fn) and reward_capable:
            try:
                reward_success = bool(success_fn(
                    'share_reward', target=target
                ))
            except TypeError:
                try:
                    reward_success = bool(success_fn('share_reward'))
                except BaseException:
                    reward_success = False
            except BaseException:
                reward_success = False
        try:
            reward_success = reward_success or str(getattr(
                context, '_qqfarm_share_reward_claimed_day', ''
            ) or '').strip() == today
        except BaseException:
            pass
        if recovery_latched and reward_success:
            return False

        # Direct-recipient send success and reward claiming are independent.
        # Every sender/template phase remains blocked, while this one dedicated
        # action can click and verify the yellow reward exactly once.
        if durable_success:
            _apply_verified_success()
            if not reward_capable:
                _set_recovery_completed(today)
                return False
            if not cfg.get('enabled', False):
                _set_recovery_completed(today)
                return False
            if reward_success:
                close_fn = globals().get('_share_close_share_page')
                if callable(close_fn) and str(getattr(
                    context, '_qqfarm_share_reward_page_closed_day', ''
                ) or '').strip() != today:
                    try:
                        close_fn(context)
                    except BaseException:
                        pass
                _set_recovery_completed(today)
                return False
            if _blocked('reward-claim-start', cfg):
                return False
            try:
                if bool(getattr(
                    context, '_qqfarm_share_visual_recovery_running', False
                )):
                    return False
            except BaseException:
                pass
            try:
                setattr(context, '_qqfarm_share_visual_recovery_running', True)
            except BaseException:
                pass
            try:
                available_fn = globals().get(
                    '_share_reward_claim_available_visible'
                )
                claimed_fn = globals().get('_share_reward_claimed_visible')

                # A visible reward checkmark is stronger evidence than any warm
                # button-like region.  Check it first so the green share panel
                # cannot be mistaken for a reward action and reopen QQ's picker.
                verified = bool(
                    callable(claimed_fn) and claimed_fn(context)
                )
                if not verified:
                    adopt_fn = globals().get(
                        '_share_reward_claimed_current_page_visible'
                    )
                    verified = bool(
                        callable(adopt_fn) and adopt_fn(context)
                    )
                available = False
                if not verified:
                    available = bool(
                        callable(available_fn) and available_fn(context)
                    )
                    if not available:
                        open_fn = globals().get('_share_open_reward_page')
                        if not callable(open_fn) or not bool(open_fn(context)):
                            return False
                        verified = bool(
                            callable(claimed_fn) and claimed_fn(context)
                        )
                        if not verified:
                            available = bool(
                                callable(available_fn) and available_fn(context)
                            )
                            if not available:
                                return False
                if not verified and available:
                    click_fn = globals().get('_share_click_reward_claim')
                    if not callable(click_fn) or not bool(click_fn(context)):
                        return False
                    verified = bool(
                        callable(claimed_fn) and claimed_fn(context)
                    )
                    if not verified and callable(available_fn):
                        try:
                            still_available = bool(available_fn(context))
                        except BaseException:
                            still_available = True
                        try:
                            probe_valid = bool(getattr(
                                context,
                                '_qqfarm_share_reward_probe_valid',
                                False,
                            ))
                        except BaseException:
                            probe_valid = False
                        verified = bool(probe_valid and not still_available)
                    if not verified:
                        log_fn = globals().get('_share_log_runtime')
                        if callable(log_fn):
                            log_fn(
                                'reward-claim-unverified-v327',
                                'daily share reward click sent but neither checkmark nor button disappearance was verified',
                                True,
                            )
                        return False

                persist_fn = globals().get(
                    '_share_mark_reward_claimed_success'
                )
                if not callable(persist_fn) or not bool(
                    persist_fn(context, cfg)
                ):
                    return False
                if not _close_stale_recipient_dialog():
                    return False
                close_fn = globals().get('_share_close_share_page')
                if callable(close_fn):
                    try:
                        close_fn(context)
                    except BaseException:
                        pass
                _set_recovery_completed(today)
                return True
            finally:
                try:
                    setattr(
                        context, '_qqfarm_share_visual_recovery_running', False
                    )
                except BaseException:
                    pass
    except BaseException:
        pass

    # This first boundary is intentionally before the due/retry check.  A
    # completed share must not reach native recovery merely because an older
    # scheduler still says it is due.
    if _blocked('recovery-start'):
        return False
    try:
        if bool(getattr(context, '_qqfarm_share_visual_recovery_running', False)):
            return False
    except BaseException:
        pass
    due_fn = globals().get('_share_recovery_due')
    if callable(due_fn) and not due_fn(context):
        return False
    try:
        setattr(context, '_qqfarm_share_visual_recovery_running', True)
    except BaseException:
        pass

    try:
        cfg = _share_target_guard_config()
        if not cfg.get('enabled', False):
            return False
        if _blocked('recovery-after-config', cfg):
            return False
        reward_visible_fn = globals().get('_share_reward_claimed_visible')
        if callable(reward_visible_fn) and reward_visible_fn(context):
            reward_success_fn = globals().get('_share_mark_reward_claimed_success')
            if not (callable(reward_success_fn) and reward_success_fn(context, cfg)):
                fail_fn = globals().get('_share_recovery_fail')
                return fail_fn(context, 'reward-success-persist-failed') if callable(fail_fn) else False
            # A claimed reward is independent from the exact-recipient send.
            # Continue into the native sender until direct-contact proof exists.
        module_fn = globals().get('_share_target_module')
        mod = module_fn() if callable(module_fn) else None
        dialog = _share_find_dialog_hwnd(mod)
        if not dialog:
            native_run = getattr(mod, 'run_daily_share', None) if mod is not None else None
            native_running = bool(getattr(
                context, '_qqfarm_share_native_recovery_running', False
            ))
            if callable(native_run) and not native_running:
                if _blocked('recovery-before-native', cfg):
                    return False
                try:
                    setattr(context, '_qqfarm_share_native_recovery_running', True)
                    frame_fn = globals().get('_get_frame_from_bot')
                    game_frame = frame_fn(context) if callable(frame_fn) else None
                    call_with_frame = False
                    try:
                        signature = __import__('inspect').signature(native_run)
                        positional = [
                            parameter for parameter in signature.parameters.values()
                            if parameter.kind in (
                                parameter.POSITIONAL_ONLY,
                                parameter.POSITIONAL_OR_KEYWORD,
                            )
                        ]
                        call_with_frame = (
                            len(positional) >= 2
                            or any(
                                parameter.kind == parameter.VAR_POSITIONAL
                                for parameter in signature.parameters.values()
                            )
                        )
                    except BaseException:
                        call_with_frame = game_frame is not None
                    if call_with_frame:
                        native_run(context, game_frame)
                    else:
                        native_run(context)
                except BaseException as native_error:
                    _throttled_write(
                        'v243-share-native-error',
                        'v243 native daily share recovery error ' + repr(native_error)[:240],
                        10.0,
                    )
                finally:
                    try:
                        setattr(context, '_qqfarm_share_native_recovery_running', False)
                    except BaseException:
                        pass
                if _blocked('recovery-after-native', cfg):
                    return False
                success_fn = globals().get('_share_direct_success_recent')
                try:
                    if callable(success_fn) and success_fn(cfg.get('target_name', '')):
                        return _apply_verified_success()
                except BaseException:
                    pass
                dialog = _share_wait_dialog_hwnd(mod, timeout_ms=2500)
        if not dialog:
            try:
                center = _share_find_prompt_button_center((context,), {})
            except TypeError:
                center = _share_find_prompt_button_center()
            if center is None:
                fail_fn = globals().get('_share_recovery_fail')
                return fail_fn(context, 'prompt-not-found') if callable(fail_fn) else False
            if _blocked('recovery-before-prompt-click', cfg):
                return False
            if not _share_click_prompt_button(center, (context,), {}):
                fail_fn = globals().get('_share_recovery_fail')
                return fail_fn(context, 'prompt-click-failed') if callable(fail_fn) else False
            # Stop/completion may arrive during the actual click; it must be
            # checked before the contact dialog is opened or searched.
            if _blocked('recovery-after-prompt-click', cfg):
                return False
            _throttled_write(
                'v78-share-prompt-clicked',
                'v78 daily share prompt button clicked by run_cycle recovery',
                5.0,
            )
            dialog = _share_wait_dialog_hwnd(mod, timeout_ms=3500)
        if not dialog:
            _throttled_write(
                'v78-share-dialog-missing',
                'v78 daily share recovery did not observe contact dialog after prompt click',
                10.0,
            )
            fail_fn = globals().get('_share_recovery_fail')
            return fail_fn(context, 'contact-dialog-missing') if callable(fail_fn) else False
        if _blocked('recovery-before-contact-search', cfg):
            return False
        confirm_fn = globals().get('_share_search_and_maybe_confirm')
        try:
            confirmed = bool(confirm_fn(mod, cfg, context=context)) if callable(confirm_fn) else False
        except TypeError:
            confirmed = bool(confirm_fn(mod, cfg)) if callable(confirm_fn) else False
        if not confirmed:
            fail_fn = globals().get('_share_recovery_fail')
            return fail_fn(context, 'target-confirm-failed') if callable(fail_fn) else False
        if _blocked('recovery-after-contact-search', cfg):
            return False
        success_fn = globals().get('_share_direct_success_recent')
        verified = False
        if callable(success_fn):
            try:
                verified = bool(success_fn(cfg.get('target_name', '')))
            except BaseException:
                verified = False
        if not verified:
            fail_fn = globals().get('_share_recovery_fail')
            return fail_fn(context, 'verified-success-missing') if callable(fail_fn) else False
        _apply_verified_success()
        _share_log_runtime(
            'sent-v78-recovery',
            'daily share completed by run_cycle recovery target=' + str(cfg.get('target_name', '')),
            False,
        )
        return True
    except BaseException as e:
        try:
            _throttled_write('v78-share-recovery-error', 'v78 daily share recovery error ' + repr(e), 10.0)
        except BaseException:
            pass
        fail_fn = globals().get('_share_recovery_fail')
        return fail_fn(context, 'unexpected-error') if callable(fail_fn) else False
    finally:
        try:
            setattr(context, '_qqfarm_share_visual_recovery_running', False)
        except BaseException:
            pass


def _share_target_guard_config():
    try:
        secs = _active_bot_sections()
    except BaseException:
        secs = ['bot']
    try:
        target = str(_cfg_get(secs, 'share_target_name', '') or '').strip()
    except BaseException:
        target = ''
    try:
        search_enabled = _truthy(_cfg_get(secs, 'share_search_enabled', 'False'), False)
    except BaseException:
        search_enabled = False
    try:
        requires_match = _truthy(_cfg_get(secs, 'share_send_requires_target_match', 'False'), False)
    except BaseException:
        requires_match = False
    try:
        dry_run = _truthy(_cfg_get(secs, 'share_dry_run', 'True'), True)
    except BaseException:
        dry_run = True
    try:
        allow_group = _truthy(_cfg_get(secs, 'share_allow_group', 'False'), False)
    except BaseException:
        allow_group = False
    # A share is eligible only when an explicit target is configured.
    # Unverified/first-row fallbacks are intentionally never enabled.
    enabled = bool(target and search_enabled and requires_match)
    return {
        'enabled': enabled,
        'search_enabled': bool(search_enabled),
        'target_name': target,
        'requires_match': bool(requires_match),
        'dry_run': bool(dry_run),
        'allow_group': bool(allow_group),
    }


def _share_log_runtime(key, msg, warning=False):
    try:
        logging_mod = sys.modules.get('logging')
        if logging_mod is not None:
            lg = logging_mod.getLogger()
            if warning:
                lg.warning(msg)
            else:
                lg.info(msg)
    except BaseException:
        pass
    try:
        _throttled_write('share-target-' + str(key), 'v31 share target guard ' + str(msg), 5.0)
    except BaseException:
        pass


def _share_set_clipboard_unicode(text):
    value = str(text or '')
    # Prefer the process-independent Win32 clipboard.  Qt's worker-thread
    # clipboard cache can report success while QQ still sees stale text.
    try:
        import win32clipboard
        opened = False
        for _ in range(6):
            try:
                win32clipboard.OpenClipboard()
                opened = True
                break
            except BaseException:
                time.sleep(0.03)
        if opened:
            try:
                win32clipboard.EmptyClipboard()
                win32clipboard.SetClipboardText(value, win32clipboard.CF_UNICODETEXT)
                return True
            finally:
                win32clipboard.CloseClipboard()
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        data = (value + '\x00').encode('utf-16le')
        kernel32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
        kernel32.GlobalAlloc.restype = ctypes.c_void_p
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        user32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
        user32.SetClipboardData.restype = ctypes.c_void_p
        hglobal = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(data))
        if hglobal:
            locked = kernel32.GlobalLock(hglobal)
            if locked:
                ctypes.memmove(locked, data, len(data))
                kernel32.GlobalUnlock(hglobal)
                opened = False
                for _ in range(6):
                    if user32.OpenClipboard(0):
                        opened = True
                        break
                    time.sleep(0.03)
                if opened:
                    try:
                        user32.EmptyClipboard()
                        if user32.SetClipboardData(CF_UNICODETEXT, hglobal):
                            return True
                    finally:
                        user32.CloseClipboard()
    except BaseException:
        pass
    try:
        from PySide6.QtGui import QGuiApplication
        app = QGuiApplication.instance()
        if app is not None:
            clipboard = app.clipboard()
            clipboard.setText(value)
            try:
                return str(clipboard.text()) == value
            except BaseException:
                return True
    except BaseException:
        pass
    try:
        import base64
        import subprocess
        payload = base64.b64encode(value.encode('utf-16le')).decode('ascii')
        script = (
            "$v=[Text.Encoding]::Unicode.GetString([Convert]::FromBase64String('" +
            payload + "')); Set-Clipboard -Value $v"
        )
        flags = int(getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000))
        completed = subprocess.run(
            ['powershell.exe', '-NoLogo', '-NoProfile', '-NonInteractive',
             '-WindowStyle', 'Hidden', '-Command', script],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=flags,
            timeout=5.0,
            check=False,
        )
        return int(getattr(completed, 'returncode', 1)) == 0
    except BaseException as error:
        try: _write('v90 share clipboard write error ' + repr(error))
        except BaseException: pass
        return False


def _share_get_clipboard_unicode():
    try:
        import win32clipboard
        opened = False
        for _ in range(6):
            try:
                win32clipboard.OpenClipboard()
                opened = True
                break
            except BaseException:
                time.sleep(0.03)
        if opened:
            try:
                value = win32clipboard.GetClipboardData(win32clipboard.CF_UNICODETEXT)
                return str(value or '')
            finally:
                win32clipboard.CloseClipboard()
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        CF_UNICODETEXT = 13
        user32.GetClipboardData.argtypes = [ctypes.c_uint]
        user32.GetClipboardData.restype = ctypes.c_void_p
        kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
        kernel32.GlobalLock.restype = ctypes.c_void_p
        kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
        opened = False
        for _ in range(6):
            if user32.OpenClipboard(0):
                opened = True
                break
            time.sleep(0.03)
        if opened:
            try:
                handle = user32.GetClipboardData(CF_UNICODETEXT)
                if handle:
                    pointer = kernel32.GlobalLock(handle)
                    if pointer:
                        try:
                            return str(ctypes.wstring_at(pointer) or '')
                        finally:
                            kernel32.GlobalUnlock(handle)
            finally:
                user32.CloseClipboard()
    except BaseException:
        pass
    try:
        from PySide6.QtGui import QGuiApplication
        app = QGuiApplication.instance()
        if app is not None:
            return str(app.clipboard().text() or '')
    except BaseException:
        pass
    return None


def _share_read_focused_text_via_clipboard():
    sentinel = '__QQFARM_SHARE_READBACK_SENTINEL__'
    try:
        if not _share_set_clipboard_unicode(sentinel):
            return None
        time.sleep(0.08)
        if not _share_send_ctrl_key(0x41):
            return None
        time.sleep(0.06)
        if not _share_send_ctrl_key(0x43):
            return None
        time.sleep(max(0.12, float(_share_int_cfg('share_input_readback_wait_ms', 220)) / 1000.0))
        value = _share_get_clipboard_unicode()
        if value is None or str(value) == sentinel:
            return None
        return str(value)
    except BaseException:
        return None

def _share_key(vk, up=False):
    try:
        import win32api
        win32api.keybd_event(int(vk), 0, 0x0002 if up else 0, 0)
        return True
    except BaseException:
        pass
    try:
        import ctypes
        KEYEVENTF_KEYUP = 0x0002
        ctypes.windll.user32.keybd_event(int(vk), 0, KEYEVENTF_KEYUP if up else 0, 0)
        return True
    except BaseException:
        return False


def _share_send_ctrl_key(vk):
    VK_CONTROL = 0x11
    key_down = False
    control_down = False
    try:
        if not _share_key(VK_CONTROL, False):
            return False
        control_down = True
        time.sleep(0.04)
        if not _share_key(vk, False):
            return False
        key_down = True
        time.sleep(0.04)
        if not _share_key(vk, True):
            return False
        key_down = False
        time.sleep(0.04)
        if not _share_key(VK_CONTROL, True):
            return False
        control_down = False
        return True
    except BaseException:
        return False
    finally:
        if key_down:
            try: _share_key(vk, True)
            except BaseException: pass
        if control_down:
            try: _share_key(VK_CONTROL, True)
            except BaseException: pass


def _share_click_abs(x, y):
    try:
        import win32api
        win32api.SetCursorPos((int(x), int(y)))
        time.sleep(0.04)
        win32api.mouse_event(0x0002, 0, 0, 0, 0)
        time.sleep(0.03)
        win32api.mouse_event(0x0004, 0, 0, 0, 0)
        return True
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        user32.SetCursorPos(int(x), int(y))
        time.sleep(0.05)
        user32.mouse_event(0x0002, 0, 0, 0, 0)
        time.sleep(0.03)
        user32.mouse_event(0x0004, 0, 0, 0, 0)
        return True
    except BaseException as e:
        try: _write('v71 share click error ' + repr(e))
        except BaseException: pass
        return False


def _share_find_dialog_hwnd(mod=None):
    try:
        if mod is not None and hasattr(mod, '_find_share_dialog_hwnd'):
            hwnd = mod._find_share_dialog_hwnd()
            if hwnd:
                return int(hwnd)
    except BaseException:
        pass
    try:
        kws = str(_cfg_get(_active_bot_sections(), 'share_dialog_title_keywords', '\u9009\u62e9\u8054\u7cfb\u4eba,\u53d1\u9001\u7ed9') or '')
        kws = kws.replace(';', ',').replace('|', ',')
        keywords = [x.strip() for x in kws.split(',') if x.strip()]
    except BaseException:
        keywords = ['\u9009\u62e9\u8054\u7cfb\u4eba', '\u53d1\u9001\u7ed9']
    try:
        import win32gui
        found = []
        def _cb(hwnd, extra):
            try:
                title = str(win32gui.GetWindowText(hwnd) or '')
                if title and any(k in title for k in keywords):
                    found.append(int(hwnd))
            except BaseException:
                pass
            return True
        win32gui.EnumWindows(_cb, None)
        if found:
            return found[0]
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        found = []
        WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        def _cb(hwnd, lparam):
            try:
                buf = ctypes.create_unicode_buffer(256)
                user32.GetWindowTextW(hwnd, buf, 256)
                title = str(buf.value or '')
                if title and any(k in title for k in keywords):
                    found.append(int(hwnd))
            except BaseException:
                pass
            return True
        user32.EnumWindows(WNDENUMPROC(_cb), 0)
        return found[0] if found else 0
    except BaseException as e:
        try: _write('v71 share find hwnd error ' + repr(e))
        except BaseException: pass
        return 0


def _share_wait_dialog_hwnd(mod=None, timeout_ms=None):
    try:
        if timeout_ms is None:
            try:
                secs = float(str(_cfg_get(
                    _active_bot_sections(), 'share_dialog_wait_timeout_seconds', '2.5'
                )).strip())
            except BaseException:
                secs = 2.5
            timeout_ms = int(max(300.0, secs * 1000.0))
        deadline = time.monotonic() + max(0.1, float(timeout_ms) / 1000.0)
        while True:
            hwnd = _share_find_dialog_hwnd(mod)
            if hwnd:
                return int(hwnd)
            if time.monotonic() >= deadline:
                return 0
            time.sleep(0.08)
    except BaseException:
        return 0

def _share_get_rect(hwnd):
    try:
        import win32gui
        rect = win32gui.GetWindowRect(int(hwnd))
        if rect and int(rect[2]) > int(rect[0]) and int(rect[3]) > int(rect[1]):
            return tuple(int(x) for x in rect)
    except BaseException:
        pass
    try:
        import ctypes
        class RECT(ctypes.Structure):
            _fields_ = [('left', ctypes.c_long), ('top', ctypes.c_long), ('right', ctypes.c_long), ('bottom', ctypes.c_long)]
        rect = RECT()
        if not ctypes.windll.user32.GetWindowRect(int(hwnd), ctypes.byref(rect)):
            return None
        return (int(rect.left), int(rect.top), int(rect.right), int(rect.bottom))
    except BaseException:
        return None


def _share_get_work_area(hwnd):
    """Return the nearest monitor work area for the contact dialog."""
    try:
        import win32api
        monitor = win32api.MonitorFromWindow(int(hwnd), 2)
        info = win32api.GetMonitorInfo(monitor)
        work = info.get('Work') if isinstance(info, dict) else None
        if work and int(work[2]) > int(work[0]) and int(work[3]) > int(work[1]):
            return tuple(int(value) for value in work)
    except BaseException:
        pass
    try:
        import ctypes
        class RECT(ctypes.Structure):
            _fields_ = [
                ('left', ctypes.c_long), ('top', ctypes.c_long),
                ('right', ctypes.c_long), ('bottom', ctypes.c_long),
            ]
        work = RECT()
        if ctypes.windll.user32.SystemParametersInfoW(
            0x0030, 0, ctypes.byref(work), 0
        ):
            rect = (int(work.left), int(work.top), int(work.right), int(work.bottom))
            if rect[2] > rect[0] and rect[3] > rect[1]:
                return rect
    except BaseException:
        pass
    return None


def _share_move_dialog_window(hwnd, left, top):
    try:
        import win32gui
        flags = 0x0001 | 0x0004 | 0x0010 | 0x0040
        win32gui.SetWindowPos(int(hwnd), 0, int(left), int(top), 0, 0, flags)
        return True
    except BaseException:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        flags = 0x0001 | 0x0004 | 0x0010 | 0x0040
        return bool(user32.SetWindowPos(
            ctypes.c_void_p(int(hwnd)), ctypes.c_void_p(0),
            int(left), int(top), 0, 0, flags
        ))
    except BaseException:
        return False


def _share_ensure_dialog_on_screen(hwnd, margin=12):
    """Clamp the whole contact dialog into its monitor before physical clicks."""
    try:
        rect_fn = globals().get('_share_get_rect')
        work_fn = globals().get('_share_get_work_area')
        move_fn = globals().get('_share_move_dialog_window')
        rect = rect_fn(hwnd) if callable(rect_fn) else None
        work = work_fn(hwnd) if callable(work_fn) else None
        if not rect or not work:
            return rect
        left, top, right, bottom = (int(value) for value in rect)
        work_left, work_top, work_right, work_bottom = (
            int(value) for value in work
        )
        width = max(1, right - left)
        height = max(1, bottom - top)
        safe_margin = max(0, min(64, int(margin)))
        min_left = work_left + safe_margin
        min_top = work_top + safe_margin
        max_left = work_right - safe_margin - width
        max_top = work_bottom - safe_margin - height
        if max_left < min_left:
            target_left = work_left + max(0, ((work_right - work_left) - width) // 2)
        else:
            target_left = max(min_left, min(left, max_left))
        if max_top < min_top:
            target_top = work_top + max(0, ((work_bottom - work_top) - height) // 2)
        else:
            target_top = max(min_top, min(top, max_top))
        if target_left == left and target_top == top:
            return rect
        if not callable(move_fn) or not move_fn(hwnd, target_left, target_top):
            return rect
        time.sleep(0.12)
        refreshed = rect_fn(hwnd) if callable(rect_fn) else None
        final_rect = refreshed or (
            target_left, target_top, target_left + width, target_top + height
        )
        try:
            _share_log_runtime(
                'dialog-repositioned',
                'daily share contact dialog moved into work area: before=' + repr(rect) +
                ' work=' + repr(work) + ' after=' + repr(final_rect),
                False,
            )
        except BaseException:
            pass
        return final_rect
    except BaseException:
        try:
            return _share_get_rect(hwnd)
        except BaseException:
            return None


