def _share_preflight_completed(context):
    """Return true when today's share is already proven before any UI click."""
    try:
        gate_fn = globals().get('_share_action_blocked')
        if callable(gate_fn):
            return bool(gate_fn(context, 'preflight'))
    except BaseException:
        pass
    try:
        config_fn = globals().get('_share_target_guard_config')
        cfg = config_fn() if callable(config_fn) else {}
        if not isinstance(cfg, dict) or not cfg.get('enabled', False):
            return False
        target = str(cfg.get('target_name', '') or '').strip()
        success_fn = globals().get('_daily_flow_success_today')
        if callable(success_fn) and success_fn('share', target=target):
            apply_fn = globals().get('_daily_flow_apply_success_context')
            if callable(apply_fn):
                apply_fn(context, 'share')
            clear_fn = globals().get('_share_clear_retry_backoff')
            if callable(clear_fn):
                clear_fn(context)
            return True
        direct_fn = globals().get('_share_direct_success_recent')
        direct_verified = False
        if callable(direct_fn):
            try:
                direct_verified = bool(direct_fn(target, max_age=86400.0))
            except TypeError:
                direct_verified = bool(direct_fn(target))
        if direct_verified:
            mark_fn = globals().get('_daily_flow_mark_status')
            if callable(mark_fn):
                mark_fn(
                    'share', 'success', target=target,
                    reason='verified-direct-contact-send-v2',
                )
            apply_fn = globals().get('_daily_flow_apply_success_context')
            if callable(apply_fn):
                apply_fn(context, 'share')
            clear_fn = globals().get('_share_clear_retry_backoff')
            if callable(clear_fn):
                clear_fn(context)
            return True
        claimed_fn = globals().get('_share_reward_claimed_visible')
        if callable(claimed_fn) and claimed_fn(context):
            persist_fn = globals().get('_share_mark_reward_claimed_success')
            if callable(persist_fn):
                persist_fn(context, cfg)
            return False
        return False
    except BaseException:
        return False


def _freebenefits_claim_button_center_from_rgb(image):
    """Locate the real first-card `??` action on the 428x800 shop page."""
    try:
        np = __import__('numpy')
        arr = np.asarray(image)
        if arr.ndim < 3 or int(arr.shape[2]) < 3:
            return None
        height, width = int(arr.shape[0]), int(arr.shape[1])
        if width < 160 or height < 240:
            return None
        pixels = arr[:, :, :3].astype(np.int16, copy=False)

        def _roi(x0, y0, x1, y1):
            left = max(0, min(width - 1, int(round(width * x0))))
            top = max(0, min(height - 1, int(round(height * y0))))
            right = max(left + 1, min(width, int(round(width * x1))))
            bottom = max(top + 1, min(height, int(round(height * y1))))
            return pixels[top:bottom, left:right]

        def _warm_ratio(area, strict=False):
            if area.size == 0:
                return 0.0
            blue = area[:, :, 0]
            green = area[:, :, 1]
            red = area[:, :, 2]
            if strict:
                mask = (
                    (red >= 165) & (green >= 115) & (blue <= 165)
                    & (red >= green + 18) & (green >= blue + 20)
                )
            else:
                mask = (
                    (red >= 170) & (green >= 125) & (blue <= 190)
                    & (red >= green + 8) & (green >= blue + 10)
                )
            return float(np.count_nonzero(mask)) / max(1.0, float(mask.size))

        card = _roi(0.082, 0.319, 0.479, 0.631)
        button = _roi(0.105, 0.572, 0.463, 0.619)
        if _warm_ratio(card, False) < 0.52:
            return None
        if _warm_ratio(button, True) < 0.55:
            return None
        return (
            int(round(width * 0.283)),
            int(round(height * 0.596)),
            width, height,
        )
    except BaseException:
        return None


def _freebenefits_claim_transition_verified(before, after):
    """Require a visible free card before click and a fresh card-state change."""
    try:
        center = _freebenefits_claim_button_center_from_rgb(before)
        if center is None or after is None:
            return False
        after_center = _freebenefits_claim_button_center_from_rgb(after)
        if after_center is None:
            return True
        np = __import__('numpy')
        before_arr = np.asarray(before)
        after_arr = np.asarray(after)
        if before_arr.ndim < 3 or after_arr.ndim < 3:
            return False
        if tuple(before_arr.shape[:2]) != tuple(after_arr.shape[:2]):
            return False
        height, width = int(before_arr.shape[0]), int(before_arr.shape[1])
        left, right = int(width * 0.105), int(width * 0.463)
        top, bottom = int(height * 0.572), int(height * 0.619)
        before_roi = before_arr[top:bottom, left:right, :3].astype(
            np.int16, copy=False
        )
        after_roi = after_arr[top:bottom, left:right, :3].astype(
            np.int16, copy=False
        )
        if before_roi.size == 0 or before_roi.shape != after_roi.shape:
            return False
        delta = np.abs(after_roi - before_roi)
        mean_delta = float(delta.mean())
        changed_ratio = float(np.count_nonzero(
            np.max(delta, axis=2) >= 18
        )) / max(1.0, float(delta.shape[0] * delta.shape[1]))
        return bool(mean_delta >= 4.0 or changed_ratio >= 0.06)
    except BaseException:
        return False


def _wrap_share_entry_settle_func(fn):
    try:
        if getattr(fn, '__qqfarm_share_entry_settle_wrapped__', False):
            return fn, False
    except BaseException:
        pass

    def _wrapped(*a, **k):
        entry_kind = _daily_entry_call_kind(a, k)
        context = None
        freebenefits_before = None
        if entry_kind == 'freebenefits':
            try:
                context_fn = globals().get('_daily_flow_context_from_args')
                context = (
                    context_fn(a, k) if callable(context_fn) else None
                )
                frame_from_call = globals().get('_share_prompt_frame_from_call')
                if callable(frame_from_call):
                    freebenefits_before = frame_from_call(a, k)
                if freebenefits_before is None:
                    frame_fn = globals().get('_get_frame_from_bot')
                    freebenefits_before = (
                        frame_fn(context) if callable(frame_fn) else None
                    )
            except BaseException:
                freebenefits_before = None
        # Pause and completion guards run before the native template click.
        # This prevents both an in-flight send after pause and any re-open of
        # a share card that already has a durable exact-send / claimed-reward
        # proof for the day.
        try:
            if _stop_requested_in_args(a, k):
                return _stop_gate_return('daily-share-entry-settle')
        except BaseException:
            pass
        if entry_kind in ('share_entry', 'share_prompt', 'share_btn_click'):
            try:
                context_fn = globals().get('_share_context_from_call')
                context = (
                    context_fn(a, k) if callable(context_fn)
                    else (a[0] if a else None)
                )
                action_gate = globals().get('_share_action_blocked')
                if callable(action_gate):
                    blocked = bool(action_gate(
                        context, 'template-before-' + str(entry_kind)
                    ))
                else:
                    preflight_fn = globals().get('_share_preflight_completed')
                    blocked = bool(callable(preflight_fn) and preflight_fn(context))
                if blocked:
                    _throttled_write(
                        'share-entry-complete-suppressed',
                        'daily share already completed or paused; skipped repeat UI click',
                        30.0,
                    )
                    return False
            except BaseException:
                pass
        result = fn(*a, **k)
        # A pause can arrive while the native click is completing.  Check it
        # again before any visual recovery or direct-recipient confirmation.
        try:
            if _stop_requested_in_args(a, k):
                return _stop_gate_return('daily-share-entry-settle')
        except BaseException:
            pass
        succeeded = _share_click_result_succeeded(result)
        if not succeeded:
            fallback_points = {
                'share_entry': (40, 190),
                'marketplace': (397, 156),
                'freebenefits': (121, 477),
                'exit_marketplace': (51, 127),
            }
            fallback_point = fallback_points.get(entry_kind)
            client_click = globals().get('_friend_guard_post_client_click')
            if fallback_point is not None and callable(client_click):
                try:
                    try:
                        recovered = bool(client_click(
                            fallback_point[0], fallback_point[1], 428, 800
                        ))
                    except TypeError:
                        recovered = bool(client_click(
                            fallback_point[0], fallback_point[1]
                        ))
                    if recovered:
                        result = True
                        succeeded = True
                        _throttled_write(
                            'v450-daily-entry-coordinate-' + str(entry_kind),
                            'v450 native daily entry coordinate fallback tag=' +
                            str(entry_kind) + ' point=' + repr(fallback_point),
                            5.0,
                        )
                except BaseException:
                    pass
        if entry_kind == 'freebenefits' and succeeded:
            try:
                time.sleep(0.75)
                frame_fn = globals().get('_get_frame_from_bot')
                freebenefits_after = (
                    frame_fn(context) if callable(frame_fn) else None
                )
                verify_fn = globals().get(
                    '_freebenefits_claim_transition_verified'
                )
                verified = bool(
                    callable(verify_fn) and verify_fn(
                        freebenefits_before, freebenefits_after
                    )
                )
                if verified and context is not None:
                    setattr(
                        context, '_qqfarm_freebenefits_claim_verified_day',
                        (globals().get('_daily_business_date')() if callable(globals().get('_daily_business_date')) else time.strftime('%Y-%m-%d')),
                    )
                    _throttled_write(
                        'v454-freebenefits-claim-verified',
                        'v454 daily free benefit click verified by fresh card transition',
                        5.0,
                    )
                if not verified:
                    _throttled_write(
                        'v454-freebenefits-claim-unverified',
                        'v454 daily free benefit click lacked fresh card transition proof',
                        5.0,
                    )
                    return False
            except BaseException:
                return False
        if entry_kind == 'task_prompt' and not succeeded:
            # v332: a stale task-prompt frame can miss the page after the native
            # template click.  Verify whether the task page is already open,
            # then re-deliver its entry and retry once with a newly captured frame.
            try:
                context = globals().get('_ACTIVE_RUN_CYCLE_CONTEXT')
                if context is None:
                    context_fn = globals().get('_share_context_from_call')
                    context = context_fn(a, k) if callable(context_fn) else None
                claim_visible_fn = globals().get('_daily_task_claim_available_visible')
                claim_visible = bool(
                    callable(claim_visible_fn) and claim_visible_fn(context)
                )
                if claim_visible:
                    result = True
                    succeeded = True
                    _throttled_write(
                        'v332-task-prompt-already-open',
                        'v332 task_prompt initial miss already shows the claim button; treating entry as open',
                        5.0,
                    )
                else:
                    client_click = globals().get('_friend_guard_post_client_click')
                    redelivered = bool(client_click(110, 655, 428, 800)) if callable(client_click) else False
                    _throttled_write(
                        'v332-task-prompt-client-redelivery',
                        'v332 task_prompt initial miss; QQ client task entry redelivered before fresh-frame retry=' + str(redelivered),
                        5.0,
                    )
                    time.sleep(1.2)
                    frame_fn = globals().get('_get_frame_from_bot')
                    fresh_frame = frame_fn(context) if callable(frame_fn) else None
                    retry_args = list(a)
                    retry_kwargs = dict(k)
                    if fresh_frame is not None:
                        for index, value in enumerate(retry_args):
                            if hasattr(value, 'shape'):
                                retry_args[index] = fresh_frame
                                break
                        for key in ('frame', 'game_frame', 'screen', 'image'):
                            if key in retry_kwargs:
                                retry_kwargs[key] = fresh_frame
                    result = fn(*retry_args, **retry_kwargs)
                    succeeded = _share_click_result_succeeded(result)
                    claim_visible = bool(
                        callable(claim_visible_fn) and claim_visible_fn(context)
                    )
                    if claim_visible:
                        result = True
                        succeeded = True
                    _throttled_write(
                        'v332-task-prompt-fresh-frame-retry',
                        'v332 task_prompt fresh-frame retry complete; click_succeeded=' + str(succeeded) + ' claim_visible=' + str(claim_visible),
                        5.0,
                    )
            except BaseException as e:
                try:
                    _throttled_write(
                        'v332-task-prompt-live-recovery-error',
                        'v332 task_prompt live recovery error ' + repr(e),
                        5.0,
                    )
                except BaseException:
                    pass
        if entry_kind in ('share_entry', 'share_prompt', 'share_btn_click'):
            try:
                action_gate = globals().get('_share_action_blocked')
                if callable(action_gate) and action_gate(
                    context, 'template-after-' + str(entry_kind)
                ):
                    return False
            except BaseException:
                pass
        if entry_kind in ('share_prompt', 'share_btn_click') and not succeeded:
            try:
                center = _share_find_prompt_button_center(a, k)
            except TypeError:
                center = _share_find_prompt_button_center()
            if center is not None:
                if entry_kind == 'share_prompt':
                    _throttled_write('share-prompt-visual-recovered', 'v73 share_prompt recovered from current farm frame', 5.0)
                    return True
                click_prompt = globals().get('_share_click_prompt_button')
                if callable(click_prompt):
                    clicked = bool(click_prompt(center, a, k))
                else:
                    clicked = bool(_share_click_abs(center[0], center[1]))
                if clicked:
                    _throttled_write('share-button-visual-click', 'v73 share_btn_click recovered by background window click', 5.0)
                    result = True
                    succeeded = True
        # Visual recovery may click the same share control after the native
        # click failed.  Pause once more before opening or confirming a contact
        # dialog so this recovery path has the same stop boundary.
        try:
            if _stop_requested_in_args(a, k):
                return _stop_gate_return('daily-share-entry-settle')
        except BaseException:
            pass
        if entry_kind == 'share_btn_click' and succeeded:
            try:
                cfg = _share_target_guard_config()
                action_gate = globals().get('_share_action_blocked')
                if callable(action_gate) and action_gate(
                    context, 'template-before-contact-dialog', cfg
                ):
                    return False
                if cfg.get('enabled', False):
                    module_fn = globals().get('_share_target_module')
                    mod = module_fn() if callable(module_fn) else None
                    dialog = _share_wait_dialog_hwnd(mod, timeout_ms=3500)
                    if callable(action_gate) and action_gate(
                        context, 'template-before-contact-search', cfg
                    ):
                        _share_close_dialog(mod, dialog or 0)
                        return False
                    if not dialog:
                        _share_log_runtime(
                            'prompt-click-unconfirmed-v84',
                            'daily share prompt click did not open the contact dialog',
                            True,
                        )
                        return False
                    confirm_fn = globals().get('_share_search_and_maybe_confirm')
                    try:
                        confirmed = bool(confirm_fn(mod, cfg, context=context)) if callable(confirm_fn) else False
                    except TypeError:
                        confirmed = bool(confirm_fn(mod, cfg)) if callable(confirm_fn) else False
                    if confirmed:
                        # Confirmation may finish after the user paused the bot
                        # or after another path made today's completion durable.
                        # Recheck before exposing any late success state/log.
                        if callable(action_gate) and action_gate(
                            context, 'template-after-contact-confirmation', cfg
                        ):
                            _share_close_dialog(mod, dialog or 0)
                            return False
                        target = str(cfg.get('target_name', '') or '').strip()
                        context_fn = globals().get('_share_context_from_call')
                        context = context_fn(a, k) if callable(context_fn) else (a[0] if a else None)
                        mark_fn = globals().get('_share_mark_runtime_success')
                        state = globals().get('_SHARE_DIRECT_SUCCESS_STATE', {})
                        evidence = state.get('evidence') if isinstance(state, dict) else None
                        if context is not None and callable(mark_fn):
                            mark_fn(context, evidence=evidence)
                        _share_log_runtime(
                            'sent-v83-direct',
                            'daily share completed immediately after share button target=' + target,
                            False,
                        )
                        return True
            except BaseException as e:
                try:
                    _throttled_write(
                        'v83-share-direct-error',
                        'v83 direct share handoff error ' + repr(e),
                        10.0,
                    )
                except BaseException:
                    pass
        if entry_kind == 'task_entry' and succeeded:
            # WGC can prove that the home task book exists while the QQ window
            # is behind another application.  The native absolute click then
            # lands on the foreground window even though it reports success.
            # Re-deliver exactly once to the QQ client only when ownership of the
            # mapped task-book point proves that the farm did not receive it.
            try:
                task_point = (110, 655)
                mapper = globals().get('_friend_guard_frame_to_screen')
                owner_check = globals().get(
                    '_friend_guard_screen_point_owned_by_farm'
                )
                client_click = globals().get('_friend_guard_post_client_click')
                if (
                    callable(mapper) and callable(owner_check)
                    and callable(client_click)
                ):
                    try:
                        screen_point = mapper(
                            task_point[0], task_point[1], 428, 800
                        )
                    except TypeError:
                        screen_point = mapper(task_point[0], task_point[1])
                    farm_owned = bool(
                        isinstance(screen_point, (tuple, list))
                        and len(screen_point) >= 2
                        and owner_check(screen_point[0], screen_point[1])
                    )
                    if not farm_owned:
                        try:
                            recovered = bool(client_click(
                                task_point[0], task_point[1], 428, 800
                            ))
                        except TypeError:
                            recovered = bool(client_click(
                                task_point[0], task_point[1]
                            ))
                        if recovered:
                            _throttled_write(
                                'task-entry-client-redelivery',
                                'v331 task entry redelivered to occluded QQ client ' +
                                'point=' + repr(task_point),
                                5.0,
                            )
            except BaseException:
                pass
        if entry_kind in ('share_entry', 'task_entry') and succeeded:
            try:
                if entry_kind == 'task_entry':
                    # On 2026-08-04 the live task page still had not exposed its
                    # prompt after the previous 1.2 second default.  Reserve a
                    # bounded 2.4 second render budget without slowing share.
                    settle_ms = _share_int_cfg('task_entry_settle_ms', 2400)
                    settle_cap = 2.5
                else:
                    settle_ms = _share_int_cfg('share_entry_settle_ms', 1200)
                    settle_cap = 1.5
            except BaseException:
                settle_ms = 2400 if entry_kind == 'task_entry' else 1200
                settle_cap = 2.5 if entry_kind == 'task_entry' else 1.5
            settle_seconds = max(0.25, min(settle_cap, float(settle_ms) / 1000.0))
            try:
                _throttled_write(
                    str(entry_kind) + '-settle',
                    'v38 daily ' + str(entry_kind) + ' clicked; waiting %.3fs before prompt detection' % settle_seconds,
                    5.0,
                )
            except BaseException:
                pass
            time.sleep(settle_seconds)
        return result

    try:
        _wrapped.__name__ = getattr(fn, '__name__', '_click_template_once')
        _wrapped.__qualname__ = getattr(fn, '__qualname__', _wrapped.__name__)
        preserve_fn = globals().get('_qqfarm_preserve_wrapper_metadata')
        if callable(preserve_fn):
            preserve_fn(_wrapped, fn)
        _wrapped.__qqfarm_share_entry_settle_wrapped__ = True
        _wrapped.__qqfarm_share_entry_settle_orig__ = fn
    except BaseException:
        pass
    return _wrapped, True



def _looks_share_entry_module(m):
    try:
        if m is None:
            return False
        module_name = str(getattr(m, '__name__', '') or '').lower()
        if not (module_name == 'bot.application.freebenefits_flow' or module_name.endswith('.freebenefits_flow')):
            return False
        for attr_name, value in list(vars(m).items()):
            if str(attr_name).startswith('__'):
                continue
            if str(attr_name) == '_click_share_dialog_first_friend_and_confirm':
                continue
            if isinstance(value, type) or not callable(value):
                continue
            return True
        return False
    except BaseException:
        return False


def _patch_share_entry_settle_for_module(m, tag=''):
    try:
        if not _looks_share_entry_module(m):
            return 0
        patched_names = []
        items = list(vars(m).items())
        items.sort(key=lambda item: (0 if str(item[0]) == '_click_template_once' else 1, str(item[0])))
        for name, old in items:
            name = str(name)
            if name.startswith('__') or name == '_click_share_dialog_first_friend_and_confirm':
                continue
            if isinstance(old, type) or not callable(old):
                continue
            if getattr(old, '__qqfarm_share_target_guard_wrapped__', False):
                continue
            new, ok = _wrap_share_entry_settle_func(old)
            if not ok:
                continue
            setattr(m, name, new)
            patched_names.append(name)
        if patched_names:
            try:
                setattr(m, '__qqfarm_share_entry_patched_names__', tuple(patched_names))
            except BaseException:
                pass
            try:
                log_fn = globals().get('_throttled_write')
                if callable(log_fn):
                    log_fn(
                        'v76-share-helper-names-' + str(getattr(m, '__name__', '')),
                        'v76 share helper aliases patched module=' +
                        str(getattr(m, '__name__', '')) + ' names=' + repr(patched_names[:40]),
                        30.0,
                    )
            except BaseException:
                pass
        return len(patched_names)
    except BaseException as e:
        try: _write('v76 share entry settle patch error ' + repr(e))
        except BaseException: pass
        return 0

def _patch_share_entry_settle_loaded(tag=''):
    changed = []
    try:
        seen = set()
        for mn, m in list(sys.modules.items()):
            if not _looks_share_entry_module(m):
                continue
            marker = id(m)
            if marker in seen:
                continue
            seen.add(marker)
            count = _patch_share_entry_settle_for_module(m, tag)
            if count:
                changed.append(str(mn) + ':' + str(count))
    except BaseException as e:
        try: _write('v34 share entry settle scan error ' + repr(e))
        except BaseException: pass
    if changed:
        sig = ', '.join(changed[:20])
        if sig not in _SHARE_ENTRY_SETTLE_PATCH_LOG_SEEN:
            _SHARE_ENTRY_SETTLE_PATCH_LOG_SEEN.add(sig)
            _write('v34 share entry settle patched ' + str(tag) + ' ' + sig)
    return changed


# ---- v36 friend radish false-positive diagnostics ----
# This is intentionally read-only. It records the compiled friend-flow
# boundary and the radish/cache-related names that are actually present at
# runtime before any behavioral gate is changed.
_FRIEND_RADISH_DIAG_SEEN = set()
_FRIEND_RADISH_DIAG_WRAP_SEEN = set()


def _friend_radish_evidence_map(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, bool):
        return {'confirmed': value}
    if isinstance(value, str):
        return {'confirmed': True, 'crop_name': value}
    try:
        fields = {}
        for key in ('confirmed', 'scope', 'crop_name', 'timestamp', 'target'):
            if hasattr(value, key):
                fields[key] = getattr(value, key)
        return fields
    except BaseException:
        return {}


def _should_skip_friend_radish(row_hint, farm_evidence, steal_evidence, skip_enabled=True, now=None, ttl=45.0):
    # A row cache is only a hint. It is deliberately not consulted here.
    if not bool(skip_enabled):
        return False
    steal = _friend_radish_evidence_map(steal_evidence)
    if bool(steal.get('confirmed')):
        return False
    evidence = _friend_radish_evidence_map(farm_evidence)
    if not bool(evidence.get('confirmed')):
        return False
    if str(evidence.get('scope', '')).strip().lower() != 'current_friend_farm':
        return False
    if str(evidence.get('crop_name', '')).strip() != '\u767d\u841d\u535c':
        return False
    try:
        current = float(now) if now is not None else float(__import__('time').time())
        observed = float(evidence.get('timestamp'))
        window = max(1.0, float(ttl))
        age = current - observed
        return 0.0 <= age <= window
    except BaseException:
        return False


def _friend_radish_wrapper_has_marker(value, marker):
    seen = set()
    current = value
    for _ in range(8):
        try:
            if current is None or id(current) in seen:
                return False
            seen.add(id(current))
            if bool(getattr(current, marker, False)):
                return True
            if bool(getattr(current, '__qqfarm_friend_radish_diag_wrapped__', False)):
                current = getattr(current, '__qqfarm_friend_radish_diag_orig__', None)
                continue
        except BaseException:
            return False
        return False
    return False


